// مولّدة آلياً بواسطة scripts/split-fatwas.mjs — لا تُعدَّل يدوياً.
export default [{"id":31,"question":"هذا سائل يقول يا فضيلة الشيخ عبد العزيز، السلام عليكم ورحمة الله وبركاته، وبعد: يوجد لدينا مسجد تقام الصلاة فيه جماعة وجمعة؛ ولكن يوجد فيه قبور حول المسجد في مقدمته ومؤخرته، والفرق بين المسجد والقبور نحو ستة أمتار فقط، علمًا أن المسجد بُني قبل وضع القبور، فهل تصح الصلاة في هذا المسجد؟","title":"حكم الصلاة في المسجد الذي حوله قبور","answer":"الجواب: نعم، تصح الصلاة فيه، ولو كان حوله قبور، إذا كان المسجد قائمًا، ووُضعت حوله القبور عن يمينه أو شماله أو أمامه أو خلفه، هذا لا يضر، وقد كان الناس فيما مضى يدفنون حول البلاد من الخوف والفتن والحروب، كانوا يدفنون حول مساجدهم، يخرج من المسجد، ويدفن حول المسجد.\nأما الآن فقد وسع الله ويسَّر، فينبغي إبعادها عن المساجد؛ حتى لو دعت الحاجة إلى توسيع المسجد وسِّع المسجد، وحتى لا يظن جاهل أن للدفن حول المساجد سرًّا أو قصدًا.\nفينبغي أن تكون المقابر بعيدة عن المساجد؛ حتى لا يظن ظان خلاف الحق، أو حتى لا تدعو الحاجة إلى التوسعة، فيكون وجود القبور مانعًا من ذلك، أو داعيًا إلى نبشها، ونقلها مرة أخرى.\nالمقصود أن القبور التي حول المساجد لا تمنع من الصلاة في المساجد، إنما المحرم أن تُبنى المساجد على القبور، وأن تتخذ القبور مساجد، هذا هو الذي نهى عنه النبي ﷺ، يقول ﷺ: لعن الله اليهود والنصارى اتخذوا قبور أنبيائهم مساجد، وقال ﷺ: ألا وإن من كان قبلكم كانوا يتخذون قبور أنبيائهم وصالحيهم مساجد، ألا فلا تتخذوا القبور مساجد، فإني أنهاكم عن ذلك.\nفلا يجوز أن يُبنى على القبور مساجد، ولا يُصلى حولها ولا بينها، ولا يدفن الميت في المسجد، لا، كل هذا لا يجوز، يجب أن تُدفن الموتى بعيدًا عن المساجد، وألا تقام المساجد على القبور، هكذا نهى الرسول ﷺ عن ذلك؛ ولكن متى وجد قبور جوار المسجد لم تمنع من الصلاة فيه.","link":"https://binbaz.org.sa/fatwas/2811/حكم-الصلاة-في-المسجد-الذي-حوله-قبور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0004.mp3","categories":["المساجد ومواضع السجود"]},{"id":49,"question":"سماحة الشيخ عبد العزيز، السلام عليكم ورحمة الله وبركاته، وبعد: أنا أحد المدرّبين في كلية عسكرية في لعبة الكاراتيه، وهي لعبة الدفاع عن النفس، والكلية لا يوجد فيها مكان مخصص للتدريب، فهل يصح أن أقوم بالتدريب في مكان يُبنى على أساس أنه مسجد، ولم يكتمل بعد؟","title":"هل يجوز التدريب البدني في المساجد؟","answer":"الجواب: ما دام أن هذا التدريب ينفع في سبيل الله وفي جهاد أعدائه؛ فلا بأس، والرسول ﷺ أقر الحبشة، ولعبوا في المسجد بالدرق والحراب، يدورون في المسجد بالدرق والحراب.\nفإذا كانت اللعبة يُستعان بها على الدفاع على النفس، وجهاد الأعداء، وتوقِّي شرهم، فلا بأس في المسجد الذي فيه رحبة، وفيه سعة، حتى يوجد مكان آخر يكون فيه اللعب، بشرط ألا يكون هذا اللعب مما يتأذّى به المسجد من تخريب أو بول أو غير ذلك.","link":"https://binbaz.org.sa/fatwas/2954/هل-يجوز-التدريب-البدني-في-المساجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0022.mp3","categories":["المساجد ومواضع السجود"]},{"id":209,"question":"يوجد بعض الإخوان ينفرون من الصلاة في مسجد ابن عباس في الطائف، ويقولون إنه مبنيٌّ على القبور، فما رأيكم؟","title":"حكم الصلاة في مسجد ابن عباس الذي في الطائف","answer":"الجواب: هذا غلطٌ وجهلٌ، فمتى نُبشت القبور لمصلحة المسلمين جازت الصلاةُ في محلِّها، فلا بأس أن يُصلَّى في مسجد ابن عباس؛ لأنها القبور نُبشت لمصلحة المسلمين، فلا حرج في ذلك، والنبي ﷺ بنى مسجده في محلِّ قبورٍ، فمسجد النبي ﷺ كانت فيه قبور، فأمرهم بنبشها وإزالتها، وكانت فيه حُفر وخربات فأزالها، وكان فيه نخلٌ فقُطِعَ، ثم بُني المسجد.\nفالمقصود أنه متى نُقلت القبور للمصلحة؛ فلا بأس.","link":"https://binbaz.org.sa/fatwas/3985/حكم-الصلاة-في-مسجد-ابن-عباس-الذي-في-الطاىف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 116.mp3","categories":["المساجد ومواضع السجود"]},{"id":288,"question":"مَن دخل المسجد والإمام يخطب هل يجلس ويستمع الخطبة أم يُصلي ركعتين؟","title":"ما المشروع لمن دخل المسجد والإمام يخطب؟","answer":"الجواب: المشروع أن يُصلي ركعتين، ثم يجلس، يبدأ بالصلاة، يقول النبيُّ ﷺ: إذا جاء أحدُكم والإمام يخطب فليركع ركعتين، وليتجوَّز فيهما، هكذا أمر النبيُّ ﷺ، فيبدأ بالصلاة ثم يجلس.","link":"https://binbaz.org.sa/fatwas/4286/ما-المشروع-لمن-دخل-المسجد-والامام-يخطب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0335.mp3","categories":["المساجد ومواضع السجود"]},{"id":326,"question":"تردد في الآونة الأخيرة بناء المُغنيين للمساجد، ما حكم ذلك؟ وإذا كان حرامًا فلماذا لا يُمنع؟","title":"ما حكم بناء المساجد من كَسْبٍ حرام؟","answer":"الجواب: بناء المسجد صحيحٌ من ذلك، لكن ينبغي أن تُصرف فيه النَّفقة الطيبة، فإذا تمَّ البناء من مالٍ حرامٍ: من غناء، أو من بنك، أو كذا؛ صحَّ وصُلِّي فيه، ولا يضرُّ، والإثم على مَن كسب الحرام. وأما المسجد فهو وجهٌ خيريٌّ، وهكذا الجهات الخيرية تُصرف فيها الأموال الضَّائعة والأموال المكسوبة من طرقٍ غير طيبةٍ؛ لأنها أموال ضائعة، أموال ليس لها مالكٌ في الحقيقة، فتُصرف في إصلاح الطّرقات، في إصلاح دورات المياه، في الصَّدقة على الفقراء، في قضاء الدَّين عن المدينين، في تزويج المُحتاجين؛ لأنها أموال شبه ضائعة، ليس لها مالكٌ في الحقيقة.\nوهكذا مهر البَغي، وحلوان الكاهن، وهكذا ما أُخذ من الربا وهدى اللهُ صاحبَه؛ يُصرف في وجوه البرِّ، لكن ينبغي تنزّه المساجد عن هذا، وألا يُنفق فيها إلا النَّفقة الطيبة، لكن متى بُني من كسبٍ ليس بطيبٍ؛ صحَّت الصلاةُ فيه ولا يُهدم.","link":"https://binbaz.org.sa/fatwas/4414/ما-حكم-بناء-المساجد-من-كسب-حرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0379.mp3","categories":["المساجد ومواضع السجود"]},{"id":699,"question":"يقول: نحن في المركز هنا أو في المُخيمات أو بعض الصَّالات نُصلي فيها أحيانًا، فهل يلزمنا تحية المسجد؟","title":"هل تأخذ المصليات المؤقتة حكم المساجد؟","answer":"الجواب: تحية المسجد للمسجد، المصليات ما لها حكم المساجد، المصليات التي تُعدّ في دائرةٍ أو في غير دائرةٍ أو في السفر تُعدّ مُصلًّى، ما تُسمَّى: مسجدًا.....، ليس لها حكم المساجد؛ لأنه لم يُوقف لهذا الأمر، إنما هو عارضٌ، لو صلّوا في غرفةٍ بمناسبة أنها مناسبة، أو في \"سيب\" وهذه الأشياء، ما يصير في حكم المسجد.\nلكن إذا صلَّى فيه الراتبة -راتبة الظهر- أربعًا قبل الظهر سنة، ما هي تحية مسجدٍ، يُقال: راتبة، وهكذا في المصلَّى الذي يُعدّ للناس عند المخيم ما يُسمَّى: مسجدًا، هو مصلّى، فإذا خرجوا للنزهة حول البلد وجعلوا لهم مصلًّى ما يُسمَّى: مسجدًا، وإذا سُمِّيَ مسجدًا فهو تسامحٌ في العبارة وتجوُّزٌ.","link":"https://binbaz.org.sa/fatwas/20548/هل-تاخذ-المصليات-الموقتة-حكم-المساجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0510فتاوى المحاضرات للشيخ عبدالعزيز بن باز رحمه الله.mp3","categories":["المساجد ومواضع السجود"]},{"id":710,"question":"المسجد المبني تحت عمارةٍ سكنيةٍ هل تجوز الصلاة فيه؟","title":"حكم الصلاة بمسجد مبني تحت عمارة سكنية","answer":"الجواب: إذا دعت الحاجةُ إلى مسجدٍ يخرج من العمارة فلا بأس، إذا دعت الحاجةُ أهلَ محلٍّ ما عندهم مسجد، وتبرع لهم إنسانٌ بالدور الأسفل، وجعلوه مسجدًا؛ فلا حرج في ذلك، أما إذا كان المسجد قائمًا فلا تُبنى عليه عمارة، إذا قام المسجدُ يُترك ظهره لحاجة المسجد، أما إذا كان المسجدُ جديدًا على العمارة والعمارة سابقة وتبرع صاحبُها بالدور الأسفل أو الثاني أو الثالث للمسجد فلا بأس، وجزاه الله خيرًا، إذا احتاجوا إلى ذلك.","link":"https://binbaz.org.sa/fatwas/20575/حكم-الصلاة-بمسجد-مبني-تحت-عمارة-سكنية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0529فتاوى المحاضرات للشيخ عبدالعزيز بن باز رحمه الله.mp3","categories":["المساجد ومواضع السجود"]},{"id":806,"question":"ما حكم مَن يحجز لنفسه مكانًا في المسجد يُخصصه له دائمًا؟","title":"حكم من يحجز مكانًا دائمًا له بالمسجد","answer":"الجواب: لا يجوز، هذا تَحَجُّر لا يجوز، المسجد ليس لواحدٍ معينٍ، هو لمن سبق، فليس لأحدٍ أن يتحجَّر مكانًا بوسط الصف الأول أو في غيره حتى يأتي من بيته أو من سوقه، لا، المسجد لمن سبق، ومَن حجز وجب على المسؤولين أن يُزيلوا حجزه، حتى لا يكون سببًا لغيره وقائدًا لغيره إلى حجز الصفوف ومنع المتسابقين إليها، فمَن أراد الخير يسبق بنفسه، لا بعصاه، ولا بشيءٍ آخر.","link":"https://binbaz.org.sa/fatwas/20839/حكم-من-يحجز-مكانا-داىما-له-بالمسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0636ما حكم حجز مكان في المسجد يكون له دائماً ؟ ابن باز فتاوى المحاضرات.mp3","categories":["المساجد ومواضع السجود"]},{"id":958,"question":"هل يجوز وضع بعض الآيات القرآنية في جدران المسجد للذكرى والموعظة؟","title":"حكم وضع آيات في جدران المسجد للموعظة","answer":"الجواب: لا نعلم به بأسًا، وقد درس هذا مجلس هيئة كبار العلماء في دورةٍ سبقت، ورأى أنه لا محظور في ذلك إذا كان لقصد الذكرى والموعظة والفائدة، لكن يُكره في المساجد؛ لأنَّ المساجد لم تُبْنَ لهذا، ولأن هذا يشغل المصلين، فينبغي أن تكون المساجد خاليةً من ذلك: من النقوش والكتابات، حتى لا يُشغل المصلون بذلك.","link":"https://binbaz.org.sa/fatwas/20998/حكم-وضع-ايات-في-جدران-المسجد-للموعظة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0795هل يجوز وضع آيات القرآن في جدرات في المجلس للذكرى والموعظة؟ ابن باز فتاوى المحاضرات.mp3","categories":["المساجد ومواضع السجود"]},{"id":965,"question":"بعضُ الشباب يرى أنَّ طلب العلم الشرعي لا يوجد إلا عند العلماء في الحلقات فحسب، ويترك بذلك الدراسة النِّظامية في المدارس، فما نصيحتكم والله يحفظكم؟","title":"ما الرأي في أن طلب العلم بالمساجد فقط؟","answer":"الجواب: هذا غلطٌ، وليس بصحيحٍ، بل توجد في المعاهد والكليات علوم عديدة: من جهة الشرعية، من جهة أصول الدين، من جهة الحديث، من جهة القرآن، فيها علمٌ عظيمٌ، المهم النُّصح والجد والنشاط في ذلك، ولا مانع أن يجمع بين الأمرين، لا مانع أن تكون له دراسة نظامية، ودراسة مع المشايخ في الليل، أو في الخميس وفي العُطل التي يستطيع الدراسة فيها، لا مانع أن يجمع بين المصلحتين والاتجاهين. لكن مَن زعم أنَّ الدراسة النِّظامية ليس فيها علمٌ فهو غالطٌ، لكن أراد أن يُسلِّي نفسه لما لم ينتظم، أراد أن يُسلِّي نفسه حتى يعذرها بهذا التأخر، وإلا فالدراسة النِّظامية فيها مصالح دينية ودنيوية وتشجيعية، فإن المنتظم يتشجع مع إخوانه ويستفيد وينفع الله به الأمة إذا كانت معه الشَّهادة، ينفع به الأمة، ويحصل له بها أيضًا المساعدة في دنياه، فلا ينبغي التَّعلق بهذا الكلام، ولا التأثر بهذا الكلام. وفَّق الله الجميع.","link":"https://binbaz.org.sa/fatwas/21006/ما-الراي-في-ان-طلب-العلم-بالمساجد-فقط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0803ما رأيكم فمن يرى أن طلب العلم فقط في المساجد وحلقات العلم؟ ابن باز فتاوى المحاضرات.mp3","categories":["المساجد ومواضع السجود","العالم والمتعلم"]},{"id":1131,"question":"هل المباني القديمة والمساجد القديمة تُعتبر من التراث بهذا المفهوم؟","title":"حكم اعتبار المباني والمساجد \"تراثًا\" وزيارتها","answer":"الجواب:\nإذا كانت تتعلق بالدِّين، مثل: المساجد والمدارس والأربطة التي بناها المسلمون لوجه الله عزَّ وجل- فتُسمَّى: تُراثًا؛ لأنها بقية، مثلما تقدم: التراث هو البقية، بقية ما كان سالفًا، فما أبقاه لنا الأوائل يُسمَّى: تُراثًا، سواء بناء، أو شيئًا منقولًا، أو غير ذلك.  لكن إن كان مما يدعو إليه الإسلامُ ويُحبب إليه الإسلامُ سُمِّي: تُراثًا إسلاميًّا.  وإن كان من الأمور العادية التي ليس لها تعلُّق بالإسلام فهو تراث عادي، تراث دنيوي، ليس له تعلُّقٌ بالإسلام: كالأواني، أو المنازل، أو البيوت التي لا تعلق لها بالإسلام، هذا تراثٌ عادي، تراث على الأقدمين من كذا: من نجد، من اليمن، من الشام، من تركيا، على حسب ما هو فيه.  وإذا كان فيه شيء مما ينفع المسلمين: كالأربطة التي على العلماء وطلاب العلم، أو المحدثين، أو الفقهاء؛ فهذا تراثٌ إسلاميٌّ، أو المساجد المعروفة: تراث إسلامي بلا شكٍّ، وهكذا المدارس المعروفة، وما أشبه ذلك مما يتعلق بالمسلمين.\nس: حكم زيارتها للاطلاع؟\nالشيخ: حكم الزيارة للاطلاع ما فيه شيءٌ، زيارة المدارس والأربطة للاطلاع عليها أو أشياء غريبة يُحبّ أن يطلع عليها: قصور غريبة، أو مبانٍ غريبة، إنما الذي يُنهى عنه شدّ الرِّحال للتَّعبد، لا تُشدّ الرِّحال إلا إلى ثلاثة مساجد، إذا كان لقصد التَّعبد فيها، أما لقصدٍ آخر كالإشراف عليها ومعرفة كيف بُنِيَتْ، أو فيها أشياء يُريد أن يعرفها من التَّصميم، أو من أشياء أخرى دعت الحاجةُ إلى أن يعرفها؛ لا بأس، مثلما يُسافر للتِّجارة أو غير التِّجارة.","link":"https://binbaz.org.sa/fatwas/21201/حكم-اعتبار-المباني-والمساجد-تراثا-وزيارتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0997هل المباني القديمة والمساجد القديمة تعتبر من التراث؟ ابن باز.mp3","categories":["المساجد ومواضع السجود"]},{"id":1306,"question":"رجلٌ بنى مسجدًا من مالٍ من والدته التي تعمل في الكهانة والشَّعوذة والذبح لغير الله، ويقول: إنا نعبد الله، ونصوم، ونصلي، ونحج، وغيرها من العبادات.و هل تجوز الصلاة في هذا المسجد؟ وما حكم ما يتقاضاه الإمامُ والمؤذن في هذا المسجد؟","title":"حكم الصلاة في مسجد بُنِي من مال مشبوه","answer":"الجواب:\nالمساجد التي بُنيت من أموالٍ مُشتبهٍ فيها وأموال محرَّمة تصح الصلاةُ فيها، والأموال الباطلة تُصرف في وجوه الخير، وأعمال الخير، تُصرف في الفقراء والمساكين والمجاهدين، والتعمير للمشاريع الخيرية؛ لأنها أموال كالأموال الضَّائعة، تُصرف فيما ينفع المسلمين، والإثم على مَن فعلها، ومصلحتها للمسلمين، لا تُحرق، ولا تُلقى في البحر، ولكن تُصرف في مصالح المسلمين، ومنها المساجد. لكن إذا تيسر مالٌ طيِّبٌ للمسجد يكون أطيب وأحسن، ولكن لو صُرفت في مسجدٍ لا يضرُّ، لا، ما يضرُّ المصلين، والإثم على مَن تعاطاها واكتسبها، ولكن إذا صرفها في تعمير المسجد، أو في دواءٍ، أو في دورات المياه، أو في مصالح المسلمين الأخرى كإصلاح الطُّرقات، أو غير ذلك، أو للجهاد؛ كان هذا مما يُخَفِّف عنه.","link":"https://binbaz.org.sa/fatwas/21363/حكم-الصلاة-في-مسجد-بني-من-مال-مشبوه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1106رجل بنى مسجد من مال والدته التي تتعامل بالكهانة والشعوذة فهل يجوز الصلاة فيه؟.mp3","categories":["المساجد ومواضع السجود"]},{"id":1385,"question":"بالنسبة للأجر المترتب على الذهاب إلى المسجد هل هو خاص بالمشي أم يَعُمُّ الراكب وغيره؟","title":"هل أجر الذهاب للمسجد يَعُمُّ الماشي والراكب؟","answer":"الجواب:\nيَعُمُّ الراكب وغيره.\nس: يكتب له أجر الخطوة كذلك؟\nج: الله أعلم، المقصود مسابقته وسيره إلى المسجد سواء بقدر الخطا التي لو مشى عُدت له أو على وجه آخر، ربنا أعلم.","link":"https://binbaz.org.sa/fatwas/21478/هل-اجر-الذهاب-للمسجد-يعم-الماشي-والراكب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الأجر المترتب على الذهاب إلى المسجد هل هو خاص بالمشي أم يعم الراكب وغيره.mp3","categories":["المساجد ومواضع السجود"]},{"id":1387,"question":"من كان بجنبه مسجد ويتخطى إلى مسجد أبعد؟","title":"حكم تَعَمُّد الذهاب لمسجد بعيد بقصد الأجر","answer":"الجواب:\n\nما في بأس إذا كان يقصد الأجر، وإذا كان المسجد القريب لا يترتب عليه شيء لذهابه منه؛ لا يُتهم بشيء، ولا يترتب عليه تخلف ناس.\n\nأما إذا كان وجوده فيه يجمعهم ويعينهم على المحافظة؛ فالصلاة في المسجد القريب الذي يحصل به جمع الناس وحرصهم على الصلاة بأسبابه أوْلى.\n\nأما إذا كان ذهابه لمسجد بعيد لا يترتب عليه شيء؛ فلا بأس مثل ما قال: أعْظَمُ الناس أجْرًا في الصلاة أبْعَدُهم فأبْعَدُهم مَمْشى.\n\nلكن بعض الناس وجوده في المسجد من أسباب جمع الناس ومن أسباب حرصهم على الحضور، وقد يُتهم لو رأوه وقالوا ما صلى وإلا كذا ويُرمى عرضه.","link":"https://binbaz.org.sa/fatwas/21480/حكم-تعمد-الذهاب-لمسجد-بعيد-بقصد-الاجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم تعمد الذهاب لمسجد بعيد بقصد الأجر.mp3","categories":["المساجد ومواضع السجود"]},{"id":1418,"question":"حكم الصلاة على البُسُط التي فيها نقوش أو زخارف؟","title":"حكم الصلاة على البُسُط التي بها صور","answer":"الجواب:\nتصح الصلاة، لكن التماس السادة أحسن؛ لأنها أبعد عن الوساوس، وإلا الصلاة صحيحة.\nس: ولو عليها صور؟\nج: الصور كذلك، أشنع. ينبغي أن يلتمس ما فيها شيء، حتى لا تشوش عليه.\nس: حديث أبي جهيم، ما يدل على التحريم؟\nج: صحيح، على الكراهة حتى لا تشوش عليه، النبي ﷺ صلى على الخميصة، ثم بعث بها إلى أبي جهيم.\nس: ملابس عليها صورة، يصلي عليها؟\nج: لا يلبس ملابس فيها صورة، يبعدها، ويلبس ملابس سليمة، هذه يخليها وسائد ونحوها.","link":"https://binbaz.org.sa/fatwas/21513/حكم-الصلاة-على-البسط-التي-بها-صور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الصلاة على البسط التي فيها نقوش أو زخارف والملابس التي فيها صور.mp3","categories":["المساجد ومواضع السجود"]},{"id":1847,"question":"أحيانًا في بعض المساجد يكون هناك اختلافٌ في الأحذية، فإذا ما وجد نعلَه يأخذ أيَّ نعلٍ ويمشي به؟","title":"حكم أخذ نعلٍ من المسجد لمن فقد نعله","answer":"الجواب:\nهذا لا يجوز له، إذا ظُلِمَ لا يظلم، لكن لو كانت النعلُ في محلٍّ معينٍ ووجد ما يُشبهها فالأوجه أن صاحبها قد غلط وأخذها، فإذا وجد نعلًا تُشبه نعله المفقودة فالظاهر أنَّ صاحبها غلط، فلا بأس أن يأخذ التي في محلِّه وهي تُشبهها، أما إذا لم تكن بينهما مُشابهة فلا يأخذها.","link":"https://binbaz.org.sa/fatwas/21956/حكم-اخذ-نعل-من-المسجد-لمن-فقد-نعله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم أخذ النعال من المساجد في حال فقدانه نعاله.mp3","categories":["المساجد ومواضع السجود"]},{"id":1898,"question":"بالنسبة لحجز المكان قبل الدرس بيومٍ وأحيانًا مثلًا يأتي الشخصُ في العصر ويجلس، فأيهما أوْلى: الذي حجز قبل الدرس بيومٍ، أو الذي أتى من بعد صلاة العصر مباشرةً؟","title":"حكم حجز المكان في المسجد؟","answer":"الجواب:\nالذي حجز ما له حق، يُمْطَل، يُؤخَذ متاعه ويُمْطَل، ما له حق، أما الذي جاء بنفسه وجلس في الصف فهو أحق.\nس: طيب، لو قلنا له: إن الشيخ عبدالعزيز بن باز يُفتي بأنه لا يجوز أن تحجز المكان، فقال: ولو كان فالشريعة تقتضي أني أضع الغرضَ وكذا؟\nج: لا، يكذب، النبي ﷺ قال: مَن سبق فهو أحقّ به، هذا ما سبق، هذا وضع نعاله أو دوشه.\nس: يستدل على مَن سبق بمتاعه؟\nج: لا، ما يصح، المسبوق أي: يسبق بنفسه فيُصلي أو يقرأ، وإلا فهذا عدوان على الناس.\nس: يعني: يُزيله ويجلس مكانه؟\nج: نعم، ما أعلم فيه خلافًا بين أهل العلم أنَّ هذا منكر.","link":"https://binbaz.org.sa/fatwas/22009/حكم-حجز-المكان-في-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/فتوى بن باز في حجز المكان في المسجد.mp3","categories":["المساجد ومواضع السجود"]},{"id":1927,"question":"إذا كان المسجد مفروشًا بالتراب...؟","title":"حكم البصق في المسجد ووضع وعاء النفايات","answer":"الجواب:\nيجب ألا يبصق فيه، لكن لو وُجِدَ البُصاق يُدْفَن أو تُنْزَع وتُنْقَل إذا كانت قد تُؤذي.\nس: بالنسبة لوضع (سطول) النِّفايات في المسجد، مثلًا وضع المناديل فيها؟\nج: هذا ما فيه شيء، هذا محفوظٌ ما يتأذَّى به أحد.\nس: في الحرم يوجد (سطول) لكن الناسَ يبصقون في وسطها؟\nج: وسطها ما يضرّ، فإذا كان هناك شيء مُعدٌّ للبصاق فلا بأس.\nس: بالنسبة لفناء المسجد؟\nج: كل ما يتبع المسجد حكمه حكم المسجد.\nس: لا يُصلَّى فيه؟\nج: ولو، ما دام تابعًا لصرح المسجد لا يُتْفَل فيه.","link":"https://binbaz.org.sa/fatwas/22040/حكم-البصق-في-المسجد-ووضع-وعاء-النفايات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/البصق في المسجد وحكم وضع سطول للنفايات في المساجد.mp3","categories":["المساجد ومواضع السجود"]},{"id":1929,"question":"ما حكم مَن كان يحمل صندوقَ دخانٍ أو علبةً أو كان شاربَ دخانٍ وهناك رائحة من فمه؟","title":"كيف يُنصح من يحمل رائحة الدخان بالمسجد؟","answer":"الجواب:\nيُنْصَح ويُعَلَّم مثل مَن أكل بصل، ويُقال: لا تُصَلِّ مع الناس حتى تتنظَّف، فالنبي ﷺ أنكر على مَن حضر ومعه الكُرَّاث والبصل؛ لئلا يُؤذي الناس.\nس: أو يتركون هذا الشيء؟\nج: يُعَلَّمون، الدِّين النَّصيحة، المسلمُ أخو المسلم، الدين النصيحة فيُنْصَحون ويُوجَّهون إلى الخير، ويُقال: يا فلان، اتَّقِ الله، هذا ما يجوز، حرام عليك، مضرَّة عليك في دينك ودُنياك وصحّتك، وتؤذي به الناس أيضًا.","link":"https://binbaz.org.sa/fatwas/22042/كيف-ينصح-من-يحمل-راىحة-الدخان-بالمسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/صلاة شاربَ دخانٍ وهناك رائحة من فمه جماعة.mp3","categories":["المساجد ومواضع السجود"]},{"id":1931,"question":"بعض المساجد يكون فيها لوحة تُعلَّق فيها المفقودات، من: مفاتيح، أو سبحة، أو أقلام، داخل المسجد؟","title":"حكم تعليق لوحة المفقودات في المساجد","answer":"الجواب:\nالأقرب أنها تكون خارج المسجد؛ لأنَّ هذا نوعُ إنشادٍ بالفعل، هذا إنشادٌ بالفعل.","link":"https://binbaz.org.sa/fatwas/22044/حكم-تعليق-لوحة-المفقودات-في-المساجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم لوحة المفقودات في المساجد.mp3","categories":["المساجد ومواضع السجود"]},{"id":1932,"question":"بالنسبة للمُصَلَّى الذي يُصلَّى فيه فرضٌ واحدٌ هل يُقاس بالمسجد؟","title":"هل يُقاس المُصَلَّى على المسجد؟","answer":"الجواب:\nإذا كان مبنيًّا للتَّعبد فهو مسجد، ولو ما صُلِّي فيه إلا الظهر أو غيره، أما إذا كان مصلَّى مثل ما يكون في بعض الدَّوائر؛ فهذا ما له حكم المساجد، هذه المصليات في الدوائر ليس لها حكم المساجد، بل هي غرفة من الغرف يُصلُّون فيها.\nس: يُطلق عليها مُصلَّى أم مسجد؟\nج: مُصلَّى.","link":"https://binbaz.org.sa/fatwas/22045/هل-يقاس-المصلى-على-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يقاس المصلى على المسجد.mp3","categories":["المساجد ومواضع السجود"]},{"id":1934,"question":"بالنسبة لحديث الدنيا في المسجد؟","title":"كيف يُنصح مَن يُكثر حديث الدنيا بالمسجد؟","answer":"الجواب:\nإذا كان قليلًا فلا بأس، أما الكثير فلا، حديث الدنيا إن كان شيئًا قليلًا فإنه يُغتفر، مثل: كيف أولادك؟ وكيف عيالك؟ أسافر فلان؟ أوصل فلان؟ الشيء الذي تدعو إليه الحاجة.\nس: وإذا كان طويلًا؟\nج: أما الإطالة فيُكره.\nس: يُنْكَر على صاحبه؟\nج: بالكلام الطيب، بالأسلوب الحسن: يُكره هذا الكلام.","link":"https://binbaz.org.sa/fatwas/22047/كيف-ينصح-من-يكثر-حديث-الدنيا-بالمسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم حديث الدنيا في المسجد.mp3","categories":["المساجد ومواضع السجود"]},{"id":1935,"question":"إدخال الفيديو والتليفزيون وآلات التصوير داخل المسجد هل يجوز؟","title":"حكم إدخال آلات التصوير والفيديو إلى المسجد","answer":"الجواب:\nلا، ما يجوز، هذا من إدخال المنكرات، كونه يُطلق العنان للراديو وأن يكون فيه شيء قبيح ويكون فيه أغانٍ ويكون فيه أصوات منكرة.\nس: بعض الناس يحتجُّون على التَّجويز بوجود آلات تصويرٍ في الحرم؟\nج: لا، ما يصلح هذا، فعلهم ما هو بحجَّةٍ، التصوير ممنوعٌ مطلقًا.\nس: حتى في الحرم؟\nج: في الحرم ممنوع، لكن إذا تساهل المسؤولون ما هو بحجَّةٍ، تساهُل المتساهل ما يكون حُجَّةً.\nس: بالنسبة للآلات التي ذكرتها آنفًا: يقول بعضُ الناس: إنَّ هذه الأشياء تُفيد الدعوة وتُفيد الناس؟\nج: لا، لا، أما لو كان مجرد شيءٍ طيبٍ كإذاعة قرآنٍ فلا بأس، لكن قد يقع فيها إذاعة أشياء ما هي طيبة، أما إذا صانها وكان يستمع إذاعة القرآن أو شيئًا طيبًا فلا بأس.","link":"https://binbaz.org.sa/fatwas/22048/حكم-ادخال-الات-التصوير-والفيديو-الى-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يجوز إدخال الفيديو والتليفزيون وآلات التصوير داخل المسجد.mp3","categories":["المساجد ومواضع السجود"]},{"id":1936,"question":"عقد المؤتمرات في المساجد؟","title":"هل يجوز عقد المؤتمرات في المساجد؟","answer":"الجواب:\nإذا دعت لها الحاجة فلا بأس؛ لأنَّ هذا من المنفعة، مؤتمر لمصلحة المسلمين لا بأس.","link":"https://binbaz.org.sa/fatwas/22049/هل-يجوز-عقد-الموتمرات-في-المساجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم عقد المؤتمرات في المساجد.mp3","categories":["المساجد ومواضع السجود"]},{"id":1966,"question":"بالنسبة لاتّخاذ المحراب في المسجد ما حكمه في الشرع؟","title":"حكم اتّخاذ المحراب في المسجد","answer":"الجواب:\nلا بأس به؛ لأنَّه دَرَجَ عليه المسلمون، وهو علامة على المساجد، وعلى توسُّط الإمام، وهو من العهد الأول، والناس دارجون على هذا.\nس: ظهر في بعض البلدان مَن يقول: اتِّخاذ المحراب في المسجد نوعٌ من البدعة، حتى صاروا يبنون المسجد دون محرابٍ؟\nج: لا، غلط، لا محذور فيه، دَرَج عليه المسلمون من العهد الأول والعهد الثاني: عليكم بسنتي وسنة الخلفاء، خير أمتي قرني، ثم الذين يلونهم، ثم الذين يلونهم، درج عليه المسلمون؛ لأن فيه مصلحةً، كتمييز المسجد من غيره، وتوسُّط الإمام، وقد يُحتاج إليه عند ضيق المسجد.\nس: هل كان هذا موجودًا في عهد النبي ﷺ؟ وهل كان في مسجد النبي ﷺ محراب؟\nج: لا، حدث في العهد الأول، في المئة الأولى، فبِنَايَتُه الظاهر أنها كانت في القرن الأولى، في المئة الأولى، بعد الخلفاء الراشدين.\nس: طيب، هؤلاء الذين يفعلون هذا الفعل هل في إمكانهم أن يحتجوا بقولهم: لم يكن في مسجد النبي ﷺ محراب؟ هل تكون حجتهم مقبولةً أم تُردُّ عليهم؟\nج: الأمر فيها واسع، فهي من باب المباحات للمصلحة، وليست من باب السُّنن، فهي مثل البناء المُسَلَّح الموجود الآن ونحوه، فهذا لم يكن موجودًا في عهد النبي ﷺ، فهذه أمور عادية.\nس: هل مَن تركه يأثم؟\nج: مَن فعله فلا بأس، ومَن تركه فلا بأس، الأمر واسع.","link":"https://binbaz.org.sa/fatwas/22081/حكم-اتخاذ-المحراب-في-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم اتّخاذ المحراب في المسجد.mp3","categories":["المساجد ومواضع السجود"]},{"id":1967,"question":"الحديث في أمور الدنيا في المسجد؟","title":"حكم الحديث في أمور الدنيا بالمسجد","answer":"الجواب:\nإذا كان شيئًا يسيرًا يُعْفَى عنه، مثلما قال النبي ﷺ لكعب بن مالك لما تقاضى هو وابن أبي حدرد في الدَّين الذي عليه، قال: ضع الشطر، ومثل ما يكون من خصوماتٍ في المسجد في بعض الأشياء، يعني: الشيء الذي ما يُشْغِل وهو قليلٌ يُعْفَى عنه.","link":"https://binbaz.org.sa/fatwas/22082/حكم-الحديث-في-امور-الدنيا-بالمسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الحديث في أمور الدنيا في المسجد.mp3","categories":["المساجد ومواضع السجود"]},{"id":2010,"question":"الخروج لدرس في مسجد آخر؟","title":"هل يجوز الخروج من المسجد بعد الأذان؟","answer":"الجواب:\nهذا عذر شرعي، لكن ينبغي أن يخرج قبل الأذان، يلاحظ أن يكون خروجه قبل الأذان حتى لا يُظن به السوء.\nس: لو خرج للصلاة في مسجد آخر؟\nالشيخ: لا، لا يخرج للصلاة في مسجد آخر بعد الأذان، ما هو بعذر؛ إلا إذا كان إمامًا أو في درس أو لأسباب مهمة.","link":"https://binbaz.org.sa/fatwas/22126/هل-يجوز-الخروج-من-المسجد-بعد-الاذان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الخروج من المسجد بعد الأذان.mp3","categories":["المساجد ومواضع السجود"]},{"id":2071,"question":"بالنسبة لانتظار الصلاة: إذا انصرف الناسُ من الصلاة، وجلس إنسانٌ في المسجد ينتظر الصلاةَ التي بعدها، فهل يجوز له أن يتحدَّث في الدنيا أم لا؟","title":"حكم الكلام الدنيوي لمن ينتظر الصلاة","answer":"الجواب:\nهو في صلاةٍ ما انتظر الصلاة، وهكذا في بدء الصلاة، ما لم يُؤْذِ أو يُحْدِث.\nس: وتحدثه في الدنيا جائز؟\nج: تركه أوْلى، إلا الشيء القليل.\nس: هل ورد عن الإمام أحمد في \"مسنده\" شيءٌ من هذا؟\nج: ما أذكر شيئًا في هذا، يذكر عن بعض السَّلف.\nس: حَمَلَ بعضُ الشراح –القرطبي وابن حجر- الحديثَ على ما ذكرتَ؟\nج: نعم، يجب حمله على هذا، إذا سَلِمَ من العِلَّة.","link":"https://binbaz.org.sa/fatwas/22189/حكم-الكلام-الدنيوي-لمن-ينتظر-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الكلام في أمور الدنيا لمن كان منتظر للصلاة.mp3","categories":["المساجد ومواضع السجود"]},{"id":2387,"question":"لا بدّ من استحضار النية في الخطوات (إلى المسجد)؟","title":"هل تلزم النية لحصول فضل الخُطَى للمسجد؟","answer":"الجواب:\nما دام ناويًا الصلاة يكفي، ما دام ذهب إلى المسجد بنية الصلاة؛ هذه النية.\nس: بالنسبة للشخص إن كان يأتي من ظهرة البديعة أو الدخل المحدود على السيارة ليسمع الدرس هنا ويحضر صلاة الجماعة؟\nالشيخ: يُرْجَى له هذا كله، كالماشي.","link":"https://binbaz.org.sa/fatwas/22512/هل-تلزم-النية-لحصول-فضل-الخطى-للمسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/استحضار النية في الخطوات إلى المساجد.mp3","categories":["المساجد ومواضع السجود"]},{"id":2438,"question":"تغيير الأماكن (في الصلاة) هل تشهد المواطن هذه؟ بالنسبة للسُّنة؟","title":"ما صحة أن مواضع الصلاة تشهد لصاحبها؟","answer":"الجواب:\nمن فعل فلا بأس، ومن ترك فلا بأس، من مشى عن مكانه فلا بأس، صلى في مكانه فلا بأس، الأمر واسع، فيه حديث ضعيف.","link":"https://binbaz.org.sa/fatwas/22567/ما-صحة-ان-مواضع-الصلاة-تشهد-لصاحبها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/تغيير الأماكن للصلاة فيها.mp3","categories":["المساجد ومواضع السجود"]},{"id":2460,"question":"رجل عليه وتر وأراد أن يوتر بركعة واحدة فدخل المسجد ليلاً فهل هذه الركعة إذا أدّاها....؟","title":"حكم تحية المسجد لمَن أراد أن يوتر بواحدة","answer":"الجواب:\nلا، يصلي تحية المسجد أولًا ركعتين ثم يوتر، تحية المسجد ركعتان ثم يوتر بواحدة، السنة ركعتان تحية المسجد، ما زاد فليس من تحية المسجد، تطوع.","link":"https://binbaz.org.sa/fatwas/22589/حكم-تحية-المسجد-لمن-اراد-ان-يوتر-بواحدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/أراد أن يوتر بواحدة بعد أن دخل المسجد.mp3","categories":["قضايا المرأة","الوتر وقيام الليل","الحيض والنفاس","المساجد ومواضع السجود"]},{"id":2462,"question":"من جلس في المسجد ليحضر درسًا ونحوه ثم انتقض وضوؤه، هل يلزمه أن يعيد الوضوء؟","title":"هل يلزم الوضوء للجلوس بالمسجد؟","answer":"الجواب:\nلا ما يلزم، لكن إذا كان على جنابة لا يجلس في المسجد، أما إذا كان ما هو على جنابة ولو كان على غير طهارة يجلس يستمع الدرس والفائدة ولو كان على غير طهارة، إلا الجنب لا، الجنب لا يجلس حتى يغتسل.\nس: لو عاد يصلي ركعتين؟\nالشيخ: إذا رجع يصلي ركعتين سنة الوضوء وتحية المسجد.\nس: ...؟\nالشيخ: يدل على عدم الوجوب، يعني أن الصلوات الخمس هي الواجبة والبقية سنة، تحية المسجد وغيرها كلها سنة.\nس: ...؟\nالشيخ: ما يضر من جهة المناديل، ما يضر ما في شيء.","link":"https://binbaz.org.sa/fatwas/22591/هل-يلزم-الوضوء-للجلوس-بالمسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/جلس في المسجد وانتقض وضوؤه، فهل يلزمه أن يعيد الوضوء.mp3","categories":["المساجد ومواضع السجود"]},{"id":2463,"question":"إذا توضأ الجنب فهل يجوز له المكوث في المسجد؟","title":"هل يجوز للجنب المُكْث في المسجد إذا توضأ؟","answer":"الجواب:\nلا، ما يكفي، يُروى عن بعض الصحابة، لكن ما يكفي، الأحاديث الصحيحة تدل على أنه لا بدّ من غُسل، أما المرور لا بأس، عابر سبيل لا بأس، أما الجلوس لا.","link":"https://binbaz.org.sa/fatwas/22592/هل-يجوز-للجنب-المكث-في-المسجد-اذا-توضا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/إذا توضأ الجنب فهل يجوز له المكوث في المسجد.mp3","categories":["المساجد ومواضع السجود"]},{"id":2464,"question":"تعليق الصورة في المسجد؟","title":"ما حكم تعليق الصورة في المسجد؟","answer":"الجواب:\nالصورة ما تجوز، لا في المسجد ولا في البيت، حتى في البيت ما يجوز، سواء صورة إنسان وإلا حيوان.\nس: مثل الجرائد؟\nالشيخ: لا، ما يجوز إذا صار عنده يمسح رأسها ولا يعلقها في الجدار.\nس: بعضهم يعلّق صور الفقراء ويضع عليها ورقة: تصدقوا، وآيات تحث على الصدقة؟\nالشيخ: لا ما يجوز، يدعو للصدقة من دون صور، يدعو للصدقة على الفقراء من دون صور.","link":"https://binbaz.org.sa/fatwas/22593/ما-حكم-تعليق-الصورة-في-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/تعليق الصورة في المسجد.mp3","categories":["الصور والتصوير","المساجد ومواضع السجود"]},{"id":2655,"question":"هل يأثمون الذين يصلون في الحرم في أثناء الصلاة الناس يتكلمون ويتقهوون وصلاة التراويح مقامة، هل يأثمون؟","title":"حكم مَن يتكلمون بالمسجد أثناء صلاة التراويح","answer":"الجواب: لا، ما يأثمون، صلاة التراويح نافلة، ما هي فريضة، لكن بس لا يشوّشون على الناس، الواجب عليهم عدم التشويش، أما إذا كان ما حولهم أحد يشوّشون عليه؛ ما يخالف.","link":"https://binbaz.org.sa/fatwas/22791/حكم-من-يتكلمون-بالمسجد-اثناء-صلاة-التراويح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/صلاة التراويح مقامة والبعض يتكلمون ويتقهوون.mp3","categories":["المساجد ومواضع السجود","الوتر وقيام الليل"]},{"id":2678,"question":"بالنسبة للجلوس في المسجد إذا كان الإنسان جُنُبًا وما توضأ؟","title":"حكم جلوس الجُنُب في المسجد","answer":"الجواب: الصواب أنه لا يجلس حتى يغتسل؛ لقوله ﷺ: إني لا أُحِلُّ المسجد لحائض ولا جُنُب ويروى عن بعض الصحابة أنه كان يجلس وهو جُنُب، ولعله ما بلغهم الحديث، والله يقول سبحانه: وَلَا جُنُبًا إِلَّا عَابِرِي سَبِيلٍ [النساء:43] يعني مارًّا بالمسجد مرورًا.","link":"https://binbaz.org.sa/fatwas/22816/حكم-جلوس-الجنب-في-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم جلوس الجنب في المسجد.mp3","categories":["المساجد ومواضع السجود"]},{"id":2808,"question":"ما حكم الصلاة بالنعال؟","title":"ما حكم الصلاة بالنعال؟","answer":"الجواب: لا بأس بها، النبي ﷺ كان يصلي في نعليه.\nس: هل هي مخالفة لليهود؟\nالشيخ: نعم، قال: صلوا في نعالكم خالفوهم لكن على الفُرُش التي في المساجد أكثر الناس ما يبالون، يوسّخون المساجد، والنبي ﷺ صلى منتعلًا وصلى حافيًا، وبخصوص إذا كان يخشى توسيخ المساجد..... لأن أكثر الناس عامة ما يبالي.\nس: بالنسبة للحديث الأول يكون في نعال للحمام، ونعال للمسجد، أقدر يعني آخذ نعال للمسجد جديدة ألبسها نعال جديدة؟\nالشيخ: ما هو بلازم، بس إذا جاء يدخل المسجد يتأملها ويلاحظها لا بأس.\nس: ما في بأس يصلي الإنسان منتعلًا أو غير منتعل؟\nالشيخ: ما في بأس، إذا كان المسجد مفروشًا لا يوسّخه على الناس وينفّرهم من المسجد.","link":"https://binbaz.org.sa/fatwas/22957/ما-حكم-الصلاة-بالنعال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الصلاة بالنعال.mp3","categories":["المساجد ومواضع السجود"]},{"id":2969,"question":"هل الصلاة في مسجد به قبر، مسجد الحسين ومسجد السيدة زينب، حرام، وإذا حان وقت إقامة الصلاة وكان لا يوجد مسجد قريب فهل يمكن الصلاة فيه أم لا؟","title":"هل الصلاة في مسجد به قبر حرام؟","answer":"الجواب: المساجد التي فيها قبور لا يُصلى فيها، المساجد التي فيها قبور لعن الرسول ﷺ أهلها لعن الله اليهود والنصارى اتخذوا قبور أنبيائهم مساجد، وقال: ألا وإن من كان قبلكم كانوا يتخذون قبور أنبيائهم وصالحيهم مساجد، ألا فلا تتخذوا القبور مساجد فإني أنهاكم عن ذلك. ما وجد إلا مسجدًا فيه قبر يُصلي في بيته، يُدَوِّر مسجدًا ما فيه قبر، وإنْ كان كلها قبور يصلي في بيته... مع إخوانه الطيبين حتى يوجدوا مسجدًا سليمًا، حتى يَعْمُروا مسجدًا لأهل السنة سليمًا، أما المساجد التي فيها قبور لا يصلى فيها سواء في مصر وإلا في غيرها في أي مكان.\nس: بعض الناس يقول يصلي فيها ويبلغ؟\nالشيخ: لا، لا يصل فيها، يبلّغهم من دون صلاة معهم، لا يصل معهم يجيهم بعد الصلاة وإلا ينتظر إذا صلوا ويعلمهم أنه لا يصلى في المسجد، هذا منكر لا تصلوا في هذا المسجد، ويعلمهم، أما أنه يتابعهم في الباطل لا يتابعهم في الباطل.\nس: لو قال: هذا الأسلوب ينفّر؟\nالشيخ: لا، الذي فعله النبي ﷺ ما ينفّر، الذي ينفّر مخالفة السنة، هو الذي ينفر، أما موافقة السنة ما تنفّر.","link":"https://binbaz.org.sa/fatwas/23126/هل-الصلاة-في-مسجد-به-قبر-حرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الصلاة في مسجد به قبر.mp3","categories":["المساجد ومواضع السجود"]},{"id":3189,"question":"حجز المكان في المسجد هل يجوز؟","title":"حكم حَجْز المكان في المسجد","answer":"الجواب: لا ما يجوز، المجلس لمن سبق.\nس: إذا كان جالسًا ثم ذهب لعلّه يضع شيئًا يحفظ المكان؟ \nالشيخ: إذا رجع إلى مجلسه فهو أحق به، قام يتوضأ أو يأتي بحاجة.\nس: بالنسبة لحجز المكان عند الدرس بين الأذان والإقامة في العشاء الإنسان يأتي يتنفل ثم ينتظر درسا، وإذا جاء وقت الدرس يضع كتابًا أو شيئًأ في مكانه ويقرب إليه يستمع؟\nالشيخ: وهو في المسجد أو قام يتوضأ، ما يخالف.\nس: الحجز في غير المكان الذي يصلي فيه المصلي، مثل درس الأحد والأربعاء عند المكان كأن يضع الكتب ويخرج؟\nالشيخ: الظاهر ما ينبغي لمن سبق في الحلقة ومن سبق في الصف، إلا إذا سبق ثم عرض له عارض قام يأتي بكتاب أو قام يتوضأ وهو سابق، أما أنه يجيء يحطه ويروح؛ لا.","link":"https://binbaz.org.sa/fatwas/23352/حكم-حجز-المكان-في-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم حجز الأمكان في المسجد.mp3","categories":["المساجد ومواضع السجود"]},{"id":3257,"question":"مسجد فيه قبر ومعروف أن به قبر، وإمام المسجد يقول إنه ليس فيه قبر؟","title":"حكم المسجد الذي به قبر","answer":"الجواب: لا يُصلّى فيه حتى يُنْبَش، إذا كان القبرُ الأخيرَ؛ يُنْبَش القبر، أما إذا كان المسجد؛ يُهْدَم الجديد منه، هو الذي يزال. إن كان الجديد القبر يُنْبَش ويُزال، وإن كان الجديدُ المسجدَ؛ يهدم.","link":"https://binbaz.org.sa/fatwas/23421/حكم-المسجد-الذي-به-قبر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الحكم في المسجد الذي به قبر.mp3","categories":["المساجد ومواضع السجود"]},{"id":3387,"question":"يُصلى على المرأة الحائض في المسجد؟","title":"هل يُصَلّى على الحائض بالمسجد إذا ماتت؟","answer":"الجواب: نعم، لا بأس، النبي ﷺ صلى على النساء في المسجد ولم يسأل.","link":"https://binbaz.org.sa/fatwas/23555/هل-يصلى-على-الحاىض-بالمسجد-اذا-ماتت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يُصَلّى على المرأة الحائض في المسجد إذا ماتت.mp3","categories":["المساجد ومواضع السجود","زكاة النقدين","الصلاة على الميت","أحكام التعزية"]},{"id":3431,"question":"يضعون في المساجد سلالا للزبائل (المهملات والقمامة)، فيتمخطون، ويرمون فيها؟","title":"هل يجوز التنخم في سلال المهملات بالمسجد؟","answer":"الجواب: لا يضر إن شاء الله، المناديل التي فيها لا يضر إن شاء الله.\nس: في القبلة؟\nالشيخ: في أوان معينة لها مثل الكراتين معدة لها.\nس: أمام المصلي؟\nالشيخ: لا يضر إن شاء الله.","link":"https://binbaz.org.sa/fatwas/23605/هل-يجوز-التنخم-في-سلال-المهملات-بالمسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/التنخم في سلالا الزبائل في المسجد.mp3","categories":["المساجد ومواضع السجود"]},{"id":3432,"question":"لو قال (بالمسجد): مَنْ رأى فلانًا فليَدْعُه، هل يكون من إنشاد الضالة؟","title":"حكم إخبار الناس بالمسجد بالدعوة إلى الطعام","answer":"الجواب: لا ما هو من إنشاد الضالة، لو قال: تفضلوا، أو قال لفلان: قل لهم يتفضلون؛ ما في بأس.","link":"https://binbaz.org.sa/fatwas/23606/حكم-اخبار-الناس-بالمسجد-بالدعوة-الى-الطعام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل من إنشاد الضالة قول من رأى فلانًا فليدعه.mp3","categories":["المساجد ومواضع السجود"]},{"id":3433,"question":"العقيقة والوليمة تكون في المسجد؟","title":"حكم العقيقة والوليمة في المسجد","answer":"الجواب: إذا دعت الحاجة لا بأس، كما يأكل المعتكف، المعتكف يأكل في المسجد.","link":"https://binbaz.org.sa/fatwas/23607/حكم-العقيقة-والوليمة-في-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم العقيقة، والوليمة في المسجد.mp3","categories":["المساجد ومواضع السجود"]},{"id":3437,"question":"هل يجوز تخصيص مكان معين للصلاة في البيت؟","title":"حكم تخصيص مكان معين للصلاة في البيت","answer":"الجواب: لا بأس إذا عَيَّنَ مكانًا يصلي فيه طيب، يصلي فيه النوافل.","link":"https://binbaz.org.sa/fatwas/23612/حكم-تخصيص-مكان-معين-للصلاة-في-البيت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم تخصيص مكان معين للصلاة في البيت.mp3","categories":["المساجد ومواضع السجود"]},{"id":3447,"question":"في القرية بنوا مسجدًا وأنفقوا عليه أموالًا كثيرة ثم بعد أن انتهوا من بناء المسجد تبين لهم أنهم بنوه على قبر؛ فيقولون لو هدمنا المسجد بعد ما أنفقنا فيه أموالًا كثيرة يكون إسرافًا؟","title":"ما يفعل مَنْ بَنَوا مسجدًا ثم علموا أن تحته قبر؟","answer":"الجواب: لا، يُنبش القبر، هم ما قصدوا البناء عليه؟\nالطالب: أي نعم.\nالشيخ: ينبش القبر مثل ما نبش النبي ﷺ القبور.\nس: ولو كان المسجد بُني على القبر؟\nالشيخ: ولو، يُنبش القبر، ويُبعَد، ما قصدوا البناء على القبور.","link":"https://binbaz.org.sa/fatwas/23622/ما-يفعل-من-بنوا-مسجدا-ثم-علموا-ان-تحته-قبر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/بني المسجد، وبعد الانتهاء من البناء تبين لهم أنهم بنوه على قبر.mp3","categories":["المساجد ومواضع السجود"]},{"id":3451,"question":"لو حدث في بعض البلدان خسوف بعد الأنبياء يكون حكمه سواء؟","title":"حكم الدخول على مَنْ خُسف بهم بعد الأنبياء","answer":"الجواب: الظاهر يعمّ، هؤلاء معذّبون، مثل ما قال ﷺ: لا تدخلوا على هؤلاء المعذّبين أن يصيبكم ما أصابهم نسأل الله العافية.\nولكن يبتعد عنهم يخرج يصلي في محل آخر.\nس: للكراهة؟\nالشيخ: ظاهره المنع، التحريم، مراده هنا التحريم، هذا مراده.\nس: لكن ما يُقدر على الإطلاق التحريم مما ورد عن السلف؟\nالشيخ: على حسب الأدلة.\nس: الصلاة صحيحة...؟\nالشيخ: ظاهر النهي التحريم، عدم الصحة.","link":"https://binbaz.org.sa/fatwas/23626/حكم-الدخول-على-من-خسف-بهم-بعد-الانبياء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/لو حدث الخسوف بعد الأنبياء فهل يحرم الدخول عليهم.mp3","categories":["المساجد ومواضع السجود"]},{"id":3458,"question":"الذي يبني مسجدًا ويعمل فيه زخرفة، هل يأثم بذلك؟","title":"ما حكم زخرفة المسجد وبناء المنارة؟","answer":"الجواب: يبني بناءً محكمًا طيبًا ما فيه خطأ الناس، لكن يترك الزخرفة التي ما لها حاجة، إنما يعتني بالإتقان.\nس: المنارة تكلف مبالغ باهظة، يعني لو كان هذا يكون على حساب توسعة المسجد؟\nالشيخ: بس المنارة لا بدّ منها، حتى يبلّغ الناس.","link":"https://binbaz.org.sa/fatwas/23635/ما-حكم-زخرفة-المسجد-وبناء-المنارة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/بناء المسجد وزخرفته، وبناء المنارة.mp3","categories":["المساجد ومواضع السجود"]},{"id":3464,"question":"تبرع بقطعة أرض، وجمع الأموال لبناء المسجد، وبعد أن تم المسجد بنى فوق المسجد بيتًا، هل له ذلك؟","title":"حكم بناء منزل فوق المسجد","answer":"الجواب: إذا كان نوى هذا من الأصل، إذا كان نوى هذا... أسفلها مسجد، وأعلاها بيت؛ لا بأس. أما إذا كان لا، إنما أراد مسجدًا ثم طرأ عليه؛ لا، ما يبني على المسجد شيئًا سُكن....\nإذا خَبّرهم، أما إذا كان ما خبّرهم لا يبني عليه شيئًا، خلّصت المسجد تبع المسجد، أما إذا اتفق وإياهم جماعة يبنونه ويجعل ظهرًا له، يسمحوا له بظهر المسجد؛ لا بأس.","link":"https://binbaz.org.sa/fatwas/23641/حكم-بناء-منزل-فوق-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم بناء المنزل فوق المسجد.mp3","categories":["المساجد ومواضع السجود"]},{"id":3466,"question":"ما رأيكم بالبيع والشراء في المسجد؟","title":"حكم البيع والشراء في المسجد","answer":"الجواب: أما البيع والشراء؛ فلا يجوز في المسجد، يقول النبي ﷺ: إذا رأيتم من يبيع أو يبتاع في المسجد فقولوا لا أربح الله تجارتك.","link":"https://binbaz.org.sa/fatwas/23643/حكم-البيع-والشراء-في-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/البيع والشراء في المسجد.mp3","categories":["المساجد ومواضع السجود"]},{"id":3468,"question":"يجوز صيانة المسجد عمال الكفار؟","title":"ما حكم صيانة عمال غير مسلمين للمسجد؟","answer":"الجواب: لا، العمال لا يرون المساجد، لا يُؤمَنون، لكن لو دخلوا المسجد ليشربوا، أو يسمعوا فائدة؛ ما في بأس. أما أن يكونوا عمالًا لعمارة المسجد: لا؛ لأنهم لا يُؤمَنون في تعمير المسجد.","link":"https://binbaz.org.sa/fatwas/23645/ما-حكم-صيانة-عمال-غير-مسلمين-للمسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يجوز صيانة المسجد من عمال الكفار.mp3","categories":["المساجد ومواضع السجود"]},{"id":3469,"question":"تعليق الدعاية التجارية في المسجد؟","title":"هل يجوز تعليق الدعاية التجارية في المسجد؟","answer":"الجواب: تُعَلّق خارج المسجد حول الأبواب، من ظاهر.","link":"https://binbaz.org.sa/fatwas/23646/هل-يجوز-تعليق-الدعاية-التجارية-في-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/تعليق الدعاية التجارية في المسجد.mp3","categories":["المساجد ومواضع السجود"]},{"id":3473,"question":"لو أن الإمام فتح بابًا من بيته على المسجد: يُمنع مِنْ ذلك؟","title":"حكم فَتْحِ الإمام بابًا من بيته على المسجد","answer":"الجواب: لا حرج ، إذا كان بيته مجاورًا للمسجد.","link":"https://binbaz.org.sa/fatwas/23650/حكم-فتح-الامام-بابا-من-بيته-على-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الحكم لو أن الإمام فتح بابًا من بيته على المسجد.mp3","categories":["المساجد ومواضع السجود"]},{"id":3610,"question":"من يتولى إخراج المستمر على الثوم؟ الإمام...؟","title":"ما العمل مع من وُجد به رائحة الثوم بالمسجد؟","answer":"الجواب: الإمام والمسؤولون مثل المؤذن ومثل الهيئة، يتولاها إنسان ما يترتب على إخراجه مشاكل.\nس: إذا صلى رجل بجابنه آخر قد أكل الثوم، وتأذى، فهل يقطع الصلاة؟\nالشيخ: يُنصح يُنصح، يقال له: اذهب لا تصل مع الناس، الرسول أمرك أن تذهب اذهب إلى بيتك ولا تصل مع الناس ولا تأكل الثوم.\nس: لكن -أحسن الله إليك- إذا دخلوا في الصلاة وقد تأذى من هذه الرائحة وأثرت في خشوعه، فهل يقطع الصلاة ويذهب إلى مكان آخر؟\nالشيخ: هذا محل نظر، إذا استطاع ألا يقطعها لا يقطعها؛ لأنها وجبت عليه، دخل فيها ووجبت عليه، وجب عليه إتمامها، إذا استطاع أن يملك نفسه يكمل.\nس: إن لم يستطع له أن يقطع ويذهب إلى مكان آخر؟\nالشيخ: إذا تيسر له قبل الإقامة.","link":"https://binbaz.org.sa/fatwas/23792/ما-العمل-مع-من-وجد-به-راىحة-الثوم-بالمسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من يتولى إخراج آكل الثوم من المسجد.mp3","categories":["المساجد ومواضع السجود"]},{"id":3618,"question":"إذا دخل وقت الأذان فهل الأفضل له أن ينتظر الأذان ثم يصلي تحية المسجد أم يشرع في تحية المسجد؟","title":"هل تُؤجل تحية المسجد للترديد مع المؤذن؟","answer":"الجواب: الأفضل يجمع بين الأمرين: يجيب المؤذن ثم يصلي.","link":"https://binbaz.org.sa/fatwas/23800/هل-توجل-تحية-المسجد-للترديد-مع-الموذن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يصلي تحية المسجد أو يردد الأذان.mp3","categories":["المساجد ومواضع السجود","الأذان والإقامة"]},{"id":3907,"question":"الصلاة على وسادة فيها نقش صلبان؟","title":"حكم الصلاة على وسادة فيها نقش صلبان","answer":"الجواب: أما الصلبان تنقض، كان النبي ﷺ إذا رأى شيئًا فيه تصليب نقضه، كما قالت عائشة. يُزال بجعل شيء عليه أو نقض صورته حتى لا يكون كهيئة الصليب في قطع شيء منه؛ لقول عائشة: \"ما رأى النبي شيئًا في البيت فيه تصليب إلا قضبه\"، وفي اللفظ الآخر: \"إلا نقضه\".؛لأن صورة الصليب معبود من دون الله.","link":"https://binbaz.org.sa/fatwas/24124/حكم-الصلاة-على-وسادة-فيها-نقش-صلبان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الصلاة على وسادة فيها نقش صلبان.mp3","categories":["المساجد ومواضع السجود"]},{"id":3950,"question":"من ناحية صلاة النافلة، كيف التوفيق بين أن الصلاة النافلة في البيت وبين التبكير للمسجد؟","title":"هل الأفضل التبكير للمسجد أم التنفل في البيت؟","answer":"الجواب: أفضل صلاة المرء في بيته إلا المكتوبة، صلاة الضحى والتهجد والرواتب كلها في البيت أفضل، وإذا صلاها في المسجد فلا بأس.\nس: الرواتب القبلية هل الأولى أن يصليها في المسجد أم في البيت؟\nالشيخ: كله عام، الحديث عام، إذا صلاها في البيت ثم جاء يصلي تحية المسجد، وإذا أراد التبكير قصده التبكير هذا له وجه يصليها في المسجد؛ لأجل إدراك الصف الأول أو في قرب الإمام، الأمر فيه سعة، فإن هذا مقصد صالح في قرب الإمام أو في الصف الأول؛ لأن بعض المساجد قد تمتلئ في وقت مبكر لكثرة روادها، فإذا تقدم مع الأذان أو قبل الأذان ليدرك الصف الأول فلعله أفضل من هذه الحيثية؛ لأجل المسابقة للصف الأول، أما البعدية فالأفضل في البيت.","link":"https://binbaz.org.sa/fatwas/24173/هل-الافضل-التبكير-للمسجد-ام-التنفل-في-البيت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/التوفيق بين التبكير للمسجد والصلاة النافلة في البيت.mp3","categories":["المساجد ومواضع السجود"]},{"id":4261,"question":"أحد الصحابة قال عن ابن عباس أنه قال: لا أصلي فيها لأجل الصور، يعني الكنائس؟","title":"حكم الصلاة في الكنائس","answer":"الجواب: هو رخّص فيها عمر للحاجة، لأجل يحتاج المسلمون والجنود الكنائس إما لمطر وإما لبرد وإما لغير ذلك، فلا بأس عند الحاجة، وإلا فلا يأتونها.","link":"https://binbaz.org.sa/fatwas/24531/حكم-الصلاة-في-الكناىس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الصلاة في الكنائس.mp3","categories":["المساجد ومواضع السجود"]},{"id":4302,"question":"الصلاة في المكان الذي به صورة معلقة أو تلفاز مشغّل؟","title":"حكم الصلاة في مكان به صورة أو تلفاز","answer":"الجواب: عند الحاجة تصح، لكن تركها أولى، لكن إن كان ما هناك حاجة لا يصلي في المحل هذا، أما إذا كانت دعت الحاجة مثل ما رخص عمر في الصلاة في الكنائس عند الحاجة.  إذا دعت الحاجة إلى محل يصلي فيه لا بأس إن شاء الله، مثل إنسان حضرته الصلاة في محل فيه صورة ولا يمكن الخروج منه، أو إنسان مريض في المحل الذي فيه صورة ما له حيلة، يعني الشيء الذي تدعو له الضرورة، وإلا الأولى والأفضل الخروج عن التشبه بالنصارى واليهود.","link":"https://binbaz.org.sa/fatwas/24576/حكم-الصلاة-في-مكان-به-صورة-او-تلفاز","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الصلاة في المكان الذي به صورة معلقة أو تلفاز مشغل.mp3","categories":["المساجد ومواضع السجود"]},{"id":4312,"question":"ما حكم الصلاة إذا كان القبر موجودًا في وسط المسجد؟","title":"ما حكم الصلاة إذا كان القبر في وسط المسجد؟","answer":"الجواب: ما تصح الصلاة، الرسول ﷺ قال: لعن الله اليهود والنصارى اتخذوا قبور أنبيائهم مساجد جئت بلدًا مسجدها فيه قبور؛ لا تصلي فيه حتى يُنبش. إلا إذا كان القبر هو الأول والمسجد هو الذي بدئ فيه يُهدم المسجد، على الدولة الإسلامية أن تهدم المسجد. أما إن كان القبر هو الجديد والمسجد قديم؛ فالواجب نبش القبر ونقله إلى محل آخر.\nس: وضع قبر النبي ﷺ في هذه الحالة هل فيه استثناء؟\nج: لا، هو ما هو في المسجد، هذا في بيت عائشة، الغلط من إدخال الوليد له لما أدخله في المسجد لما وسعوا المسجد صار شبهة لضعفاء البصيرة، الذم على الذي أدخله.\nس: الذي صلى في مسجد وفيه مقبرة ولا يعلم هل يعيد الصلاة؟\nج: يعيدها نعم.\nس: أنا صليت من كم سنة ما أدري عنها؟\nج: تعيدها.\nس: ما أدري كم صلاة؟\nج: حسب ظنك.\nس: كيف الترتيب؟\nج: الترتيب كل يوم لحاله على حسب ظنه.","link":"https://binbaz.org.sa/fatwas/24586/ما-حكم-الصلاة-اذا-كان-القبر-في-وسط-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الصلاة في المسد الذي فيه قبر.mp3","categories":["المساجد ومواضع السجود"]},{"id":4320,"question":"إذا المرأة أرادت أن تصلي ركعتين في الروضة لا تُمنع؟","title":"هل تمنع المرأة من الصلاة في الروضة؟","answer":"الجواب: الروضة مشتركة بين الرجال والنساء تشوف الوقت اللي الرجال فيه قليل وتصلي فيها لا بأس؛ لكن لا يكون مع زحمة الرجال، تشوف الوقت المناسب اللي يكون فيه سعة، والحمد لله.","link":"https://binbaz.org.sa/fatwas/24594/هل-تمنع-المراة-من-الصلاة-في-الروضة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/صلاة المرأة في الروضة.mp3","categories":["قضايا المرأة","المساجد ومواضع السجود"]},{"id":4352,"question":"بعض النساء تعودت أن تصلي صلاة التراويح في أيام رمضان في المسجد فإذا أتتها الدورة تقول: أريد أن أذهب وأجلس في طرف المسجد؛ كي تراجع مع الإمام، وتتعلم القراءة الصحيحة، هل لها ذلك؟","title":"حكم مكث الحائض في المصلى لسماع التراويح","answer":"الجواب: إذا كان في محل خارج المسجد ما يخالف، عند الباب، خارج المسجد، ما في بأس.\nس: في نفس مصلى النساء؟\nج: إذا كان في المسجد لا، إذا كان مصلاهن من المسجد لا.","link":"https://binbaz.org.sa/fatwas/24628/حكم-مكث-الحاىض-في-المصلى-لسماع-التراويح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة في صلاة المرأة التراويح في المسجد.mp3","categories":["المساجد ومواضع السجود","الوتر وقيام الليل"]},{"id":4390,"question":"أخذ الزينة للمسجد للاستحباب أو للوجوب؟","title":"هل أخذ الزينة للمسجد مستحب أم واجب؟","answer":"الجواب: المعروف للاستحباب، الواجب السترة بس.","link":"https://binbaz.org.sa/fatwas/24667/هل-اخذ-الزينة-للمسجد-مستحب-ام-واجب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم أخذ الزينة للمسجد.mp3","categories":["المساجد ومواضع السجود"]},{"id":4419,"question":"الأفضل الصلاة في الأرض أو على الفُرُش؟","title":"هل الصلاة على الأرض أفضل من الفُرُش؟","answer":"الجواب: الأصل الأرض، هو الأفضل، الأرض أفضل، ولكن لما تنعَّم الناسُ وتغيّرت أحوالهم احتاجوا إلى الفراش؛ حتى لا يتركوا الصلاةَ في الجماعة.","link":"https://binbaz.org.sa/fatwas/24696/هل-الصلاة-على-الارض-افضل-من-الفرش","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما الأفضل الصلاة في الأرض أو على الفرش.mp3","categories":["المساجد ومواضع السجود"]},{"id":4421,"question":"معاطن الإبل ومراحها...، المعاطن شيء، والمراح شيء، يُصلّى في المراح؟","title":"حكم الصلاة في معاطن الإبل ومراحها","answer":"الجواب: كثير  من المعاطن، معاطنها ما تقف عند الماء، إذا شربت وقفت حول الماء وعطنت، قال: هذه تُسمَّى معاطن، وألحق بها بعضُ أهل العلم ما تكون فيه، تريح فيه، وتُقيم فيه، وأن يُسمَّى معطنًا؛ لأنها تجلس فيه، وتُقيم فيه، المهم هو من جنس المعطن الذي عند الماء، فلا ينبغي... لا في مراحها، ولا في معاطنها عند الماء.","link":"https://binbaz.org.sa/fatwas/24698/حكم-الصلاة-في-معاطن-الابل-ومراحها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الصلاة في معاطن الإبل ومراحها.mp3","categories":["المساجد ومواضع السجود"]},{"id":4471,"question":"إذا كان دخولُ المسجد لأجل حاجةٍ؛ كأذانٍ أو غير ذلك؟","title":"حكم المٌكث في المسجد للجنب والمحدث","answer":"الجواب: لا بأس، لكن المؤذن يُقيم لمدةٍ طويلةٍ يُشبه الجلوس، فينبغي له ألا يأتي إلا وهو مُغتسل، إلا إذا كان الأذانُ في خارج المسجد، كما كان في المنارة خارج المسجد، أو في بيتٍ خارج المسجد، فالأمر سهل، لكن كونه يُؤذن في منارةٍ في داخل المسجد تابعة للمسجد فالأحوط ألا يفعل ذلك، وإن كان قائمًا وليس بجالس، لكن قيامه يُشبه الجلوس؛ لأنه قيام له قيمة، فالأحوط له أيضًا.  ثم يُسنُّ له أن يكون على طهارةٍ، المؤذن يُستحب له أن يكون على طهارةٍ، فالأولى به أن يغتسل قبل ذلك، لكن لو ضاق الوقتُ عليه يُرجى ألا يكون عليه شيء؛ لأنه ليس بجلوسٍ، وقوف عارض، لكن الأحوط له أن يجتهد، وأن يتقدم بالغسل ويحتاط.","link":"https://binbaz.org.sa/fatwas/24749/حكم-المكث-في-المسجد-للجنب-والمحدث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة في دخول الجنب إلى المسجد لحاجة أو عابر سبيل.mp3","categories":["المساجد ومواضع السجود"]},{"id":4527,"question":"إذا كانت السجادة التي يُصلَّى عليها فيها صورة؟","title":"هل تجوز الصلاة على سجادة بها صورة؟","answer":"الجواب: لا يضرّ، لكن فقط يُخشى التَّشويش، مثل: النقوش، لو كان المصلَّى سادة أولى وأفضل حتى لا يشوش.","link":"https://binbaz.org.sa/fatwas/24807/هل-تجوز-الصلاة-على-سجادة-بها-صورة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/السجادة التي يُصلَّى عليها فيها صورة.mp3","categories":["المساجد ومواضع السجود"]},{"id":4540,"question":"الصلاة على المنزل أو على البلاط؟","title":"هل تصح الصلاة على البلاط والرمل ونحوهما؟","answer":"الجواب: ما في بأس، على البلاط، وعلى الجبس، وعلى التراب، وعلى الرمل، وعلى الحصاة، ولو كان قد طُبخ بالنار ما يضرّ.","link":"https://binbaz.org.sa/fatwas/24820/هل-تصح-الصلاة-على-البلاط-والرمل-ونحوهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الصلاة على المنزل أو على البلاط.mp3","categories":["المساجد ومواضع السجود"]},{"id":4541,"question":"اتّخاذ السجادة في البيوت ولا يُصلي إلا عليها؟","title":"حكم اتّخاذ السجادة في البيوت للصلاة عليها","answer":"الجواب: ما في بأس إذا كان لأجل الحرص على الطهارة؛ لأنَّ المحل لا يُؤمن، فهذا أسلم له، لا بأس.\nس: والتي يجهل حالها مثل الشعر..؟\nج: الأصل الطَّهارة إذا كان يجهلها، الأصل الطهارة لا بأس، إلا إذا علم، الأمور ثلاثة: طاهر معلوم، ونجس معلوم، وشيء مجهول، فتُصلي على الطاهر وعلى المجهول، أما معلوم النَّجاسة فلا يُصلَّى عليه.\nس: إذا كانت السجادة فيها بعض الصور ..؟\nج: تصح الصلاة، لكن الأولى أن تكون سادةً ما فيها شيء يُشوش عليه، لا خطوط، ولا نقوش، ولا صور، وإلا الصورة في الأرض التي توطأ تجوز: كالبساط ونحوه، لكن إذا كانت سادةً سليمةً يكون أسلم وأفضل.\nس: صور ذوات الأرواح في المكان الذي يُصلي عليه ويسجد عليه؟\nج: ما يضرّ؛ لأنها ممتهنة، النبي ﷺ في قصة عائشة قالت: \"فاتَّخذنا منها وسادتين يرتفق بها النبيُّ ﷺ\"، وفي حديث أبي هريرة قال له جبريل: ومُرْ بالستر أن يتّخذ منه وسادتان مُنتبذتان تُوطآن. التي فيها تصاوير يعني.\nس: اتِّخاذ السجاجيد في المساجد المفروشة؟\nج: ما أعرف فيه شيئًا، مثل: بقية البسط.","link":"https://binbaz.org.sa/fatwas/24821/حكم-اتخاذ-السجادة-في-البيوت-للصلاة-عليها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم اتّخاذ السجادة في البيوت للصلاة عليها.mp3","categories":["المساجد ومواضع السجود"]},{"id":4544,"question":"الصلاة إلى القبور باطلة؟","title":"حكم الصلاة إلى القبور وفي قارعة الطريق","answer":"الجواب: نعم، باطلة، باطلة، وزيادة...\nس: بالنسبة للصلاة في قارعة الطريق؟\nج: جاء فيها هذا الحديث الضعيف، لكن تجنبها أولى، وجاء في بعض الروايات الأخرى تجنب... على قارعة الطريق؛ لأنها مأوى الهوام، فالمكث فيها والصلاة فيها ينبغي تركه؛ لأنها خطرة.\nس: معنى قارعة الطريق؟\nج: محل قرع الأقدام، محل السير... الجوانب أمرها سهل، إذا كان الطريق له جوانب متسعة... فيها فلا بأس.","link":"https://binbaz.org.sa/fatwas/24824/حكم-الصلاة-الى-القبور-وفي-قارعة-الطريق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الصلاة إلى القبور وفي قارعة الطريق.mp3","categories":["المساجد ومواضع السجود"]},{"id":4546,"question":"الصلاة في المسجد الذي يكون فيه قبر، وكذلك حكم الصلاة في المسجد الذي يكون في قبلته قبر، ولكن بينه وبينه حائل وجدار؟","title":"حكم الصلاة في مسجد في وسطه أو قبلته قبر","answer":"الجواب: الصلاة تصحّ، إذا كان القبر خارج المسجد تصحّ، إلا إذا كان المسجد فيه قبور ما تصحّ، ولو قبرًا واحدًا.\nس: إذا كان في فناء المسجد؟\nج: إذا كان تبع المسجد لا يُصلَّى فيه، إذا كان تابعًا للمسجد، أما إذا كان خارج المسجد وليس في حكم المسجد فلا يضرّ.\nس: يعني إذا كان الحائل موجودًا سواء كان في قبلته أو ..؟\nج: عن يمين أو شمال أو أمام أو خلف، إذا كان خارج المسجد صار صحيحًا.\nس: إذا كان في شيء المسجد طبعًا في القبلة، والقبر في شرق المسجد عند دورة المياه؟\nج: خارج المسجد يعني؟\nالطالب: نعم خارج المسجد.\nالشيخ: ما يضرّ.\nس: ولو كان المسجد بُني على القبر مع العزل، يعني معزولًا، ولكن المسجد بُني على القبر؟\nج: إذا كان خارج المسجد ما يكون المسجد فيه قبور.\nس: لكن المسجد مبنيٌّ عليه؟\nج: ... اتّخاذ المساجد على القبور...، ولا يتّخذ عليه إلا إذا كان في داخله.\nس: لكن ما بُني إلا من أجله، يعني: وُضع القبر ثم جهز المسجد بعدها؟\nج: ما دام خارج الذي يظهر لي أنه... حكمه... إزاحة القبر إذا تيسر ونقل رفاته إلى المقبرة يكون هذا أبعد من الشُّبهة، يُنقل القبر ويُزال.\nس: لكنه هو الأصل ولو أزلناه هو الأصل؟\nج: ينبغي إزالته، ولو الأصل، ينبغي إزالته.\nس: لو كان هو العارض..؟\nج: ينبغي إزالته... يُبعد.","link":"https://binbaz.org.sa/fatwas/24826/حكم-الصلاة-في-مسجد-في-وسطه-او-قبلته-قبر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الصلاة في المسجد الذي يكون في وسطه أو في قبلته قبر.mp3","categories":["المساجد ومواضع السجود"]},{"id":4547,"question":"لو فقد الإنسانُ مثلًا ساعةً أو قلمًا في المسجد، هل يسأله في المسجد في الداخل؟","title":"ماذا يفعل من فقد ضالة في المسجد؟","answer":"الجواب: ظاهر العموم لا؛ لأنَّ النهي عن نشد الضَّالة يعمّ غير الضَّالة، الضَّوال في الحيوانات وغير الحيوانات، حكمه حكمها: مَن وجد عباءتي؟ مَن وجد كتابي؟ مَن وجد نعالي؟ يكون مثل الضَّالة، لم يُبْنَ لهذا.\nس: أضاعه في نفس المسجد؟\nج: الظاهر [أنه] يقف عند الباب ويقول: مَن وجد كتابي؟ أو: مَن وجد عباءتي؟ أخذًا بالعموم.","link":"https://binbaz.org.sa/fatwas/24827/ماذا-يفعل-من-فقد-ضالة-في-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/إنشاد الضالة في المسجد.mp3","categories":["المساجد ومواضع السجود"]},{"id":4548,"question":"الدروس وكذا إعلانها في المساجد؟","title":"حكم إعلان الدروس والمحاضرات في المساجد","answer":"الجواب: الظاهر لا بأس، ما أعلم يعني، قد يُقال: إنَّ هذا –يعني- شيء يتعلق بالمسجد، لكن لو جُعل خارج المسجد يكون أحوط؛ لعموم النَّهي عن النَّقش في المساجد، وعن الكتابة في المساجد، فقد يعمّها؛ وسدًّا للباب أيضًا .....","link":"https://binbaz.org.sa/fatwas/24828/حكم-اعلان-الدروس-والمحاضرات-في-المساجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/إعلان الدروس والمحاضرات في المساجد.mp3","categories":["المساجد ومواضع السجود"]},{"id":4549,"question":"بعض السائلين قد يحتاج الإنسانُ إلى الصرف معهم في المسجد؟","title":"حكم صرف المال بالمسجد لإعطاء السائل","answer":"الجواب: ج: الأقرب والله أعلم والأحوط... نوع من البيع، لكن قد يُقال إنه ليس من التجارة، وإنما أخذ ذلك لإحسانه للمساكين، والله أعلم، قد يكون الخروج يفوّت المصلحة، قد يُقال هذا.. لا أربح الله تجارتك، وهو ما أراد التجارة، ولا أراد إلا الإحسان إلى الفقير، هذا من باب الاحتياط، أو يأتي وقد هيَّأ نفسه ووضع في جيبه ما يحتاج إليه؛ يكون أبعد عن الذي يعمّ عن البيع والشِّراء.","link":"https://binbaz.org.sa/fatwas/24829/حكم-صرف-المال-بالمسجد-لاعطاء-الساىل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة في الصرف من السائلين في المسجد.mp3","categories":["المساجد ومواضع السجود"]},{"id":4550,"question":"مكوث النساء في الحرم الآن؟","title":"حكم مكوث النساء في الحرم","answer":"الجواب: النساء كذلك إن كان ما في ضرر، مع التَّستر ومع البُعد عن الفتنة فلا بأس، كما في قصة سعد بن معاذ لما أُصيب في أكحله يوم الخندق ضرب عليه النبيُّ ﷺ خيمةً في المسجد، وكان في المسجد أيضًا امرأة لها خيمة، عندها خيمة في المسجد، ما لها أهل، وأقرَّها النبيُّ في المسجد عليه الصلاة والسلام.  فإذا دعت الحاجةُ إلى ذلك فلا بأس، لكن تكون في محلٍّ مستورٍ .....، وكان بعض نساء النبي ﷺ يعتكفن في المسجد في خيام مستورة، فإذا كان وجود المرأة في المسجد لا ضررَ فيه كخيمةٍ خاصةٍ ..... خاصة، ودعت الحاجةُ إلى ذلك فلا حرج في ذلك .......، لكن لا بد [من] الحذر من إيذاء المسجد، حتى ولو كان بعض الناس يُقيم الأعياد في المساجد، أدركت هذا في هذه البلاد وفي غيرها، يوم العيد يُقدِّمون الطعام في المسجد؛ لأنهم ما عندهم مساكن تتسع للناس .....، فالمسجد أوسع، فإذا جعلوه للطعام وأكلوا فلا بأس عند الحاجة، لكن إذا ..... ألا يقع في المسجد فيه من الأكل.","link":"https://binbaz.org.sa/fatwas/24830/حكم-مكوث-النساء-في-الحرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مكوث النساء في الحرم.mp3","categories":["قضايا المرأة","الوتر وقيام الليل","الحيض والنفاس","المساجد ومواضع السجود"]},{"id":4609,"question":"إذا كان المسجد قريبًا من البيت، والرجل يذهب إلى الأبعد طلبًا للأجر ........؟","title":"حكم الصلاة في المسجد البعيد طلبًا للأجر","answer":"الجواب: لا حرج فيه إن شاء الله، إذا كان ما فيه مضرَّة، أما إذا كان يُثبِّط غيره عن الصلاة في المسجد أو يُؤثر عليهم أو يترتب على ذلك شيءٌ من المضار فيُصلي في المسجد الذي جنبه، وأما إذا كان ما فيه مضرة، أو ذهب لمسجدٍ آخر لأجل درسٍ، أو لأجل حُسن قراءة الإمام والانتفاع بقراءة الإمام لمصلحةٍ شرعيةٍ؛ فلا بأس.","link":"https://binbaz.org.sa/fatwas/24898/حكم-الصلاة-في-المسجد-البعيد-طلبا-للاجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم ترك المسجد القريب والذهاب إلى الأبعد طلبًا للأجر.mp3","categories":["المساجد ومواضع السجود"]},{"id":4610,"question":"صلاة المرأة في المسجد الحرام أفضل من صلاتها في بيتها؟","title":"هل صلاة المرأة في الحرم أفضل من بيتها؟","answer":"الجواب: بيتها أفضل، وإن صلَّت في المسجد الحرام متأدبةً بدون تجمُّلٍ ولا طيبٍ ولا شيءٍ من المحظورات فلا بأس.","link":"https://binbaz.org.sa/fatwas/24899/هل-صلاة-المراة-في-الحرم-افضل-من-بيتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/أيهما أفضل للمرأة صلاتها في المسجد الحرام أم في بيتها.mp3","categories":["قضايا المرأة","الوتر وقيام الليل","الحيض والنفاس","المساجد ومواضع السجود"]},{"id":4868,"question":"الصلاة على السجاد التي فيها صور؟","title":"هل تصح الصلاة على السجاد التي فيها صور؟","answer":"تصح، لكن ينبغي ألا يُصلي عليها، ولا التي فيها نقوش؛ لأنها تشغله، وإلا السجاد يُوطأ عليه، ولا يضرّ، لكن كونه يُصلي على محلٍّ سادة -ما فيه صور ولا نقوش- أفضل؛ حتى لا يتشوش في صلاته.\nس: المقصود بالنُّقوش يعني الألوان: الأحمر والأصفر؟\nج: النقوش التي قد تُشوش عليه، ويُفكر فيها، مثلما قال النبيُّ ﷺ في قصة الخميصة التي صلَّى فيها.","link":"https://binbaz.org.sa/fatwas/25344/هل-تصح-الصلاة-على-السجاد-التي-فيها-صور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الصلاة على السجاد التي فيها صور.mp3","categories":["المساجد ومواضع السجود"]},{"id":4945,"question":"لا يُعيد الصلاة إذا صلى في القبر؟","title":"هل يُعيد الصلاة مَن صلى في القبر؟","answer":"الجواب: الصواب أنها تُعاد؛ لأنه ما هو محل صلاة الرسول ﷺ نهى، حذر من هذا، والأصل في هذا البطلان.","link":"https://binbaz.org.sa/fatwas/27421/هل-يعيد-الصلاة-من-صلى-في-القبر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يعيد الصلاة من صلى في القبر.mp3","categories":["المساجد ومواضع السجود"]},{"id":4969,"question":"يجوز إقامة الأفراح والأعراس في المساجد؟","title":"حكم إقامة الأفراح والأعراس في المساجد","answer":"الجواب: لا، الشيء الذي يتعلق بالجهاد؛ لأن لعب الحبشة من الجهاد بالنبل، بالدَّرَق.\nأما ما يتعلق بالأفراح قد يكون فيه شَرٌّ في المسجد، قد يكون فيه فساد.","link":"https://binbaz.org.sa/fatwas/27769/حكم-اقامة-الافراح-والاعراس-في-المساجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم إقامة الأفراح والأعراس في المساجد.mp3","categories":["المساجد ومواضع السجود"]},{"id":5036,"question":"حكم الدخول إلى المساجد بعلبة الدخان؟","title":"ما حكم الدخول إلى المسجد بعلبة الدخان؟","answer":"الجواب: إذا كان مستورًا فعليه فقط أن يتجنّبه، أمَّا إذا كانت هناك رائحة تُؤذي الناس فلا يجوز له، كالبصل والكُرَّاث وأشد وأقبح، إذا كانت الرائحة ظاهرةً تُؤذي الناس، وصاحب الكُرَّاث كان يُخْرَج من المسجد.","link":"https://binbaz.org.sa/fatwas/28969/ما حكم-الدخول-الى-المسجد بعلبة-الدخان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما حكم الدخول إلى المسجد بعلبة الدخان؟.mp3","categories":["المساجد ومواضع السجود"]},{"id":5085,"question":"هذا سائل يقول يا فضيلة الشيخ عبد العزيز، السلام عليكم ورحمة الله وبركاته، وبعد:يوجد لدينا مسجد تقام الصلاة فيه جماعة وجُمُعة؛ ولكن يوجد فيه قبور حول المسجد في مقدمته ومؤخرته، والفرق بين المسجد والقبور نحو ستة أمتار فقط، علمًا أن المسجد بُني قبل وضع القبور، فهل تصح الصلاة في هذا المسجد؟","title":"حكم الصلاة في مسجد بمقدمته ومؤخرته قبور","answer":"الجواب: نعم، تصح الصلاة فيه، ولو كان حوله قبور، إذا كان المسجد قائمًا، ووُضعت حوله القبور عن يمينه أو شماله أو أمامه أو خلفه هذا لا يضر، وقد كان الناس فيما مضى يدفنون حول البلاد من الخوف والفتن والحروب، كانوا يدفنون حول مساجدهم، يخرج... المسجد، ويدفن حول المسجد. أما الآن فقد وسَّع الله ويسَّر، فينبغي إبعادها عن المساجد؛ حتى لو دعت الحاجة إلى توسيع المسجد وسِّع المسجد، وحتى لا يظن جاهل أن للدفن حول المساجد سرًّا أو قصدًا. فينبغي أن تكون المقابر بعيدة عن المساجد؛ حتى لا يظن ظان خلاف الحق، أو حتى لا تدعو الحاجة إلى التوسعة، فيكون وجود القبور مانعًا من ذلك، أو داعيًا إلى نبشها، ونقلها مرة أخرى. المقصود أن القبور التي حول المساجد لا تمنع من الصلاة في المساجد، إنما المحرم أن تُبنى المساجد على القبور، وأن تتخذ القبور مساجد، هذا هو الذي نهى عنه النبي ﷺ، يقول ﷺ: لعن الله اليهود والنصارى اتخذوا قبور أنبيائهم مساجد، وقال ﷺ: ألا وإن من كان قبلكم كانوا يتخذون قبور أنبيائهم وصالحيهم مساجد، ألا فلا تتخذوا القبور مساجد، فإني أنهاكم عن ذلك . فلا يجوز أن يُبنى على القبور مساجد، ولا يُصلى حولها ولا بينها، ولا يُدفن الميت في المسجد، لا، كل هذا لا يجوز، يجب أن تُدفن الموتى بعيدًا عن المساجد، وألا تقام المساجد على القبور، هكذا نهى الرسول ﷺ عن ذلك؛ ولكن متى وجد قبور جوار المسجد لم تمنع من الصلاة فيه.","link":"https://binbaz.org.sa/fatwas/29987/حكم-الصلاة-في-مسجد-بمقدمته-وموخرته-قبور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 04.mp3","categories":["المساجد ومواضع السجود"]},{"id":5097,"question":"هذا سائل يقول: سماحة الشيخ عبد العزيز، السلام عليكم ورحمة الله وبركاته، وبعد:أنا أحد المدربين في كلية عسكرية في لعبة الكاراتيه، وهي لعبة الدفاع عن النفس، والكلية لا يوجد فيها مكان مخصص للتدريب، فهل يصح أن أقوم بالتدريب في مكان يُبنى على أساس أنه مسجد، ولم يكتمل بعد؟","title":"هل يجوز التدريب في مكان بناء مسجد؟","answer":"الجواب: ما دام أن هذا التدريب ينفع في سبيل الله وفي جهاد أعدائه فلا بأس، والرسول ﷺ أقر الحبشة، ولعبوا في المسجد بالدَّرَق والحراب، يدورون في المسجد بالدرق والحراب. فإذا كانت اللعبة يُستعان بها على الدفاع على النفس، وجهاد الأعداء، وتوقي شرهم، فلا بأس في المسجد الذي فيه رحبة، وفيه سعة، حتى يوجد مكان آخر يكون فيه اللعب، بشرط ألا يكون هذا اللعب مما يتأذّى به المسجد من تخريب أو بول أو غير ذلك.","link":"https://binbaz.org.sa/fatwas/30005/هل-يجوز-التدريب-في-مكان-بناء-مسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 22.mp3","categories":["المساجد ومواضع السجود"]},{"id":5167,"question":"يقول: يوجد بعض الإخوان ينفِّرون من الصلاة في مسجد ابن عباس في الطائف، ويقولون إنه مبنيٌّ على القبور، فما رأيكم؟","title":"ما حكم الصلاة في مسجد ابن عباس بالطائف؟","answer":"الجواب: هذا غلطٌ وجهلٌ، فمتى نُبشت القبور لمصلحة المسلمين جازت الصلاةُ في محلِّها، فلا بأس أن يُصلَّى في مسجد ابن عباس؛ لأنها القبور نُبشت لمصلحة المسلمين، فلا حرج في ذلك، والنبي ﷺ بنى مسجده في محلِّ قبورٍ، فمسجد النبي ﷺ كانت فيه قبور، فأمرهم بنبشها وإزالتها، وكانت فيه حُفر وخربات فأزالها، وكان فيه نخلٌ فقُطِعَ، ثم بُني المسجد. فالمقصود أنه متى نُقلت القبور للمصلحة؛ فلا بأس.","link":"https://binbaz.org.sa/fatwas/30092/ما-حكم-الصلاة-في-مسجد-ابن-عباس-بالطاىف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 116.mp3","categories":["المساجد ومواضع السجود"]},{"id":5578,"question":"إذا كان المؤذن جنبًا فهل يدخل المسجد ليُؤذن وهو واقف ثم يخرج؟","title":"هل يجوز دخول الجُنُب المسجد للأذان؟","answer":"الجواب: ما ينبغي الوقوف، هذا يُشبه الجلوس، وقوف طويل، فالأحوط ألا يدخل إلا بوضوءٍ، لكن لو فعل صحَّ؛ لأنه ليس بجالسٍ، لا يجلس، قد يُشبه العابر من بعض الوجوه، لكن طول قيامه يُشبه الجلوس، فالأحوط له أن يتأهَّب قبل الأذان، يغتسل، هذا هو الأحوط. س: ليس شرطًا الوضوء في الأذان؟ ج: ليس بشرطٍ، الصحيح ليس بشرطٍ؛ لأنَّ الحديث ضعيف، ليس بشرطٍ.[1]","link":"https://binbaz.org.sa/fatwas/31531/هل-يجوز-دخول-الجنب-المسجد-للاذان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/al rawth_almuraba 019.mp3","categories":["الأذان والإقامة","المساجد ومواضع السجود"]},{"id":5580,"question":"مساجد العيد الآن تُسَوَّر وتُحجب عن الناس، فهل تُعتبر مساجد؟","title":"هل تعتبر مصليات العيد مساجد ولها حكمها؟","answer":"الجواب: من باب الاحتياط والخروج من الخلاف طيب، هذا من باب الاحتياط والخروج من الخلاف؛ لئلا تُمتهن، ولئلا يُلقى فيها شيء من القاذورات، هذا من باب الحيطة، ومن باب تنزيهها وتنظيفها للناس. أما كونه مسجدًا يحتاج إلى تحية المسجد أو يَحْرُم فيه جلوس الجنب أو الحائض فهذا محل نظرٍ، أما كون المسجد يُنظف ويُصان عن القاذورات فهذا طيب ومهم.[1]","link":"https://binbaz.org.sa/fatwas/31532/هل-تعتبر-مصليات-العيد-مساجد-ولها-حكمها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/al rawth_almuraba 020.mp3","categories":["صلاة العيدين","المساجد ومواضع السجود"]},{"id":5591,"question":"من قال أنَّ المنارات التي في المساجد أنها من البدع التي أُحدثت؟","title":"ما حكم المنارات والمنابر في المساجد؟","answer":"الجواب: لا، كلام ما هو بصحيح، النبي أمر بالأذان على المرتفعات، على سطح، على غيره؛ لأنَّ المقصود إبلاغ الناس، كلما كان أرفع أبلغ الناس. س: المنابر يقولون: ما أكثر من ثلاث درج أنه بدعة؟ ج: الأمر واسع إن شاء الله، الأمر واسع.[1]","link":"https://binbaz.org.sa/fatwas/31552/ما-حكم-المنارات-والمنابر-في-المساجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/al rawth_almuraba 031.mp3","categories":["المساجد ومواضع السجود"]},{"id":5598,"question":"مَن اعتاد بعد الأذان أن يذهب إلى بيته ثم يعود قبل الإقامة بقليلٍ فهل يأثم على ذلك؟","title":"ما حكم الخروج من المسجد بعد الأذان؟","answer":"الجواب: لا، ما يأثم، لكن كونه يبقى في المسجد أوْلى، يأتي المسجد وقد انتهى من كل شيءٍ، قد تأهب، لكن لو أذَّن وهو على غير وضوءٍ ثم راح يتوضأ ما في شيء. س: عادة؟ ج: ولو، ما يضرّ، لكن إذا كان يذهب ويأتي لأسبابٍ لا بأس، لكن الأولى له أن يأتي وقد تأهَّب حتى يُؤذن وينتظر. س: ورد النَّهي عن الخروج من المسجد بعد الأذان، هل هو للتحريم؟ ج: نعم: \"فقد عصى أبا القاسم\" إلا لعذر شرعي. س: يذهب إلى بيته لكي يأتي بسنة الاضطجاع بين الأذان والإقامة؟ ج: يُصلي في المسجد والحمد لله، الأمر واسع.[1]","link":"https://binbaz.org.sa/fatwas/31561/ما-حكم-الخروج-من-المسجد-بعد-الاذان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/al rawth_almuraba 038.mp3","categories":["المساجد ومواضع السجود"]},{"id":5619,"question":"الحمام الحشّ، أم حمام الاغتسال؟","title":"ما المقصود بالحمام الذي لا تصح الصلاة فيه؟","answer":"الجواب: هو الحشّ. س: إذا كان في القبلة الحمام؟ ج: ما يضرّ، لو صلَّى وهو في قبلته ما يضرّ. س: داخل الحمام تصح الصلاة فيه؟ ج: ما تصح الصلاة في الحمام، في داخل الحمام لا يُصلَّى فيه؛ النبي ﷺ نهى: الأرض كلها مسجد إلا المقبرة والحمام؛ لأنها مظنة النَّجاسات. س: إذا حُبس في الحمام وما استطاع الخروج حتى خرج وقت الصلاة؟ ج: وَقَدْ فَصَّلَ لَكُمْ مَا حَرَّمَ عَلَيْكُمْ إِلَّا مَا اضْطُرِرْتُمْ إِلَيْهِ [الأنعام:119]، الضرورة لها أحكامها.[1]","link":"https://binbaz.org.sa/fatwas/31602/ما-المقصود-بالحمام-الذي-لا-تصح-الصلاة-فيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/al rawth_almuraba 059.mp3","categories":["المساجد ومواضع السجود"]},{"id":5620,"question":"البيوت التي داخل المقابر؟","title":"ما حكم الصلاة في البيوت التي داخل المقابر؟","answer":"الجواب: ما يجوز، يجعلون بيوتًا داخل المقابر، لا يُصلَّى فيها.[1]","link":"https://binbaz.org.sa/fatwas/31603/ما-حكم-الصلاة-في-البيوت-التي-داخل-المقابر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/al rawth_almuraba 060.mp3","categories":["المساجد ومواضع السجود"]},{"id":5621,"question":"إذا كانت معاطن ثم تُركت، يعني: نُقلت الإبل من هذا الموطن؟","title":"ما حكم الصلاة في أماكن كانت معاطن ثم تُركت؟","answer":"الجواب: إذا غُيّر المكان من كونه معطنًا وجُعل محل جلوسٍ، أو أُزيل، أو طُهِّر المحل، أو طُيِّن، يعني: أُزيلت آثاره. س: لكن لو كان في بريةٍ ثم نقل إبله عن هذا الموطن بالكلية؟ ج: ما دامت آثار المعطن فيه يبقى الحكم، أما لو تغير بأن أُزيل أو سفت عليه السوافي صار ما هو بمعطنٍ. س: وإن صلى فيه يقال له: أعد الصلاة؟ ج: نعم يُعيد الصلاة، مثل: مَن صلَّى في مزبلةٍ. س: ولو كان ناسيًا؟ ج: ولو، ولو. س: معاطن البقر والغنم؟ ج: لا بأس بها، معاطن البقر والغنم لا بأس بها.[1]","link":"https://binbaz.org.sa/fatwas/31608/ما-حكم-الصلاة-في-اماكن-كانت-معاطن-ثم-تركت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/al rawth_almuraba 061.mp3","categories":["المساجد ومواضع السجود"]},{"id":5622,"question":"قارعة الطريق الحكمة في المنع؟","title":"ما حكمة منع الصلاة في قارعة الطريق؟","answer":"الجواب: إذا كانت فيها نجاسة، لكن الحديث ضعيف، الحكم يدور مع علته؛ إن كان في المزبلة نجاسة أو المجزرة نجاسة، أما إن صلَّى في محلٍّ ما فيه نجاسة لا بأس. س: قارعة الطريق؟ ج: قارعة الطريق ترك الصلاة فيها أولى، أحوط؛ لأنَّ الرسول نهى عن الجلوس في قارعة الطريق، والمبيت في قارعة الطريق؛ لأنها عرضة لإيذاء الناس، أما الحديث فضعيف في قارعة الطريق، لكن كونه يبتعد عن ذلك أحوط. س: لو صلَّى صحَّت يعني؟ ج: خروجًا من الخلاف، والصواب صحة الصلاة، لكن ترك ذلك أولى وأحوط؛ لئلا يتعرض للناس –للمُشاة- بالأذى: يعثروا فيه، أو يطؤه أحد، أو يصدمه أحد.[1]","link":"https://binbaz.org.sa/fatwas/31610/ما-حكمة-منع-الصلاة-في-قارعة-الطريق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/al rawth_almuraba 062.mp3","categories":["المساجد ومواضع السجود"]},{"id":5682,"question":"هل يجوز للإنسان أن يعطي من زكاة ماله لبناء مسجد يوشك على الانتهاء، وتوقف بناؤه؟","title":"هل يشرع بناء المساجد من زكاة المال؟","answer":"الجواب:\nالمعروف عند العلماء كافة، وقول الجمهور، والأكثرين وهو كالإجماع من علماء السلف الصالح الأولين: أن الزكاة لا تصرف في عمارة المساجد، وشراء الكتب، ونحو ذلك، وإنما تصرف في الأصناف الثمانية: الفقراء، والمساكين، والعاملين عليها، والمؤلفة قلوبهم، وفي الرقاب والغارمين، وفي سبيل الله، وابن السبيل، وفي سبيل الله يختص بالجهاد، هذا المعروف عند أهل العلم، وليس من ذلك صرفه في تعمير المساجد، ولا تعمير المدارس، ولا الطرق، ولا نحو ذلك، هذا هو المعروف عند أهل العلم.","link":"https://binbaz.org.sa/fatwas/982/هل-يشرع-بناء-المساجد-من-زكاة-المال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_11.mp3","categories":["المساجد ومواضع السجود","إخراج الزكاة وأهلها"]},{"id":5739,"question":"هل تجوز الزكاة في بناء المساجد حيث يقول الله: وَفِي سَبِيلِ اللّهِ [التوبة : 60]؟","title":"هل تصرف الزكاة في بناء المساجد؟","answer":"الجواب: سبق أن المراد في سبيل الله عند أهل العلم الغزاة الذين جاهدوا في سبيل الله، فلا تصرف في المساجد، ولا في المدارس عند عامة أهل العلم.  الصواب عند أهل العلم، وهو كالإجماع منهم: أنها لا تصرف إلا في المصارف الثمانية، وأن المساجد والمدارس ليست منها، وأن المراد في سبيل الله يعني الجهاد، المجاهدون، وذهب بعض المتأخرين إلى جواز صرفها في المشاريع الخيرية، ولكنه قول مرجوح؛ لأنه يخالف ما دلت عليه الأدلة، ويخالف ما مضى عليه أهل العلم في هذا السبيل.","link":"https://binbaz.org.sa/fatwas/1063/هل-تصرف-الزكاة-في-بناء-المساجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_78.mp3","categories":["إخراج الزكاة وأهلها","المساجد ومواضع السجود"]},{"id":5746,"question":"ذكرتم قول الرسول ﷺ عن صلاة العشاء: لا تمنعوا إماء الله مساجد الله عن صلاة النساء، ثم ما ورد عن عائشة -رضي الله عنها-: \"لو علم رسول الله ما أحدثته النساء اليوم لمنعهن\" كيف يمكن التوفيق بين هذا وذاك؟","title":"السنة في خروج النساء للمساجد","answer":"الجواب: النبي ﷺ هو المشرع عن الله  والمبلغ عن الله، وهو الذي قال: لا تمنعوا إماء الله مساجد الله وقال -عليه الصلاة والسلام-: إذا استأذنت أحدكم امرأته إلى المسجد فلا يمنعها فقال بعض أبناء عبدالله بن عمر: والله لنمنعهن، يعني لما رأى من تغير الأحوال، فأقبل عليه عبدالله والده وسبّه سبًّا شديدًا؛ لأنه عارض السنة برأيه. فالسنة دلت على أنه لا تمنع النساء المساجد، ولكن بشروط، قال ﷺ: أي امرأة أصابت بخورًا فلا تشهد معنا العشاء وحث على الستر والجلباب وغير ذلك، فالمرأة لا تمنع لكن بشروط، بشرط أن تكون على الطريقة الحسنة، وعلى السيرة الحميدة، وعلى التستر التام. أما إذا كانت تفتن الناس بإبراز زينتها، ومفاتنها وبخروجها بالطيب تمنع كما دل عليه قول النبي ﷺ: أي امرأة أصابت بخورًا فلا تشهد معنا العشاء فهذا يدل على أنها لا تخرج بالطيب، لا بالبخور، ولا بغيره الذي يظهر للناس، ولا بدّ أن تكون متسترة متحجبة، ولا بدّ أن تكون ليست ذات ريبة، فإذا كانت ذات ريبة تستغل خروجها للصلاة، وتستغل هذا لأمر آخر مما يضر زوجها وأهلها تمنع.  فالحاصل: أنها لا تمنع إذا كانت سليمة، إذا كانت طيبة، إذا كانت متسترة، إذا كانت متباعدة عما حرم الله، وخروجها ينفعها ولا يضر الناس فلا بأس. وأما قول عائشة: لو علم النبي ما أحدث النساء لمنعهن من الخروج، فجواب ذلك: أن الله -جل وعلا- يعلم كل شيء، والرسول المشرع عن الله ما ينطق عن الهوى، فالله يعلم ذلك، يعلم ما يحدث اليوم، وما حدث قبلًا، ومع هذا شرع لنا أن لا نمنعهن، فقول عائشة هنا ليس بجيد، وليس بمعتمد، وإنما العمدة على سنة رسول الله، عليه الصلاة والسلام. فالله يعلم كل شيء، ربنا يعلم ما يكون في القرن الرابع عشر، والقرن الخامس عشر، والقرن السادس عشر وما بعده، إن عاش الناس إلى ذلك يعلم كل شيء، فالشريعة عامة، شريعة للصحابة ولأهل هذا القرن، ولمن يأتي بعدهم، شريعة عامة، فقول عائشة هنا ليس بجيد في هذا المقام، وإنما قالت هذا من اجتهادها وظنها، والظن يخطئ ويصيب.","link":"https://binbaz.org.sa/fatwas/1054/السنة-في-خروج-النساء-للمساجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_71.mp3","categories":["قضايا المرأة","المساجد ومواضع السجود"]},{"id":5918,"question":"ما  رأي الشارع في قيامي بصرف جزء من زكاة مالي في تشييد مسجد منذ بعض سنوات، دون علمي بالحكم، وعرفت هذه السنة أن الزكاة لا تجوز على تشييد مسجد، فما الحكم فيما فعلت قبل ذلك؟ هل هو جائز؟ وماذا أفعل؟","title":"حكم تعمير المساجد من الزكاة","answer":"الجواب: المعروف عند أهل العلم: أن الزكاة لا تصرف للمساجد، هذا الذي عليه جمهور أهل العلم، وهو المعروف عن السلف الصالح، ومن بعدهم أن الزكاة ليس من مصارفها تعمير المساجد، ولا تعمير المدارس، وأشباه ذلك، بل هي لأصناف ثمانية، وليس منها تعمير المساجد، بل ما يتعلق به من قال بذلك كلمة في سبيل الله وفي سبيل الله ذكر العلماء أن المراد بها المجاهدون (الجهاد). فالذي صرف زكاته في المساجد؛ ينبغي له أن يقضيها، وأن يصرفها في جهاتها، ويكون ذلك عمل بر له أجره، وثوابه، فيقضي مثل ما صرف في المساجد، ويخرجه في جهات أخرى للفقراء، والمساكين، وفي المجاهدين، أو في المؤلفة قلوبهم. المقصود: أنه يقضي ما صرف يعني ذلك الذي صرفه يقضي بدله في مصارف الزكاة.","link":"https://binbaz.org.sa/fatwas/1278/حكم-تعمير-المساجد-من-الزكاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_265.mp3","categories":["إخراج الزكاة وأهلها","المساجد ومواضع السجود"]},{"id":5986,"question":"ما حكم الصلاة على الجرائد المنتشرة في هذه الأيام؟","title":"حكم الصلاة على ورق الجرائد","answer":"الجواب: الجرائد لا يجوز الصلاة عليها؛ لأن فيها ذكر الله، وفيها الأحاديث، والآيات، فهذا امتهان، لكن الواجب أنها تجمع، وتحفظ في الدواليب، أو تحرق، أو تدفن، أما أنها تستعمل في أن يصلى عليها، أو توضع سفرة للموائد، أو ملفًا للحاجات، هذا لا يجوز؛ لأنها في الغالب لا تخلو من آيات.  أما لو وجد جريدة ما فيها شيء، ما فيها ذكر الله، ولا آية، ولا شيء؛ فهذا لا بأس أن تمتهن، لكن قل أن توجد جريدة من الجرائد في هذه البلاد، لا يوجد جريدة إلا وفيها شيء من ذكر الله، أو آية، أو حديث، فلا ينبغي، ولا يجوز أن تمتهن، بل يجب أن تحرق إذا كان ما لهم حاجة فيها تحرق، أو تدفن في أرض طيبة، أو تحفظ عنده في دواليب حتى لا تمتهن.  وأما الصور التي فيها فبالإمكان مسح الرؤوس، وإذا دفنت، ولم يظهر منها شيء؛ ما ضرت، المضر ظهورها، وانتشارها، أو جعلها على .... أو جعلها على الأبواب، أما إذا دفنت حتى يقضي الله ما شاء فيها، أو تحرق، أو تدفن في أرض.","link":"https://binbaz.org.sa/fatwas/1351/حكم-الصلاة-على-ورق-الجراىد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_308.mp3","categories":["قضايا المرأة","المساجد ومواضع السجود"]},{"id":6004,"question":"يوجد في إحدى القرى مقبرة، ويوجد بتلك المقبرة مسجد تحيط به المقبرة من ثلاث جهات، الشمال، والجنوب، والشرق، والمسجد قد تصدعت حيطانه، ولم يبق سوى أرضيته، وتقام فيه الصلاة، فما حكم الصلاة؟ وهل تجوز فيه الصلاة إذا أقيم بناؤه؟","title":"حكم الصلاة في مسجد تحيط به مقبرة من ثلاث جهات","answer":"الجواب: نعم، ما دام المسجد مقامًا، ما يضره كون القبور عن يمينه، وشماله، ما يضره، يصلون في ذلك، ولا حرج عليهم. وإذا كانت القبور قريبة من جهة الغرب إلى القبلة، فينبغي أن يكون بين المسجد، وبين القبور جدار آخر تحجز المقبرة عن المسجد، هذا هو الأولى والأكمل أن يكون هناك جدار آخر يفصل المقبرة عن المسجد غير جدار المسجد، هذا هو الأحسن.","link":"https://binbaz.org.sa/fatwas/1373/حكم-الصلاة-في-مسجد-تحيط-به-مقبرة-من-ثلاث-جهات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_331.mp3","categories":["قضايا المرأة","المساجد ومواضع السجود"]},{"id":6007,"question":"يوجد في إحدى القرى مقبرة، ويوجد بتلك المقبرة مسجد تحيط به المقبرة من ثلاث جهات، الشمال، والجنوب، والشرق، والمسجد قد تصدعت حيطانه، ولم يبق سوى أرضيته، وتقام فيه الصلاة، فما حكم الصلاة؟ وهل تجوز فيه الصلاة إذا أقيم بناؤه؟","title":"حكم الصلاة في مسجد تحيط به مقبرة من ثلاث جهات","answer":"الجواب: نعم، ما دام المسجد مقامًا، ما يضره كون القبور عن يمينه، وشماله، ما يضره، يصلون في ذلك، ولا حرج عليهم. وإذا كانت القبور قريبة من جهة الغرب إلى القبلة، فينبغي أن يكون بين المسجد، وبين القبور جدار آخر تحجز المقبرة عن المسجد، هذا هو الأولى والأكمل أن يكون هناك جدار آخر يفصل المقبرة عن المسجد غير جدار المسجد، هذا هو الأحسن.","link":"https://binbaz.org.sa/fatwas/1373/حكم-الصلاة-في-مسجد-تحيط-به-مقبرة-من-ثلاث-جهات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_331.mp3","categories":["قضايا المرأة","المساجد ومواضع السجود"]},{"id":6138,"question":"هل يجوز يا شيخ الحديث في المساجد في أمور الدنيا؟","title":"كراهة الحديث عن أمور الدنيا في المساجد","answer":"الجواب: لا ينبغي يكره إلا إذا كان شيء قليل، أحاديث الدنيا تكون في البيوت، وفي المجالس، أما المساجد تصان عن هذا إلا الشيء اليسير، ينبغي أن تكون المساجد محل القراءة، والتسبيح، والتهليل، ومذاكرة العلم لا في أمور الدنيا، لكن يعفى عن اليسير. السؤال: ما كان السلف الصالح يفعلونه؟ الجواب: ما كانوا يفعلونه لا، اللهم إلا الشيء اليسير.","link":"https://binbaz.org.sa/fatwas/1580/كراهة-الحديث-عن-امور-الدنيا-في-المساجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_481.mp3","categories":["المساجد ومواضع السجود","الآداب والأخلاق"]},{"id":6141,"question":"هل يجوز قراءة القرآن بصوت مرتفع في المسجد؟","title":"حكم قراءة القرآن بصوت مرتفع في المسجد","answer":"الجواب: لا ما ينبغي، كل يقرأ قراءة خفيفة بقدر ما يسمع نفسه، ومن حوله، ولا يشوش على الناس، لا يرفع صوته في المساجد، يشوش على إخوانه القراء، والمصلين، بل يقرأ قراءة خفيفة سرية، يسمعها من حوله، أو قريب ينتفع منه، ولا يؤذي من حوله. وإذا كان من حوله يقرأ، أو يصلي؛ يخفي قراءته؛ حتى لا يؤذيهم، وحتى لا يشوش عليهم، النبي ﷺ خرج ذات يوم على الناس، وهم يصلون في المسجد، ويرفع بعضهم صوته على بعض، فقال: إنكم تناجون الله، فلا يرفع بعضكم على بعض أو قال: لا يجهر بعضكم على بعض وفي اللفظ الآخر: فلا يؤذي بعضكم بعضًا.","link":"https://binbaz.org.sa/fatwas/1593/حكم-قراءة-القران-بصوت-مرتفع-في-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_487.mp3","categories":["المساجد ومواضع السجود","القرآن وعلومه"]},{"id":6192,"question":"هناك بعض الساعات الحائطية في المساجد تصدر أصوات الجرس الموسيقي، فما حكم ذلك؟","title":"حكم الأجراس التي في الساعات الحائطية في المساجد","answer":"الجواب: ينبغي أن يزال هذا الجرس، وتبقى الساعة، ولكن يزال منها هذا الجرس الذي يشوش على المصلين، والقارئين، تبقى بدون جرس، الناس يرونها، ويشاهدونها، ويستفيدون منها في المسجد للأوقات، لكن ليس هناك حاجة إلى الجرس.","link":"https://binbaz.org.sa/fatwas/1646/حكم-الاجراس-التي-في-الساعات-الحاىطية-في-المساجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_534.mp3","categories":["قضايا المرأة","المساجد ومواضع السجود"]},{"id":6211,"question":"لو كانت لبناء المساجد؟","title":"حكم بناء المساجد من الزكاة","answer":"الجواب: لا، المساجد لا تبنى من الزكاة، المساجد، والمدارس لا تبنى من الزكاة، لكن تبنى بمساعدة أهل الخير، أما الزكوات فتصرف فيما قال الله -جل وعلا-: إِنَّمَا الصَّدَقَاتُ لِلْفُقَرَاءِ وَالْمَسَاكِينِ وَالْعَامِلِينَ عَلَيْهَا وَالْمُؤَلَّفَةِ قُلُوبُهُمْ وَفِي الرِّقَابِ وَالْغَارِمِينَ وَفِي سَبِيلِ اللَّهِ وَابْنِ السَّبِيلِ [التوبة: 60] وفي سبيل الله: هؤلاء هم المجاهدون عند أهل العلم.","link":"https://binbaz.org.sa/fatwas/1708/حكم-بناء-المساجد-من-الزكاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_565.mp3","categories":["إخراج الزكاة وأهلها","المساجد ومواضع السجود"]},{"id":6221,"question":"لو كانت لبناء المساجد؟","title":"حكم بناء المساجد من الزكاة","answer":"الجواب: لا، المساجد لا تبنى من الزكاة، المساجد، والمدارس لا تبنى من الزكاة، لكن تبنى بمساعدة أهل الخير، أما الزكوات فتصرف فيما قال الله -جل وعلا-: إِنَّمَا الصَّدَقَاتُ لِلْفُقَرَاءِ وَالْمَسَاكِينِ وَالْعَامِلِينَ عَلَيْهَا وَالْمُؤَلَّفَةِ قُلُوبُهُمْ وَفِي الرِّقَابِ وَالْغَارِمِينَ وَفِي سَبِيلِ اللَّهِ وَابْنِ السَّبِيلِ [التوبة: 60] وفي سبيل الله: هؤلاء هم المجاهدون عند أهل العلم.","link":"https://binbaz.org.sa/fatwas/1708/حكم-بناء-المساجد-من-الزكاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_565.mp3","categories":["إخراج الزكاة وأهلها","المساجد ومواضع السجود"]},{"id":6274,"question":"وآخر يرجو سماحة الشيخ أن يفتح المجال للنساء لحضور مثل هذه الندوات المفيدة، حتى يتفقهن في دينهن، ثانيًا أن يتهيأ الملحق الأخير من المسجد للنساء للصلاة فيه كل وقت، حيث إننا نرى النساء في الشوارع يجلسن على الأرصفة وقت الصلاة، مع أنها واجبة عليهن، والله يحفظكم، ويرعاكم!","title":"حكم حضور النساء للصلاة في المساجد وسماع الدروس","answer":"الجواب:  هذا غير ممنوع، لو حضروا غير ممنوع، لو حضروا، وصلوا في المؤخرة؛ ما يضر، ويجعل عندهم أيضًا سماعة تفيدهم؛ فهذا طيب، مثل ما فعل في الحرمين الشريفين، ولكن الجماعة ما هي واجبة عليهن، إنما يحضرن لاستماع الفائدة، أما صلاتهن في بيوتهن فهي أفضل لهن، وأسلم، وأصون كما في الحديث: وبيوتهن خير لهن قال: لا تمنعوا إماء الله مساجد الله، وبيوتهن خير لهن.  فإن حضروا؛ فلا بأس، وإن صلوا في بيوتهم؛ فذلك أفضل لهن، وأستر، وأبعد عن الشر، وإذا حضروا لسماع الفائدة من دروس، مثل هذه الليلة، أو في أي مكان لسماع حلقة العلم، والفائدة في مكان مناسب، وعندهن سماعات؛ فهذا لا شك أنه طيب، ومفيد. وقد قلنا غير مرة أنه لا بأس بحضورهن في المؤخرة، ولكن ما سمعت حتى الآن أنه حضر منهن أحد، وإذا حضر منهن أحد فلا شك أن هذا يفيدهن في هذه الليلة إذا كان عندهن سماعات تفيدهن، وسنفعل إن شاء الله ما يحصل به هذا الشيء. ولكن من المصائب أنه قل من يذكِّر، إذا قمنا من هذه الجلسة، قل من يذكر بهذا الأمر، فلو ذكرنا لأن مشاغلنا كثيرة جدًا، فلو ذكرنا هذا الأمر في غير هذا الوقت؛ لفعلنا ما يلزم -إن شاء الله- من جهة السماعة، ومن جهة الاهتمام بهذا الأمر، وينبغي لمن كتب هذا الكتاب أن يذكر، أو غيره، كذلك من الإخوان الذين يسمعون الكلام ينبغي أن يذكرنا في غير هذا الوقت؛ حتى نعمل ما يلزم من هذه ... الخير.","link":"https://binbaz.org.sa/fatwas/1772/حكم-حضور-النساء-للصلاة-في-المساجد-وسماع-الدروس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_611.mp3","categories":["قضايا المرأة","المساجد ومواضع السجود"]},{"id":6313,"question":"أحد الإخوة يقول: مسجد بني بالإحساء كلف خمسة وثلاثون مليون ريال، مزين بذهب قيمته ثلاثة ملايين ريال، ما حكم هذا في الإسلام؟ وما هو الموقف الرسمي من هذا العمل؟","title":"حكم المغالاة في بناء المساجد","answer":"الجواب:  سمعتم السؤال هذا يقول: مسجد في الإحساء بني بخمسة وثلاثين مليون، وفيه مقدار ثلاثة ملايين من الذهب، إن صح قول السائل هذا خطأ، ولا شك أنه لا يجوز الإسراف في بناء المساجد، ولا الزخارف التي تضيع الأموال، وتؤذي المصلين، كيف يجعل الذهب؟! لماذا يجعل الذهب؟! بالذهب يبني مساجد أخرى، هذا من الأغلاط إن صح هذا الخبر، وسنبحث في الحقيقة، هذا منكر، ولا يجوز السكوت عليه. ولا شك أن هذا منكر، والناس في حاجة إلى المساجد في حارات كثيرة، يحتاجون إليها كنا، وغيرنا نتعب، ما حصلنا من يبني المساجد؟ متى نحصل الثري الغني الذي يقوم ببناء مسجد؟ فكيف تصرف الأموال هكذا؟! ما يجوز مطلقًا، بل يجب الاقتصاد في بناء المساجد، وأن يعتنى بقوتها، وسلامتها؛ حتى لا تضر المصلين، أما الزخارف فلا. وكان عمر  لما أمر ببناء مسجد النبي ﷺ قال: إياك أن تحمر، أو تصفر وأمره أن يبني بناء شديدًا سليمًا، لا يضر المسلمين، ولكن إذا بني بناء فيه إحكام، وفيه إتقان؛ لا بأس أن يكون فيه حجر، أو سيكون فيه جص، سيكون فيه أسمنت، لكن الزخرفة، والنقوش التي تؤذي المصلين، أو بذهب، أو فضة، أو أشياء من المعادن الأخرى التي لها قيمتها كل هذا لا يجوز، ولا وجه له، فإنما يبنى بالحجر، أو بالأسمنت، أو بالطين، بالخشب لا بأس، أما الزيادة على ذلك كنقوش تؤذي، فهذا أقل أحواله الكراهة. أما وجود الذهب’ والفضة فهذا لا وجه له، بل هو محرم، ومنكر، كل مال يصرف في هذا السبيل بغير وجهه؛ فهو من الإسراف، ومن إضاعة المال، والواجب أن ينزع، وأن يصرف في مساجد أخرى، وفي أعمال شرعية تنفع المسلمين، ولا شك إن كان هذا واقعًا أنه جهل من صاحبه، وغلط من صاحبه، نسأل الله له الهداية وسوف يوجه إن شاء الله إلى الخير.","link":"https://binbaz.org.sa/fatwas/1884/حكم-المغالاة-في-بناء-المساجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_668.mp3","categories":["المساجد ومواضع السجود","الأخلاق المذمومة"]},{"id":6365,"question":"ما حكم كتابة الآيات القرآنية، وتلصيقها في المساجد، أو المنازل؟","title":"حكم تعليق الآيات القرآنية على جدران المساجد والبيوت","answer":"الجواب: لا ينبغي، أقل أحواله الكراهة؛ لأنه يشغل المصلين، ويؤذيهم، ويشوش عليهم، والمساجد ينبغي أن تكون سليمة من هذه الأشياء حتى لا يشغل المصلون بالقراءات، والكتابات، والرسوم التي في الجدران. السؤال: حتى في المنازل؟  الجواب: لا، المنازل أسهل، لكن المساجد هي التي ينبغي تنزيهها من هذا؛ لئلا تشغل المصلين، أما المنازل فأمرها أوسع. السؤال: لعل الآيات تذكره بالصلاة، أو بالخشوع؟ الجواب: ما كان سلفنا يفعلون هذا في المساجد.","link":"https://binbaz.org.sa/fatwas/1936/حكم-تعليق-الايات-القرانية-على-جدران-المساجد-والبيوت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_721.mp3","categories":["المساجد ومواضع السجود","القرآن وعلومه"]},{"id":6471,"question":"مسجد قديم يصلى فيه، ثم تبين أنه منحرف عن القبلة، وعندما أريد تعديل الصفوف أثناء الصلاة؛ لوحظ عدم استقامتها، وأن السواري تعوق ذلك، فما الحكم وفقكم الله؟","title":"حكم الصلاة في المسجد الذي به انحراف عن القبلة","answer":"الجواب: إذا كان الميل خفيفًا لا يضر، إذا كان الانحراف في جهة المسجد قليلًا، وما زال إلى جهة القبلة، ولكن به انحراف؛ فلا يضر، يصلي الناس، ولا يضرهم ذلك، أما إذا كان الانحراف كثيرًا بأن انحرف عن الجهة انحرافًا شديدًا، فيعدل من جهة البناء، أو من جهة الصفوف، أما الانحراف اليسير فيعفى عنه، ولا يضر.  النبي ﷺ قال: ما بين المشرق، والمغرب قبلة يعني بالنسبة إلى أهل الشمال، والجنوب، فهكذا أهل الشرق، والغرب يقال في حقهم ما بين الجنوب، والشمال قبلة، إذا كانوا في الشرق، فالغرب قبلتهم، فإذا مال عن الجهة، لكن ما يزال على جهة الغرب، لكن يميل عنها جنوبًا، أو شمالًا، فلا يضر.  أما إن كان الميل شديدًا -يعني أن يكون إلى الجهة الأخرى أقرب- فإن هذا يضر الصلاة، ويجب تعديل الصفوف، أو تحويل المسجد، وإنشاؤه من جديد، وأما الميول الخفيفة فتغتفر.","link":"https://binbaz.org.sa/fatwas/2216/حكم-الصلاة-في-المسجد-الذي-به-انحراف-عن-القبلة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_835.mp3","categories":["استقبال القبلة","المساجد ومواضع السجود"]},{"id":6596,"question":"هل يجوز نزع ملكية المساجد، وهدمها، وإنشاء بدلًا منها حديقة، وملاعب للأطفال، وإذا كان الجواب عكس ذلك فلماذا تنوي أمانة مدينة الرياض هدم مسجد حي غميقة وإنشاء محله حديقة وملاعب، للمعلومية هذا الخبر نشر بجريدة الرياض بعددها 5753 بتاريخ كذا، فما هو موقف سماحة الشيخ؟","title":"حكم هدم المسجد لمصلحة","answer":"الجواب: ننظر في الأمر، لا يجوز هدم المساجد إلا لمصلحة كبرى، المساجد لا تهدم لأجل الحدائق إذا كان لها حاجة للمسجد، إذا كان هناك حاجة للمسجد يبقى، أما إذا كان المسجد ليس له حاجة، بأن يقيم مسجدًا أوسع منه، وأنفع للحارة؛ فلا بأس أن يهدم حينئذ، إذا أقامت الدولة، أو المسلمون مسجدًا أحسن؛ لأنه أضيق، أو لأنه طين، وأقاموا مسلحًا، أو لأنه خارب؛ فهدموه، وأقاموا ما هو أحسن منه في الحارة، وما هو أنفع لأهل الحارة؛فهذا حينئذ لهدمه مسوغ، أما أن يهدم بغير مسوغ، لا يجوز، لا لحديقة، ولا لغير الحديقة.\n\nالسؤال: كذلك انظروا في فتح الحدائق، أصبحت محل دعارة الآن، تبرج نساء؟ الجواب: على كل حال فيها شر كثير -نسأل الله- أن يكفيها شرها، تحتاج إلى عناية كبيرة، تحتاج إلى مراقبة من الهيئات، وإلى رقابة من الأعيان، تحتاج إلى جهات، هذه الحدائق، ولا مفر منها، لكنها تحتاج إلى جهاد، ونسأل الله أن يوفق الدعاة إلى الله، وأهل الهيئة، ورجال الهيئة، وأعيان المسلمين، نسأل الله أن يوفقهم للتعاون حتى يصلحوا ما فسد منها. السؤال: في بعض إخواننا المسلمين يميلون إلى السوق، ومعهم نساء كاسيات، وعاريات، فما حكم ذلك؟ الجواب: هذا من المنكر، هذا من المنكر، يجب عليهم أن يتقوا الله، وأن يحذروا هذا، وإذا رأيت من جيرانك، ومن أقاربك لا تكسل، انصح يا أخي، اتق الله يا أخي، لا، هذا ما يجوز، اتق الله يا فلان بالأساليب الحسنة .. يخرج بزوجته كاسية عارية، نعوذ بالله، فهذا حرام منكر، هذا عرض لها للفساد، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/2454/حكم-هدم-المسجد-لمصلحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_981.mp3","categories":["قضايا المرأة","المساجد ومواضع السجود"]},{"id":6634,"question":"بعض الإخوان في غير هذه البلدان يقومون بعقد النكاح في المسجد، ما حكم هذا، ويقولون إن هذا بركة؟","title":"مشروعية عقد النكاح في المسجد","answer":"الجواب: قد استحب هذا بعض أهل العلم عقد النكاح في المسجد، فإذا فعلوه في المسجد؛ فلا حرج، وإذا فعلوه في أي مكان في البيت، أو في الدكان، أو في السوق؛ فلا بأس، ولكن بعض أهل العلم استحبه في المسجد، ولست أعلم دليلًا واضحًا على ذلك، إلا أن المسجد يفضل، ولا  أذكر الآن شيئًا ما يدل على شرعية ذلك إلا أنه من كلام بعض أهل العلم، وإذا عقد في غير المسجد في بيت الزوج، أو بيت الزوجة، أو في بيت أحد الجيران، أو الأقارب، كل هذا لا بأس به، والحمد لله، الأمر واسع. السؤال: طيب بالنسبة لأهل مكة خاصة أغلبهم لا يعقدون إلا في الحرمين؟  الجواب: ما هو بلازم في أي مكان، والحمد لله. السؤال: يشترط هذا؟ الجواب: ما هو بشرط ما هو بلازم. السؤال: ما رأيكم بحديث أعلنوا هذا النكاح، واضربوا عليه بالدفوف، واجعلوه في المساجد؟ الجواب: هذا إن صح ما في....","link":"https://binbaz.org.sa/fatwas/2489/مشروعية-عقد-النكاح-في-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_1016.mp3","categories":["إخراج الزكاة وأهلها","المساجد ومواضع السجود"]},{"id":6649,"question":"بعض الإخوان في غير هذه البلدان يقومون بعقد النكاح في المسجد، ما حكم هذا، ويقولون إن هذا بركة؟","title":"مشروعية عقد النكاح في المسجد","answer":"الجواب: قد استحب هذا بعض أهل العلم عقد النكاح في المسجد، فإذا فعلوه في المسجد؛ فلا حرج، وإذا فعلوه في أي مكان في البيت، أو في الدكان، أو في السوق؛ فلا بأس، ولكن بعض أهل العلم استحبه في المسجد، ولست أعلم دليلًا واضحًا على ذلك، إلا أن المسجد يفضل، ولا  أذكر الآن شيئًا ما يدل على شرعية ذلك إلا أنه من كلام بعض أهل العلم، وإذا عقد في غير المسجد في بيت الزوج، أو بيت الزوجة، أو في بيت أحد الجيران، أو الأقارب، كل هذا لا بأس به، والحمد لله، الأمر واسع. السؤال: طيب بالنسبة لأهل مكة خاصة أغلبهم لا يعقدون إلا في الحرمين؟  الجواب: ما هو بلازم في أي مكان، والحمد لله. السؤال: يشترط هذا؟ الجواب: ما هو بشرط ما هو بلازم. السؤال: ما رأيكم بحديث أعلنوا هذا النكاح، واضربوا عليه بالدفوف، واجعلوه في المساجد؟ الجواب: هذا إن صح ما في....","link":"https://binbaz.org.sa/fatwas/2489/مشروعية-عقد-النكاح-في-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_1016.mp3","categories":["إخراج الزكاة وأهلها","المساجد ومواضع السجود"]},{"id":6678,"question":"نذكر أمرين يحدثان في هذا المسجد يوم الجمعة خاصة: يحجز المكان الذي خلف الإمام لما يتسع لعدد من الناس، وإذا أحد جاء ليجلس فيه يمنع، ويقال: هذا محل شيخ، ثم يأتي من يجلس فيه بعد فترة، وإذا أتي بجنازة فإن من يأتي بها يكونون قبل الصف الأول، صف صغير بعد الإمام إلى اليسار، ولكن ليس كاملًا، آمل الإفادة حول ذلك، وهل لنا أن نجلس في المكان الخالي، حتى وإن غضب بعضهم؟","title":"حكم حجز الأماكن في المسجد","answer":"الجواب: الحمد لله وصلى الله وسلم على رسول الله، وعلى آله، وأصحابه، ومن اهتدى بهداه، أما بعد: فالمسجد بيت الله، أعد لعبادته وطاعته من الصلاة، وغيرها، فلا يجوز لأحد أن يتحجر ما خلف الإمام، ولا ما عن يمينه، ولا ما عن شماله، فهو لمن سبق، الصف الأول لمن سبق، ولهذا قال -عليه الصلاة والسلام-: لو يعلم الناس ما في النداء، والصف الأول، ثم لم يجدوا إلا أن يستهموا عليه؛ لاستهموا يعني لاقترعوا للمسابقة إليه، والحرص على أن يتقدموا.  فحجزه أمر لا يجوز، وغصب للمكان، ولا حق لمن غصبه، فالسابق أولى منه، وأحق منه في المكث فيه، والتقدم إليه، والواجب التنبيه على هؤلاء، وأن يعلموا أن هذا لا يجوز، وأن حجز الصف الأول، أو وسط الصف الأول لمن يأتي بعد ذلك لا يجوز. والواجب أن تزال هذه الأشياء، وألا تبقى في مكانها، بل يكون الصف لمن سبق، وكنا نعلم هذا من قديم، كان أهل الحل، والعقد، والآمرون بالمعروف، والناهون عن المنكر يلاحظون هذا، ويزيلون ما يضعه الناس في الصف الأول حتى يتقدم الناس بأنفسهم، لا بالخرق، ولا بغير الخرق، ولا بالسجادات، ولكن يتقدمون بأنفسهم إلى الصف الأول، فهو لمن سبق بنفسه لا لمن سبق بالسجادة، أو النعلين، أو غير هذا لا، هذا هو الحق، هذا هو الصواب، فالسابق أولى بالمكان. نعم إذا كان الإنسان تقدم في الصف الأول، ثم عرض له عارض، فقام يتوضأ فهو أحق بمكانه، حتى ولو ما جعل فيه شيئًا، هو أحق بمكانه أن يرجع إليه إذا عرض له عارض، فقام يتوضأ، أو لغير ذلك من العوارض التي تعرض، وجاء للإقامة في المسجد، والجلوس، والانتظار، فهذا ينبغي أن يعرف، ويعرفه جيرانه، ويقولون لمن جاء هذا المكان: له صاحب، قام لعارض، وهو أحق به، أما إنسان يتقدم بالسجادة، أو غيرها، ويبقى في بيته، أو يبقى في دكانه، هذا غلط، هذا لا يجوز. وأهل الجنازة إذا كان لهم في مكان في الصف الأول يدخلون في الصف الأول، أو في الثاني، وإذا كان ما لهم مكان يصفون خلف الإمام، لا معه، الإمام لا يكون معه أحد، يكونون خلفه، ولو كان صفًا قاصرًا، يكونون خلف الإمام، والجنائز يتسامح في صفوفها، ولهذا قال بعض الصحابة: إنه لا بأس أن تكون الصفوف ثلاثة، ولو كانت غير تامة. فالمقصود: أنه إذا تيسر أن يكونوا في الصف أن يدخلوا في الصف؛ كان الأولى، والأفضل، سواء كان في الصف الأول، أو من ورائه الصف الثاني، أو الثالث إذا تيسر لهم مكان، إذا صفوا خلف الإمام صفًا، ولو كان غير كثير لا بأس.","link":"https://binbaz.org.sa/fatwas/2537/حكم-حجز-الاماكن-في-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1032.mp3","categories":["المساجد ومواضع السجود","الآداب والأخلاق"]},{"id":6811,"question":"بعض من الناس عندما يريد التبرع في مشروع مسجد، يشترط أن يكون التبرع في أرض المسجد فقط، وعمارتها، ولا يكون التبرع لبيت الإمام، والمؤذن؛ لاعتقاد أن الأجر يختلف، وأنه في أرض المسجد يكون أفضل، حتى أن أحدهم لما علم أن ما تبرع به لا يدخل في عمارة المسجد، سحب تبرعه، نرجو إفتاء الناس، ونرجو توضيح ذلك بالتفصيل؟","title":"هل بناء سكن للإمام والمؤذن من الإعانة على عمارة المساجد؟","answer":"الجواب: التبرع في بيت الإمام، والمؤذن إعانة على عمارة المسجد، وإعانة على استقامة أحوال الجماعة في المسجد، لأن الإمام إذا كان موجودًا قريبًا من المسجد؛ استقام أمر المسجد، وحافظ عليه الإمام، وهكذا المؤذن. ثم أيضًا كل مسجد لا يكون للإمام بيت، ولا للمؤذن يكون في الغالب ما يحصلون إمامًا راتبًا، ولا يحصلون إمامًا تتوافر فيه الشروط، فالبيت الإمام في حاجة إليه، فقد يكون الإمام في محل بعيد، ولا يتيسر له المجيء إلى هذا المسجد، فإذا كان حولهم بيت الإمام، وبيت المؤذن؛ صار هذا أكمل في النفع، وأكمل في الفائدة، وأتم لعمارة المسجد. فينبغي للمتبرع أن يتبرع لهذا، ولهذا، إن تبرع لهما جميعًا؛ فهو خير، وإن تبرع للمسجد وحده؛ فهو خير، وإن تبرع لبيت الإمام، والمؤذن؛ فهو خير، كله خير، كله مشاريع خير، كله أبواب خير.","link":"https://binbaz.org.sa/fatwas/2694/هل-بناء-سكن-للامام-والموذن-من-الاعانة-على-عمارة-المساجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1193.mp3","categories":["قضايا المرأة","المساجد ومواضع السجود"]},{"id":6828,"question":"بعض من الناس عندما يريد التبرع في مشروع مسجد، يشترط أن يكون التبرع في أرض المسجد فقط، وعمارتها، ولا يكون التبرع لبيت الإمام، والمؤذن؛ لاعتقاد أن الأجر يختلف، وأنه في أرض المسجد يكون أفضل، حتى أن أحدهم لما علم أن ما تبرع به لا يدخل في عمارة المسجد، سحب تبرعه، نرجو إفتاء الناس، ونرجو توضيح ذلك بالتفصيل؟","title":"هل بناء سكن للإمام والمؤذن من الإعانة على عمارة المساجد؟","answer":"الجواب: التبرع في بيت الإمام، والمؤذن إعانة على عمارة المسجد، وإعانة على استقامة أحوال الجماعة في المسجد، لأن الإمام إذا كان موجودًا قريبًا من المسجد؛ استقام أمر المسجد، وحافظ عليه الإمام، وهكذا المؤذن. ثم أيضًا كل مسجد لا يكون للإمام بيت، ولا للمؤذن يكون في الغالب ما يحصلون إمامًا راتبًا، ولا يحصلون إمامًا تتوافر فيه الشروط، فالبيت الإمام في حاجة إليه، فقد يكون الإمام في محل بعيد، ولا يتيسر له المجيء إلى هذا المسجد، فإذا كان حولهم بيت الإمام، وبيت المؤذن؛ صار هذا أكمل في النفع، وأكمل في الفائدة، وأتم لعمارة المسجد. فينبغي للمتبرع أن يتبرع لهذا، ولهذا، إن تبرع لهما جميعًا؛ فهو خير، وإن تبرع للمسجد وحده؛ فهو خير، وإن تبرع لبيت الإمام، والمؤذن؛ فهو خير، كله خير، كله مشاريع خير، كله أبواب خير.","link":"https://binbaz.org.sa/fatwas/2694/هل-بناء-سكن-للامام-والموذن-من-الاعانة-على-عمارة-المساجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1193.mp3","categories":["قضايا المرأة","المساجد ومواضع السجود"]},{"id":6939,"question":"ما حكم الصلاة في مسجد به قبر؟ وما حكمه إذا كان القبر خلف المسجد؟ كما نسألكم عن حكم إهداء الحلوى بمناسبة مولد الرسول ﷺ؟","title":"ما حكم الصلاة في مسجد به قبر لكنه خلف المسجد؟","answer":"الجواب: الصلاة في المساجد التي فيها قبور ما تجوز، الرسول ﷺ قال: لعن الله اليهود والنصارى اتخذوا قبور أنبيائهم مساجد قالت عائشة -رضي الله عنها-: يحذر ما صنعوا، قالت: ولولا ذلك؛ لأبرز قبره، يعني في البقيع، غير أنه خشي أن يتخذ مسجدًا.  وقال -عليه الصلاة والسلام-: ألا وإن من كان قبلكم كانوا يتخذون قبور أنبيائهم، وصالحيهم مساجد، ألا فلا تتخذوا القبور مساجد، فإني أنهاكم عن ذلك أخرجه مسلم في الصحيحين عن جندب بن عبدالله البجلي. الرسول ﷺ حذر من هذا، وبين أن من قبلنا فعلوا هذا المنكر اتخذوا قبور أنبيائهم، وصالحيهم مساجد ثم نهانها، وحذرنا عن ذلك.  فالصلاة في المساجد التي بنيت على القبور لا تصح، سواء كان القبر في مقدمها، أو عن يمينه، أو شماله، أو خلفه، أما إذا كان خارج المسجد، والمسجد خارج عنه؛ تصح الصلاة. أما ما دام المسجد بني على القبر، سواء جعل أمام المصلين، أو عن يمينهم، أو عن شمالهم، أو خلفهم، فلا يصلى فيه، وإذا كان القبر هو الجديد؛ ينبش، ويخرج رفات القبر إلى المقبرة العامة، ويسوى أرضه، أما إذا كان المسجد هو الجديد، بني على القبر؛ يهدم، ويزال، وتبقى القبور ضاحية للشمس، كما هي ضاحية في عهد النبي ﷺ.","link":"https://binbaz.org.sa/fatwas/2869/ما-حكم-الصلاة-في-مسجد-به-قبر-لكنه-خلف-المسجد ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1317.mp3","categories":["البدع والمحدثات","الفرق والمذاهب","المساجد ومواضع السجود"]},{"id":6942,"question":"في بعض القرى يصلون صلاة العيدين بقرب القبور، هل تصح الصلاة، وهناك بعض الأضرحة المنصوبة؟ فهل يصح هدمها، وإزالتها؟","title":"حكم صلاة العيد بجانب الأضرحة والقبور","answer":"الجواب: إذا كانت المساجد بعيدة عن القبور، أو بينها وبينها حائل؛ ما يضر، المقابر موجودة في كل مكان، لكن إذا كان بينها وبينها جدار، حائل بينها وبين القبور؛ كفى -والحمد لله- وإن تيسر إبعاد المصلى عن القبور؛ فالحمد لله، وإن ما تيسر؛ يجعل حائلًا، ويكفي الحائل.","link":"https://binbaz.org.sa/fatwas/2872/حكم-صلاة-العيد-بجانب-الاضرحة-والقبور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1320.mp3","categories":["صلاة العيدين","المساجد ومواضع السجود"]},{"id":7201,"question":"إن عندنا مسجدًا، وفيه قبران في داخل السور، فهل يجوز نقلهن، أم يبقين في أفيدونا؟","title":"حكم نبش القبور التي توجد داخل سور المسجد والصلاة فيه","answer":"الجواب:\n\nإذا كان القبران أحدثا في المسجد يجب نقلهما، يجب أن ينبشا، وأن تنقل رفاتهما إلى المقبرة العامة، ولا يجوز بقاؤها في المسجد أبدًا، النبي ﷺ يقول: لعن الله اليهود والنصارى اتخذوا قبور أنبيائهم مساجد ويقول: ألا وإن من كان قبلكم يعني من الأمم كانوا يتخذون قبور أنبيائهم وصالحيهم مساجد، ألا فلا تتخذوا القبور مساجد، فإني أنهاكم عن ذلك ونص أهل العلم: أنه لا يجوز الدفن في المساجد، وأنه متى دفن فيها شيء؛ يجب أن ينبش، ويبعد إلى المقابر العامة.\n\nالسؤال: ولو مريت يا شيخ من هذا المسجد يحق لي أن أصلي فيه؟\n\nالجواب: لا، لا تصل فيه وفيه قبور، لا تصل معهم.\n\nالسؤال: القبور قبل المسجد؟\n\nالجواب: يهدم المسجد.","link":"https://binbaz.org.sa/fatwas/3271/حكم-نبش-القبور-التي-توجد-داخل-سور-المسجد-والصلاة-فيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1597.mp3","categories":["قضايا المرأة","المساجد ومواضع السجود"]},{"id":7236,"question":"كلفني أحد أئمة المساجد أن أسألكم على الكتابات المعلقة في المساجد، آيات وأحاديث، هل يجوز هذا؟","title":"حكم تعليق الآيات والأحاديث في المساجد","answer":"الجواب:\n\nكثير من أهل العلم يكره ذلك في المساجد؛ لأنها قد تشوش على المصلين، ولا سيما في قبلة المصلين، فلا ينبغي تعليق شيء من الكتابات في قبلة المصلين؛ لأن هذه قد تشوش على الناس، وقد تشغل المصلي.","link":"https://binbaz.org.sa/fatwas/3297/حكم-تعليق-الايات-والاحاديث-في-المساجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1622.mp3","categories":["المساجد ومواضع السجود","الآداب والأخلاق المحمودة"]},{"id":7348,"question":"حكم دفن الميت في المسجد، واتخاذه مزارًا، ويستثمروا منه فلوس؟","title":"حكم دفن الموتى في المساجد واتخاذها قبورًا","answer":"الجواب:  هذا منكر، لا يجوز الدفن في المساجد، المساجد ما هي مقبرة، الموتى تدفن خارج المساجد،  في محلات في الصحراء، أما المسجد ما يجوز الدفن فيه، ولا يجوز أن يقام مسجد على القبور، لا يقبر فيه، ولا يقام على القبور الاثنين، يقول النبي ﷺ: لعن الله اليهود والنصارى اتخذوا قبور أنبيائهم مساجد. ويقول ﷺ: ألا وإن من كان قبلكم كانوا يتخذون قبور أنبيائهم وصالحيهم مساجد، ألا فلا تتخذوا القبور مساجد، فإني أنهاكم عن ذلك ينصحون ويعلمون، وإذا دفن في المسجد؛ ينبش وينقل إلى المقبرة، ولا يجوز بقاؤه في المسجد -نسأل الله الهداية-.","link":"https://binbaz.org.sa/fatwas/3416/حكم-دفن-الموتى-في-المساجد-واتخاذها-قبورا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1728.mp3","categories":["المساجد ومواضع السجود","حمل الميت ودفنه"]},{"id":7359,"question":"حكم دفن الميت في المسجد، واتخاذه مزارًا، ويستثمروا منه فلوس؟","title":"حكم دفن الموتى في المساجد واتخاذها قبورًا","answer":"الجواب:  هذا منكر، لا يجوز الدفن في المساجد، المساجد ما هي مقبرة، الموتى تدفن خارج المساجد،  في محلات في الصحراء، أما المسجد ما يجوز الدفن فيه، ولا يجوز أن يقام مسجد على القبور، لا يقبر فيه، ولا يقام على القبور الاثنين، يقول النبي ﷺ: لعن الله اليهود والنصارى اتخذوا قبور أنبيائهم مساجد. ويقول ﷺ: ألا وإن من كان قبلكم كانوا يتخذون قبور أنبيائهم وصالحيهم مساجد، ألا فلا تتخذوا القبور مساجد، فإني أنهاكم عن ذلك ينصحون ويعلمون، وإذا دفن في المسجد؛ ينبش وينقل إلى المقبرة، ولا يجوز بقاؤه في المسجد -نسأل الله الهداية-.","link":"https://binbaz.org.sa/fatwas/3416/حكم-دفن-الموتى-في-المساجد-واتخاذها-قبورا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1728.mp3","categories":["المساجد ومواضع السجود","حمل الميت ودفنه"]},{"id":7395,"question":"بعد صلاة العصر يأتي أشخاص، ويحجزون أماكن في المسجد الجامع للمحاضرة، ثم يذهبون إلى السوق، إلى خارج المسجد قبل أذان المغرب، فيأتون في أماكنهم المحجوزة، هل هذا العمل صحيح منهم؟","title":"حكم حجز مكان في الصف الأول","answer":"الجواب:  لا يجوز هذا العمل، الحجز في الصف الأول وهو يذهب لا، هذا ما يجوز، الصف الأول لمن تقدم بنفسه، لا لمن قدم نعليه، أو عصاه، أو ظرف، أو كذا أو كذا، لا، الواجب أن يتقدم بنفسه، ويجلس هو، فإذا تقدم بعصاه الذي يأتي يزيلها، ويجلس مكانه، ليس له أن يتقدم بغير جسمه، المسابقة تكون بالجسم، يتقدم ويجلس في الصف، ويسبح الله، ويذكره، أو يقرأ القرآن وينتظر الصلاة، أما أن يضع شيئًا ويذهب إلى السوق، فإذا جاء الأذان جاء، هذا منكر لا يجوز.  فالواجب على المسلم ترك ذلك، وأن يدع الصف الأول لمن تقدم بنفسه ليجلس في الصف، وينتظر الصلاة، ولا يتقدم بمجرد عصا، أو غيرها من الأشياء التي يضعها في مكانه -نسأل الله الهداية للجميع-. السؤال: وإذا ذهب للوضوء؟ الجواب: هذا فتح باب، يروح يتوضأ وإذا عاد الحمد لله يجلس في المكان الثاني؛ لأن هذا فتح باب، كل واحد يتعذر بهذا، العذر أنا رحت أتوضأ، وأنا رحت أسوي كذا، الحمد لله هو على نيته الطيبة، والحمد لله، وإلا هو أحق به إذا قام يتوضأ ولا جلس، ولكن عرض له عارض، أما أن يأتي وهو ليس متوضئًا، ويحط، ويذهب يتوضأ، لا، يتوضأ قبل ما يأتي. أما إذا كان جالسًا، ولكن عرض له عارض، وذهب يتوضأ؛ فهو أحق بمكانه، من قام من موضعه، ثم عاد إليه؛ فهو أحق به، لكن بعض الناس قد يفعل هذا وهو ما جاء متوضئَا، إنما جاء ناويًا أن يحط هذه العصا، ويذهب، فهذا ما يصلح. السؤال: إذا كان جالسًا في المسجد، ويتقدم، أو يتأخر وهو حاجز مكانًا؟ الجواب: لماذا يتأخر عن مكانه؟ السؤال: يريد يذكر، أو كذا. الجواب: كل هذا تركه أولى؛ لأنه يفتح باب للآخرين، لو ترك ذلك والحمد لله، ولو كان في طرف الصف إذا جاء أولى من وضعه، وإلا هو ما يكون متحجرًا؛ لأنه متقدم، لكن كونه يبتعد عن الصف؛ قد يفتح بابًا لغيره، كل واحد يدعي هذه الدعوى يقول: أنا ما ذهبت، أنا ما رحت، أنا ما فعلت، يختلط الحابل بالنابل، وتقع المشكلة، وتبقى هذه البدعة. السؤال: لو قدر الله أصابه ريح، أو حاجة، وذهب، ورجع في محله ما في بأس؟ الجواب: لا مانع نعم، إذا كان جلس أولًا، جاء متطهرًا، هو ناوي الجلوس، ولكن عرض له هذا العارض، أما واحد يأتي من بيته، ما عنده نية إلا يذهب، يعني ما توضأ ويحط هذا، ويقول: أروح أتوضأ.","link":"https://binbaz.org.sa/fatwas/3483/حكم-حجز-مكان-في-الصف-الاول","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1787.mp3","categories":["المساجد ومواضع السجود","الأخلاق المذمومة"]},{"id":7414,"question":"بعد صلاة العصر يأتي أشخاص، ويحجزون أماكن في المسجد الجامع للمحاضرة، ثم يذهبون إلى السوق، إلى خارج المسجد قبل أذان المغرب، فيأتون في أماكنهم المحجوزة، هل هذا العمل صحيح منهم؟","title":"حكم حجز مكان في الصف الأول","answer":"الجواب:  لا يجوز هذا العمل، الحجز في الصف الأول وهو يذهب لا، هذا ما يجوز، الصف الأول لمن تقدم بنفسه، لا لمن قدم نعليه، أو عصاه، أو ظرف، أو كذا أو كذا، لا، الواجب أن يتقدم بنفسه، ويجلس هو، فإذا تقدم بعصاه الذي يأتي يزيلها، ويجلس مكانه، ليس له أن يتقدم بغير جسمه، المسابقة تكون بالجسم، يتقدم ويجلس في الصف، ويسبح الله، ويذكره، أو يقرأ القرآن وينتظر الصلاة، أما أن يضع شيئًا ويذهب إلى السوق، فإذا جاء الأذان جاء، هذا منكر لا يجوز.  فالواجب على المسلم ترك ذلك، وأن يدع الصف الأول لمن تقدم بنفسه ليجلس في الصف، وينتظر الصلاة، ولا يتقدم بمجرد عصا، أو غيرها من الأشياء التي يضعها في مكانه -نسأل الله الهداية للجميع-. السؤال: وإذا ذهب للوضوء؟ الجواب: هذا فتح باب، يروح يتوضأ وإذا عاد الحمد لله يجلس في المكان الثاني؛ لأن هذا فتح باب، كل واحد يتعذر بهذا، العذر أنا رحت أتوضأ، وأنا رحت أسوي كذا، الحمد لله هو على نيته الطيبة، والحمد لله، وإلا هو أحق به إذا قام يتوضأ ولا جلس، ولكن عرض له عارض، أما أن يأتي وهو ليس متوضئًا، ويحط، ويذهب يتوضأ، لا، يتوضأ قبل ما يأتي. أما إذا كان جالسًا، ولكن عرض له عارض، وذهب يتوضأ؛ فهو أحق بمكانه، من قام من موضعه، ثم عاد إليه؛ فهو أحق به، لكن بعض الناس قد يفعل هذا وهو ما جاء متوضئَا، إنما جاء ناويًا أن يحط هذه العصا، ويذهب، فهذا ما يصلح. السؤال: إذا كان جالسًا في المسجد، ويتقدم، أو يتأخر وهو حاجز مكانًا؟ الجواب: لماذا يتأخر عن مكانه؟ السؤال: يريد يذكر، أو كذا. الجواب: كل هذا تركه أولى؛ لأنه يفتح باب للآخرين، لو ترك ذلك والحمد لله، ولو كان في طرف الصف إذا جاء أولى من وضعه، وإلا هو ما يكون متحجرًا؛ لأنه متقدم، لكن كونه يبتعد عن الصف؛ قد يفتح بابًا لغيره، كل واحد يدعي هذه الدعوى يقول: أنا ما ذهبت، أنا ما رحت، أنا ما فعلت، يختلط الحابل بالنابل، وتقع المشكلة، وتبقى هذه البدعة. السؤال: لو قدر الله أصابه ريح، أو حاجة، وذهب، ورجع في محله ما في بأس؟ الجواب: لا مانع نعم، إذا كان جلس أولًا، جاء متطهرًا، هو ناوي الجلوس، ولكن عرض له هذا العارض، أما واحد يأتي من بيته، ما عنده نية إلا يذهب، يعني ما توضأ ويحط هذا، ويقول: أروح أتوضأ.","link":"https://binbaz.org.sa/fatwas/3483/حكم-حجز-مكان-في-الصف-الاول","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1787.mp3","categories":["المساجد ومواضع السجود","الأخلاق المذمومة"]},{"id":7463,"question":"الأخ أيضاً يستمع دائماً للأذان أو نقل الأذان من المسجد الحرام، فيقول: بالرغم من بعد المسافة نسمع دائماً عند صلاة المغرب والعشاء صريخ وضجيج أطفال في بيت الله الحرام، هل هذا يجوز في هذا المكان أو في أي مسجد من المساجد؟","title":"اصطحاب النساء لأولادهن إلى المساجد","answer":"الجواب:  لا حرج في ذلك؛ لأن من طبيعة الطفل أنه يحصل منه هذا الشيء، وكان الأطفال في عهد النبي ﷺ يسمعهم النبي يسمع صراخهم، ولم يمنع أمهاتهم من الحضور، بل ذلك جائز، ومن طبيعة الطفل أن يحصل له بعض الصراخ، وقد ثبت عنه ﷺ ما يدل على أنه يسمع ذلك ولم يمنع، بل قال: إنه يقوم في الصلاة ويريد تطويلها فيسمع بكاء الصبي فيخفف؛ لئلا تفتتن أمه.  هذا يدل على أنه أقرهن على ذلك، وراعهن في الصلاة أيضاً عليه الصلاة والسلام؛ ولأن منع الأطفال معناه وسيلة إلى منع الأمهات من الحضور، وقد يكون حضورهن فيه فائدة للتأسي بالإمام في الصلاة، والطمأنينة فيها، ومعرفتها كما ينبغي، أو لتسمع فائدة من المكبر أو من إمام في العلم.  فالحاصل: أن حضورها إلى المسجد مع التستر والتحجب والعناية وعدم الطيب فيه فوائد، فإن كانت لا تأتي إلا بتبرج وإظهار محاسنها أو الطيب فلا يجوز لها ذلك، بل صلاتها في بيتها أولى، وبكل حال صلاتها في بيتها أولى وأفضل إلا إذا كان خروجها تستفيد منه فائدة واضحة كالنشاط في قيام رمضان، وكسماع العلم والفائدة، أو التأسي بالإمام في صلاته الراكدة والطمأنينة؛ لأنها تجهل كيفية الصلاة كما ينبغي، فتستفيد صفة الصلاة والطمأنينة فيها، تستفيد سماع المواعظ والذكرى، فهذا قد يعني يجعل خروجها أولى لهذه المصلحة، وإلا فالأصل أن بيتها خير لها، صلاتها في البيت أولى لها.\nأما خروجها متبرجة بالملابس الحسنة الفاتنة، أو بإبراز بعض محاسنها، أو إظهار الطيب الذي يعني قد يسبب الفتنة بمن تمر عليهم، فكل هذا لا يجوز، بل يجب عليها أن تبقى في بيتها ولا تخرج بهذه الأحوال التي تفتن الناس وتضر الناس.\nأما الطفل فلا بأس بوجوده معها، لكن تتحفظ منه، وتجعله في محل محفوظ حتى لا يقذر المسجد ولا يؤذي المصلين، وإذا دعت الحاجة إلى حمله عند الحاجة ليسكت فلا بأس، فقد حمل النبي ﷺ أمامة بنت زينب ، حملها وهو يصلي بالناس عليه الصلاة والسلام.\nفالحاصل: أن وجود الأطفال في المسجد وحملهن حتى في الصلاة لا حرج فيه عند الحاجة؛ ولكن ينبغي أن يراعى في ذلك سلامة الطفل من النجاسات حتى لا ينجس أمه.\nالمقدم: أحسنتم.","link":"https://binbaz.org.sa/fatwas/4181/اصطحاب-النساء-لاولادهن-الى-المساجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_001/00105.mp3","categories":["المساجد ومواضع السجود","سترة المصلي"]},{"id":7504,"question":"سؤاله الآخر يقول: هل يجوز من حضر إلى المسجد متأخر وصلى تحية المسجد أمام وجه مصلي آخر، أو ضايقه حتى كاد يخرج من مكانه، وفي بعض الحالات يخرج ويترك المكان له، وهذا كثير ما يحدث، والبعض يضع سجادة أو إحرامه ويذهب للطواف ليحجز المكان في المسجد الحرام، نرجو الإفادة عن هذين النقطتين؟","title":"حكم مضايقة المصلين في الصفوف وحجز الأماكن","answer":"الجواب: ليس للمؤمن أن يضايق أخاه في الصف، بل يصلي حيث انتهى، بل يقف ويصف مع الناس حيث انتهى الصف، وليس له أن يفرق بين اثنين كما جاءت به النصوص، لكن إذا وجد فرجة تسع له فإنه لا بأس أن يدخل فيها ويسدها؛ لأن المسلمين مأمورون بسد الفرج وبالتراص في الصفوف، وله أن يصلي إذا كان أمامه أحد له أن يصلي تحية المسجد أو الراتبة، وإن كان أمامه شخص جالس كالإمام ونحو ذلك لا بأس، لا حرج عليه في ذلك، وإنما يجب عليه أن يلاحظ عدم الإيذاء لإخوانه المسلمين، بل يصف مع الناس حيث انتهت الصفوف، ولا يؤذي الناس بمضايقتهم في الصفوف ما لم يجد فرجة ... تسع له، فلا بأس أن يسدها كما هو مأمور بذلك. نعم.\nالمقدم: طيب! وبالنسبة لحجز المكان بسجادة؟\nالشيخ: كذلك حجز المكان؛ ليس له حجز المكان، ليس لأحد أن يحجز المكان لا في يوم الجمعة ولا في غيره، بل ينبغي له أن يأتي إلى الصلاة على نية الإقامة في المسجد حتى يصلي مع الناس، أما أنه يأتي يحط يجعل في المكان سجادة أو شيئاً آخر حتى يرجع، يذهب إلى بيته، أو إلى الطواف، أو إلى شيء آخر ثم يرجع ليس له ذلك؛ لأن هذا يمنع منه المتقدمين إلى الصلاة وإلى الصفوف، فالواجب على المؤمن أن يدع هذه الأمور، وأن يقصد الصلاة ليقيم في المسجد لا ليضع عمامة أو عباءة أو سجادة أو غير ذلك ثم يخرج لحاجاته الأخرى. نعم.","link":"https://binbaz.org.sa/fatwas/4465/حكم-مضايقة-المصلين-في-الصفوف-وحجز-الاماكن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_008/00803.mp3","categories":["المساجد ومواضع السجود","سترة المصلي"]},{"id":7506,"question":"سؤاله الأخير يقول: هل يجوز دخول المسجد والجلوس فيه دون الصلاة حتى يؤذن؟ أرجو إفادتي جزاكم الله خير الجزاء.","title":"حكم دخول المسجد للراحة والنوم","answer":"الجواب: لا بأس أن يدخل المسجد ويجلس فيه للراحة أو للنوم؛ القائلة، أو ما أشبه ذلك، لا بأس بذلك، فقد كان بعض الصحابة ينام في المسجد في عهد النبي عليه الصلاة والسلام، ولكن ليس له أن يجلس.. ما ينبغي له الجلوس إلا بعد التحية إذا كان على طهارة، إذا كان على وضوء يصلي ركعتين ثم يجلس، أما إن كان على غير طهارة فلا حرج عليه يجلس والحمد لله، ولا حرج في ذلك.","link":"https://binbaz.org.sa/fatwas/4467/حكم-دخول-المسجد-للراحة-والنوم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_008/00805.mp3","categories":["المساجد ومواضع السجود","سترة المصلي"]},{"id":7624,"question":"السؤال الثاني من المستمع عبد الله إبراهيم بخاري من مكة المكرمة يقول: ما حكم المرور بين يدي المصلي في المسجد الحرام، وهل الحديث خاص في المسجد الحرام أم يشمل مكة ومساجدها؟ وهل يأثم من مر بين المصلي من غير قصد وليس متعمداً؟","title":"ما حكم المرور بين يدي المصلي في المسجد الحرام؟","answer":"الجواب: أما المسجد الحرام الذي حول الكعبة، فالمعروف عند أهل العلم: أنه لا حرج في المرور بين يديه للحاجة؛ لأن الغالب هو الزحمة فيه، ومظنة عدم تيسر السترة والسلامة من المار، فالأمر فيه واسع، وهكذا عند الازدحامات في المسجد النبوي وغيرها من المساجد، إذا ازدحم الناس وتكاثر الناس ولم يتيسر للمسلم المرور إلا بين أيدي المصلين، فالظاهر والله أعلم أنه لا حرج في ذلك للضرورة والمشقة الكبيرة. \nوينبغي للمصلي أن يتحرى المكان الذي ليس فيه تعرض للمرور بين يديه، في لزوم السواري التي في المسجد وأشباهها حتى يكون بعيداً عن المرور بين يديه، أما مساجد مكة وأرضها فالظاهر أنها كغيرها، ولهذا لما صلى النبي صلى الله عليه وسلم بالأبطح جعل أمامه العنزة، وصلى إلى عنزة عليه الصلاة والسلام وهو في الأبطح في المسجد الحرام، فدل ذلك على أن المسجد الحرام مثل غيره في اتخاذ السترة، يعني بقية الحرم؛ لأن الحرم كله يسمى مسجد حرام، لكن ما كان حول الكعبة فالأمر فيه أوسع وأسهل للزحمة غالباً، ولما جاء في ذلك من الآثار عن بعض الصحابة في عدم توقي مرور الناس؛ لأنه موضع زحمة في الغالب، مظنة عدم القدرة على السلامة من المار؛ ولأن في السترة ورد الناس مشقة على الطائفين وعلى غير الطائفين، فالأولى والأقرب والأرجح أنه لا حرج في ذلك إن شاء الله، ولا لزوم للسترة، لكن في بقية مكة في بقية الحرم ويسمى المسجد الحرام ينبغي اتخاذ السترة ومنع المار كما اتخذها النبي صلى الله عليه وسلم في الأبطح عليه الصلاة والسلام. نعم.","link":"https://binbaz.org.sa/fatwas/4677/ما-حكم-المرور-بين-يدي-المصلي-في-المسجد-الحرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_024/02407.mp3","categories":["المساجد ومواضع السجود","سترة المصلي"]},{"id":7626,"question":"هذه الرسالة وردتنا من القنفذة من معهد المعلمين وباعثها هو أحمد سعيد العمري ، يقول في رسالته بعد الشكر والثناء على المتصدين للإجابة على أسئلة المستمعين واستفساراتهم: أرجو من الله ثم منكم توضيح هذه المسألة توضيحاً دقيقاً، وهي أنه يوجد بقريتنا مسجد جامع، وهذا المسجد واقع وسط المقابر التي تحيط به من الشمال والجنوب، والمسافة بينه وبين الجهة الشمالية مترين وكذلك الجنوبية مترين، وأن تلك المقابر في طريقها للتوسع، كما أن بعض المصلين هداهم الله يجعلون تلك المقابر مواقف لسياراتهم، أخبرونا جزاكم الله عنا كل خير في الحكم في مثل ذلك، ولكم جزيل الشكر والتقدير؟","title":"حكم المسجد المجاور للقبور ووقوف السيارات على القبور","answer":"الجواب: الظاهر أنه لا يضر ذلك شيئاً؛ لأن هذا عادة جارية في كثير من البلدان يدفنون حول المساجد، فلا يضر ذلك شيئاً، المقصود أن من عادة بعض الناس في بعض البلدان يدفنون حول المساجد؛ لأنه أسهل عليهم، إذا خرجوا من المسجد دفنوا حول المسجد، فلا يضر ذلك شيئاً ولا يؤثر في صلاة المصلين، لكن إذا كان في قبلة المسجد شيئاً من القبور فالأحوط أن يكون بين المسجد وبين المقبرة جدار آخر غير جدار المسجد، هذا هو الأحوط والأولى، ليكون ذلك أبعد عن استقبالهم للقبور، أما إن كان عن يمين المسجد وعن شماله، عن يمين المصلين أو عن شمالهم فلا يضر ذلك شيئاً؛ لأنهم لا يستقبلونها، أما إذا كان في القبلة فالأولى أن يكون هناك جدار آخر غير جدار المسجد إذا تيسر ذلك؛ لأن هذا أبعد عن استقبالها وعن شبهة الاستقبال. نعم. \nالمقدم: لكن بالنسبة لما سأل عنه المستمع وهو إيقاف السيارات؟\nالشيخ: أما إيقاف السيارات فلا يجوز إيقافها على القبور، بل تكون بعيدة عن القبور، تكون في الأراضي السليمة التي ليس فيها قبور، أما كونهم يمتهنون القبور، ويقفون السيارات على القبور هذا منكر لا يجوز، بل الواجب أن يبعدوها عن القبور وأن تكون في محلات سليمة ليس فيها قبور. نعم.","link":"https://binbaz.org.sa/fatwas/4680/حكم-المسجد-المجاور-للقبور-ووقوف-السيارات-على-القبور ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_025/02502.mp3","categories":["المساجد ومواضع السجود"]},{"id":7682,"question":"أيضاً يقول حمد مسعود فضل السيد من السودان: هل يجوز السلام على الجالسين في المسجد قبل تحية المسجد وجزاكم الله خير؟","title":"حكم السلام على الجالسين قبل أن يصلي تحية المسجد","answer":"الجواب: نعم إذا دخل المسجد وأتى الصف يقول: السلام عليكم، قبل أن يبدأ بالصلاة، السلام عليكم على الحاضرين ولو كانوا يصلون، والمصلي يرد بالإشارة يشير بيده كالمصافح يرد بالإشارة كما فعله النبي عليه الصلاة والسلام، ثم يكبر لتحية المسجد يصلي تحية المسجد. نعم.","link":"https://binbaz.org.sa/fatwas/4879/حكم-السلام-على-الجالسين-قبل-ان-يصلي-تحية-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_040/04007.mp3","categories":["المساجد ومواضع السجود"]},{"id":7687,"question":"أيضاً يقول: هل يجوز لغير المسلمين وهم المشركون والشيوعيون دخول المساجد، فهناك من يقول: يجوز لهم دخول المساجد، نرجو الإفادة لعل الله يهديهم، وهناك من يقول: لا يجوز لهم؟","title":"حكم دخول الكافر المسجد","answer":"الجواب: أما المسجد الحرام فلا يجوز دخول المسجد الحرام لجميع الكفرة، من اليهود والنصارى وعباد الأوثان والشوعيين ، جميع الكفرة لا يجوز لهم دخول المسجد الحرام؛ لأن الله سبحانه يقول: يَا أَيُّهَا الَّذِينَ آمَنُوا إِنَّمَا الْمُشْرِكُونَ نَجَسٌ فَلا يَقْرَبُوا الْمَسْجِدَ الْحَرَامَ بَعْدَ عَامِهِمْ هَذَا [التوبة:28] الآية، فمنع سبحانه من دخولهم المسجد الحرام، والمشركون يدخل فيهم اليهود والنصارى عند الإطلاق، فلا يجوز دخول أي مشرك المسجد الحرام لا يهودي ولا نصراني ولا غيرهما، بل هذا خاص بالمسلمين، وأما بقية المساجد فلا بأس بدخول المسجد لحاجة ومصلحة، ومن ذلك المدينة وإن كانت المدينة يعني لها خصوصية، لكنها في هذه المسألة مثل غيرها من المساجد؛ لأن الرسول ﷺ ربط فيها ثمامة بن أثال وهو كافر في مسجد النبي ﷺ، وأقر وفد ثقيف حين دخلوا المسجد قبل أن يسلموا، وهكذا وفد النصارى دخلوا مسجده عليه الصلاة والسلام، فدل ذلك على أنه يجوز دخول المسجد النبوي للمشرك، وهكذا بقية المساجد إذا كان لحاجة إما لسؤال أو لحاجة أخرى أو لسماع درس يستفيد أو ليسلم ليعلن إسلامه أو ما أشبه ذلك. \nفالحاصل أنه يجوز دخوله إذا كان هناك مصلحة، أما إذا كان ما هناك مصلحة فلا حاجة إلى دخوله المسجد، أو يخشى من دخوله عبث في المسجد أو فساد في المسجد أو نجاسة يمنع. نعم.","link":"https://binbaz.org.sa/fatwas/4886/حكم-دخول-الكافر-المسجد ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_027/02706.mp3","categories":["المساجد ومواضع السجود"]},{"id":7700,"question":"يقول في سؤاله الثاني: ما حكم البناء على القبر؟ ويقصد بذلك بناء المسجد؟","title":"حكم بناء المساجد على القبور والعكس","answer":"الجواب: أما البناء على القبور فهو محرم سواء كان مسجداً أو قبة أو أي بناء، لا يجوز ذلك؛ لأن الرسول ﷺ لعن اليهود قال: لعن الله اليهود والنصارى اتخذوا قبور أنبيائهم مساجد فعلل اللعنة باتخاذهم المساجد على القبور، فدل ذلك على تحريم البناء على القبور وأنه لا يجوز، واتخاذها مساجد من أسباب الفتنة بها؛ لأنها إذا وضعت عليها المساجد افتتن بها الناس، وربما دعوها من دون الله واستغاثوا بأهلها فوقع الشرك، وفي حديث جندب بن عبد الله البجلي عند مسلم في صحيحه يقول النبي ﷺ: ألا وإن من كان قبلكم كانوا يتخذون قبور أنبيائهم وصالحيهم مساجد، ألا فلا تتخذوا القبور مساجد، فإني أنهاكم عن ذلك هكذا يقول النبي ﷺ، يحذرنا من اتخاذ المساجد على القبور. \nفينبغي لأهل الإسلام أن يحذروا ذلك، بل الواجب عليهم أن يحذروا ذلك، وفي حديث جابر عند مسلم عن النبي ﷺ أنه نهى عن تجصيص القبور وعن القعود عليها وعن البناء عليها، فالبناء عليها منهي عنه مطلقاً، واتخاذ المساجد والقباب عليها كذلك؛ لأن ذلك من وسائل الشرك، إذا بني على القبر المسجد أو القبة أو نحو ذلك عظمه الناس وفتن به الناس، وصار من أسباب الشرك به، ودعاء أصحاب القبور من دون الله عز وجل، كما هو واقع في دول كثيرة وبلدان كثيرة، عظمت القبور وبنيت عليها المساجد، وصار الجهلة يطوفون بها ويدعونها ويستغيثون بأهلها وينذرون لهم، ويتبركون بقبورهم، ويتمسحون بها، كل هذا وقع بأسباب البناء على القبور واتخاذ المساجد عليها، وهذا من الغلو الذي حرمه الله، يقول النبي ﷺ: إياكم والغلو في الدين، فإنما أهلك من كان قبلكم الغلو في الدين، وقال: هلك المتنطعون، هلك المتنطعون، هلك المتنطعون يعني: المتشددون الغالون. \nوالخلاصة: أنه لا يجوز البناء على القبور لا مسجد ولا غير مسجد ولا قبة، وأن هذا من المحرمات العظيمة ومن وسائل الشرك، فلا يجوز فعل ذلك، وإذا وقع فالواجب على ولاة الأمور إزالته وهدمه وألا يبقى على القبور مساجد ولا قباب، بل تبقى ضاحية مكشوفة كما كان هذا في عهد النبي ﷺ وفي عهد أصحابه رضي الله عنهم وأرضاهم والسلف الصالح، ولأن بناءها -بناء المساجد على القبور- من وسائل الشرك، كذلك القباب والأبنية الأخرى كلها من وسائل الشرك فلا تجوز، بل الواجب إزالتها وهدمها؛ لأن ذلك هو مقتضى أمر النبي ﷺ، فهو أمر عليه الصلاة والسلام بأن تزار القبور للذكرى والعظة، ونهى عن البناء عليها واتخاذ المساجد عليها؛ لأن هذا يجعلها مساجد تعبد من دون الله، يجعلها آلهة، يجعلها أوثان تعبد من دون الله، فوجب امتثال أمره بالزيارة، يعني شرع لنا أن نمتثل أمره بالزيارة.. شرع، زيارة القبور مستحبة، يشرع لنا أن نزورها للذكرى والدعاء لأهلها بالمغفرة والرحمة، لكن لا نبني عليها لا مساجد ولا قباب، ولا أبنية أخرى؛ لأن البناء عليها من وسائل الشرك والفتنة بها. نعم. \nالمقدم: هو سأل سؤال ثالث، لكن دخلت الإجابة ويقول: ما حكم وضع القبر قبلة المسجد داخله، وقد تكلمتم..\nالشيخ: هذا.\nالمقدم: إيه نعم، أما سؤاله الرابع فيقول: سمعنا في برنامجكم ... \nالشيخ: هنا مسألة أخرى وهي: وضع القبور في المساجد، كونه يدفن الميت في المسجد هذا لا يجوز أيضاً، بعض الناس إذا مات قال: ادفنوني في المسجد، هذا لا يجوز دفنه في المسجد، بل يجب أن ينبش وينقل إلى المقبرة، إذا دفن في داخل المسجد ينبش وينقل للمقبرة، ولا يجوز بقاءه في المسجد أبداً، هذا هو الواجب على أهل الإسلام ألا يدفنوا في المساجد، يعني ليس لأحد أن يدفن في المسجد بل إذا دفن أحد في المسجد ينبش وينقل إلى المقبرة العامة. نعم.","link":"https://binbaz.org.sa/fatwas/4899/حكم-بناء-المساجد-على-القبور-والعكس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_029/02902.mp3","categories":["المساجد ومواضع السجود"]},{"id":7721,"question":"أيضاً يقول: هل المحراب بدعة في المسجد، أم لا؟","title":"حكم اتخاذ المحراب في المسجد","answer":"الجواب: ليس المحراب بدعة، بل فعله السلف الصالح من آخر القرن الأول إلى يومنا هذا، وفيه فوائد: فإنه يوضح أن هذا مسجد، ويوضح القبلة، يستفيد منه الناس لمعرفة القبلة، وقد يحتاج إليه في زيادة صف إذا دخل فيه الإمام عند الحاجة وعند الضيق، فليس ببدعة، وفيه فوائد طيبة. نعم.","link":"https://binbaz.org.sa/fatwas/4920/حكم-اتخاذ-المحراب-في-المسجد ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_031/03107.mp3","categories":["المساجد ومواضع السجود"]},{"id":7745,"question":"آخر رسالة معنا وردتنا من المستمع وصيم محمد أحمد عسيري وعلي أحمد زاهد الفيفي يقول: إني قد بنيت مسجد في أحد الحارات من الخشب، وقد نقلت إلى حارة أخرى، ولم يبق أحد في الحارة، وقد نقلت المسجد معي إلى الحارة الأخيرة، فهل علينا من نقله شيء من الذنب؟ أفيدونا وفقكم الله.","title":"حكم نقل المساجد وتحويل مقتنياتها","answer":"الجواب: إذا انتقل الناس من حارة إلى حارة -من حارة قديمة إلى حارة جديدة- ولم يبق في الحارة أحد يصلي في المسجد فإنه ينقل إلى الحارة الجديدة، لا مانع من نقضه ونقل أخشابه وأدواته إلى المسجد الجديد، ثم يباع محله، يباع ويصرف الثمن في تعمير المسجد الجديد، أو لتعمير مسجد آخر؛ لأن بقاءه حينئذ تعطيل بلا فائدة، إذا انتقل الناس من حارة إلى حارة.. من مكان إلى مكان وبقيت مساجد الحارة خالية ليس فيها أحد يصلي فيها فإنها تهدم وتنقل أدواتها إلى المساجد الأخرى للعمارة أو تباع وتصرف قيمتها في تعمير مساجد جديدة يحتاجها المسلمون في حارات أخرى، هذا هو الواجب ولا تعطل أبداً..","link":"https://binbaz.org.sa/fatwas/4948/حكم-نقل-المساجد-وتحويل-مقتنياتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_042/04206.mp3","categories":["المساجد ومواضع السجود"]},{"id":7805,"question":"هذه سائلة للبرنامج تقول: ما حكم الصلاة في غرفة يوجد بها عرائس وغيرها من الألعاب الأطفال المجسمة لذوات الأرواح؟","title":"حكم الصلاة في غرفة بها ألعاب على شكل عرائس","answer":"الجواب: لا حرج في ذلك الصلاة في غرفة التي فيها لعب، لا حرج في ذلك إذا لم تشغل، إذا لم تكن أمامه تشغله تشوش عليه فلا بأس، لكن الأفضل أن يعطى الصبية الصغار ألعاباً أخرى غير الصور، الصور فيها أحاديث عظيمة تدل على وجوب طمسها وإتلافها، فالأحوط للمؤمن والمؤمنة أن يتخذوا للصبية الصغار ألعاباً أخرى، ولكن الصلاة في الغرفة التي فيها ألعاب لا تشوش على المصلي لا حرج عليه في ذلك. نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/5185/حكم-الصلاة-في-غرفة-بها-العاب-على-شكل-عراىس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_051/05104.mp3","categories":["المساجد ومواضع السجود"]},{"id":7814,"question":"هذا سائل أرسل بمجموعة من الأسئلة يقول: سؤالي الأول: إذا دخلت المسجد والمؤذن ينادي للصلاة هل أصلي ركعتين تحيةً للمسجد أم أنتظر حتى ينتهي المؤذن من الأذان؟","title":"حكم من دخل المسجد والمؤذن يؤذن للصلاة","answer":"الجواب: الأفضل أن .... المؤذن، تنتظر تجيب المؤذن ثم تصلي ركعتين حتى تجمع بين الحسنيين وبين الفضيلتين وبين الأمر المشروع، تبدأ بالأذان تجيب المؤذن ثم تصلي ركعتين. نعم.","link":"https://binbaz.org.sa/fatwas/5204/حكم-من-دخل-المسجد-والموذن-يوذن-للصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_051/05122.mp3","categories":["المساجد ومواضع السجود","الأذان والإقامة"]},{"id":7823,"question":"هذه سائلة للبرنامج تقول: ما حكم الصلاة في غرفة يوجد بها عرائس وغيرها من الألعاب الأطفال المجسمة لذوات الأرواح؟","title":"حكم الصلاة في غرفة بها ألعاب على شكل عرائس","answer":"الجواب: لا حرج في ذلك الصلاة في غرفة التي فيها لعب، لا حرج في ذلك إذا لم تشغل، إذا لم تكن أمامه تشغله تشوش عليه فلا بأس، لكن الأفضل أن يعطى الصبية الصغار ألعاباً أخرى غير الصور، الصور فيها أحاديث عظيمة تدل على وجوب طمسها وإتلافها، فالأحوط للمؤمن والمؤمنة أن يتخذوا للصبية الصغار ألعاباً أخرى، ولكن الصلاة في الغرفة التي فيها ألعاب لا تشوش على المصلي لا حرج عليه في ذلك. نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/5185/حكم-الصلاة-في-غرفة-بها-العاب-على-شكل-عراىس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_051/05104.mp3","categories":["المساجد ومواضع السجود"]},{"id":7885,"question":"أيضاً يقول: في حضرموت عندنا توجد مساجد للنساء ملاصقة تماماً لمساجد الرجال، حيث تصلي فيها النساء الفرائض - وقد رسم في الورقة جزاه الله خير رسماً يوضح المسجدين- والسؤال هو: هل للنساء مساجد؟الشيخ: يعني: في مؤخر المسجد .......... ؟المقدم: إيه نعم، وضع لا، على يسار المسجد، رسمه على يسار المسجد محاذ للمحراب، أو يقصر عن المحراب شيئاً بسيطاً، ويقول: أيضاً يوجد باب يفصل مسجد النساء عن مسجد الرجال، وحينما تقوم الصلاة يفتح الباب وتصلي النساء مع الرجال، الباب الذي بين المسجد وبين مسجد النساء، يفتح الباب وتصلي النساء مع الرجال في مسجدهن علماً بأنهن لسن خلف الرجال بل موازين تماماً مثل اللون الأحمر في الرسم ووضع لون أحمر داخلاً في المسجد اللي هو مسجد الرجال وخارج مسجد النساء، يعني: موازنات للرجال وخلف الإمام.الشيخ: صفوف الرجال؟المقدم: إيه نعم.الشيخ: موازنات لصفوف الرجال؟المقدم: نعم ولكنه خلف الإمام.","title":"حكم مصلى النساء المحاذي للرجال مع وجود جدار فاصل","answer":"الجواب: إيه، لا نعلم لهذا أصل أنه يوجد لهن مساجد، وإنما المعروف أنهن يصلين خلف الرجال في مؤخر المسجد، هذا هو الأولى أن يكن في مؤخر المسجد خلف الرجال هذه السنة، أن يكن خلف الرجال في مؤخر المسجد، لكن هؤلاء إذا جعلوا عن يمين الرجال أو عن شمال الرجال فلا بأس يصح؛ لأنهم ليسوا مخالطين للرجال فيصح أن يكونوا معهم في هذا، إذا كانت صفوفهن تواري صفوف الرجال من جهة اليمين أو الشمال فإن الصلاة صحيحة حينئذٍ، صلاتهم صحيحة ولا حرج في ذلك.\nلكن الأفضل والأولى أن تكون مصلياتهم خلف الرجال في مؤخر المساجد وأن يكون بينهم وبين الرجال شيئاً من الستر أن يكون حسناً حتى يتمكن من الصلاة من غير تعب ولا مشقة، إذا كان بينهن وبين الرجال ستور، لكنه لا يمنع من رؤيتهن المأمومين ولا يمنع من سماع صوت الإمام، هذا هو الأفضل، لكن وجودهن عن يمين الصفوف أو عن شمال الصفوف مثلما ذكر هنا لا حرج فيه إن شاء الله، نعم؛ لأنهن يستفدن من صلاة الإمام ومن الخطبة ومما قد يقع من المواعظ هذا كله لا بأس به، والنبي عليه السلام قال: لا تمنعوا إماء الله مساجد الله لكن عليهن أن يخرجن في غير تبرج ولا طيب ولا تكشف حتى لا يفتن الرجال. نعم.","link":"https://binbaz.org.sa/fatwas/5355/حكم-مصلى-النساء-المحاذي-للرجال-مع-وجود-جدار-فاصل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_059/05903.mp3","categories":["المساجد ومواضع السجود"]},{"id":7904,"question":"وردتنا رسالة من مستمعين من القصيم، الأول: ناصر السعود الشهيد وعيد بن فهيد ، يقولان في هذه الرسالة: هل يجوز أن يكون المسجد على شكل رباعي أو سداسي؟","title":"حكم بناء المسجد بشكل رباعي أو سداسي","answer":"الجواب: ما نعلم في هذا شيء، لا نعلم شيئاً في كونه رباعي أو سداسي، المهم أن يكون على هيئة المساجد الواضحة، بمحرابه وطريقه والشكل الذي يناسب الصفوف، لا يكون فيها اعوجاج، ولا يكون بها مضايقات، تكون الصفوف كاملة ومستقيمة، أما أشكال البناء أمرها واسع، أشكال البناء أمرها واسع، لا نعلم في شكل البناء شيئاً خاصاً، لكن يراد من هذا: أن تكون البناية واسعة للمصلين، والصف والصفوف تكون منتظمة مستقيمة على سمت واحد، حيث إذا رآه الناس أو دخله الناس عرفوا أنه مسجد، يعني يكون واضح، بناية مسجد واضحة على عرف البلاد وطريقة البلاد التي فيها مساجد. نعم.","link":"https://binbaz.org.sa/fatwas/5395/حكم-بناء-المسجد-بشكل-رباعي-او-سداسي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_062/06204.mp3","categories":["المساجد ومواضع السجود"]},{"id":7914,"question":"وردتنا رسالة من مستمعين من القصيم، الأول: ناصر السعود الشهيد وعيد بن فهيد ، يقولان في هذه الرسالة: هل يجوز أن يكون المسجد على شكل رباعي أو سداسي؟","title":"حكم بناء المسجد بشكل رباعي أو سداسي","answer":"الجواب: ما نعلم في هذا شيء، لا نعلم شيئاً في كونه رباعي أو سداسي، المهم أن يكون على هيئة المساجد الواضحة، بمحرابه وطريقه والشكل الذي يناسب الصفوف، لا يكون فيها اعوجاج، ولا يكون بها مضايقات، تكون الصفوف كاملة ومستقيمة، أما أشكال البناء أمرها واسع، أشكال البناء أمرها واسع، لا نعلم في شكل البناء شيئاً خاصاً، لكن يراد من هذا: أن تكون البناية واسعة للمصلين، والصف والصفوف تكون منتظمة مستقيمة على سمت واحد، حيث إذا رآه الناس أو دخله الناس عرفوا أنه مسجد، يعني يكون واضح، بناية مسجد واضحة على عرف البلاد وطريقة البلاد التي فيها مساجد. نعم.","link":"https://binbaz.org.sa/fatwas/5395/حكم-بناء-المسجد-بشكل-رباعي-او-سداسي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_062/06204.mp3","categories":["المساجد ومواضع السجود"]},{"id":8002,"question":"هذه الرسالة وردتنا من سليمان العثمان يقول في رسالته: بسم الله الرحمن الرحيم.أصحاب الفضيلة! السلام عليكم ورحمة الله وبركاته. وبعد: ما حكم الجهر بتلاوة القرآن الكريم في المسجد، وهل هناك أحاديث تتعلق بالقراءة السرية أو الجهرية؟","title":"حكم الجهر بقراءة القرآن في المسجد","answer":"الجواب: لا حرج في الجهر بالقراءة في المساجد، لا بأس أن يجهر الإنسان بالقراءة، لكن جهراً لا يؤذي أحداً، أما إذا كان حوله مصلون أو حوله قراء فإنه يقرأ قراءة لا تؤذيهم، ولا تلبس عليهم صلاتهم وقراءتهم، يخفض صوته، حتى لا يؤذيهم، أما إذا كان حوله أناس يستمعون له وينتفعون بقراءته فلا بأس أن يرفع صوته حتى يسمعهم وحتى يستفيدوا إذا كان لا يؤذي أحداً من القراء الذين حوله ولا المصلين الذين حوله، فينبغي أن يعلم هذا.\nوقد ثبت عنه ﷺ أنه خرج ذات يوم على جماعة في مسجد في الليل يتهجدون ويقرءون جهراً فقال لهم: لا يؤذي بعضكم بعضا، كلكم يناجي ربه فأمرهم أن يخفضوا أصواتهم حتى لا يؤذي بعضهم بعضاً، هكذا ينبغي، إذا كان الإنسان يقرأ وعنده قراء أو مصلون فإنه لا يرفع رفعاً يؤذيهم، ويلبس عليهم قراءتهم أو صلاتهم لا، بل يخفض صوته خفضاً ينفعه ولا يضرهم، أما إذا كان حوله أناس يستمعون له .. يستمعون لقراءته فإنه يجهر جهراً يفيدهم وينفعهم ولا يضر غيرهم. نعم.","link":"https://binbaz.org.sa/fatwas/5557/حكم-الجهر-بقراءة-القران-في-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_074/07404.mp3","categories":["المساجد ومواضع السجود"]},{"id":8007,"question":"أيضاً لديه سؤال آخر يقول: ما حكم النوم في المسجد؟","title":"حكم النوم في المسجد","answer":"الجواب: النوم في المسجد لا حرج فيه ولا بأس به، فهي بيوت الله أقيمت للعبادة، والنوم لا يمنع في ذلك، فقد يكون النوم عبادة إذا أريد به التقوية على طاعة الله، وقد نام الصحابة في مسجد النبي ﷺ أهل الصفة وغيرهم، ونام علي في المسجد لما صار بينه وبين زوجته بعض الشيء، فجاءه النبي ﷺوهو في المسجد فأيقظه وقال له: قم أبا تراب .. قم أبا تراب لما رأى التراب عليه عليه الصلاة والسلام، وكان ابن عمر ينام في المسجد بعض الأحيان، فالحاصل أنه لا حرج في ذلك.","link":"https://binbaz.org.sa/fatwas/5573/حكم-النوم-في-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_075/07506.mp3","categories":["المساجد ومواضع السجود"]},{"id":8017,"question":"سؤالها الثاني تقول: تأتي لي العادة بكذا من الأيام في الشهر وتنقطع عني، لكن نص السؤال تقول: إننا ذهبنا إلى مكة المكرمة وقد أتتني العادة الشهرية، وحيث أنه لا يوجد لدينا في مكة من أبقى عنده فقد دخلت في الحرم وجلست فيه، هل علي شيء أم لا وشكراً لكم؟","title":"حكم مكوث الحائض في المسجد","answer":"الجواب: الواجب على من أصابها الحيض أن تبقى في محلها .. في مخيمها .. منزلها في الأبطح أو في غيره ولا تأتي إلى المسجد؛ لأن دخول الحائض المسجد لا يجوز إلا على سبيل المرور والعبور، وأما الجلوس عمداً في المسجد الحرام أو غيره من المساجد ما يجوز، لكن لو اضطرت لو جاءت وهي سليمة ليس فيها حيض ثم بليت بالحيض وهي في المسجد ولا تعرف أحداً تذهب إليه فإن الأولى بها أن تخرج وتجلس عند باب المسجد حتى يفرغ أصحابها ولا تجلس في المسجد، تعدهم باباً معروفاً فتجلس فيه حتى يأتوا وتذهب معهم مهما استطاعت إلى ذلك سبيلا، ولا تجلس في المسجد وهي حائض؛ لأن الرسول نهى عن ذلك عليه الصلاة والسلام قال: لا أحل المسجد لحائض ولا جنب فالمسجد لا يجلس فيه، لا يجلس فيه الحائض ولا الجنب، لكن عابر السبيل الذي يمر مرور لا بأس بذلك، فهي تجتهد وتحرص على أن تنتظرهم خارج المسجد عند الأبواب. نعم.","link":"https://binbaz.org.sa/fatwas/5578/حكم-مكوث-الحاىض-في-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_076/07605.mp3","categories":["المساجد ومواضع السجود","الحيض والنفاس","قضايا المرأة"]},{"id":8102,"question":"هذه الرسالة وردتنا من أحد السادة المستمعين، ويقول فيها: بعد أرجو من فضيلتكم إفادتي عن السؤال التالي: فيه مسجد مجاور لبيتنا ومضر علينا، وهو خرب من آثار السيول، ومهجور من الصلاة من مدة عام ونصف، ولم يصل فيه؛ لأنه أنشئ مسجد جديد غيره جامع، وقد أردت أن أهدمه، ولكن عارض علي بعض الناس، أنه لا يجوز هدم المسجد هذا. أرجو من فضيلتكم إفادتي بذلك؛ لأنه مضر علينا موقعه، هذا والله يحفظكم ويرعاكم مترك حنش مقعد الرشيدي ؟","title":"حكم هدم المسجد المستغنى عنه والمهجور","answer":"الجواب: إذا كان هذا المسجد قد استغني عنه بمسجد جديد، وما بقي له حاجة، فإنه يباع، ويصرف ثمنه في مسجد آخر، في تعمير مساجد أخرى؛ لأنه وقف سبل، لا يجوز التصرف فيه إلا على الوجه الشرعي، فيستفتي جيرانه أو من يرغب في شرائه يستفتون القاضي قاضي البلد، وقاضي البلد يوكل من يتولى بيعه، فإن كان ما فيه قاضي، فالأمير، أمير البلد الذي يرأس البلد وهو أميرها، فيوكل أميرها إذا لم يوجد القاضي، فإن وجد القاضي فالقاضي، فيوكل من يعرضه على أهل الرغبة من الجيران ويبيعه على أرفعهم سوماً، إذا استقر السوم يبيع عليه، وهذا الثمن يصرف في مساجد أخرى، ترميم مساجد أو تعمير مساجد في محلات محتاجة، يعني: في أماكن محتاجة للمساجد، هذا هو الواجب.\nأما إن كان هذا المسجد يحتاجه جيرانه؛ لأن المسجد الجديد بعيد عنهم، ويحتاجه جيرانه، فإنه يعمر من المحسنين ويصلي فيه المسلمون الذين حوله، فإن لم يتيسر من يعمره، يرفع أمره إلى وزارة الأوقاف في البلد لعلها تقوم بتعميره، ويزول هجره، وينتفع به من حوله، هذا هو الجواب في هذه المسألة. نعم.","link":"https://binbaz.org.sa/fatwas/5898/حكم-هدم-المسجد-المستغنى-عنه-والمهجور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_087/08702.mp3","categories":["المساجد ومواضع السجود"]},{"id":8267,"question":"ننتقل إلى رسالة أخرى ومواضيع أخرى، وأولى هذه الرسائل رسالة من أخ يقول: (د. ف. ل. ب) مصري مقيم في المملكة، أخونا يشكو من بخر في الفم، ويشكو أيضاً من وضعه في الصلاة، وكذلك في الحج وفي العمرة، هل يأثم إذا ذهب إلى المسجد أو إذا طاف وسعى وهو على تلكم الحال؟ أفيدوه لو تكرمتم سماحة الشيخ.","title":"الواجب على المريض المصاب ببخر في الفم","answer":"الجواب:  هذا الأمر قد يقع لبعض الناس، فالواجب عليه أن يعنى بالأسباب التي تزيله، بالعلاج وتعاطي الأدوية، وعرض أمره على المختصين من الأطباء لعله يجد علاجاً يزيل عنه هذا البخر الذي قد يتأذى به من يجاوره، فهو متى عجز عن ذلك ولم يتيسر له العلاج فإن كان يضر من حوله من المصلين ويؤذيهم فله عذر في الصلاة في بيته، كما منع النبي ﷺ من أكل ثوماً أو بصلاً أن يصلي مع الناس، وكان يخرجهم من المسجد عليه الصلاة والسلام لئلا يتأذى به المسلمون، قال ﷺ: من أكل ثوماً أو بصلاً فلا يقربن مصلانا وقال: فإن الملائكة تتأذى مما يتأذى منه بنو آدم.\nفالحاصل أنه إذا كان هذا البخر شديداً يتأذى به من يجاوره في المسجد فإنه يعذر في ترك الجماعة والصلاة في بيته بعد أن يجتهد في العلاج وأسباب إزالته، فإذا عجز عن ذلك فهو معذور.\nأما الحج فلا، الحج يحجه كل أحد، فالحج يحج ولو كان فيه هذا الأمر، يحج ويعتمر وليس يلزمه أن يلاصق أحداً في هذا، وعند الزحام هو كغيره لا يضر زحامه مع الناس في الطواف أو في السعي أو في رمي الجمار، لا نرى هذا عذراً في الحج ولا في العمرة، إنما هذا في الجماعة خاصة، صلاة الجماعة خاصة. نعم. المقدم: وبالنسبة للزيارة سماحة الشيخ؟ الشيخ: أما الزيارة فهذا يختلف، إن كان المزور يسمح له بذلك ولا يتأذى بزيارته لقرابته منه أو صداقته له أو أسباب أخرى فلا بأس عليه. فأما إن كان المزور يتأذى به فإنه لا يزور، لا يزوره بل يسعى في قضاء حاجته من الطرق الأخرى كالمكاتبة والهاتف وإرسال مندوب منه في حاجاته التي يريد أن يباشر بها ذلك الشخص. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6079/الواجب-على-المريض-المصاب-ببخر-في-الفم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_099/09903.mp3","categories":["صلاة الجماعة","المساجد ومواضع السجود"]},{"id":8270,"question":"ننتقل إلى رسالة أخرى ومواضيع أخرى، وأولى هذه الرسائل رسالة من أخ يقول: (د. ف. ل. ب) مصري مقيم في المملكة، أخونا يشكو من بخر في الفم، ويشكو أيضاً من وضعه في الصلاة، وكذلك في الحج وفي العمرة، هل يأثم إذا ذهب إلى المسجد أو إذا طاف وسعى وهو على تلكم الحال؟ أفيدوه لو تكرمتم سماحة الشيخ.","title":"الواجب على المريض المصاب ببخر في الفم","answer":"الجواب:  هذا الأمر قد يقع لبعض الناس، فالواجب عليه أن يعنى بالأسباب التي تزيله، بالعلاج وتعاطي الأدوية، وعرض أمره على المختصين من الأطباء لعله يجد علاجاً يزيل عنه هذا البخر الذي قد يتأذى به من يجاوره، فهو متى عجز عن ذلك ولم يتيسر له العلاج فإن كان يضر من حوله من المصلين ويؤذيهم فله عذر في الصلاة في بيته، كما منع النبي ﷺ من أكل ثوماً أو بصلاً أن يصلي مع الناس، وكان يخرجهم من المسجد عليه الصلاة والسلام لئلا يتأذى به المسلمون، قال ﷺ: من أكل ثوماً أو بصلاً فلا يقربن مصلانا وقال: فإن الملائكة تتأذى مما يتأذى منه بنو آدم.\nفالحاصل أنه إذا كان هذا البخر شديداً يتأذى به من يجاوره في المسجد فإنه يعذر في ترك الجماعة والصلاة في بيته بعد أن يجتهد في العلاج وأسباب إزالته، فإذا عجز عن ذلك فهو معذور.\nأما الحج فلا، الحج يحجه كل أحد، فالحج يحج ولو كان فيه هذا الأمر، يحج ويعتمر وليس يلزمه أن يلاصق أحداً في هذا، وعند الزحام هو كغيره لا يضر زحامه مع الناس في الطواف أو في السعي أو في رمي الجمار، لا نرى هذا عذراً في الحج ولا في العمرة، إنما هذا في الجماعة خاصة، صلاة الجماعة خاصة. نعم. المقدم: وبالنسبة للزيارة سماحة الشيخ؟ الشيخ: أما الزيارة فهذا يختلف، إن كان المزور يسمح له بذلك ولا يتأذى بزيارته لقرابته منه أو صداقته له أو أسباب أخرى فلا بأس عليه. فأما إن كان المزور يتأذى به فإنه لا يزور، لا يزوره بل يسعى في قضاء حاجته من الطرق الأخرى كالمكاتبة والهاتف وإرسال مندوب منه في حاجاته التي يريد أن يباشر بها ذلك الشخص. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6079/الواجب-على-المريض-المصاب-ببخر-في-الفم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_099/09903.mp3","categories":["صلاة الجماعة","المساجد ومواضع السجود"]},{"id":8348,"question":"رسالة وصلت إلى البرنامج من الأخت (ع. ع. د. ث) من الطائف، أختنا تسأل مجموعة من الأسئلة من بينها سؤال يقول: لقد سمعت من بعض الأشخاص أن الصلاة في مسجد العباس الموجود في مدينة الطائف لا تجوز، بحكم أن تحته قبور، وأمامه قبور، فهل هذا صحيح أم لا، أفتونا في ذلك ولكم عظيم الشكر والامتنان؟","title":"حكم الصلاة في مسجد ابن عباس بالطائف","answer":"الجواب: ليس هذا بصحيح؛ لأن مسجد ابن عباس قد نبشت القبور التي فيه، وهيئ للصلاة، وقام بهذا ولاة الأمور، وغرهم عليه العلماء فلا حرج في ذلك، فالصلاة فيه لا حرج فيها والحمد لله. نعم.","link":"https://binbaz.org.sa/fatwas/6166/حكم-الصلاة-في-مسجد-ابن-عباس-بالطاىف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_113/11305.mp3","categories":["المساجد ومواضع السجود"]},{"id":8564,"question":"وله سؤال آخر في هذه الرسالة يقول: لنا مسجد آخر في قرية صغيرة وقع فيه نزاع بين الشيوخ والشباب، فالشيوخ لا يرضون أن يتولى الشباب المسئولية في داخل المسجد، وبعض الرجال قطعوا الصلاة في المسجد فيصلون في منازلهم، والجمعة يؤدونها في مدينة تلمسان، فهل في ذلك إثم على الجميع؟","title":"حكم هجر بعض المصلين المسجد بسبب خلاف حصل بينهم","answer":"الجواب: هذا محل نظر؛ لأن الخلاف لم يبين أسبابه لم تبين أسباب الخلاف، والواجب على الشيوخ والشباب أن يتفقوا على الخير، وأن يتعاونوا على البر والتقوى، فيصلون جميعاً في المسجد ويتعاونون على الخير، ويقدمون أفضلهم وأقرأهم كما قال النبي ﷺ: يؤم القوم أقرؤهم لكتاب الله، فلا ينبغي التنازع في مثل هذا؛ لأن المقصود أداء الجماعة، فعليهم جميعاً أن يتعاونوا على البر والتقوى وأن يؤدوا الصلاة جماعة، وليس لهم الصلاة في بيوتهم، بل الواجب عليهم أن يصلوا في المسجد وأن يتفقوا جميعاً وأن يؤمهم أقرؤهم لكتاب الله، فإن كانوا في القراءة سواء فأعلمهم بالسنة، فإن كانوا في السنة سواء فأقدمهم هجرة، فإن كانوا في ذلك سواء فأقدمهم سلماً، يعني: أكبرهم سناً وأقدمهم إسلاماً.\nهذا الواجب عليهم أن يتأدبوا بآداب الشريعة، أما أن يتخلى الشيوخ عن المسجد ويتخلى الآخرون عن المسجد يبقى المسجد ما فيه أحد، أو يصلي فيه الشباب وحدهم، ويصلي الكبار في بيوتهم، هذا لا يجوز، الواجب أن ينظر في الأمر وأن يحل الخلاف الذي بينهم بالطريقة الشرعية، فإن كانوا ينقمون على الشباب شيئاً نصحوهم ووجهوهم إلى الخير، وإن كان الشيوخ عندهم بدعة أو عندهم معاصي تابوا إلى الله منها حتى يتفقوا مع الشباب، فالحاصل: أنه لابد من حل المسألة بالطرق الشرعية، أما أن يصلي الكبار في بيوتهم أو الصغار في بيوتهم من أجل النزاع فهذا لا يجوز، الواجب القضاء عليه، نعم، والله المستعان. نعم.\nالمقدم: جزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/6645/حكم-هجر-بعض-المصلين-المسجد-بسبب-خلاف-حصل-بينهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_207/20706.mp3","categories":["المساجد ومواضع السجود"]},{"id":8617,"question":"هذه رسالة من السائل عبدالله سرور لم يذكر عنواناً يقول فيها: الصلاة في مكة وفي بيوتها هل هي مضاعفة مثل الصلاة عند الكعبة؟","title":"عموم مضاعفة الصلاة في الحرم كله","answer":"الجواب: نعم، الصواب أن المضاعفة تعم الحرم كله، حرم مكة، ولكن فعلها حول الكعبة يكون أفضل من جهة الجمع لكثرة الجمع، من جهة أنه محل متفق عليه من جهة الفضل، ولكن من جهة عموم المضاعفة فالصواب أنها تعم، تعم جميع مساجد مكة وحرم مكة كله إلى الأميال إلى حدود الحرم؛ لأن الكل يسمى مسجد حرام، جميع الحرم يسمى المسجد الحرام، والصلاة فيه مضاعفة لكنها فيما حول الكعبة ومع الجماعة التي حول الكعبة مع الإمام الذي في المسجد الحرام نفسه يكون أفضل، ذلك أفضل وأكمل لقربه من الكعبة ولأنه محل متفق عليه، ولكثرة الجمع. نعم.\nالمقدم: بارك الله فيكم، وجزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/6741/عموم-مضاعفة-الصلاة-في-الحرم-كله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_210/21007.mp3","categories":["فضائل الأزمنة والأمكنة","المساجد ومواضع السجود"]},{"id":8685,"question":"هذه رسالة وردت إلى البرنامج من علي هادي علي أحمد العسيري ، يقول فيها: نحن قوم في قرية يبلغ عددنا حوالي مائة وخمسين رجلاً، كنا نصلي في مسجد قديم في مكان صعب الوصول إليه إلا بشق الأنفس، ممن هو طاعن في السن، فهؤلاء لا يستطيعون إليه، وهو يقع في الحارة التي يسكن فيها أقل عدد من سكان القرية، وقد تبرع أحد التجار ببناء أحد المساجد في مكان مزدحم بالسكان ويسهل الوصول إليه، وعندما انتهى البناء رفض المجاورون للمسجد القديم الصلاة في المسجد الجديد بحجة أن المسجد الجديد بدعة، فما الحكم إذا كان من يصلي الجمعة في المسجد الحديث أكثر ممن يصلون في المسجد القديم، أفيدونا أفادكم الله؟","title":"نصيحة لمن ينكر الصلاة في مسجد بني حديثاً","answer":"الجواب: عليكم أن تراجعوا القاضي قاضي البلد والعلماء عندكم في البلد حتى يفتوكم في هذا الشيء، أو تكتبوا لنا حتى ننظر في الأمر ونرسل من يعرف الحقيقة. في أي بلد؟\nالمقدم: ما ذكر البلد، لكنه من داخل المملكة.\nالشيخ: نعم، عليك أيها السائل أن تستفتي قاضي البلد وترفع الأمر إليه وهو ينظر في الأمر، أو تكتب لنا ننظر في الأمر من طريق العلماء ومن طريق القاضي. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6820/نصيحة-لمن-ينكر-الصلاة-في-مسجد-بني-حديثا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_215/21507.mp3","categories":["المساجد ومواضع السجود"]},{"id":8782,"question":"له سؤال آخر في هذه الرسالة يقول فيه: بنينا مسجداً في القرية، لكن عندما يجلس فيه الناس لانتظار الصلاة يتحدثون بحديث غير ذكر الله ولا كلام الرسول ﷺ، وإذا نهيناهم لا ينتهون. نرجو من فضيلتكم أن تفتونا كيف نعمل معهم؟","title":"حكم الإكثار من الكلام في أمور الدنيا في المسجد","answer":"الجواب: مثل هؤلاء ينصحون كما فعلتم، ينصحون بأن يشتغلوا بذكر الله.. بقراءة القرآن.. بالتسبيح والتهليل.. بالاستغفار، أو بالصمت، فالمساجد ليست محلاً لحديث الدنيا، وإنما هي محل لذكر الله وقراءة القرآن والصلاة والعبادة ومذاكرة العلم، فهؤلاء ينصحون ويوجهون إلى الخير ويبين لهم أن هذا أمر مكروه لا ينبغي لهم أن يكون حديثهم في أمور الدنيا، بل ينبغي أن يشتغلوا بشيء ينفعهم في الآخرة من ذكر الله وقراءة القرآن والتحدث بما ينفعهم في الآخرة، هكذا ينبغي للمؤمن، أما الشيء القليل من حديث الدنيا لا بأس، لو تحدثوا قليلاً أو تحدث الإنسان مع أخيه قليلاً في أمر عارض من الدنيا لا حرج في ذلك، لكن كونها تتخذ مجالس لحديث الدنيا هذا أمر مكروه لا ينبغي. نعم..\nالمقدم: بارك الله فيكم وجزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/6929/حكم-الاكثار-من-الكلام-في-امور-الدنيا-في-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_219/21902.mp3","categories":["المساجد ومواضع السجود"]},{"id":8880,"question":"أخونا عبد المعين بن غيث الزعاني فيما يبدو من طريق المدينة المنورة له سؤال يقول: هناك مساجد مدورة بناؤها مثل الكرة، تجد الصف الأول خمسة من المصلين والذي بعده أطول، وهكذا ثم تعود الصفوف الأخرى أو الأخيرة إلى مثل عدد الصفوف الأولى، ويسأل: هل هذا الطراز من البناء جائز بالنسبة للمساجد أو كيف توجهون الناس لو تكرمتم؟","title":"حكم جعل المساجد دائرية الشكل","answer":"الجواب: لا أعلم لهذا البناء أصلاً في المساجد، لا أعلم له أصلاً، والمشروع أن تكون المساجد واسعة ومستوية حتى تكون الصفوف معتدلة وحتى يكون ذلك أوسع للمصلين وأنفع لأهل البلد، فينبغي أن تكون المساجد مربعة ومستوية هذا هو الأولى والأفضل، أما كون هذا حراماً أو غير جائز فهو محل نظر، لكنه خلاف الأولى وخلاف المعتاد في بناء المساجد، لكن كونه حرام محل نظر، فإن المسجد قد يكون واسعاً لا يضره هذا، قد يكون واسعاً وتكون الصفوف الأولى قليلة والأخيرة قليلة والوسطى واسعة فيحصل بها المقصود، لكن كونه هذا هو الأفضل أو ليس بالأفضل الذي يظهر لي هو أن الأفضل أن تكون الصفوف متساوية ويكون المسجد مربعاً حتى تكون الصفوف الأولى والثانية والأخيرة كلها متقاربة، هذا هو الأفضل والأنفع للمسلمين، والله جل وعلا أعلم.\nالمقدم: جزاكم الله خيراً. إذا كان في ذلك شبه ببناء الكنائس سماحة الشيخ فماذا تقولون؟\nالشيخ: إذا كان فيه شبه ينبغي تجنبه، إذا كان فيه تشبه بالكنائس فالواجب تجنبه؛ لقول النبي ﷺ: من تشبه بقوم فهو منهم، فلا يجوز أن تبنى على هيئة .... الكنائس، ولا يجوز للمؤمن أن يتشبه بأعداء الله في كنائسهم ولا في غيرها. نعم.\nالمقدم: الذي يعرفه سماحة الشيخ بالنسبة لطراز المساجد أن تبقى مربعة أو مستطيلة أو أن هذه الأشكال الدائرية غرفت أيضاً؟\nالجواب: المقصود أنها لا يكون فيها شبه للكنائس والبيع حق اليهود و النصارى ، بل تكون على طريقة المسلمين في مساجدهم، سواء كانت متساوية من جهة الطول أو من جهة القصر المقصود تكون صفوفها متساوية ومتقاربة إلا لعلة عارضة مثل كأن يكون الأرض ضيقة أو..... في أسفلها أو في مقدمها حتى صار بعض الصفوف أقصر لعلة فلا بأس بهذا الأمر في هذا واسع. نعم.\nالمقدم: لكن من أجل الطراز المعماري أو الفن الهندسي؟\nالشيخ: هذا هو محل البحث، ينبغي أن يراعى في ذلك الفن الذي سار عليه المسلمون في مساجدهم، والحذر من التشبه بأعداء الله في كنائسهم. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/7036/حكم-جعل-المساجد-داىرية-الشكل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_139/13906.mp3","categories":["المساجد ومواضع السجود"]},{"id":8946,"question":"من الدمام أخونا مصطفى العناني بعث برسالة وضمنها ثلاثة أسئلة:سؤاله الأول يقول: ما حكم الصلاة في المساجد التي بها قبور مع العلم أنني أعيش في بلد تكثر فيه هذه الظاهرة، أرجو توجيهي ولاسيما إذا لم يكن حولي وقريب مني إلا مسجد واحد خال من القبور؟","title":"ما حكم الصلاة في المساجد التي بها قبور؟","answer":"الجواب: ثبت عن رسول الله عليه الصلاة والسلام أنه قال: لعن الله اليهود والنصارى اتخذوا قبور أنبيائهم مساجد قالت عائشة رضي الله عنها: يحذر ما صنعوا وقال عليه الصلاة والسلام: ألا وإن من كان قبلكم كانوا يتخذون قبور أنبيائهم وصالحيهم مساجد ألا فلا تتخذوا القبور مساجد فإني أنهاكم عن ذلك ونهى عن الصلاة إلى القبور، فدل ذلك على أنه لا يجوز الصلاة في المسجد الذي فيه قبر، فإذا بني المسجد على القبر أو على قبرين أو أكثر لا يصلى فيه بل يصلى في المساجد الخالية من ذلك التي ليس فيها قبور.\nوإذا لم يجد شيئًا صلى في بيته أو مع إخوانه في بيوتهم، وإن وجدوا مسجدًا ليس فيه قبور صلوا فيه، ولا يجوز بقاء القبور في المساجد بل يجب نبشها وإبعادها عن المساجد إذا كانت بعد بناء المسجد دفن في المسجد فإنه ينبش وتنقل رفاته إلى المقابر العامة وتبقى المساجد سليمة من ذلك.\nأما إن كان المسجد هو الأخير بني على القبور فهذا المسجد أسس على غير التقوى، أسس على باطل فيجب هدمه، يجب على ولاة الأمور أن يهدموه ويزيلوه؛ لأنه بني على القبر، والرسول ﷺ لعن اليهود والنصارى على اتخاذهم القبور مساجد، فالواجب على ولاة الأمور أن يعنوا بهذا الأمر في أي مكان في أي دولة إسلامية، الواجب على ولاة الأمور أن ينزهوا المساجد من القبور فإن كان القبر هو الأخير نبش ونقل إلى المقبرة العامة، وإن كان القبر هو القديم وبني عليه المسجد هدم المسجد وأزيل طاعة لله ولرسوله عليه الصلاة والسلام.\nوعلى المسلمين أن ينتبهوا لهذا وأن يحذروا الصلاة في المساجد التي فيها القبور؛ لأن الصلاة فيها وسيلة للشرك، وسيلة للشرك بأهل القبور ودعائهم من دون الله كما قد وقع ذلك في بلدان كثيرة ولا حول ولا قوة إلا بالله. نعم.","link":"https://binbaz.org.sa/fatwas/7104/ما-حكم-الصلاة-في-المساجد-التي-بها-قبور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_172/17208.mp3","categories":["المساجد ومواضع السجود"]},{"id":9005,"question":"السؤال الثاني في رسالة الأخ: رزق محمد رزق المصري، والأخ: عابد هريسان فهيد، يقولون فيه: ما هو حكم المساجد التي بها قبور بعض الصالحين، هل تصح الصلاة فيها أم لا؟ وهل يصح النذر لهؤلاء المشايخ أفيدونا أفادكم الله، وما هو حكم الشرع في أصحاب الطرق الموجودة حالياً في أكثر الدول الإسلامية أمثال: الصوفية، والبومية، والبهائية، والمعتزلة وغيرها من الطرق، وما حكم ما يذكرونه من الصلوات النارية، والتسبيح بأعداد كبيرة، وقراءة القرآن بأعداد أيضاً أفيدونا أفادكم الله؟","title":"حكم بناء المساجد على القبور، والتعريف ببعض الفرق الضالة","answer":"الجواب: أما المساجد التي تبنى على القبور فحكمها الهدم لا يجوز بقاؤها، ولا يصلى فيها، لما ثبت عن رسول الله عليه الصلاة والسلام أنه قال: لعن الله اليهود والنصارى اتخذوا قبور أنبيائهم مساجد، قالت عائشة رضي الله عنها: يحذر ما صنعوا، متفق على صحته.\nوقال عليه الصلاة والسلام: ألا وإن من كان قبلكم كانوا يتخذون قبور أنبيائهم وصالحيهم مساجد، ألا فلا تتخذوا القبور مساجد فإني أنهاكم عن ذلك خرجه مسلم في الصحيح.\nفبين ﷺ أن الله لعن اليهود والنصارى بسبب اتخاذ قبور أنبيائهم مساجد، وبين صلى الله عليه وسلم أن الواجب على المسلمين أن يتجنبوا ذلك، وأن لا يتأسوا بـاليهود والنصارى في هذا الأمر، فدل ذلك على أنه لا يجوز اتخاذ المساجد على القبور، ولا يصلى فيها؛ لأن هذا يسبب ويفضي إلى الشرك بها وعبادتها من دون الله ولا حول ولا قوة إلا بالله.\nومن هذا ما رواه مسلم في الصحيح عن جابر ، عن النبي ﷺ: أنه نهى عن تجصيص القبر، وعن القعود عليه، وعن البناء عليه، فالقبور لا تجصص ولا يبنى عليها لا مساجد ولا غيرها، وما ذاك إلا لأن اتخاذها مساجد والبناء عليها من أسباب الغلو فيها، وعبادة أهلها من دون الله، بالنذر لهم، والذبح لهم ونحو ذلك.\nفلهذا نهى الرسول ﷺ عن اتخاذ المساجد على القبور، وأخبر أن الله لعن اليهود والنصارى بأسباب ذلك.\nفالواجب على المسلمين أن يحذروا هذا، وأن لا يبنوا على القبور مساجد، وأن لا يبنوا عليها شيئاً لا قبة ولا حجرة، ولا مسجد ولا تجصص؛ لأن الرسول نهى عن هذا عليه الصلاة والسلام وحذر منه، صلى الله وسلم عليه وعلى آله وأصحابه.\nأما إن كان المسجد المبني قائم قبل ذلك، ثم دفن فيه ميت فهذا الميت ينبش، إذا كان المسجد موجود ولكن حدث فيه أن دفن فيه ميت أو أموات، فالواجب نبش هذه القبور وجعلها في المقابر العامة، حتى يبقى المسجد سليماً من القبور هذا هو الواجب، وبهذا يصلى فيها، إذا نبشت..... صلي فيه؛ لأنه هو القديم وهو الأصل، أما إذا كانت القبور هي الأصلية ثم حدث المسجد، فالواجب هدمه وإزالته وأن تبقى القبور كسائر القبور ضاحية ليس عليها بناء، كما كان النبي ﷺ فعل ذلك وأصحابه، في البقيع وفي غير البقيع.\nولا يخفى ما يترتب على بناء المساجد على القبور، واتخاذ القباب عليها وفرشها وتنويرها وتطييبها، لا يخفى ما يترتب على هذا من الغلو فيها وتعظيم أهلها وعبادتهم من دون الله، بالنذر لهم ودعائهم وطلب منهم المدد، وهذا شرك أكبر، دعاء الأموات والاستغاثة بالأموات والنذر لهم هذا من الشرك الأكبر عند جميع أهل العلم المعتبرين، وهو مثل دعاء الأصنام ومثل دعاء الأشجار والأحجار، ومثل دعاء الكواكب والاستغاثة بها، كله شرك بالله عز وجل، وتعظيمها ببناء المساجد عليها والقباب وسيلة إلى ذلك، وأما الطرق التي أحدثها الناس، طرق الصوفية والبهائية والقاديانية وغيرها فهي طرق منكرة محدثة يجب أن تعرض على كتاب الله وسنة الرسول ﷺ، فما وافق سنة الرسول ﷺ أو وافق كتاب الله قبل، وما خالف ذلك مما أحدثه الناس فإنه يرد ويطرح، لقول النبي ﷺ: من عمل عملاً ليس عليه أمرنا فهو رد رواه مسلم، يعني: مردود، وقال عليه الصلاة والسلام: من أحدث في أمرنا هذا ما ليس منه فهو رد يعني: فهو مردود، متفق على صحته، وكان الرسول ﷺ يقول في خطبة الجمعة: أما بعد: فإن خير الحديث كتاب الله، وخير الهدي هدي محمد ﷺ، وشر الأمور محدثاتها، وكل بدعة ضلالة خرجه مسلم في الصحيح.\nفالواجب على أهل الإسلام أن يحذروا ما أحدثه الناس، من الطرق التي تخالف شرع الله عز وجل، سواء كانت صوفية أو غير صوفية، الواجب عرض ما أحدثه الناس من الطرق على كتاب الله، وعلى سنة رسوله ﷺ، فما وافقهما أو أحدهما قبل وما خالفهما رد على من أحدثه، قال الله : يَا أَيُّهَا الَّذِينَ آمَنُوا أَطِيعُوا اللَّهَ وَأَطِيعُوا الرَّسُولَ وَأُوْلِي الأَمْرِ مِنْكُمْ فَإِنْ تَنَازَعْتُمْ فِي شَيْءٍ فَرُدُّوهُ إِلَى اللَّهِ وَالرَّسُولِ إِنْ كُنتُمْ تُؤْمِنُونَ بِاللَّهِ وَالْيَوْمِ الآخِرِ ذَلِكَ خَيْرٌ وَأَحْسَنُ تَأْوِيلًا [النساء:59] فأمر سبحانه برد ما تنازع فيه الناس إلى الله ورسوله معنى: إلى الله: إلى كتابه العظيم، ومعنى إلى الرسول: يعني: إليه في حياته ﷺ وإلى سنته بعد وفاته عليه الصلاة والسلام، هكذا قال أهل العلم رحمة الله عليهم، وهكذا قال سبحانه: وَمَا اخْتَلَفْتُمْ فِيهِ مِنْ شَيْءٍ فَحُكْمُهُ إِلَى اللَّهِ [الشورى:10] لكن البهائية طائفة كافرة، معروف كفرها بما لديها من دعوى النبوة للبهاء، وربما ادعوا أنه الله! فهي طائفة كافرة يجب الحذر منها، ويجب على الدول الإسلامية إبعادها والقضاء عليها وعدم إقرارها في البلاد، وهكذا القاديانية طائفة كافرة؛ لأنها تثبت النبوة لـمرزا غلام أحمد القادياني وهذا كفر وضلال؛ لأن محمداً رسول الله صلى الله عليه وسلم هو خاتم الأنبياء عليه الصلاة والسلام، ليس بعده نبي، قال الله : مَا كَانَ مُحَمَّدٌ أَبَا أَحَدٍ مِنْ رِجَالِكُمْ وَلَكِنْ رَسُولَ اللَّهِ وَخَاتَمَ النَّبِيِّينَ [الأحزاب:40] وقد ثبت عن رسول الله ﷺ وتواتر عنه، أنه قال: أنا خاتم النبيين لا نبي بعدي فدعوى القاديانية: أن مرزا غلام أحمد أنه نبي وأنه يوحى إليه، هذا كفر مستقل وردة كبرى عند أهل العلم، فيجب الحذر منهم وعدم إقرارهم حتى يستجيبوا لله ورسوله حتى يتوبوا من هذه العقيدة، وحتى يرجعوا عن هذا الباطل والمنكر، نسأل الله لنا ولهم الهداية.","link":"https://binbaz.org.sa/fatwas/7159/حكم-بناء-المساجد-على-القبور-والتعريف-ببعض-الفرق-الضالة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_223/22302.mp3","categories":["المساجد ومواضع السجود","البدع والمحدثات"]},{"id":9129,"question":"السؤال الثالث في رسالة الأخ خالد علي من جمهورية السودان الديمقراطية يقول فيه: هناك مسجد أسسه رجل يعمل بالتمائم والحجب، ويؤتى له بالنذر وتضرب في دياره الطبول، ويزعمون أنه يعالج المجانين بالطبول والتمائم وما شابه ذلك، فهل هذا المال المكتسب الذي أسس به المسجد يجعل المسجد مؤسس على غير التقوى كمسجد ضرار أفيدونا أفادكم الله؟ وهل يجوز الصلاة خلفه، أفيدونا أفادكم الله؟","title":"حكم الصلاة في مسجد أسس من حرام","answer":"الجواب: هذا الرجل لا يصلى خلفه؛ لأن ظاهره فساد العقيدة، أما المسجد فلا بأس أن يصلى فيه ولا ينظر إلى نفقته، بل يصلى فيه ويصلي فيه أهل السنة والجماعة حتى يبتعد عنه أهل الشر والفسق والفساد، وأما هذا الرجل الذي هذا عمله فإنه لا يصلى خلفه لأن ظاهره فساد العقيدة وعدم الاستقامة، رزق الله الجميع العافية والسلامة.","link":"https://binbaz.org.sa/fatwas/7297/حكم-الصلاة-في-مسجد-اسس-من-حرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_229/22909.mp3","categories":["المساجد ومواضع السجود"]},{"id":9191,"question":"هل الصلاة في المسجد في مكان واحد الفرض والنافلة يعد في ذلك محذور أو لا؟","title":"حكم تخصيص مكان معين في المسجد للصلاة فيه","answer":"الجواب: نعم، اعتياد ذلك لا ينبغي، كونه يعتاد مكانًا معينًا يكره له ذلك، بل السنة أنه يسابق إلى الصلاة ويحرص على الصف الأول والقرب من الإمام.\nأما أن يتخذ محلًا معينًا يجلس فيه ولو بكر ووجد ما هو أفضل منه، فهذا خلاف المشروع، فالسنة للمؤمن أن يسابق ويسارع إلى الصلاة وأن يحرص على الصف الأول وعلى قربه من الإمام ولا يتخذ له مكانًا معينًا يصلي فيه ويترك ما هو أفضل منه، والله المستعان. نعم.\nالمقدم: جزاكم الله خيرا.","link":"https://binbaz.org.sa/fatwas/7351/حكم-تخصيص-مكان-معين-في-المسجد-للصلاة-فيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_181/18102.mp3","categories":["المساجد ومواضع السجود"]},{"id":9298,"question":"الرسالة الخامسة في هذه الحلقة وردت من السائل محمد بن عبد الرحمن الخميس يقول: هناك جماعة يصلون في مسجد في الدور الثاني، والدور الثالث من عمارة مبنية على مقبرة، فهل صلاتهم فيها جائزة فيستمروا فيها أم لا، أفيدونا أفادكم الله؟","title":"حكم الصلاة في عمارة مبنية في مقبرة","answer":"الجواب: إذا كانت العمارة مستقلة وليس فيها في محل الصلاة قبور، فإن الصلاة صحيحة إذا صلوا في الدور الأول أو الدور الثاني، أو الدور الثالث، إذا صلوا في هذه الأدوار، سواء كان في الأول أو في الثاني أو في الثالث، فالصلاة صحيحة، أما إن كانت القبور في نفس الأدوار أو في الدور الأول، وصلوا في الدور الأول، فالصلاة عند القبور وبين القبور لا تصح، النبي ﷺ قال: ألا وإن من كان قبلكم كانوا يتخذون قبور أنبيائهم وصالحيهم مساجد، ألا فلا تتخذوا القبور مساجد فإني أنهاكم عن ذلك ، وقال: لعن الله اليهود والنصارى اتخذوا قبور أنبيائهم مساجد ، ولو كان حولها قبور ما دام الأرض سليمة، الأرض سليمة ليس فيها قبور.\nالمقدم: أرض العمارة.\nالشيخ: أرض العمارة بنيت عليها العمارة سليمة من القبور، ولكن حولها قبور أمامها أو خلفها أو عن يمينها، أو عن شمالها، فلا يضرها ذلك، إذا كانت الأرض سليمة ليس فيها المقبرة.\nأما إن كانت الأرض من المقبرة واغتصبوها فصارت غير صحيحة، لا يصلى في العمارة لا في الدور الأول ولا في الثاني ولا في الثالث؛ لأنها تابعة المقبرة ومغصوبة، فلا يحل لهم البقاء فيها، ولا يجوز الصلاة فيها، بل يجب أن تزال من المقبرة؛ لأن هذا ظلم وعدوان على المقبرة. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7465/حكم-الصلاة-في-عمارة-مبنية-في-مقبرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_236/23608.mp3","categories":["المساجد ومواضع السجود"]},{"id":9440,"question":"يقول في رسالته أيضاً: عندنا مقام شيخ في المسجد من قديم الزمان بعض الناس قالوا: نهدمه، والبعض الآخر قالوا: نتركه فبماذا تنصحوننا بارك الله فيكم؟","title":"حكم المقامات الموجودة في المساجد","answer":"الجواب: إذا كان هذا المقام يتبرك به الجهال، أو يعتقدون فيه أنه يشفي مرضاهم إذا تمسحوا به أو أخذوا من ترابه أو ما أشبه ذلك، فهذا يهدم لأنه من قواعد الشرك ومن أساسات الشرك فيهدم، أما إذا كان هذا المقام لتدريس القرآن وتعليم العلم، يعني: حجرة أو غرفة أو محل يعني لتدريس القرآن، لتعليم العلم فلا بأس بهذا، إذا كان ليس فيه ما يسبب الشرك لا تمسح ولا أخذ شيء من ترابه، ولا غلو في الشيخ ودعائه من دون الله، وإنما هو مقام بناه ليعلم فيه العلم أو ليقرئ فيه القرآن وليس فيه ما يسبب الشرك، وليس فيه ما يدعو إلى الغلو في الشيخ فلا حرج فيه، وهذه المقامات في الغالب الذي فيما بلغنا عنها أنها لا تخلو من الغلو، وأن الجهلة يقصدونها للتبرك بها والتمسح بها أو دعاء الشيخ فيها أو ما أشبه هذا منكر لا يجوز، ومتى كان المقام يفعل به ذلك وجب أن يزال، كما أزال النبي صلى الله عليه وسلم العزى ومناة واللات وأشباهها من مقامات المشركين وأوثانهم سداً لباب الشرك، وقضاءً على أسباب الفتن. نعم.\nالمقدم: بارك الله فيكم، غالباً ما يكون في هذه المقامات قبور، يعني يكون الشيخ مدفون في المقام؟\nالشيخ: إذا كان فيها قبر هذا أشد وأشد، إذا كان فيه قبر يجب أن يزال، يجب أن يرفع من المسجد، يجب أن ينبش وينقل إلى مقابر المسلمين، ويسوى محله بالمسجد حتى يكون مصلى للمسلمين، والقبر ينبش ويزال إذا كان موضوعاً في المسجد، أما إذا كان المسجد بني عليه من أجله فالمسجد يهدم ويزال، وتبقى البقعة مدفناً للناس يدفن فيها، والمسجد يزال ويبنى مسجد آخر لأهل الحارة في غير القبور، في محل غير محل القبر حتى لا تقع الفتنة.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7600/حكم-المقامات-الموجودة-في-المساجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_239/23902.mp3","categories":["المساجد ومواضع السجود"]},{"id":9493,"question":"يسأل أيضاً ويقول في آخر رسالته: نحن نعلم أن المساجد لله ولا يجوز التكلم فيها إلا بذكر الله تعالى أو بحديث ينفع الإسلام والمسلمين، لكن مع الأسف أصبح كثير من الناس يتحدثون في مساجد الله بأمور تخرج عن ذلك، فما الحكم في هذا، أفيدونا أفادكم الله؟","title":"حكم الكلام في أمور الدنيا في المساجد","answer":"الجواب: الكلام في أمور الدنيا إذا كان قليلاً لا يضر، إذا كان قليلاً كأن سأل أخاه عن حاله وعن حال أولاده، أو عن حاجة أخرى تتعلق بضيعته، أو تتعلق ببيته، أو تتعلق بأخ له غائب أو في المستشفى أو ما أشبه ذلك لا حرج في ذلك، لكن اتخاذ ذلك عادة والإكثار من ذلك هذا هو المكروه، أما الشيء القليل فيعفى عنه والحمد لله. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7666/حكم-الكلام-في-امور-الدنيا-في-المساجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_242/24209.mp3","categories":["المساجد ومواضع السجود"]},{"id":9500,"question":"يسأل أيضاً ويقول في آخر رسالته: نحن نعلم أن المساجد لله ولا يجوز التكلم فيها إلا بذكر الله تعالى أو بحديث ينفع الإسلام والمسلمين، لكن مع الأسف أصبح كثير من الناس يتحدثون في مساجد الله بأمور تخرج عن ذلك، فما الحكم في هذا، أفيدونا أفادكم الله؟","title":"حكم الكلام في أمور الدنيا في المساجد","answer":"الجواب: الكلام في أمور الدنيا إذا كان قليلاً لا يضر، إذا كان قليلاً كأن سأل أخاه عن حاله وعن حال أولاده، أو عن حاجة أخرى تتعلق بضيعته، أو تتعلق ببيته، أو تتعلق بأخ له غائب أو في المستشفى أو ما أشبه ذلك لا حرج في ذلك، لكن اتخاذ ذلك عادة والإكثار من ذلك هذا هو المكروه، أما الشيء القليل فيعفى عنه والحمد لله. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7666/حكم-الكلام-في-امور-الدنيا-في-المساجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_242/24209.mp3","categories":["المساجد ومواضع السجود"]},{"id":9539,"question":"يسأل أيضاً ويقول: هناك من يقول: إن الصلاة يختلف حكمها في المسجد الذي فيه قبر عن المسجد الذي فيه قبران عن المسجد الذي فيه ثلاثة أو أكثر، نرجو التوضيح في هذا، وكيف الحكم والرسول عليه الصلاة والسلام قال: لعن الله اليهود والنصارى اتخذوا قبور أنبيائهم مساجد، ويسأل أيضاً ويقول: إن كثيراً ممن يعودون من المدينة المنورة بعد الحج إلى بلادهم يحتجون بجواز الصلاة في المساجد التي فيها قبور ويقولون: إن قبر النبي ﷺ وقبري صاحبيه رضي الله عنهما موجودان في المسجد والناس يصلون إليهما أرجو الإيضاح في هذه النقطة؟","title":"الرد على من يحتج بجواز الصلاة في المساجد التي فيها قبور بقبر النبي","answer":"الجواب: الرسول ﷺ لعن من اتخذ المساجد قبور وحذر من ذلك عليه الصلاة والسلام قال: لعن الله اليهود والنصارى اتخذوا قبور أنبيائهم مساجد، وقال ﷺ: ألا وإن من كان قبلكم كانوا يتخذون قبور أنبيائهم وصالحيهم مساجد، ألا فلا تتخذوا القبور مساجد فإني أنهاكم عن ذلك رواه مسلم في الصحيح، والأول رواه الشيخان، وروى الشيخان أيضاً عن عائشة رضي الله عنها: أن أم حبيبة وأم سلمة رضي الله تعالى عنهما ذكرتا عند النبي ﷺ كنيسة رأتاها بأرض الحبشة وما فيها من الصور، فقال: أولئك إذا مات فيهم الرجل الصالح بنوا على قبره مسجداً وصوروا فيه تلك الصور، ثم قال عليه السلام: أولئك شرار الخلق عند الله، فبين ﷺ أن الذين يبنون المساجد على القبور هم شرار الخلق عند الله وحذر من فعلهم، فدل ذلك على أن المسجد المقام على قبر أو قبرين أو ثلاثة لا يصلى فيه، ولا فرق بين الواحد والعدد، بل يجب ترك ذلك فإن كان المسجد هو الذي بني أخيراً وجب هدمه وأن تبقوا القبور ضاحية ليس عليها بناء، كما كانت القبور في المدينة في عهده ﷺ وعهد أصحابه ضاحية وهكذا اليوم في عهد المملكة العربية السعودية ضاحية ليس عليها بناء، هذا هو المشروع وهذا هو الواجب.\nأما إن كان المسجد قديم، المسجد كان قديماً ولكن حدث فيه قبر، فالقبر ينبش، يجب على ولاة الأمور وعلى أهل الحل والعقد أن ينبشوه وأن يزيلوا الرفات التي فيه ينقلوها إلى المقابر العامة، ويبقى المسجد سليماً ليس فيه شيء حتى يصلى فيه، هذا هو الواجب.\nأما احتجاج بعض الجهلة بوجود قبر النبي ﷺ وقبر صاحبه في المسجد، فهذا غلط لأن الرسول دفن في بيته عليه الصلاة والسلام ليس في المسجد، دفن في بيته بيت عائشة ودفن معه صاحباه أبو بكر وعمر رضي الله عنهما في البيت، ولكن لما وسع الوليد بن عبد الملك بن مروان المسجد في آخر القرن الأول أدخل البيت في المسجد بسبب التوسعة وقد غلط في هذا، وكان الواجب أن لا يدخله في المسجد لئلا يحتج بهذا الجهلة وأشباههم ولكنه غلط في هذا، فلا يجوز أن يتأسى به ويقتدى به في ذلك، ولا يظن ظان أن هذا من جنس البناء على القبور أو من جنس اتخاذ القبور مساجد لا؛ لأن هذا بيت مستقل أدخل في المسجد للحاجة إلى التوسعة وفصل عن المسجد بالجدر، فهذا من جنس المقبرة التي أمام المسجد مفصولة عن المسجد ما تضر المسجد لو فصلت عنه بجدار لا تضره، فهكذا مسجد النبي فإنه مفصول محمي بالشبك والجدران فليس من المسجد في شيء، فينبغي أن يعلم هذا وينبغي للمؤمن أن يبلغ هذا إخوانه حتى لا يغلطوا في هذه المسائل. نعم.\nالمقدم: بارك الله فيكم، يعني أن الأرض التي فيها قبر النبي ﷺ لم تدخل في المسجد؟\nالشيخ: ليس في المسجد لا، بل مفصول عن المسجد وهي بيت عائشة، ثم هو مفصول بالجدران التي أخرجت البيت من المسجد. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7710/الرد-على-من-يحتج-بجواز-الصلاة-في-المساجد-التي-فيها-قبور-بقبر-النبي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_246/24609.mp3","categories":["المساجد ومواضع السجود"]},{"id":9652,"question":"وهذا سؤال ورد من السائل (ن. ع. د) من الدرعية يقول: ما حكم الصلاة فوق سطح البيارة المبلطة والمسقوفة بالإسمنت، حيث كان في مؤخرة مسجدنا غرفة نستعملها كمستودع بنيت فوق البيارة فاحتجنا إلى توسعة صرحة المسجد وأزلنا الغرفة، وأبقينا البيارة مسقوفة ومبلطة فما حكم الصلاة فوقها أفيدونا أفادكم الله؟","title":"حكم الصلاة فوق سطح البيارة وما شابهها","answer":"الجواب: لا حرج في ذلك على الصحيح سطوح البيارات وأشباهها والحشوش والطرقات، كل صروحها يصلى فيها ولا حرج، ما دامت طاهرة من حيث الظاهر، أما ما تحتها فلا ينظر إليه، العبرة بالظاهر. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7817/حكم-الصلاة-فوق-سطح-البيارة-وما-شابهها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_251/25102.mp3","categories":["المساجد ومواضع السجود"]},{"id":9758,"question":"وهذه رسالة وردت من (س) شبوة من اليمن الديمقراطية، يقول في رسالته: يوجد في قريتنا مسجد، ويوجد في هذا المسجد ضريح يزعم أجدادنا أنه لأحد الأولياء، يطلقون عليه اسم الحبيب، والمسجد يتكون من ثلاث غرف كبيرة في اتجاه العرض بالنسبة للقبلة، وهذا الضريح يوجد في الغرفة الأمامية، ونحن نصلي في الوسطى، ولا يحجز بينها وبين التي فيها الضريح إلا جدار، فما حكم صلاتنا في هذا المسجد، أفيدونا أفادكم الله؟","title":"بناء المساجد على القبور محرم ومنكر","answer":"الجواب: بناء المساجد على القبور محرم ومنكر، يقول النبي صلى الله عليه وسلم في الحديث الصحيح: لعن الله اليهود والنصارى اتخذوا قبور أنبيائهم مساجد، وقال عليه الصلاة والسلام: ألا وإن من كان قبلكم كانوا يتخذون قبور أنبيائهم وصالحيهم مساجد، ألا فلا تتخذوا القبور مساجد فإني أنهاكم عن ذلك.\nفالرسول ﷺ نهى عن البناء على القبور واتخاذها مساجد، كما صح عنه ﷺ أنه: نهى عن تجصيصها والقعود عليها والبناء عليها فلا يجوز الصلاة في هذا المسجد، بل يجب أن يهدم إذا كان بني على القبر.\nأما إذا كان القبر أحدث في المسجد والمسجد قديم، والقبر أحدث فيه فإنه يزال، ينبش وتنقل رفاته إلى المقبرة العامة في حفرة خاصة، يسوى ظاهرها كسائر المساجد، ويبقى المسجد على حاله يصلى فيه، والقبر يزال إذا كان هو الأخير، يعني تزال الرفات يعني آثار الميت من عظام ونحوها تنقل إلى حفرة في المقبرة العامة ويسوى ظاهرها كالقبر أسوة بقية القبور.\nوأما هذا القبر فيسوى، تسوى الأرض بعد نقل الرفات ويصلى في المسجد، هذا إذا كان القبر هو الأخير، أما إذا كان القبر قديماً فإن المسجد هو الذي يهدم الذي بني عليه؛ لأنه أسس على غير التقوى، لأنه فيه عصيان للرسول ﷺ، والتأسي بـاليهود والنصارى في أعمالهم الخبيثة، والله المستعان نعم.\nالمقدم: بارك الله فيكم يقول: إذا لم تصح صلاتنا في هذا المسجد فما العمل مع العلم أنه هو المسجد الوحيد في القرية؟\nالشيخ: تقدم الجواب عن هذا، إن كان المسجد هو القديم والقبر أحدث يزال، القبر يعني ينبش وتنقل رفاته إلى حفرة في المقبرة العامة، ويسوى محله ويصلى في المسجد، أما إن كان المسجد بني عليه وهو القديم القبر هو قديم، فإن المسجد هذا يهدم ويبدل، يعني: يبنى مسجد آخر في محل آخر ليس فيه قبر. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7913/بناء-المساجد-على-القبور-محرم-ومنكر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_256/25604.mp3","categories":["المساجد ومواضع السجود"]},{"id":9812,"question":"وهذه رسالة من المستمع أحمد بغدادي مصري مقيم في جدة يقول فيها: يوجد في بلدنا مسجد داخله ضريح، هل الصلاة جائزة في هذا المسجد أم لا؟ علمًا أننا لا نعرف هل بني المسجد أولًا أم الضريح، رجائي الإفادة عن الصلاة في هذا المسجد، مع ملاحظة أن كثيرًا من الناس يأتون من بلادهم لزيارة هذا الضريح والذبح له ووضع النقود داخله، فأفيدونا بارك الله فيكم؟","title":"النهي عن اتخاذ القبور مساجد","answer":"الجواب: المساجد التي فيها قبور لا يصلى فيها، ويجب أن تنبش القبور وتبعد إلى المقابر المعروفة ولا يبقى فيها قبر، لا قبر ولي ولا غيره، لا من يسمى وليًا ولا غيره، بل يجب أن تنبش وتبعد إلى المقابر العامة، ولا يجوز الذبح للقبور ولا تقديم النقود إليها، ولا تقديم النذور، بل هذا من الشرك الأكبر، فالواجب أن تنبش القبور في المساجد وأن ينقل رفاتها إلى المقابر العامة في حفرة خاصة، كل قبر في حفرة خاصة كسائر القبور، أما المساجد فلا يجوز أن يقام فيها قبور؛ لأن الرسول ﷺ نهى عن هذا وحذر، وذم اليهود والنصارى على عملهم ذلك، فقد ثبت عنه ﷺ أنه قال: لعن الله اليهود و النصارى اتخذوا قبور أنبيائهم مساجد قالت عائشة رضي الله عنها: يحذر ما صنعوا متفق عليه، وقال عليه الصلاة والسلام: لما أخبرته أم سلمة و أم حبيبة بكنيسة فيها صور، وأنها كذا وكذا، قال: أولئك إذا مات فيهم الرجل الصالح بنوا على قبره مسجدًا، وصوروا فيه تلك الصور، أولئك شرار الخلق عند الله فأخبر أن الذين يبنون المساجد على القبور أنهم من شرار الخلق، وقال عليه الصلاة والسلام: ألا وإن من كان قبلكم كانوا يتخذون قبور أنبيائهم وصالحيهم مساجد، ألا فلا تتخذوا القبور مساجد فإني أنهاكم عن ذلك فنهى عن اتخاذ القبور مساجد عليه الصلاة والسلام.\nومعلوم أن من صلى عند قبر فقد اتخذه مسجدًا، ومن بنى عليه ليصلى فيه فقد اتخذه مسجدًا، فالواجب أن تبعد القبور عن المساجد وأن لا يجعل فيها قبور امتثالًا لأمر رسول الله ﷺ، وحذرًا من اللعنة التي صدرت من ربنا  لمن بنى على القبور، قال: لعن الله اليهود والنصارى اتخذوا قبور أنبيائهم مساجد فعلم بذلك أنه لا يجوز اتخاذها مساجد بل يجب أن تكون مستقلة والمساجد مستقلة، فالقبور في ناحية على حدة، لا يبنى علها مساجد، والمساجد تكون بعيدة عن القبور ليس فيها قبور، بل تكون سليمة من ذلك، فإذا وجد في المسجد قبر لم يصل فيه حذرًا من هذه اللعنة، وحذرًا من وسائل الشرك؛ لأنه إذا صلى في المسجد قد يزين له الشيطان دعوة الميت، أو الاستغاثة بالميت أو الصلاة له أو السجود له فيقع الشرك الأكبر.\nولأن هذا من عمل اليهود والنصارى فوجب أن نخالفهم وأن نبتعد عن طريقهم وعن عملهم السيئ.\nلكن لو علم أن المسجد بني على القبر وجب هدم المسجد، إذا كانت القبور هي الأصلية ثم بني عليها وجب هدم المسجد؛ لكن إذا كان لا يعلم، فإنها تنبش القبور وتبعد إلى المقابر ويبقى المسجد ويصلى عليه؛ لأن الأصل وجود المساجد قبل القبور. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7979/النهي-عن-اتخاذ-القبور-مساجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_197/19711.mp3","categories":["المساجد ومواضع السجود"]},{"id":9934,"question":"أيضًا له سؤال ثانٍ في رسالته يقول فيه: ما حكم الذي يدخل المسجد ويصلي وهو لابس حذاءه، ويتقدم أحيانًا إلى الصف الأول مع العلم أن المساجد اليوم ولله الحمد مفروشة بأحسن الفرش، وفوق هذا يحدث أذى للمصلين أثناء السجود بحيث يكون ظهر حذائه في وجه من خلفه؟","title":"حكم الصلاة بالنعال في المسجد","answer":"الجواب: هذا فيه تفصيل: إذا كانت الحذاء نظيفة وسليمة ليس فيها شيء يؤذي المصلين ولا يؤذي الفرش فلا حرج في ذلك وصلاته صحيحة، والنبي ﷺ صلى في نعليه، ثبت عن رسول الله ﷺ أنه صلى في نعليه عليه الصلاة والسلام، وقال للصحابة لما خلع نعليه ذات يوم من أجل أذى فيهما خلع الناس نعالهم، فلما سلم من صلاته سألهم قال: مالكم خلعتم نعالكم؟ قالوا: رأيناك يا رسول الله خلعت نعليك فخلعنا نعالنا، فقال ﷺ: إن جبريل أتاني فأخبر أن بهما أذى -وفي لفظ: قذرًا- فخلعتهما، فإذا أتى أحد المسجد فلينظر، فإن رأى في نعليه أذى فليمسحه ثم ليصل فيهما هكذا جاء عنه عليه الصلاة والسلام، فأمر بالصلاة فيهما وصلى فيهما هو أيضًا، هذا كله إذا كان كانت نظيفة سليمة ليس فيها علة.\nأما إن كانت قذرة فإنه لا يصلى فيها ولهذا خلع النبي ﷺ نعليه لما كان فيهما قذر، إذا كانت فيها نجاسة أو فيها شيء يؤذي الفرش من أنواع الطين أو القاذورات غير النجاسة أو ما أشبه مما يؤذي فإنه لا يصلي فيهما ولا يدخل بهما المسجد، بل يجعلهما في مكان عند باب المسجد أو في مكان آخر حتى لا يؤذي المسجد وأهله، وحتى لا يقذر عليهم موضع صلاتهم، ولاسيما بعد الفرش فإنه لما جاءت الفرش صارت تتأثر بكل شيء، فالأولى بالمؤمن في هذه الحالة أنه يحفظ نعليه في أي مكان حتى يمشي في المسجد بدون نعلين حتى لا يؤذي أحدًا لا بجوال ولا غيره. نعم.\nالمقدم: بعض الناس سماحة الشيخ يقول: أنا أحافظ وأحيي السنة بالصلاة في نعلي بالرغم من وجود الفرش؟\nالشيخ: ولو السنة أن تحييها بالكلام والبيان أن هذا فعله النبي ﷺ وأنه لا حرج فيه لكن بعض الناس أو أكثر الناس لا يبالي ولا يتحفظ من نعليه، بل يدخل المسجد ولا يبالي فإذا سمح لهؤلاء بدخول المسجد تجمعت القاذورات والأذى في الفرش وتمنع بعض الناس من الصلاة في المساجد من أجل هذا فهو يجني على المصلين ويؤذيهم بما يتقذرون منه، وهو إنما جاء للخير وقصد الخير وفعل السنة، فالسنة في هذه الحال أن لا يؤذي المصلين وأن لا يقذر عليهم مسجدهم، هذا هو الذي ينبغي للمؤمن، ولاشك أن الفرش تتأثر بكل شيء، قد يكون فيه تراب قد يكون فيه طين قد يكون هناك أشياء متعلق بها من خرق أو أسلاك أو ما أشبه ذلك، فينبغي له في هذه الحال أنه يخلعها خارجًا عند الباب يصلي مكشوف القدمين حتى لا يؤذي الفرش ولا يؤذي المصلين بشيء، هذا هو الأفضل وهو مقتضى القواعد الشرعية، أما بدون فراش إذا صلى في نعليه فهو أفضل إذا كانت نظيفة سليمة ما فيها علة. نعم.\nالمقدم: جزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/8096/حكم-الصلاة-بالنعال-في-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_199/19908.mp3","categories":["المساجد ومواضع السجود"]},{"id":9951,"question":"في آخر رسالته الأخ أحمد علي حسن الزهراني يسأل بعد سؤاله عن حكم البناء على القبور يسأل: هل تجوز الصلاة في مسجد فيه قبر؟","title":"المسجد الذي فيه قبر، هل يُزال الأول منهما؟","answer":"الجواب: أما إن كانت القبور قديمة وبني المسجد عليها للتبرك بها فهذا هو المنكر فيهدم المسجد ولا يبقى المسجد إذا كان هو الأخير، إذا كان الأخير مسجد يهدم، وإذا كان المسجد قديمًا ثم دفن فيه ميت ينبش وينقل رفاته إلى مقابر المسلمين، نسأل الله الهداية للجميع. نعم.\nالمقدم: جزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/8119/المسجد-الذي-فيه-قبر-هل-يزال-الاول-منهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_200/20003.mp3","categories":["المساجد ومواضع السجود"]},{"id":9975,"question":"هذه رسالة من المستمع محمد شريف من المنطقة الشرقية الخبر، يقول في رسالته: يوجد عندنا في العمل مسجدان قام ببنائهما الموظفون وكلا المسجدين منحرفان عن القبلة، وواحد منهما فيه زيادة في جهة اليسار عن المحراب بحيث الذين يصفون من جهة اليسار يصلون إلى عشرين فرد والذين يصفون في جهة اليمين يصلون إلى عشرة فقط، والإخوان جميعًا يعلمون عن انحراف المسجدين عن القبلة وكذلك من يؤمنا، فما حكم الصلاة في هذه المساجد؟","title":"حكم الصلاة في المسجد المنحرف عن القبلة","answer":"الجواب: إذا كان الانحراف يسيرًا والجهة جهة القبلة فلا يضر، الانحراف اليسير يعفى عنه عند أهل العلم لقول النبي ﷺ: ما بين المشرق والمغرب قبلة يقوله في حق أهل المدينة ونحوهم، فهكذا في الشرق يقال: ما بين الجنوب والشمال قبلة وهكذا في الغرب يقال ما بين الجنوب والشمال قبلة، فالمقصود أن الانحراف اليسير الميل اليسير الذي لا يخرجه عن الجهة هذا يعفى عنه.\nأما إذا انحرف إلى الجهة الأخرى فهذا هو الذي لا يعفى عنه، أما الانحراف اليسير فيعفى عنه، وتوسط الإمام هو السنة، كون الإمام.... في الوسط هو السنة، فإذا كان الانحراف غير متوسط فالمشروع أن يوسطوه وأن ينقلوه إلى وسط المسجد لا إلى جهة أبعد عن الوسط فيكون الجماعة عنه على حد سواء، فإذا كان الصف ثلاثين يكون عنه كذا خمسة عشر وعنه من هنا خمسة عشر المتوسطة، هذا هو السنة وهذا هو المشروع. نعم.\nالمقدم: جزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/8131/حكم-الصلاة-في-المسجد-المنحرف-عن-القبلة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_200/20004.mp3","categories":["استقبال القبلة","المساجد ومواضع السجود"]},{"id":9992,"question":"تسأل وتقول: هل يجوز للحائض دخول المسجد وإذا كان الدم قد انقطع عنها ولكنها لم تغتسل بعد فما الحكم؟","title":"حكم دخول الحائض والجنب المسجد","answer":"الجواب: إذا كان الدخول لحاجة تأخذ حاجة من المسجد، تأخذ سجادة من المسجد تأخذ عصا تأخذ نعلين تأخذ حاجة من المسجد لا بأس، أما الجلوس فيه لا تجلس النبي ﷺ قال لـعائشة: ناوليني الخمرة - الحصير الذي يصلي عليه سجادة- قالت: يا رسول الله! إني حائض قال: إن حيضتك ليست في يدك فأمرها بالدخول وأخذ الخمرة يعني: الحصير وهي حائض، وقال الله جل وعلا في هذا المعنى: وَلا جُنُبًا إِلَّا عَابِرِي سَبِيلٍ [النساء:43] فالجنب كالحائض لا يدخل المسجد إلا عابر سبيل لا يجلس، فأذن الله في عابر السبيل الذي يمر مرور ويأخذ حاجة ويمر، سواءً من الجنب أو حائض أو نفساء، أما الجلوس لا، جاء في الحديث يقول ﷺ: إني لا أحل المسجد لحائض ولا جنب يعني: الجلوس فيه، ولهذا قال سبحانه: وَلا جُنُبًا إِلَّا عَابِرِي سَبِيلٍ [النساء:43]. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8164/حكم-دخول-الحاىض-والجنب-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_300/30005.mp3","categories":["المساجد ومواضع السجود","الحيض والنفاس","قضايا المرأة"]},{"id":10110,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من المستمع البشير حسن عثمان من السودان، أخونا البشير يقول: يوجد بقريتنا مسجد واحد، وعن شماله وخلفه قباب تشد إليها الرحال ويطاف حولها ويستغاث بها، ما حكم الصلاة في هذا المسجد وخاصة صلاة الجمعة، وهذا المسجد هو الوحيد في القرية؟ جزاكم الله خيرًا.","title":"حكم الصلاة في مسجد بجواره قباب تشد إليها الرحال","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فهذا المسجد إذا كان على ما ذكرت ليس في الصلاة فيه بأس، لا حرج أن يصلى فيه الجمعة وغير الجمعة، وكون هناك قبور عن شماله أو خلفه لا يمنع من ذلك، ولكن الواجب على أهل العلم وعلى أخيار القرية أن ينكروا على الناس عملهم مع القبور من الشرك بالله والاستغاثة بأهلها ودعائهم من دون الله والطواف بها كل هذا من المحرمات العظيمة، بل من الشرك الأكبر، سؤال الأموات والاستغاثة بالأموات من الشرك الأكبر ومن عمل الجاهلية، من عمل أبي جهل وأشباهه، وهكذا الطواف بالقبور يتقرب إليهم بالطواف هذا من الشرك الأكبر، أما إن كان يظن أن الطواف بالقبور عبادة لله لا يتقرب بها للقبر فهو بدعة ومنكر ومن وسائل الشرك؛ لأن الطواف إنما يكون بالبيت العتيق بالكعبة، فالطواف بالقبور إذا كان لقصد التقرب إلى أهلها كان شركًا أكبر، وإن كان قصد التقرب إلى الله يظن أنه قربة هنا فهذا كله بدعة ومنكر وباطل؛ لأن الطواف من خصائص البيت العتيق وَلْيَطَّوَّفُوا بِالْبَيْتِ الْعَتِيقِ [الحج:29].\nالمقصود أنه لا يجوز الطواف بالقبور، وإنما الطواف يكون بالبيت العتيق كما قال الله سبحانه: ثُمَّ لْيَقْضُوا تَفَثَهُمْ وَلْيُوفُوا نُذُورَهُمْ وَلْيَطَّوَّفُوا بِالْبَيْتِ الْعَتِيقِ [الحج:29]، والواجب على أهل العلم أينما كانوا أن يعلموا الناس ويرشدوهم، ولا سيما في السودان وفي غيرها من البلاد التي فيها القبور التي تعبد من دون الله، يجب على أهل العلم أن يعلموهم وأن ينكروا عليهم هذا الشرك العظيم، وهكذا المساجد التي تبنى على القبور لا تجوز، بل يجب هدمها وإزالتها، القبور يجب أن تكون ضاحية شامسة ليس فوقها بناء، لا قبور ولا غيرها، يقول النبي ﷺ: لعن الله اليهود والنصارى اتخذوا قبور أنبيائهم مساجد، ولما أخبرت أم سلمة وأم حبيبة رضي الله تعالى عنهما عن كنائس في الحبشة وما فيها من الصور قال عليه الصلاة والسلام: أولئك إذا مات فيهم الرجل الصالح بنوا على قبره مسجدًا وصوروا فيه تلك الصور أولئك شرار الخلق عند الله، فأخبر أنهم شرار الخلق لأنهم بنوا على القبور واتخذوا عليها الصور، وهذا من وسائل العبادة، من وسائل عبادتها من دون الله والشرك بها، فلهذا بين أنهم شرار الخلق عليه الصلاة والسلام، وصح عن جابر  عن النبي ﷺ: أنه نهى عن تجصيص القبور والقعود عليها والبناء عليها رواه مسلم في الصحيح، فلا يجوز أن يبنى على القبور لا مساجد ولا قباب ولا غيرها، ولا أن تجصص، ولا أن تدعى من دون الله، ولا يستغاث بأهلها، بل يجب الحذر من ذلك، إنما تزار الزيارة الشرعية للسلام على أهلها والدعاء لهم بالمغفرة والرحمة، فأما البناء عليها أو اتخاذ المساجد عليها أو القباب فهذا كله منكر ومن وسائل الشرك، وأما دعاؤها والاستغاثة بأهلها وطلبه المدد فهذا من الشرك الأكبر، إذا قال: يا فلان يا سيدي فلان المدد المدد، الغوث الغوث، هذا من الشرك الأكبر نعوذ بالله، كما يفعل ذلك عند بعض القبور كقبر البدوي والحسين في مصر والشيخ عبدالقادر في العراق وغيرها من القبور التي يعبدها الجهلة.\nفالواجب على أهل العلم أينما كانوا بيان هذا للناس وتحذيرهم من الشرك، والله أخذ على العلماء العهد والميثاق أن يبينوا للناس وأن ينذروهم ويعلموهم، والواجب على العامة أن يسألوا وأن يتبصروا ويتفقهوا في الدين، ولا يغتروا بعادات الآباء والأجداد، الله سبحانه ذم المشركين لما احتجوا بآبائهم حيث قال الله عنهم: إِنَّا وَجَدْنَا آبَاءَنَا عَلَى أُمَّةٍ وَإِنَّا عَلَى آثَارِهِمْ مُقْتَدُونَ [الزخرف:23] ذمهم على هذه الحال، فالواجب على المسلم أن يتبصر في دينه ويتفقه في دينه، يتعلم ويتبصر، يسأل أهل العلم ولا يحتج بالعادات الجاهلية ولا بعادات الآباء والأجداد التي تخالف شرع الله ، نسأل الله للجميع الهداية.\nالمقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8281/حكم-الصلاة-في-مسجد-بجواره-قباب-تشد-اليها-الرحال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_334/33401.mp3","categories":["المساجد ومواضع السجود"]},{"id":10261,"question":"رسالة وصلت إلى البرنامج من المستمع: عبدالمطلب عبدالرحمن حسين من السودان يقول فيها: يوجد عندنا مسجد جامع ولكن هنالك غرفة ملاصقة لصحن المسجد وبداخلها قبران، ويقدمون لها النذور العينية والمالية، ويعتقدون أن المقبورين من سلالة النبي ﷺ، ما حكم الصلاة في هذا المسجد؟ وأيضًا داخل السور توجد أمكنة كمصلى للأوقات ما حكم الصلاة أيضًا في ذلك المكان؟ علمًا بأنني أريد أن أدعو هؤلاء إلى الله عز وجل، ولكن لوجود القبرين توقفت عن الدعوة في هذا المسجد، ماذا أفعل؟ أرجوكم وجهوني جزاكم الله خيرًا؟","title":"حكم الصلاة في المسجد الذي فيه قبور والدعوة فيه","answer":"الجواب: إذا كان القبران خارجين عن سور المسجد فلا بأس أن يصلى في المسجد، وينبغي السعي من جماعة المسجد والمسئولين في نقل رفاتهما إلى المقبرة العامة حتى يسلم المسجد من الشبهة التي يحصل بها توقف بعض الناس عن الصلاة فيه، وإنما الممنوع إذا كانا في المسجد بني عليهما المسجد؛ لأن الرسول ﷺ لعن اليهود والنصارى اتخذوا قبور أنبيائهم مساجد فإذا كان القبران خارجين عن المسجد يمينًا أو شمالًا أو غربًا أو شرقًا، ليسا في داخله فلا بأس بالصلاة فيه، أما إذا كانا في داخل المسجد وبداخل سور المسجد فلا، إذا كان المسجد بني عليهما يعني: لتعظيمهما أما إذا كانا وجدا فيه بعد بنائه فإنهما ينبشان، وهكذا لو كان أكثر تنبش وتنقل إلى المقبرة ولا تبقى في المسجد، ويصلى في المسجد، إما إذا كان بني على القبور فهو الذي يهدم هو وتبقى القبور ضاحية شامسة ليس فيها مسجد ولا يصلى حولها؛ لأن الرسول ﷺ نهى من ذلك قال: لا تصلوا إلى القبور ولا تجلسوا عليها وقال: ألا وإن من كان قبلكم كانوا يتخذون قبور أنبيائهم وصالحيهم مساجد، ألا فلا تتخذوا القبور مساجد فإني أنهاكم عن ذلك وقال: لعن الله اليهود والنصارى اتخذوا قبور أنبيائهم مساجد.\nفالواجب على أهل الإيمان الحذر من ذلك، وألا يبنى على المساجد لا يتخذ عليها قبور، ولا تدفن الأموات في المساجد، بل يجب أن يكون الأموات مع إخوانهم في المقابر.\nويجب أن تكون المساجد خالية من ذلك بعيدة عن الشبهة، هذا هو الواجب على المسلمين، ولكن الصلاة صحيحة إذا كان القبر خارج المسجد خارج سور المسجد أما إن كان في داخل المسجد فلا يصلى فيه ولا تصح الصلاة. نعم.\nالمقدم: جزاكم الله خيرًا إذًا الدعوة في هذا المسجد ما حكمها والحال ما ذكر؟\nالشيخ: إذا جاء يدعوهم إلى الله لا بأس ما دام القبران خارجان عن المسجد، أما إذا كانا في المسجد فإنه يدعوهم إلى ترك الصلاة في المسجد ويدعوهم إذا كان بني على القبر يدعوهم إلى هدمه وإزالته، ويتصل بالمسئولين حتى يزال.\nأما إذا كان القبران محدثين في المسجد وهو السابق المسجد، فإنهما ينقلان، وهكذا لو كان أكثر من قبرين تنبش وتنقل إلى المقبرة العامة ويصلى في المسجد بعد ذلك ولا حرج؛ لأنها حادثة في المسجد هي، فلا حكم لها بل تنبش. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8432/حكم-الصلاة-في-المسجد-الذي-فيه-قبور-والدعوة-فيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_337/33701.mp3","categories":["المساجد ومواضع السجود"]},{"id":10321,"question":"بجوار بيتنا مسجد لا يصلي فيه إلا نحن أو من يزورنا، فهل تلزمنا الصلاة فيه دائماً؟","title":"هل يلزم الصلاة في المسجد المجاور الذي لا يأتي إليه المصلون","answer":"الجواب: نعم، تلزمكم الصلاة في المسجد المعد للصلاة، تصلون فيه ومن يزوركم أو من يمر عليكم. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8490/هل-يلزم-الصلاة-في-المسجد-المجاور-الذي-لا-ياتي-اليه-المصلون","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_314/31403.mp3","categories":["المساجد ومواضع السجود"]},{"id":10478,"question":"هل تجوز المحادثة بين الناس قبل الصلاة في المسجد إذا كانت المحادثة في أمور الدنيا، هذا السؤال من المستمع عبدالحميد عبد الله من الرياض؟","title":"حكم تحدث الناس عن أمور الدنيا في المساجد","answer":"الجواب:المساجد بنيت لذكر الله، وقراءة القرآن والصلاة والاعتكاف ودراسة العلم، لم تبن لأحاديث الدنيا، فلا ينبغي لأهل الإيمان أن يتخذوا المساجد لأحاديث الدنيا، لكن إذا كان شيء قليل لا حرج، الشيء القليل لا حرج فيه، كأن يسأله عن حاجة دنيوية، أو نحو ذلك لا تأخذ وقتاً، أو متى يسافر؟ أو هل قدم فلان أو ما قدم فلان؟ وكيف أولادك؟ كيف حالك؟ كيف مزرعتك لعلها سليمة؟ الشيء القليل الذي تدعو له الحاجة.\nالمقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/8653/حكم-تحدث-الناس-عن-امور-الدنيا-في-المساجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_281/28105.mp3","categories":["المساجد ومواضع السجود"]},{"id":10545,"question":"من المستمع أحمد سالم غالب من عدن رسالة وضمنها قضية يقول: في مسجدنا جامع كبير إلا أنه مبني على قبر، والناس يصلون في هذا المسجد، وقد أجريت توسعة لهذا المسجد لكن القبر لا زال داخل المسجد، كيف تنصحوننا وتنصحون الناس لدينا، جزاكم الله خيراً؟","title":"ما النصيحة في مسجد تم توسعته ولكنه مبني على قبر","answer":"الجواب: الواجب أن لا يدفن في المسجد قبور، الواجب أن تكون القبور خارج المساجد في مقابر خاصة، كما كان النبي ﷺ وأصحابه يفعلون في البقيع وغير البقيع، أما الصلاة في المساجد التي فيها القبور هذه لا تجوز ولا تصح، النبي عليه السلام يقول: لعن الله اليهود والنصارى اتخذوا قبور أنبيائهم مساجد، ويقول ﷺ: إلا وإن من كان قبلكم كانوا يتخذون قبور أنبيائهم وصالحيهم مساجد ألا فلا تتخذوا القبور مساجد فإني أنهاكم عن ذلك.\nوالرسول ﷺ نهى أن تتخذ مساجد، واتخاذ المساجد بالصلاة فيها والاعتكاف فيها، فلا يجوز هذا العمل بل يجب أن ينبش الموتى الذين في المساجد ويدفنون في خارج المساجد في المقابر العامة، إذا كان القبر حدث أخيراً بعد بناء المسجد وجب أن ينبش وينقل الرفاة إلى المقبرة العامة في حفرة مستقلة يواسع ظاهرها كالقبور حتى يسلم المسجد، وحتى يصلى فيه.\nولا يجوز التساهل في هذا الأمر، فإن الرسول ﷺ لعن من فعل ذلك وهو من سنة اليهود والنصارى ، فلا يجوز التشبه بهم في هذا الأمر، والصلاة باطلة في المسجد الذي فيه قبور تكون الصلاة فيه باطلة، سواءً كان في عدن أو في غير عدن.\nوإذا كان المسجد هو الأخير هو الذي بني على القبور وجب هدمه، وأن لا يبقى؛ لأنه أسس على الباطل، فالأول منهما يبقى، إن كان الأول القبر يبقى القبر ويهدم المسجد، فإذا كان الأول هو المسجد والقبر هو الحادث ينبش القبر ويزال من المسجد، ولا يجوز للمسلمين أن يصلوا في المساجد التي فيها قبور، والصلاة فيها غير صحيحة؛ لأن الأحاديث الصحيحة جاءت بذلك عن النبي ﷺ.\nولما ذكرت له أم سلمة و أم حبيبة رضي الله عنهما كنيسة رأتاها بأرض الحبشة وما فيها من الصور، قال: أولئك إذا مات فيهم الرجل الصالح بنوا على قبره مسجداً وصوروا فيه تلك الصور ثم قال ﷺ: أولئك شرار الخلق عند الله سماهم شرار الخلق بسبب عملهم السيئ، وهو البناء على القبور، واتخاذ المساجد عليها، وتصوير الصور عليها.\nفالواجب الحذر الواجب على المسلمين في أي مكان الحذر من هذا العمل السيئ، يجب على المسئولين في مصر والشام واليمن وغيرها، يجب عليهم أن يزيلوا القبور من المساجد، وينقلوها للمقابر العامة، إذا كانت ........... أو لم يتوضأ أجزأ .......... نعم ..... جزاكم .......... كونه يعاشرها عشرة طيبة وهي تعاشره عشرة طيبة، وليس لها أن تعصيه في المعروف، وليس له أيضاً أن يؤذيها ويظلمها بل عليه أن يعاشرها بالمعروف من جهة الخلق والكلام الطيب، والعمل الطيب والإنفاق عليها كما شرع الله، و ............ والكلام الطيب، وهي عليها كذلك أن تبادله ذلك، مع السمع والطاعة في المعروف، وليس لها أن تعصيه في معروف، وإذا حلف عليها أن تفعل كذا وكذا ولم تبر يمينه فعليه كفارة يمين، إذا كان قصده إنما هو أمرها أو تحذيرها كأن يقول: والله تفعلي كذا، والله لا تفعلي كذا قصده من هذا حثها أو ترهيبها، وليس قصده طلاقاً، فإن عليه كفارة يمين، فإذا قال عليه الطلاق أن تلزمي بيتك ولا تخرجي إلى آل فلان ثم خرجت وقصده ترهيبها ........................\nالمقدم: ....... على خير.\nالشيخ: نسأل الله ذلك.","link":"https://binbaz.org.sa/fatwas/8730/ما-النصيحة-في-مسجد-تم-توسعته-ولكنه-مبني-على-قبر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_321/32110.mp3","categories":["المساجد ومواضع السجود"]},{"id":10651,"question":"هذا السائل علي محمد يقول: السلام عليكم ورحمة الله وبركاته، يوجد في قريتنا في بلدي مسجد وهذا المسجد بداخله قبر، فهل نقوم بإلغاء المسجد أو بإلغاء القبر من داخله، وهل الصلاة في مسجد يوجد فيه قبر صحيحة، السائل من اليمن ومقيم بالقصيم؟","title":"مسجد بداخله قبر، فهل نهدم المسجد أم نزيل القبر؟","answer":"الجواب: الصلاة في المساجد التي فيها القبور لا تجوز، ولا تصح، ولا يجوز البناء على القبور، بناء المساجد على القبور لا يجوز، ولا يجوز اتخاذ القباب عليها ولا الستور، كل هذا لا يجوز، بل هو من أسباب الشرك، فالمسجد الذي فيه قبر لا يصلى فيه، والصلاة فيه غير صحيحة، لكن إذا كان المسجد هو القديم وقبر فيه قبور تنبش، تنقل إلى المقبرة، يصلى في المسجد لا بأس، أما إذا كان القبور هي القديمة وهو اللي بني عليها يهدم، ولا يجوز بقاءه بل يهدم، وبكل حال فالمسلم لا يصلي في المساجد التي فيها القبور، بل صلاته غير صحيحة؛ لأن بناء المساجد على القبور والصلاة عند القبور وسيلة للشرك، ولهذا قال ﷺ: لعن الله اليهود والنصارى اتخذوا قبور أنبيائهم مساجد وقال ﷺ: لا تصلوا إلى القبور ولا تجلسوا عليها وقال: ألا وإن من كان قبلكم كانوا يتخذون قبورر أنبيائهم وصالحيهم مساجد ألا فلا تتخذوا القبور مساجد فإني أنهاكم عن ذلك فالمقصود ﷺ أنه نهى اتخاذ المساجد على القبور، وعن الصلاة عند القبور، وعن الجلوس عليها، فلا يجوز للمسلم أن يطأ عليها، ولا يجلس عليها، ولا يصلي إليها، ولا يبني عليها بناء، ولا مسجد ولا قبة، ولا تجصص، نهى الرسول عن تجصيصها وعن القعود عليها وعن البناء عليها، عليه الصلاة والسلام، كل هذا من عمل أهل الشرك، نعم.\nالمقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/8828/مسجد-بداخله-قبر-فهل-نهدم-المسجد-ام-نزيل-القبر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_285/28513.mp3","categories":["المساجد ومواضع السجود"]},{"id":10718,"question":"يقول: في بلدتنا يوجد مكان لمقبرة قديمة وقد أزيلت هذه المقبرة منذ خمسة وعشرين أو ثلاثين عاماً، وبني على أرضها مسجد كبير، ما صحة صلاتنا في هذا المسجد؟","title":"حكم الصلاة في مقبرة نبشت وأقيم مكانها مسجد","answer":"الجواب: إذا كانت قد أزيلت بوجه شرعي وفتوى شرعية، أزيلت القبور ونبشت وحولت إلى مكان آخر فلا بأس، إذا كان على وجه شرعي، فقد كان موضع مسجد النبي ﷺ فيه قبور، فلما أراد أن يبني المسجد أمر بالقبور فنبشت من قبور المشركين نبشت وأزيلت، وكان في حفر وخرب فسويت، وكان في محل نخيل فقطعت، ثم بنى مسجده عليه الصلاة والسلام، فإذا كانت المقبرة في محل غير مناسب، ورأى ولي الأمر والعلماء نبشها ونقل القبور إلى محل مناسب، فلا بأس أن يبنى فيها مسجد أو بيوت للمصلحة الشرعية، نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8891/حكم-الصلاة-في-مقبرة-نبشت-واقيم-مكانها-مسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_343/34306.mp3","categories":["المساجد ومواضع السجود"]},{"id":10733,"question":"رسالة من المستمع (ش. ع. ب) من العراق، يسأل ويقول: هل صحيح ما قرأت في بعض كتب الفتاوى: بأن القطن والصوف والسجاد لا يجوز الصلاة عليها، وأن الصلاة تجوز على الأرض وما زرع عليها.ويقولون: بأن الرسول ﷺ كان يصلي على حصير، ولم يصل على عباءته أو شيء مصنوع من الصوف والقطن؟","title":"حكم الصلاة على القطن والصوف والسجاد","answer":"الجواب: الصواب في هذا أنه لا حرج في ذلك، لا بأس بالصلاة على الفرش من القطن والصوف والوبر، وكذلك من سعف النخل وغير ذلك، كل هذا لا حرج فيه عند أهل العلم، والنبي ﷺ صلى على الخضرة وهي من سعف النخل وصلى الصحابة على الأنماط من القطن وغيرها، وليس في هذا محظور بحمد الله عند أهل العلم عند علماء السنة، كل ذلك جائز والحمد لله، يصلي الإنسان على القطن والصوف وعلى ما نبت من الأرض من سائر الشجر من سعف النخل وغيره كله بحمد الله واسع. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8916/حكم-الصلاة-على-القطن-والصوف-والسجاد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_345/34507.mp3","categories":["المساجد ومواضع السجود"]},{"id":10772,"question":"ننتقل بعد هذا إلى السودان عبر رسالة وصلت من المستمع مختار عثمان من دنقلة ديوان الضرائب، أخونا مختار ضمن رسالته جمعاً من الأسئلة من بينها سؤال يقول فيه: في مدينة دنقلة مسجد كبير وبه ضريحان لشخصين يعتقد الناس أنهم من الصالحين، وهذه الأضرحة تزار وتقدم له القربان والمقابر من جهة القبلة، ويفصل بينها وبين المصلين حائط المصلى فقط،  هل يجوز لي أن أصلي في هذا المسجد لتبليغ الدين، علماً بأن المسجد يجمع أناساً كثيرين من مناطق مختلفة، وإذا صليت ما حكم صلاتي هل أعيدها أم ماذا أفعل؟","title":"بناء المساجد على القبور من وسائل الشرك","answer":"الجواب: بناء المساجد على القبور منكر عظيم ومن وسائل الشرك، لقول النبي ﷺ: لعن الله اليهود و النصارى اتخذوا قبور أنبيائهم مساجد، فلا يجوز البناء على القبور ولا اتخاذ المساجد عليها، ولا جعلها مصلى، فالمسجد الذي فيه قبر أو أكثر لا يصلى فيه، والصلاة فيه غير صحيحة؛ لأن الرسول ﷺ نهى عنها ولعن من فعل ذلك عليه الصلاة والسلام، وقال في الحديث الآخر الذي رواه مسلم في الصحيح: ألا وإن من كان قبلكم كانوا يتخذون قبور أنبيائهم وصالحيهم مساجد، ألا فلا تتخذوا القبور مساجد فإني أنهاكم عن ذلك، فنهى عن اتخاذ القبور مساجد وقال: إنه ينهى عن هذا، ولعن من فعل هذا وذمه.\nفلا يجوز للمسلمين أن يصلوا في المساجد التي فيها قبور، بل يجب نبشها.. يجب على الدولة وعلى أهل الحل والعقد أن ينبشوها ويجعلوها في مقابر المسلمين، لتبقى المساجد ليس فيها قبور، على الدولة إذا كانت تدين بالإسلام أن تنبش هذه القبور التي في المساجد وأن تجعلها مع المسلمين في مقابرهم، حتى تخلو المساجد من القبور.\nهذا إن كانت القبور بعد المسجد، أما إن كان المسجد بني عليها وهي قديمة فالواجب أن يهدم المسجد، ولا يصلى فيه ويلتمس أهل الحي أرضاً أخرى ليس فيها قبور فيعمروا بها مسجداً ويصلون فيه.\nأما المسجد الذي بني على القبور الواجب هدمه؛ لأنه أسس على معصية الله، وقد ثبت عن الرسول ﷺ: أنه نهى عن تجصيص القبور والقعود عليها والبناء عليها رواه مسلم في الصحيح من حديث جابر .\nوالخلاصة: أن القبر إن كان جديداً والمسجد هو الأسبق وجب نبش القبر ونقل الرفاة إلى المقابر الأخرى، تجعل في حفرة ويسوى ظاهرها كالقبر، وهكذا لو كان أكثر من قبر قبرين ثلاثة كلها تنقل، كل رفاة قبر تجعل في حفرة وحدها في المقابر العامة يجعل ظاهرها كظاهر القبور حتى لا تمتهن ويبقى المسجد خالياً يصلى فيه.\nأما إن كانت القبور هي الأصل والمسجد هو الحادث بني عليها فإنه يهدم، لأنه أسس على غير التقوى على المعصية فيهدم، ويبنى لأهل الحي مسجد في محل آخر ليس فيه قبور طاعة لله ولرسوله عليه الصلاة والسلام، وعملاً بما دلت عليه النصوص، وتحذيراً للمسلمين من الشرك وقطعاً لوسائله؛ لأن وجود القبور في المساجد من وسائل الشرك ومن وسائل الغلو فيها، ومن وسائل دعائها والاستغاثة بها والنذر لها، ثم الطواف بها ولا حول ولا قوة إلا بالله فيجب الحذر من ذلك.\nأما إن كان القبر خارج المسجد عن يمنيه أو شماله أو أمامه أو خلفه وليس في داخله فالصلاة صحيحة، لكن لو تيسر إبعاده في المقابر يكون أولى حتى لا يغلو فيه أحد، إذا كان خارج المسجد خارج بناء المسجد عن يمين أو شمال أو أمام أو خلف فالأولى والأفضل أن ينقل لا يبقى قبر عند المسجد لئلا يغلى فيه، فينقل للمقابر العامة، ولكن الصلاة به صحيحة؛ لأن المسجد سليم من القبور ليس فيه قبور ليس بداخله قبور.\nونسأل الله أن يوفق ولاة أمور المسلمين لتطهير بلادهم من آثار الشرك ووسائله، وأن يعينهم على كل خير، وأن يصلح قلوبهم وأعمالهم وبطانتهم، وأن يوفق العلماء للقيام بما يجب من النصيحة لولاة الأمور وإرشادهم إلى الخير وإعانتهم عليه، فإن واجب العلماء عظيم في كل مكان في السودان وغير السودان واجب العلماء عظيم، يجب عليهم أن يرشدوا الناس إلى أن دعاء الأموات والاستغاثة بالأموات أمر منكر بل شرك أكبر، وأنه لا يجوز الغلو في القبور ولا الطواف بها ولا دعاء أهلها والاستغاثة بهم ولا أن يطلب منهم المدد هذا منكر عظيم وشرك أكبر.\nفالواجب على أهل العلم في السودان، وفي مصر وفي الشام وفي الأردن وفي كل مكان وفي هذه الجزيرة كلها في اليمن وفي هذه الجزيرة وفي الخليج في كل مكان، الواجب على العلماء أن يبينوا أمر الله، وأن يرشدوا الناس إلى توحيد الله وطاعة الله، وأن ينكروا عليهم المنكرات حتى يعرف الناس المنكر وحتى يحذروه، فالعلماء هم ورثة الأنبياء وعليهم واجب عظيم هو واجب الدعوة والبلاغ والأمر بالمعروف والنهي عن المنكر، في كل بلد وفي كل دولة.\nوعلى العلماء إذا كانت الدولة كافرة أن يرفعوا إليها ويبينوا لها أن هذا الأمر كذا وكذا حتى تسمح لهم بعمل ما شرعه الله؛ لأنه لابد من قوة تعين على إزالة المنكر؛ لأن العامة الجهلة قد يعترضون على أهل العلم فلابد من الاستعانة بالله ثم بالدولة حتى تعينهم على هدم المساجد التي بنيت على القبور، وحتى تعينهم على نقل القبور التي وضعت في المساجد تنقل رفاتها إلى المقابر العامة، وليس لأحد أن يفعل ما يحصل به التشويش بل عليه أن يستأذن من ولاة الأمور حتى تجري الأمور على طريقة حسنة مضبوطة من جهة ولاة الأمور، وإذا كان ولي الأمر قد جعل الأمر لأمير البلد وعلماء البلد قاموا بالواجب، فالعلماء يرفعون لأمير البلد وأمير البلد ينفذ ويتعاون الجميع على البر والتقوى، كما قال الله سبحانه: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى [المائدة:2]، ولا يجوز للعالم السكوت عن هذا الأمر العظيم والخطر الكبير، يجب على أنصار السنة في مصر والشام وفي السودان وفي كل مكان وعلى العلماء جميعاً في كل مكان أن يبينوا للناس أمر الله، وأن يشرحوا لهم حقيقة الدين، وأن يوضحوا لهم أنواع الشرك الأكبر والأصغر وسائر المعاصي حتى يجتنبوها حتى يحذروها، ويجب على العلماء أن ينكروا على الناس دعاء الأموات والاستغاثة بالأموات والنذر للأموات والذبح لهم وأن يجعل صناديق للنذور هذا منكر عظيم وشرك وخيم، يجب أن ينكر.. يجب على العلماء أن ينكروه بغاية النشاط وبالأساليب الحسنة التي يحصل بها إنكار المنكر، ولا يحصل بها التشويش مع ولاة الأمور بل يتصلون بولاة الأمور ويخبرونهم بما يجب حتى تتفق الكلمة مع ولاة الأمور في إنكار المنكر، والقضاء على أسباب الشر والفساد والشرك.\nفالعلماء واجبهم عظيم وهم مسئولون أمام الله يوم القيامة، مسئولون عما قصروا فيه وعما لم يقوموا به من الواجب هم ورثة الرسل هم خلفاؤهم، يقول الله سبحانه: فَوَرَبِّكَ لَنَسْأَلَنَّهُمْ أَجْمَعِينَ ۝ عَمَّا كَانُوا يَعْمَلُونَ [الحجر:92-93]، ولاسيما فيما يتعلق بالعقيدة ما يتعلق بالشرك والتوحيد فإنه أعظم من غيره، فأصل الدين وأساس الملة عبادة الله وحده، وهو معنى: لا إله إلا الله، فإن معناها: لا معبود حق إلا الله، كما قال سبحانه: وَإِلَهُكُمْ إِلَهٌ وَاحِدٌ لا إِلَهَ إِلَّا هُوَ الرَّحْمَنُ الرَّحِيمُ [البقرة:163] وقال سبحانه في سورة الحج: ذَلِكَ بِأَنَّ اللَّهَ هُوَ الْحَقُّ وَأَنَّ مَا يَدْعُونَ مِنْ دُونِهِ هُوَ الْبَاطِلُ [الحج:62].\nفدعوة الأموات والاستغاثة بالأموات والنذر لهم وطلبهم المدد هذا من الشرك الأكبر، سواء كانوا أنبياء أو صالحين أو غيرهم، هذا حق الله، العبادة حق الله وحده لا يدعى إلا الله ولا يستغاث إلا به، فالأموات قد انقطعت أعمالهم إلا مما شرع الله من صدقة جارية أو علم ينتفع به أو ولد صالح يدعو لأبيه وأمه.\nالمقصود: أنهم لا يدعون مع الله ولا يستغاث بهم، ولا ينذر لهم ولا يذبح لهم، ولا يطلب منهم المدد ولو كانوا عظماء في الدين، كالعلماء والرسل لا يجوز هذا أبداً، بل دين الله سبحانه إخلاص العبادة لله وحده قال: وَقَضَى رَبُّكَ أَلَّا تَعْبُدُوا إِلَّا إِيَّاهُ [الإسراء:23] .. إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ [الفاتحة:5] .. وَمَا خَلَقْتُ الْجِنَّ وَالإِنسَ إِلَّا لِيَعْبُدُونِ [الذاريات:56] هكذا يقول سبحانه، ويقول  فَادْعُوا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ [غافر:14] .. فَاعْبُدِ اللَّهَ مُخْلِصًا لَهُ الدِّينَ [الزمر:2].\nأما الحي القادر لا بأس أن يستعان به الحي القادر، تقول لأخيك: أعني على كذا يسمع كلامك، أو من طريق الهاتف أو من طريق الكتابة تقول: يا أخي! ساعدني على كذا، أعني على مزرعتي على إصلاح سيارتي، اشتر لي كذا، لا بأس بالتعاون بين الأحياء. أما دعاء الأموات أو دعاء الغائبين يعتقد أن لهم سراً يسمعون وهم غائبون بدون واسطة هذا شرك أكبر، أو دعاء الجن، أو دعاء الملائكة أو الاستغاثة بهم هذا هو الشرك الأكبر، الذي بعث الله الرسل بإنكاره والنهي عنه والتحذير منه، وهو مصادم لقوله : إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ [الفاتحة:5] ولقوله سبحانه: وَقَضَى رَبُّكَ أَلَّا تَعْبُدُوا إِلَّا إِيَّاهُ [الإسراء:23] .. وَمَا خَلَقْتُ الْجِنَّ وَالإِنسَ إِلَّا لِيَعْبُدُونِ [الذاريات:56].\nنسأل الله أن يوفق ولاة الأمور من الأمراء والعلماء لكل ما فيه صلاح العباد والبلاد، وأن يعينهم على كل خير، وأن يصلح لهم البطانة وأن يجعلهم هداة مهتدين وإيانا وسائر إخواننا، ولا حول ولا قوة إلا بالله. نعم.\nالمقدم: اللهم آمين، جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8950/بناء-المساجد-على-القبور-من-وساىل-الشرك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_349/34902.mp3","categories":["المساجد ومواضع السجود"]},{"id":10773,"question":"يسأل أيضاً سماحة الشيخ فيما يسأل عنه ويقول: هل لي أن أبلغ في هذا المسجد والحال كما ذكرت؟","title":"حكم دخول المسجد الذي فيه قبر لإنكار المنكر","answer":"الجواب: يبلغ ما يصلي معهم، إذا كان.. ما دام القبور في المسجد لا يصلي معهم.\nالمقدم: إذا كان القبر داخل المسجد.\nالشيخ: يجلس فإذا صلوا ينبههم أو في أوقات أخرى، في غير المساجد في الاجتماعات الأخرى، أما إذا كان القبر خارج المسجد فلا بأس يصلي معهم ويذكرهم بالله ويعلمهم دينهم، أما إذا كان القبر في داخل المسجد أو القبور في داخل المسجد فلا يصلى فيها لعن الله اليهود و النصارى اتخذوا قبور أنبيائهم مساجد، هكذا قال عليه الصلاة والسلام، ولكن المؤمن يتحرى الأوقات المناسبة، فإذا جاءهم وقد صلوا ذكرهم أو ذكرهم قبل الصلاة وقال: إني أحب أن أصلي معكم لولا هذا القبر، والمساجد التي فيها قبور لا يصلى فيها، يعلمهم يرشدهم أو بعد الصلاة كذلك يرشدهم ولا حرج في ذلك، والحمد لله. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8951/حكم-دخول-المسجد-الذي-فيه-قبر-لانكار-المنكر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_349/34903.mp3","categories":["المساجد ومواضع السجود"]},{"id":10777,"question":"ننتقل بعد هذا إلى السودان عبر رسالة وصلت من المستمع مختار عثمان من دنقلة ديوان الضرائب، أخونا مختار ضمن رسالته جمعاً من الأسئلة من بينها سؤال يقول فيه: في مدينة دنقلة مسجد كبير وبه ضريحان لشخصين يعتقد الناس أنهم من الصالحين، وهذه الأضرحة تزار وتقدم له القربان والمقابر من جهة القبلة، ويفصل بينها وبين المصلين حائط المصلى فقط،  هل يجوز لي أن أصلي في هذا المسجد لتبليغ الدين، علماً بأن المسجد يجمع أناساً كثيرين من مناطق مختلفة، وإذا صليت ما حكم صلاتي هل أعيدها أم ماذا أفعل؟","title":"بناء المساجد على القبور من وسائل الشرك","answer":"الجواب: بناء المساجد على القبور منكر عظيم ومن وسائل الشرك، لقول النبي ﷺ: لعن الله اليهود و النصارى اتخذوا قبور أنبيائهم مساجد، فلا يجوز البناء على القبور ولا اتخاذ المساجد عليها، ولا جعلها مصلى، فالمسجد الذي فيه قبر أو أكثر لا يصلى فيه، والصلاة فيه غير صحيحة؛ لأن الرسول ﷺ نهى عنها ولعن من فعل ذلك عليه الصلاة والسلام، وقال في الحديث الآخر الذي رواه مسلم في الصحيح: ألا وإن من كان قبلكم كانوا يتخذون قبور أنبيائهم وصالحيهم مساجد، ألا فلا تتخذوا القبور مساجد فإني أنهاكم عن ذلك، فنهى عن اتخاذ القبور مساجد وقال: إنه ينهى عن هذا، ولعن من فعل هذا وذمه.\nفلا يجوز للمسلمين أن يصلوا في المساجد التي فيها قبور، بل يجب نبشها.. يجب على الدولة وعلى أهل الحل والعقد أن ينبشوها ويجعلوها في مقابر المسلمين، لتبقى المساجد ليس فيها قبور، على الدولة إذا كانت تدين بالإسلام أن تنبش هذه القبور التي في المساجد وأن تجعلها مع المسلمين في مقابرهم، حتى تخلو المساجد من القبور.\nهذا إن كانت القبور بعد المسجد، أما إن كان المسجد بني عليها وهي قديمة فالواجب أن يهدم المسجد، ولا يصلى فيه ويلتمس أهل الحي أرضاً أخرى ليس فيها قبور فيعمروا بها مسجداً ويصلون فيه.\nأما المسجد الذي بني على القبور الواجب هدمه؛ لأنه أسس على معصية الله، وقد ثبت عن الرسول ﷺ: أنه نهى عن تجصيص القبور والقعود عليها والبناء عليها رواه مسلم في الصحيح من حديث جابر .\nوالخلاصة: أن القبر إن كان جديداً والمسجد هو الأسبق وجب نبش القبر ونقل الرفاة إلى المقابر الأخرى، تجعل في حفرة ويسوى ظاهرها كالقبر، وهكذا لو كان أكثر من قبر قبرين ثلاثة كلها تنقل، كل رفاة قبر تجعل في حفرة وحدها في المقابر العامة يجعل ظاهرها كظاهر القبور حتى لا تمتهن ويبقى المسجد خالياً يصلى فيه.\nأما إن كانت القبور هي الأصل والمسجد هو الحادث بني عليها فإنه يهدم، لأنه أسس على غير التقوى على المعصية فيهدم، ويبنى لأهل الحي مسجد في محل آخر ليس فيه قبور طاعة لله ولرسوله عليه الصلاة والسلام، وعملاً بما دلت عليه النصوص، وتحذيراً للمسلمين من الشرك وقطعاً لوسائله؛ لأن وجود القبور في المساجد من وسائل الشرك ومن وسائل الغلو فيها، ومن وسائل دعائها والاستغاثة بها والنذر لها، ثم الطواف بها ولا حول ولا قوة إلا بالله فيجب الحذر من ذلك.\nأما إن كان القبر خارج المسجد عن يمنيه أو شماله أو أمامه أو خلفه وليس في داخله فالصلاة صحيحة، لكن لو تيسر إبعاده في المقابر يكون أولى حتى لا يغلو فيه أحد، إذا كان خارج المسجد خارج بناء المسجد عن يمين أو شمال أو أمام أو خلف فالأولى والأفضل أن ينقل لا يبقى قبر عند المسجد لئلا يغلى فيه، فينقل للمقابر العامة، ولكن الصلاة به صحيحة؛ لأن المسجد سليم من القبور ليس فيه قبور ليس بداخله قبور.\nونسأل الله أن يوفق ولاة أمور المسلمين لتطهير بلادهم من آثار الشرك ووسائله، وأن يعينهم على كل خير، وأن يصلح قلوبهم وأعمالهم وبطانتهم، وأن يوفق العلماء للقيام بما يجب من النصيحة لولاة الأمور وإرشادهم إلى الخير وإعانتهم عليه، فإن واجب العلماء عظيم في كل مكان في السودان وغير السودان واجب العلماء عظيم، يجب عليهم أن يرشدوا الناس إلى أن دعاء الأموات والاستغاثة بالأموات أمر منكر بل شرك أكبر، وأنه لا يجوز الغلو في القبور ولا الطواف بها ولا دعاء أهلها والاستغاثة بهم ولا أن يطلب منهم المدد هذا منكر عظيم وشرك أكبر.\nفالواجب على أهل العلم في السودان، وفي مصر وفي الشام وفي الأردن وفي كل مكان وفي هذه الجزيرة كلها في اليمن وفي هذه الجزيرة وفي الخليج في كل مكان، الواجب على العلماء أن يبينوا أمر الله، وأن يرشدوا الناس إلى توحيد الله وطاعة الله، وأن ينكروا عليهم المنكرات حتى يعرف الناس المنكر وحتى يحذروه، فالعلماء هم ورثة الأنبياء وعليهم واجب عظيم هو واجب الدعوة والبلاغ والأمر بالمعروف والنهي عن المنكر، في كل بلد وفي كل دولة.\nوعلى العلماء إذا كانت الدولة كافرة أن يرفعوا إليها ويبينوا لها أن هذا الأمر كذا وكذا حتى تسمح لهم بعمل ما شرعه الله؛ لأنه لابد من قوة تعين على إزالة المنكر؛ لأن العامة الجهلة قد يعترضون على أهل العلم فلابد من الاستعانة بالله ثم بالدولة حتى تعينهم على هدم المساجد التي بنيت على القبور، وحتى تعينهم على نقل القبور التي وضعت في المساجد تنقل رفاتها إلى المقابر العامة، وليس لأحد أن يفعل ما يحصل به التشويش بل عليه أن يستأذن من ولاة الأمور حتى تجري الأمور على طريقة حسنة مضبوطة من جهة ولاة الأمور، وإذا كان ولي الأمر قد جعل الأمر لأمير البلد وعلماء البلد قاموا بالواجب، فالعلماء يرفعون لأمير البلد وأمير البلد ينفذ ويتعاون الجميع على البر والتقوى، كما قال الله سبحانه: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى [المائدة:2]، ولا يجوز للعالم السكوت عن هذا الأمر العظيم والخطر الكبير، يجب على أنصار السنة في مصر والشام وفي السودان وفي كل مكان وعلى العلماء جميعاً في كل مكان أن يبينوا للناس أمر الله، وأن يشرحوا لهم حقيقة الدين، وأن يوضحوا لهم أنواع الشرك الأكبر والأصغر وسائر المعاصي حتى يجتنبوها حتى يحذروها، ويجب على العلماء أن ينكروا على الناس دعاء الأموات والاستغاثة بالأموات والنذر للأموات والذبح لهم وأن يجعل صناديق للنذور هذا منكر عظيم وشرك وخيم، يجب أن ينكر.. يجب على العلماء أن ينكروه بغاية النشاط وبالأساليب الحسنة التي يحصل بها إنكار المنكر، ولا يحصل بها التشويش مع ولاة الأمور بل يتصلون بولاة الأمور ويخبرونهم بما يجب حتى تتفق الكلمة مع ولاة الأمور في إنكار المنكر، والقضاء على أسباب الشر والفساد والشرك.\nفالعلماء واجبهم عظيم وهم مسئولون أمام الله يوم القيامة، مسئولون عما قصروا فيه وعما لم يقوموا به من الواجب هم ورثة الرسل هم خلفاؤهم، يقول الله سبحانه: فَوَرَبِّكَ لَنَسْأَلَنَّهُمْ أَجْمَعِينَ ۝ عَمَّا كَانُوا يَعْمَلُونَ [الحجر:92-93]، ولاسيما فيما يتعلق بالعقيدة ما يتعلق بالشرك والتوحيد فإنه أعظم من غيره، فأصل الدين وأساس الملة عبادة الله وحده، وهو معنى: لا إله إلا الله، فإن معناها: لا معبود حق إلا الله، كما قال سبحانه: وَإِلَهُكُمْ إِلَهٌ وَاحِدٌ لا إِلَهَ إِلَّا هُوَ الرَّحْمَنُ الرَّحِيمُ [البقرة:163] وقال سبحانه في سورة الحج: ذَلِكَ بِأَنَّ اللَّهَ هُوَ الْحَقُّ وَأَنَّ مَا يَدْعُونَ مِنْ دُونِهِ هُوَ الْبَاطِلُ [الحج:62].\nفدعوة الأموات والاستغاثة بالأموات والنذر لهم وطلبهم المدد هذا من الشرك الأكبر، سواء كانوا أنبياء أو صالحين أو غيرهم، هذا حق الله، العبادة حق الله وحده لا يدعى إلا الله ولا يستغاث إلا به، فالأموات قد انقطعت أعمالهم إلا مما شرع الله من صدقة جارية أو علم ينتفع به أو ولد صالح يدعو لأبيه وأمه.\nالمقصود: أنهم لا يدعون مع الله ولا يستغاث بهم، ولا ينذر لهم ولا يذبح لهم، ولا يطلب منهم المدد ولو كانوا عظماء في الدين، كالعلماء والرسل لا يجوز هذا أبداً، بل دين الله سبحانه إخلاص العبادة لله وحده قال: وَقَضَى رَبُّكَ أَلَّا تَعْبُدُوا إِلَّا إِيَّاهُ [الإسراء:23] .. إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ [الفاتحة:5] .. وَمَا خَلَقْتُ الْجِنَّ وَالإِنسَ إِلَّا لِيَعْبُدُونِ [الذاريات:56] هكذا يقول سبحانه، ويقول  فَادْعُوا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ [غافر:14] .. فَاعْبُدِ اللَّهَ مُخْلِصًا لَهُ الدِّينَ [الزمر:2].\nأما الحي القادر لا بأس أن يستعان به الحي القادر، تقول لأخيك: أعني على كذا يسمع كلامك، أو من طريق الهاتف أو من طريق الكتابة تقول: يا أخي! ساعدني على كذا، أعني على مزرعتي على إصلاح سيارتي، اشتر لي كذا، لا بأس بالتعاون بين الأحياء. أما دعاء الأموات أو دعاء الغائبين يعتقد أن لهم سراً يسمعون وهم غائبون بدون واسطة هذا شرك أكبر، أو دعاء الجن، أو دعاء الملائكة أو الاستغاثة بهم هذا هو الشرك الأكبر، الذي بعث الله الرسل بإنكاره والنهي عنه والتحذير منه، وهو مصادم لقوله : إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ [الفاتحة:5] ولقوله سبحانه: وَقَضَى رَبُّكَ أَلَّا تَعْبُدُوا إِلَّا إِيَّاهُ [الإسراء:23] .. وَمَا خَلَقْتُ الْجِنَّ وَالإِنسَ إِلَّا لِيَعْبُدُونِ [الذاريات:56].\nنسأل الله أن يوفق ولاة الأمور من الأمراء والعلماء لكل ما فيه صلاح العباد والبلاد، وأن يعينهم على كل خير، وأن يصلح لهم البطانة وأن يجعلهم هداة مهتدين وإيانا وسائر إخواننا، ولا حول ولا قوة إلا بالله. نعم.\nالمقدم: اللهم آمين، جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8950/بناء-المساجد-على-القبور-من-وساىل-الشرك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_349/34902.mp3","categories":["المساجد ومواضع السجود"]},{"id":10914,"question":"ننتقل بعد هذا إلى السودان عبر رسالة وصلت إلينا من المستمع الطيب محمد صالح إبراهيم من الإدارة الزراعية، الأخ الطيب بعث بستة أسئلة: في أحدها يقول: عندنا في السودان قل أن تجد مسجدًا لا توجد فيه بدعة، وأحيانًا تجد بنيانًا مزعومًا لولي، أو قبورًا في فناء المسجد، فماذا أفعل حيال هذه المنكرات؟ أؤصلي في مثل هذه المساجد؟","title":"حكم الصلاة في المساجد التي فيها بدع","answer":"الجواب:  نعم، إذا كنت في مسجد فيه بعض البدع صل مع الناس، وأنكر البدعة، إذا كان فيه بدعة أنكرها، قل: يا إخواني! هذا ما يجوز -هداكم الله- وتعاون مع العلماء والأخيار في إزالتها، ومع المسؤولين من الأمراء وغيرهم، تعاونوا على البر والتقوى، أما المسجد الذي فيه قبور لا تصل فيه، الرسول ﷺ لعن اليهود والنصارى قال: اتخذوا قبور أنبيائهم مساجد. فالمسجد الذي فيه قبر لا تصل فيه، التمس مسجدًا ليس فيه قبر، وأما إذا كان فيه بدعة، وأنت تجد مساجد ما فيها بدعة صل في المساجد التي ما فيها بدعة، وإذا لم تجد، أو استطعت أن تنكر البدعة فصل معهم، وأنكر البدعة وعلمهم، وجههم حتى تكون هاديًا مهديًا، وحتى تنقذهم من هذه البدعة، فإن لم يستجيبوا لك ووجدت مسجدًا ليس فيه بدعة فاعتزلهم، وصل في مسجد الآخر، وإلا فصل معهم، واستقم على إنكار البدعة، وتعليمهم، ولا تيئس، والله يعينك ويوفقك على مثل هذا الخير. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9096/حكم-الصلاة-في-المساجد-التي-فيها-بدع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_361/36106.mp3","categories":["المساجد ومواضع السجود"]},{"id":10948,"question":"ننتقل إلى سؤال آخر عبر رسالة بعث بها المستمع فتح الرحمن علي صالح مقيم بالمملكة، ومن خطه يبدو أنه سوداني وفعلًا هو سوداني يقول: عندنا مسجد في السودان، وهو المسجد الوحيد بالقرية، وداخل سوره، أو بداخله خمسة من القبور، فقد سألت بعض العلماء فمنهم من قال: لا تجوز الصلاة فيه، ومنهم من أجازها، نرجو الإفادة جزاكم الله خيرًا.","title":"حكم الصلاة في المسجد الذي فيه قبور","answer":"الجواب:  جميع المساجد التي فيها القبور لا يصلى فيها؛ لأن النبي ﷺ لعن من فعل ذلك، قال: لعن الله اليهود والنصارى اتخذوا قبور أنبيائهم مساجد، وقال -عليه الصلاة والسلام-: ألا وإن من كان قبلكم كانوا يتخذون قبور أنبيائهم وصالحيهم مساجد، ألا فلا تتخذوا القبور مساجد، فإني أنهاكم عن ذلك فنهاهم عن اتخاذ القبور مساجد، واتخاذها مساجد بالصلاة فيها، فإن من صلى في الأرض فقد اتخذها مسجدًا، يقول -عليه الصلاة والسلام-: جعلت لي الأرض مسجدًا وطهورًا، فليس للمؤمن أن يصلي في مسجد فيه قبور، ولو قبرًا واحدًا، ولا يجوز للمسلمين أن يفعلوا ذلك، بل يجب عليهم أن تكون قبورهم خارج المساجد، في مقابر مستقلة كما فعله النبي ﷺ في المدينة، ما كان يقبر في المساجد، المقبرة معروفة وحدها في البقيع. وهكذا المسلمون في كل مكان، المقابر وحدها مستقلة، لا يجوز الدفن في المساجد، ولا يجوز بناء المساجد على القبور أيضًا لا هذا ولا هذا، لا يُبنى مسجد على قبر، ولا يدفن الميت في المسجد بعد بناء المسجد، لا هذا ولا هذا.  الواجب أن تكون القبور خارج المساجد، ولا تكون في المساجد، وكل مسجد فيه قبور لا يصلى فيه، ولا تصح الصلاة فيه؛ لأن هذا فيه مشابهة اليهود والنصارى في أعمالهم القبيحة، ولهذا لعن الرسول من فعل هذا -عليه الصلاة والسلام- وهذا يدل على بطلان الصلاة، لما ذمهم النبي ﷺ وعابهم، ولعنهم على هذا الفعل دل على بطلانها، نسأل الله السلامة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9131/حكم-الصلاة-في-المسجد-الذي-فيه-قبور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_363/36315.mp3","categories":["المساجد ومواضع السجود"]},{"id":11204,"question":"هذه رسالة وصلت من السودان الطيب موسى يقول: لنا مسجد جوار المقابر بحوالي خمسين مترًا، فأحد المصلين امتنع عن الصلاة في هذا المسجد نسبة للحديث الذي يقول: لا تجعلوا مساجدكم مقابر نرجو منكم الإفادة؟","title":"حكم الصلاة في مسجد بجواره مقابر","answer":"الجواب:  إذا كان المسجد في أرض ليس فيها قبور وبينها وبين القبور فاصل من طريق أو جدار فلا بأس فالحمد لله، المقابر لا تتخذ مساجد، يقول النبي ﷺ: لعن الله اليهود والنصارى اتخذوا قبور أنبيائهم مساجد، ويقول ﷺ: لا تصلوا إلى القبور ولا تجلسوا عليها، فإذا كان خارجًا عن المقبرة وليست قبلته بل بينه وبينها جدار أو طريق فلا حرج في ذلك...","link":"https://binbaz.org.sa/fatwas/9385/حكم-الصلاة-في-مسجد-بجواره-مقابر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_291/29104.mp3","categories":["المساجد ومواضع السجود"]},{"id":11305,"question":"بعد هذا رسالة من المستمع محمد أطهر حكيم من ينبع، الأخ محمد يسأل ويقول: رجل يصلي في المسجد المجاور له مراعيًا في ذلك حق الجوار، ورجل يصلي في الجامع الكبير البعيد عن بيته تاركًا هذا المسجد المجاور له بقصد كثرة الثواب، نظرًا لكثرة الناس فيه وأنه كلما كثرت الخطا كثر الأجر، فنسأل الآن: من هو صاحب الأجر الأكثر؟ جزاكم الله خيرًا.","title":"حكم الذهاب إلى المسجد البعيد وترك القريب لكثرة المصلين","answer":"الجواب:  لا شك أن الذي يأتي إلى المسجد البعيد ويصبر على التعب يكون له الأجر أكثر، يقول النبي ﷺ: إن أعظم الناس في الصلاة أجرًا أبعدهم فأبعدهم ممشى، لكن إذا كانت الصلاة في المسجد القريب تجمع الناس ويعظهم ويذكرهم ..... فصلاته معهم أولى، أما إذا كان ما يفقد ولا يتأثر المسجد به وهو يريد أجر الخطوات فهو على خير -إن شاء الله- وهذا الحديث: إن أعظم الناس في الصلاة أجرًا أبعدهم فأبعدهم ممشى. المقدم: الله المستعان جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9486/حكم-الذهاب-الى-المسجد-البعيد-وترك-القريب-لكثرة-المصلين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_376/37618.mp3","categories":["المساجد ومواضع السجود"]},{"id":11308,"question":"يقول: يوجد في بلدنا مسجد وهذا المسجد بناه أحد سكان القرية، وأوصى عند موته بأن يدفن فيه، والآن هو مدفون في المسجد فما حكم ذلك؟ وهل تجوز لنا الصلاة في هذا المسجد؟ جزاكم الله خيرًا.","title":"حكم من بنى مسجداً وأوصى أن يدفن فيه","answer":"الجواب: هذا لا يجوز هذا جهل منه، الواجب نبشه وإبعاده إلى المقابر، الواجب أن ينبش وأن يدفن في المقابر مع الناس ويصلى في المسجد. أما مادام في المسجد فلا يصلى في المسجد حتى ينبش ويبعد وينقل إلى المقبرة العامة؛ لأنه لا يجوز الدفن في المساجد، فإذا دفن أحد في المسجد ينبش وينقل، أما إذا كان قديمًا ثم بني المسجد عليه فالمسجد هو الذي يزال يهدم ويزال، أما مادام بنى المسجد وعمره ثم دفن فيه فإنه ينقل ينبش وينقل إلى المقبرة العامة والحمد لله. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9502/حكم-من-بنى-مسجدا-واوصى-ان-يدفن-فيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_377/37713.mp3","categories":["المساجد ومواضع السجود"]},{"id":11323,"question":"يقول: يوجد في بلدنا مسجد وهذا المسجد بناه أحد سكان القرية، وأوصى عند موته بأن يدفن فيه، والآن هو مدفون في المسجد فما حكم ذلك؟ وهل تجوز لنا الصلاة في هذا المسجد؟ جزاكم الله خيرًا.","title":"حكم من بنى مسجداً وأوصى أن يدفن فيه","answer":"الجواب: هذا لا يجوز هذا جهل منه، الواجب نبشه وإبعاده إلى المقابر، الواجب أن ينبش وأن يدفن في المقابر مع الناس ويصلى في المسجد. أما مادام في المسجد فلا يصلى في المسجد حتى ينبش ويبعد وينقل إلى المقبرة العامة؛ لأنه لا يجوز الدفن في المساجد، فإذا دفن أحد في المسجد ينبش وينقل، أما إذا كان قديمًا ثم بني المسجد عليه فالمسجد هو الذي يزال يهدم ويزال، أما مادام بنى المسجد وعمره ثم دفن فيه فإنه ينقل ينبش وينقل إلى المقبرة العامة والحمد لله. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9502/حكم-من-بنى-مسجدا-واوصى-ان-يدفن-فيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_377/37713.mp3","categories":["المساجد ومواضع السجود"]},{"id":11363,"question":"هذه رسالة وصلت من مجموعة من الشباب لهم مجموعة من الأسئلة، السؤال الأول -سماحة الشيخ- يقولون فيه: ما حكم الصلاة في مسجد به قبر؟ ولماذا أصبح قبر الرسول ﷺ داخل مسجده؟ نرجو بهذا التوجيه مأجورين؟","title":"لماذا قبر الرسول عليه الصلاة والسلام داخل مسجده؟","answer":"الجواب:  الصلاة في المساجد التي فيها قبور لا تصح، ولا تجوز، ولا يجوز الدفن في المساجد، بل هذا من عمل اليهود والنصارى ، والرسول ﷺ لعنهم على هذا العمل قال: لعن الله اليهود والنصارى اتخذوا قبور أنبيائهم مساجد. فالواجب على أهل الإسلام أن يحذروا مشابهتهم وأن تكون قبورهم خارج مساجدهم في مقابر خاصة، أما المسجد فلا يجوز الدفن فيه ولا أن يصلى في المسجد الذي فيه القبور؛ لأن وجود القبر في المسجد وسيلة للشرك ووسيلة إلى أن يدعى من دون الله وأن يستغاث به، فلا يجوز للمسلمين الدفن في المساجد، بل يجب على المسلمين أن يدفنوا موتاهم خارج المساجد في مقابر خاصة، كما فعل النبي ﷺ في المدينة كان يدفنهم في البقيع، ودفن الشهداء في محل قتلهم في أحد. أما قبره ﷺ فهو في بيته ليس في المسجد، دفنه الصحابة في بيت عائشة؛ خوفًا أن يغلى فيه إذا كان في البقيع بارزًا، فدفنوه في بيته خشية أن يحصل فيه الغلو، وأن يتخذ قبره مسجدًا، فدفنوه في البيت، ثم لما وسع المسجد أدخل في المسجد -البيت نفسه: الحجرة- لما وسعه الوليد بن عبد الملك أمير المؤمنين في زمانه على رأس المائة الأولى من الهجرة، وأدخل الحجر -حجر النبي ﷺ في المسجد- دخلت حجرة عائشة من ضمنها، وكان علماء وقته قد نصحوه بألا يدخله، ولكنه رأى أن إدخاله لا يضر؛ لأنه معلوم أنه في بيته والتوسعة تدعو إلى ذلك، وقد أساء في هذا، يعفو الله عنا وعنه وعن كل مسلم. فالمقصود أنه ﷺ دفن في بيته وليس في المسجد، وإنما البيت أدخل في المسجد فهو الآن في بيته لا في المسجد، ولا يجوز أن يقتدى بذلك فيقول: ندفن في المسجد لأجل قبر النبي ﷺ في المسجد، لا. قبر النبي في بيته، في بيته ﷺ ولكن أدخلت الحجرة برمتها في المسجد من أجل التوسعة. فالواجب على المسلمين أن يحذروا الدفن في المساجد وأن يمتثلوا أمر الرسول ﷺ في النهي عن ذلك، يقول ﷺ: لعن الله اليهود والنصارى اتخذوا قبور أنبيائهم مساجد، فالمساجد لا يدفن فيها بل تكون القبور خارج المساجد، والمساجد معدة للصلاة والعبادة والقراءة فلا يكون فيها قبور. نعم.","link":"https://binbaz.org.sa/fatwas/9545/لماذا-قبر-الرسول-عليه-الصلاة-والسلام-داخل-مسجده","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_293/29305.mp3","categories":["المساجد ومواضع السجود"]},{"id":11390,"question":"بعد هذا رسالة بعث بها أحد الإخوة المستمعين يقول: العتقي إبراهيم من المغرب، أخونا له جمع من الأسئلة، في أحدها يقول: ما هو رأي سماحتكم -بارك الله فيكم- في مسجد لا تقام فيه من الصلوات إلا صلاة الجمعة؟ جزاكم الله خيرًا.","title":"حكم المسجد الذي لا تقام فيه إلا صلاة الجمعة","answer":"الجواب:  إذا كانت الحاجة ماسة لذلك؛ فلا حرج في ذلك، أما إن كان هناك مساجد تغني عنه، تقام فيها الجمعة؛ فلا حاجة إلى إقامتها فيه، أما إذا كانت بعيدة، وجيران المسجد يحتاجون إلى إقامة الجمعة فيه؛ فلا حرج في ذلك، وهذا يراجع فيه قاضي البلد، محكمة البلد، أو يكتب لنا فيه؛ حتى ننظر في الأمر؛ لأن هذا المقام مقام يحتاج إلى عناية، لماذا لا يصلى فيه إلا الجمعة، فعلى السائل أن يراجع المحكمة في البلد، أو يكتب إلينا في الموضوع؛ حتى نكتب للمحكمة في ذلك.","link":"https://binbaz.org.sa/fatwas/9558/حكم-المسجد-الذي-لا-تقام-فيه-الا-صلاة-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_379/37907.mp3","categories":["المساجد ومواضع السجود"]},{"id":11441,"question":"المستمع أيمن متولي بعث يسأل ويقول: ما رأي الشرع في الصلاة في مسجد تحيط به المقابر من كل الجهات؟","title":"حكم الصلاة في مسجد تحيط به المقابر","answer":"الجواب:  إذا كان المسجد ليس فيه قبور؛ فلا حرج، لكن إذا كان بعيدًا عنها، عن يمينها، أو شمالها، أو أمامها؛ يكون أبعد عن الشبهة، أما إذا حدثت القبور بعد ذلك؛ فلا يضر، لكن إذا تيسر أن يكون بعيدًا عنها، أمامها، أو عن يمينها، أو عن شمالها؛ حتى لا يتوهم أحد أن الصلاة لها، فهذا يكون أطيب، وأبعد عن الشبهة.  المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9623/حكم-الصلاة-في-مسجد-تحيط-به-المقابر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_294/29418.mp3","categories":["المساجد ومواضع السجود"]},{"id":11606,"question":"بعد هذا رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين يقول: قدري أحمد حافظ مصري يسأل ويقول: في قريتنا مسجد، وخلفه قبر لأحد الصالحين، وبينهما جدار، ولكن هناك باب مفتوح في المسجد من هذا الضريح، فما حكم الصلاة في ذلكم المسجد؟","title":"حكم الصلاة في مسجد بجواره قبر","answer":"الجواب: الصلاة صحيحة؛ لأن المسجد لم يبن عليه، مادام خارج المسجد الصلاة صحيحة، لكن ينبغي إبعاد هذا القبر إلى المقابر؛ حتى لا يكون فتنة للناس، ولا يغلى فيه، الواجب إبعاده، وأن ينقل إلى المقبرة العامة، وأما المسجد إذا كان ليس القبر في داخله، بل هو خارجه؛ فالصلاة صحيحة. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9782/حكم-الصلاة-في-مسجد-بجواره-قبر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_387/38708.mp3","categories":["المساجد ومواضع السجود"]},{"id":11721,"question":"يسأل أيضًا ويقول: بعض الناس يطيل آخر سجدة في آخر ركعة، ويخصها بالدعاء دون غيرها، وقد يكون إمامًا فنلاحظ نحن المأمومين أنه يطيل أكثر من غيرها، فما حكم ذلك؟ جزاكم الله خيرًا.","title":"حكم إطالة الإمام السجدة الأخيرة للدعاء","answer":"الجواب:  لا نعلم دليلًا يدل على شرعية الدعاء في السجود الأخير، بل السنة أن يكون مثل بقية السجدات، لا يطيل على الناس، بل تكون سجداته معتدلة متقاربة، وهكذا ركوعه، وهكذا قيامه، يطيل في الأولى والثانية، ويعتدل في السجود، ولا يطول على الناس تطويلًا يضر، وهكذا في الثالثة والرابعة من الظهر والعصر والعشاء يقرأ الفاتحة، ويركع ركوعًا معتدلًا ليس فيه طول كثير، ويعتدل بعد الركوع اعتدالًا ليس فيه طول يشق على الناس. وهكذا السجود كله سواء، يكون فيه طمأنينة واعتدال، وعدم عجلة، لكن لا يخص السجدة الأخيرة بمزيد طول لعدم الدليل على ذلك، إنما هو مأمور بالطمأنينة، وعدم العجلة في ....... في قيامه يخشع في القراءة ولا يعجل، وفي ركوعه يخشع ولا يعجل، واعتداله بعد الركوع يطمئن ولا يعجل، وهكذا في السجود، وهكذا بين السجدتين، وتكون صلاته متقاربة كفعل النبي، عليه الصلاة والسلام. المقدم: اللهم صل عليه، جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9904/حكم-اطالة-الامام-السجدة-الاخيرة-للدعاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_421/42102.mp3","categories":["المساجد ومواضع السجود"]},{"id":11747,"question":"مستمع يقول رفعت مصري مقيم في المملكة يسأل جمعًا من الأسئلة، في أحدها يقول: ما حكم الصلاة في مسجد فيه ضريح، مع العلم بأن هذا الضريح خلف المصلين، وليس أمامهم، وبين المصلين، وهذا الضريح حاجز من لوح من الزجاج؟","title":"حكم الصلاة في مسجد خلفه قبور","answer":"الجواب:  المساجد التي فيها القبور لا يصلى فيها، سواء كان القبر قدام المصلين، أو عن يمينهم، أو عن شمالهم، أو خلفهم، جميع المساجد التي تبنى على القبور لا يصلى فيها، لقول النبي ﷺ: لعن الله اليهود والنصارى اتخذوا قبور أنبيائهم مساجد وقال ﷺ: ألا وإن من كان قبلكم كانوا يتخذون قبور أنبيائهم وصالحيهم مساجد، ألا فلا تتخذوا القبور مساجد؛ فإني أنهاكم عن ذلك فلا يجوز الصلاة فيها بالكلية الصلاة فيها باطلة. فالواجب على المؤمن أن يحذر ذلك في أي بلد كان، كل مسجد بني على قبر لا يصلى فيه مطلقًا. أما مسجد النبي ﷺ فلم يبن على قبر، النبي ﷺ دفن في بيته، ليس في المسجد، لكن لما وسع الوليد بن عبدالملك أمير المؤمنين ذاك الوقت في آخر المائة الأولى أدخل الحجرة، التي فيها القبر أدخلها في المسجد، فهي ليست من المسجد، ولم يدفن في المسجد -عليه الصلاة والسلام- وإنما دفن في بيته، فأدخلت الحجرة في المسجد بسبب التوسعة، ثم جعل عليها ما يميزها عن المسجد، ويخرجها عن المسجد، فلا يضر المصلين في المسجد وجودها في المسجد؛ لأنه في بيته مجاور للمسجد، وليس في المسجد، فالصلاة في مسجد النبي ﷺ لا محذور فيها، ولا بأس بها. أما ما يوجد من القبور التي تدفن في المسجد عمدًا، أو يقام عليها القبر؛ فهذه هي محل النهي، ومحل التحذير، وهي التي لعن الرسول ﷺ أصحابها، نسأل الله العافية. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9929/حكم-الصلاة-في-مسجد-خلفه-قبور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_393/39310.mp3","categories":["المساجد ومواضع السجود"]},{"id":11986,"question":"من الهند المستمع محمد عالم بعث يسأل ويقول: هل يجوز سماع القرآن الكريم في أجهزة تسجيل في المسجد، أو لا؟","title":"حكم سماع القرآن عبر المسجل في المسجد","answer":"الجواب:  إذا دعت الحاجة إلى ذلك لا بأس، إذا كان ما فيه تشويش، جماعة مجتمعين، وحضروا تسجيل يسمعونه؛ لا بأس، أما إذا كان فيه تشويش على المصلين، أو القراء؛ فلا، لكن إذا كان جماعة مجتمعين، وحضروا تسجيلًا يسمعوا القرآن؛ فلا حرج في ذلك، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10171/حكم-سماع-القران-عبر-المسجل-في-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_430/43009.mp3","categories":["المساجد ومواضع السجود"]},{"id":12032,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من المستمع محمد إسماعيل محمود من جدة، أخونا محمد له جمع من الأسئلة من بينها سؤال يقول: إذا دخلت المسجد، والناس كلهم مشغولون بقراءة القرآن، فهل أسلم، أو لا؟","title":"حكم إلقاء السلام على المصلي وقارئ القرآن في المسجد","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد: فالمشروع لمن دخل المسجد والناس يصلون، أو يقرؤون أن يسلم، فالمصلي يرد بالإشارة والقراء يردون بالكلام، قد كان النبي ﷺ جالسًا في أصحابه، فرأى رجلًا قد أساء صلاته، فلما سلم جاء الرجل، وسلم عليهم، ورد عليه النبي ﷺ السلام وقال له: ارجع فصل؛ فإنك لم تصل وكانوا يسلمون على النبي ﷺ وهو في الصلاة؛ فيرد عليهم بالإشارة -عليه الصلاة والسلام- نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10217/حكم-القاء-السلام-على-المصلي-وقارى-القران-في-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_433/43301.mp3","categories":["المساجد ومواضع السجود"]},{"id":12058,"question":"أحد الإخوة المستمعين يقول المرسل محسن عفيف من اليمن، يسأل ويقول: هل يجوز لمن يوصي أن يوضع قبره في أحد المساجد، هل يجوز أن تنفذ وصيته؛ لأنا نلاحظ أن كثيرًا من المساجد تحتوي على بعض القبور، فما هو توجيهكم؟ هل نخرج عظام الموتى من القبور حتى تخلو من المقابر؟ وجهونا حول هذين الأمرين، جزاكم الله خيرًا.","title":"حكم من أوصى بأن يدفن في المسجد","answer":"الجواب:  من أوصى بأن يدفن في المساجد؛ وصيته باطلة، لا تنفذ، لا يجوز تنفيذها، بل يجب أن يدفن مع المسلمين في المقابر، ولا يجوز أبدًا أن يدفن في المسجد، هذا منكر، ومن عمل اليهود والنصارى، ومن أسباب الشرك. وهكذا إذا وجد قبرًا في المسجد، والمسجد سابق، والقبر هو الجديد الحادث؛ يجب أن ينبش، وتنقل عظامه ورفاته إلى المقابر في حفرة خاصة، يوضع فيها ويسوى ظاهره كسائر القبور، ولا يجوز بقاء القبور في المساجد أبدًا. أما إن كان المسجد هو الحادث، والمقبرة سابقة، وأحدث المسجد على القبور، بني على القبور؛ فإن هذا المسجد يهدم، ويزال؛ لأنه هو الحادث، قد قال -عليه الصلاة والسلام- في الحديث الصحيح: لعن الله اليهود والنصارى؛ اتخذوا قبور أنبيائهم مساجد وقال -عليه الصلاة والسلام-: ألا وإن من كان قبلكم كانوا يتخذون قبور أنبيائهم وصالحيهم مساجد، ألا فلا تتخذواا القبور مساجد، فإني أنهاكم عن ذلك فاتخاذ القبور في المساجد من عمل اليهود والنصارى، ومن أسباب الشرك، فيجب الحذر من ذلك، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم، إذًا تنبش القبور سماحة الشيخ الموجودة داخل المساجد وحينئذ تخلوا المساجد من القبور؟ الشيخ: نعم. إذا كانت القبور هي الحادثة، وجب أن تنبش، وتبعد، وتنقل عظامها إلى المقابر، كل رفات قبر كل رفات ميت توضع في حفرة وحدها، ويسوى ظاهرها كسائر القبور، أما إذا كان المسجد هو الجديد، والمقبرة السابقة، هو الذي بني على القبر تعظيمًا للقبر، فهذا المسجد يهدم، لا يبقى في المقبرة، يزال؛ لأنه هو الحادث، نعم. المقدم: إذًا من كان جديدًا؛ فهو الذي يزال، سواءً كان القبر، أو المسجد؟ الشيخ: نعم نعم. المقدم: بارك الله فيكم. الشيخ: نعم.","link":"https://binbaz.org.sa/fatwas/10243/حكم-من-اوصى-بان-يدفن-في-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_434/43407.mp3","categories":["المساجد ومواضع السجود"]},{"id":12289,"question":"رسالة وصلت إلى هذا البرنامج بعث بها أحد الإخوة المستمعين رمز إلى اسمه بقوله: رجب من جدة، الأخ رجب ضمن رسالته عددًا من الأسئلة: من بينها يرجو التوجيه لأولئك الذين يقرؤون القرآن بصوت مرتفع، وبعض الناس قد يؤدي بعض السنن، أو بعض الفرائض في المسجد، يرجو من سماحتكم التوجيه جزاكم الله خيرًا.","title":"رفع الصوت بالقرآن في المسجد","answer":"الجواب:  نعم ننصح القراء في المساجد ألا يرفعوا أصواتهم رفعًا قد يشغل المصلين والقراء الذين حولهم، بل يقرأ قراءة سرية، لا تؤذي من حوله من المصلين، أو القراء، هذا هو السنة، وقد خرج النبي ﷺ ذات ليلة إلى المسجد والناس يصلون أوزاعًا، ويرفعون أصواتهم، فقال -عليه الصلاة والسلام-: كلكم يناجي ربه؛ فلا يجهر بعضكم على بعض أو كما قال، عليه الصلاة والسلام.  فينبغي للمؤمن أن يتحرى عدم إيذاء أخيه المصلي أو القاري، فيقرأ قراءة يخفض فيها الصوت خفضًا لا يبقى معه تشويش على مصلٍ، ولا قارئ، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10489/رفع-الصوت-بالقران-في-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_452/45209.mp3","categories":["المساجد ومواضع السجود"]},{"id":12297,"question":"تقول في سؤال آخر: جميع مساجد قريتنا فيها قبور، كما أنها تسمى بأسماء هؤلاء الموتى، ولا يفصل بين المكان الذي تقام فيه الصلاة والقبور سوى جدار واحد فقط، فهل تجوز الصلاة في هذه المساجد، علمًا بأن أئمتها يؤمنون بأن أصحاب القبور هم أولياء صالحون، ويشركونهم في دعائهم؟","title":"واجب المسلمين تجاه المساجد التي يوجد فيها قبور","answer":"الجواب: المساجد التي فيها القبور لا يصلى فيها، إذا كان القبر داخل المسجد، داخل سور المسجد؛ فلا يصلى فيه؛ لقول النبي ﷺ: لعن الله اليهود والنصارى اتخذوا قبور أنبيائهم مساجد متفق على صحته، ولقوله ﷺ: ألا وإن من كان قبلكم كانوا يتخذون قبور أنبيائهم وصالحيهم مساجد، ألا فلا تتخذوا القبور مساجد؛ فإني أنهاكم عن ذلك فقد نهى ﷺ عن اتخاذ القبور مساجد، والصلاة عندها اتخاذ لها مساجد، والبناء على القبور اتخاذ لها مساجد، إذا بني عليها للصلاة، فلا يجوز الصلاة عندها، ولا يجوز أيضًا اتخاذها مساجد بالبناء، ولهذا قال -عليه الصلاة والسلام-: لعن الله اليهود والنصارى اتخذوا قبور أنبيائهم مساجد. أما إذا كان القبر خارج المسجد عن يمين المسجد، أو شماله، أو أمامه مفصولًا بالجدران؛ فلا حرج، وأما في داخل المسجد فلا يجوز، وإذا كان القبر جعل في المسجد؛ فالواجب نبشه، إذا كان القبر هو الأخير، والمسجد سابقًا؛ فإن القبر ينبش وينقل الرفات إلى المقبرة العامة، ويصلى في المسجد. أما إن كان القبر هو القديم، والمسجد بني عليه تعظيمًا له، فالمسجد هو الذي يهدم، ولا يصلى فيه، وتبقى القبور على حالها بدون مساجد، ولا يصلى فيها ولا عندها؛ لأن الرسول لعن من فعل هذا -عليه الصلاة والسلام- وحذر من ذلك، عليه الصلاة والسلام. والحكمة في ذلك أن الصلاة عندها، واتخاذها مساجد من وسائل الشرك بأهلها، ودعائهم من دون الله، واتخاذهم آلهة مع الله، فلهذا منع النبي ﷺ من ذلك سدًا لذريعة الشرك، وحسمًا لوسائله، ولا يجوز أن يصلى خلف الأئمة الذين يدعون أصحاب القبور، ويستغيثون بهم ويعظمونهم، هؤلاء مشركون إذا كانوا يدعون أصحاب القبور، ويستغيثون بهم، وينذرون لهم، هؤلاء يكونوم مشركين لا يصلى خلفهم، وإنما يصلى خلف الأئمة المستقيمين على دين الله المعروفين بالتوحيد والإيمان، لا بالشرك، نسأل الله للجميع الهداية، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10497/واجب-المسلمين-تجاه-المساجد-التي-يوجد-فيها-قبور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_453/45303.mp3","categories":["المساجد ومواضع السجود"]},{"id":12364,"question":"بعد هذا رسالة بعث بها مستمع يقول: (أبو لافي . ع. ع)، له جمع من الأسئلة في أحدها يقول: ما حكم الصلاة على السجادة المعتاد الصلاة عليها، والمرسوم عليها بعض المساجد، إذ أني سمعت أن الصلاة عليها لا تجوز، وجهونا جزاكم الله خيرًا.","title":"حكم الصلاة على سجادة عليها رسم مسجد","answer":"الجواب:  الصلاة على السجادة صحيحة، ولو كان عليها رسم المسجد، أو أي رسم، الصلاة صحيحة، لكن يشرع للمصلي أن تكون سجادته بعيدة عن النقوش، ليس فيها رسوم، لا مسجد ولا غيره، حتى لا تشوش عليه صلاته، تكون سجادة سادة، سادة ليس فيها شيء، هذا هو الذي ينبغي، هذا هو الأحوط للمؤمن، ولهذا لما صلى النبي ﷺ في خميصة لها أعلام بعدما سلم بعث بها إلى أبي جهم، وقال: إن أعلامها شغلتني عن صلاتي.  فالمقصود: أن المؤمن يتحرى في صلاته الملابس السليمة من شغله، والسجادة السليمة، تكون بعيدة عن الإلهاء والإشغال، ليس فيها نقوش ما يشغله، نعم.","link":"https://binbaz.org.sa/fatwas/10568/حكم-الصلاة-على-سجادة-عليها-رسم-مسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_400/40006.mp3","categories":["المساجد ومواضع السجود"]},{"id":12728,"question":"هل الصلاة تجوز على بسط، أو سجاد مرسوم عليها صور حيوانات، أو إنسان، أو نبات، أو غير ذلك؟","title":"حكم الصلاة على بساط فيه تصاوير","answer":"الجواب:  نعم تصح الصلاة؛ لأنها ممتهنة، لكن تركها أولى، كونه يلتمس سجادة، أو بساطًا ما فيه صور، ولا نقوش؛ يكون أفضل، حتى لا تشوش؛ لأن النقوش والصور قد تشوش عليه صلاته وفكره، قد يشتغل بها بعض الشيء، فإذا كان هناك فراش، ليس فيه نقوش، ولا صور؛ يكون أفضل. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10941/حكم-الصلاة-على-بساط-فيه-تصاوير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_460/46016.mp3","categories":["المساجد ومواضع السجود","الصور والتصوير"]},{"id":12760,"question":"هل يجوز لي أن أترك إلقاء الدروس في المسجد، وذلك لعدم حضور أحد إلي، مع تكرار ذلك لعدة مرات، والسؤال لا زال للمستمع (م. ص. ع) من الأردن -؟","title":"دعوة المرأة لبنات جنسها وتعليمهن","answer":"الجواب:  إذا تيسر لك إلقاء الدرس على الجماعة بعد العصر، أو بعد المغرب، أو بعد العشاء.  المقدم: هذه سائلة جزاكم الله خيرًا.  الشيخ: امرأة؟ المقدم: امرأة نعم. الشيخ: تعلمين من حضرك من النساء في بيتك، ومن يزورك في البيت، وإذا كنت في المدرسة كذلك إن كنت مدرسة تعلمين الطالبات، وتبحثين مع المدرسات إذا كن دونك في العلم، أو مذاكرة معهن إذا كن مثلك، أو أعلم منك حتى تستفيدي ويستفيدوا. المقصود: أنك تبذلين ما تستطيعين في توجيه الناس إلى الخير، الطالبات، ومن يجالسك في البيت، ومن يزورك، ومع المدرسات بالمذاكرة، تستفيدين منهن إن كن أعلم منك، وتفيدينهن إن كنت أعلم منهن. المقصود: التعاون على البر والتقوى بالمذاكرة بينك وبين المدرسات، وبتوجيه الطالبات وتعليمهن، وهكذا في البيت مع من يزورك من أخواتك في الله، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم، حول تدريس النساء في المساجد سماحة الشيخ لبعض إخوانكم طلبة العلم رأي آخر، إذ لا يرى ذلك، ما هو توجيه سماحة الشيخ؟! الشيخ: هذا فيه تفصيل: إذا أمكن أن تدرس النساء في المسجد على رجل لا فتنة فيه، مع التحجب، أو مع كونهن في محل خاص لا يأتيه الرجال، فهذا لا بأس به، ولا حرج فيه، المهم إيصال العلم إلى الرجال والنساء، فإذا كان في المسجد محل خاص، أو في مدرسة، أو في البيت، المهم أن تعمل ما تستطيع في إيصال العلم إلى أخواتها في الله، أو إلى الطالبات في المسجد، أو في المدرسة، أو في بيتها، أو في بيت إحدى أخواتها، والحمد لله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10974/دعوة-المراة-لبنات-جنسها-وتعليمهن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_419/41909.mp3","categories":["العالم والمتعلم","المساجد ومواضع السجود"]},{"id":12786,"question":"يقول: نصلي مع جماعة قبوريين يعتقدون في الأموات بأن لهم صلاحية الضر والنفع والبركة، والمكان الذي نصلي فيه توجد به قباب مدفون فيها عدد كثير من الناس، من هؤلاء الذين يسمونهم بالصالحين والأولياء، ومكان المصلى لا يبعد شيء عن المكان الذي نصلي فيه، فهل الصلاة في هذا المكان جائزة، وهل هذا المكان من حرم المقابر لوجود هذه القبور داخل القباب بالقرب منه، أو لصيقة بالمكان، والمسجد أيضًا في نفس المكان، هل يعتبر من حرم المقابر، وهل الصلاة فيه جائزة، ولا يوجد مسجد آخر في القرية إلا هذا المسجد، أفيدونا أفادكم الله؟","title":"حكم الصلاة بجوار القبور","answer":"الجواب:  هذا المكان لا يصلى فيه، نعوذ بالله، المقابر الصلاة فيها باطلة، النبي ﷺ قال: لا تصلوا إلى القبور، ولا تجلسوا عليها قال -عليه الصلاة والسلام-: ألا وإن من كان قبلكم كانوا يتخذون قبور أنبيائهم وصالحيهم مساجد، ألا فلا تتخذوا القبور مساجد، فإني أنهاكم عن ذلك خرجه مسلم في صحيحه، وقال -عليه الصلاة والسلام-: لعن الله اليهود والنصارى؛ اتخذوا قبور أنبيائهم مساجد متفق على صحته. فلا يجوز الصلاة في هذا المكان الذي فيه القبور، ولا بناء المسجد فيها ولا بينها، بل يجب أن تكون المساجد في محلات بعيدة عن القبور، لا تكون في ضمن مقبرة، بل بعيدة عن القبر أمامها وخلفها، وعن يمينها وعن شمالها، وأن تفصل عنها المقبرة. فلا يجوز الصلاة في المقبرة، ولا البناء فيها، بناء المسجد فيها، كل هذا منكر وباطل -نسأل الله العافية- ومن وسائل الشرك -نسأل الله العافية- والدعاء للأموات، والاستغاثة بالأموات من الشرك الأكبر، دعاء الأموات، والاستغاثة بهم، والنذر لهم هذا من الشرك الأكبر عند جميع أهل العلم. فيجب على المسلم أن يحذر هذا، يجب على من يأتي القبور لهذا الأمر أن يتوب إلى الله؛ لأن هذا هو الشرك الأكبر، هذا عمل الجاهلية، دعاء الأموات والاستغاثة بالأموات والنذر لهم، والذبح لهم، هذا هو من دين المشركين الذين قال فيهم سبحانه: وَلَوْ أَشْرَكُوا لَحَبِطَ عَنْهُمْ مَا كَانُوا يَعْمَلُونَ [الأنعام:88] وقال فيهم سبحانه: وَقَدِمْنَا إِلَى مَا عَمِلُوا مِنْ عَمَلٍ فَجَعَلْنَاهُ هَبَاءً مَنْثُورًا [الفرقان:23] لشركهم وكفرهم، نسأل الله العافية. فالواجب على جميع المسلمين في كل مكان أن تكون مساجدهم بعيدة عن القبور، وألا يصلوا في القبور، ولا يجلسوا عليها، ولا يبنوا عليها، بل تكون مكشوفة، ليس عليها بناء، ولا يصلى حولها، ولا يبنى عليها مسجد، كل هذا منكر أنكره النبي ﷺ وحذر منه، نعم. المقدم: جزاكم الله خيرًا، إذًا: تنصحون من عندهم مسجد كهذا المسجد، تنصحونهم بهجره، أو هدمه سماحة الشيخ؟! الشيخ: نعم، يجب هدمه وإزالته، وأن تقام المساجد في محلات بعيدة عن القبور، ليس لها صلة بالقبور. نعم. المقدم: جزاكم الله خيرًا، قد يتكلف الناس في بناء المساجد؛ وحينئذ يكون هذا عائقًا، فبماذا تنصحون الناس حول هذا الموضوع جزاكم الله خيرًا؟ الشيخ: يصلون في محل بعيد عن المقابر، ولو ما بني، أرضي، يتخيرون أرضًا يصلون فيها، ولو في خيام؛ حتى يعينهم الله على البناء. المقصود: أن يصلوا في أرض طاهرة طيبة، ليس فيها مقبرة حتى يعينهم الله على البناء، وإذا جعلوا فوقها خيمة، أو شيئًا من الجريد، وسعف النخل حتى يقدرهم الله على البناء، كله طيب. المقدم: وهذا أفضل من مسجد فيه قبور؟ الشيخ: ما هو بأفضل، هذا هو الواجب، هذا هو الواجب، المسجد الذي فيه قبور هذا باطل ومنكر لا يجوز. المقدم: بارك الله فيكم، وجزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11000/حكم-الصلاة-بجوار-القبور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_420/42013.mp3","categories":["المساجد ومواضع السجود"]},{"id":12807,"question":"يسأل أيضًا ويقول: كان رجل يعمل عندنا، وبقي مدة من الزمن، وفي أحد الأيام من عمله كان يعمل تحت جدار من التراب، فانقض عليه، ووافاه أجله، ومات، وأراد صاحب العمل أن يعطينا قدرًا من المال، أي دية المرحوم، هل لنا أن نأخذها ونبني بها مسجدًا، أم كيف توجهوننا، جزاكم الله خيرًا؟","title":"حكم بناء المسجد بالدية","answer":"الجواب:  إذا كان صاحب العمل لم يفرط في شيء؛ فليس عليه دية، وهذا أجله المحتوم، أما إن كان فرط في ذلك، بأن كان الجدار على وشك السقوط، ولم يبين له أنه على وشك السقوط، هذا محل نظر، يرجع فيه للحاكم، إلى المحكمة.  أما إذا تبرع بالدية، ولم يطلبوه دية، وليس بينهم خصومة، ولكن تبرع لهم بالمال؛ فلا حرج في أخذ المال، يتصرفون فيه إذا تبرع صاحب العمل بالمال، ولم يخاصموه، بل هو بنفسه تبرع؛ فهو محسن في هذا، وجزاه الله خيرًا، ولا حرج في أن تبنوا به مسجدًا إذا كنتم مرشدين، لا بأس هذا للورثة، إن شاؤوا بنوا به مسجدًا، وإن شاؤوا أكلوه، وإن شاؤوا تصدقوا به، هذا ما لهم يتصرفون فيه، كيف شاؤوا إذا كانوا مرشدين، هذا إلى الورثة، أما إذا كانوا قاصرين؛ فهو لهم، لا يتصرف أحد فيه، بل يبقى لهم، والمرشد منهم لا بأس أن يتصرف في حقه. نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11021/حكم-بناء-المسجد-بالدية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_462/46212.mp3","categories":["المساجد ومواضع السجود"]},{"id":12822,"question":"رسالة وصلت من المستمع يقول: أنا مواطن مسلم أقطن بقرية نائية في الجمهورية التونسية، توجد بها مقبرة مهجورة استعملها أجدادنا سابقًا، وهي الآن غير مستعملة لوجود مقبرة أخرى بنفس القرية، وقد اجتمع أهل البر والإحسان، وتبرعوا بمشروع بناء مسجد، لكنهم لم يجدوا له مكانًا إلا تلك المقبرة، لكن هناك من اعترض وقال: لا يجوز بناء المسجد في المقبرة، أرجو أن توجهونا حينئذٍ، كيف نتصرف، جزاكم الله خيرًا؟ وهل لنا أن نبني المسجد مكان تلك المقبرة القديمة؟","title":"حكم بناء مسجد فوق مقبرة قديمة","answer":"الجواب:  ليس لكم ذلك، المقبرة تبقى على حالها محترمة، لا يدفن فيها أحد، ولا تمتهن بالوطء والمشي عليها، ولا بإلقاء القمامة عليها، وإذا تيسر تسويرها بشبك، أو بناء يحميها عن الامتهان؛ كان هذا أولى. وأما المسجد فلا يبنى فيها، يبنى في غيرها، ولو بالشراء، ولو بشراء أرض، يشتريها أهل الحي، ويبنوا عليها المسجد، أما البناء في المقبرة فلا يجوز، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11036/حكم-بناء-مسجد-فوق-مقبرة-قديمة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_463/46310.mp3","categories":["المساجد ومواضع السجود"]},{"id":12823,"question":"أيضًا يسأل عن تلاوة القرآن مسجلة قبل أوقات الصلاة بربع ساعة مثلًا، هل تجوز في مكبر الصوت في المسجد؟","title":"حكم تشغيل القرآن عبر مكبر الصوت في المساجد","answer":"الجواب:  لا في المسجد لا يفعل، كل يقرأ على حسب حاله في المسجد، ولكن إذا فعلوه في بيوتهم، أو في السفر، أو ما أشبه ذلك؛ فلا بأس، أو اجتمعوا في المسجد بعض الأحيان، وسمعوا القرآن مسجلًا؛ لا بأس، أما أن يشغلوا الناس وقت انتظارهم للصلاة لا، يدعون الناس في .... الذي يقرأ والذي يصلي الحمد لله، كونه يشغل المكبر بقراءة القرآن، تركه أولى، لا أعلم لهذا أصلًا، وفيه أيضًا مشغلة للناس، هذا قد يحب أن يقرأ، وهذا يصلي تحية المسجد أو يصلي الراتبة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11037/حكم-تشغيل-القران-عبر-مكبر-الصوت-في-المساجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_463/46311.mp3","categories":["المساجد ومواضع السجود"]},{"id":12914,"question":"من العراق -بغداد- المستمع محمد حسين علي محمد بعث يسأل ويقول: هل يجوز أن يذهب الفرد من بلد إلى بلد ليصلي صلاة الجمعة في مسجد يقال له: مسجد الشيخ فلان؟","title":"حكم شد الرحل إلى مسجد غير المساجد الثلاثة","answer":"الجواب:  إذا كان السفر من أجل أنه يقال: مسجد فلان لا، لا يشد الرحل من أجل المسجد الفلاني، ولا من أجل أنه ينسب إلى الشيخ فلان، العمدة على إمامه الحاضر إذا كان إمامه طيبًا، والصلاة خلفه جيدة؛ لأجل خشوعه، وحسن تلاوته، هذا إذا قصده الإنسان يصلي خلفه من أجل حسن تلاوته، ومن أجل إقامته للصلاة، وخشوعه فيها هذا حسن. أما شد الرحل لأجل فضل المسجد أنه منسوب إلى فلان، هذا لا يجوز؛ لأن الرسول  قال: لا تشد الرحال إلا إلى ثلاثة مساجد: المسجد الحرام، ومسجدي هذا، والمسجد الأقصى هكذا قال -عليه الصلاة والسلام- لا تشد الرحال إلا إلى ثلاثة مساجد: المسجد الحرام يعني: مكة مسجد مكة ومسجدي هذا مسجد المدينة والمسجد الأقصى مسجد القدس. أما المساجد الأخرى فلا يشد الرحل لها، ولو كان صاحبها معروفًا بالخير، وتنسب إلى شيخ معروف بالخير، أما إذا شد الرحل للتعلم، أو للصلاة خلفه، لا من أجل المسجد، بل للصلاة خلفه، والإقامة عنده هناك؛ ليتعلم عليه، وليستفيد منه؛ لا بأس، هذا من أجل طلب العلم، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11129/حكم-شد-الرحل-الى-مسجد-غير-المساجد-الثلاثة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_468/46816.mp3","categories":["المساجد ومواضع السجود"]},{"id":12915,"question":"من الجمهورية اليمنية المستمع: عبود أحمد بو عسكر، من محافظة حضرموت، مديرة القطن، بعث يسأل ويقول: لقد انتقلت من القرية لغرض العمل في مكان صحراوي لمدة أشهر، وكان قرب هذا المكان يوجد قرية، وبها مسجد، وفيه قبر، وفي بداية الأمر كنت أذهب لصلاة الجمعة إلى هذه القرية؛ لأنها الوحيدة القريبة منا، ولكن عندما اتضح بأن المسجد به قبر؛ تركت الصلاة، وطول مدة عملي في هذا المكان، وأنا لا أصلي الجمعة، علمًا بأن جميع الفروض أصليها كاملة، فهل علي ذنب لتركي الصلاة طول هذه المدة -وأعني: صلاة الجمعة- جزاكم الله خيرًا؟","title":"مكان ليس فيه إلا مسجد فيه قبر فهل يترك الجمعة؟","answer":"الجواب:  ليس عليك بأس؛ لأن المساجد التي فيها القبور لا يصلى فيها، وعليك أن تعيد ما صليت في المسجد هذا الذي فيه القبر، عليك أن تعيد صلواتك، تعيدها ظهرًا، وتصلي في محلك، وإذا تيسر بقربك جيران يصلون معك؛ صلوا جماعة، وجب عليكم أن تصلوا جماعة، فحرصًا تجتمع مع جيرانك، وأن تصلوا جماعة في بيت أحدكم، أو في مسجد تقيمونه سليمًا من القبور، وعليكم أن تنصحوا أصحاب المسجد، تجتمع أنت وإخوانك الطيبون بالمسؤولين عن المسجد حتى يزال القبر من المسجد، حتى ينقل إلى القبور، ينبش، وينقل إلى القبور، وحتى يبقى المسجد سليمًا من القبور، الرسول  قال: لعن الله اليهود والنصارى اتخذوا قبور أنبيائهم مساجد وقال -عليه الصلاة والسلام-: ألا وإن من كان قبلكم كانوا يتخذون قبور أنبيائهم وصالحيهم مساجد، ألا فلا تتخذوا القبور مساجد، فإني أنهاكم عن ذلك فنهاهم عن اتخاذها مساجد.  ورأى عمر أنسًا أراد أن يصلي حول قبر، فقال له عمر  القبر القبر! نبهه على أن هناك قبر؛ حتى لا يصلى حوله. فالمقصود: أن الصلاة في المساجد التي فيها القبور، أو الصلاة بين القبور، أو في المقبرة كلها باطلة. فالواجب على المسلمين أن يحذروا ذلك، وأن تكون مساجدهم سليمة من القبور، والواجب على العلماء أن ينبهوا الناس، الواجب على العلماء في كل مكان، وفي كل دولة أن ينبهوا الناس على ذلك، حتى تسلم القبور، حتى تسلم المساجد من وجود القبور، وكل مسجد فيه قبر؛ يجب نبش القبر، وإبعاده عن المسجد، إلا إذا كان المسجد بني عليه، والقبور سابقة، والمسجد بني على القبور؛ فإنه يهدم، وتبقى القبور على حالها. أما إذا كان المسجد هو القديم، ثم دفن فيه عالم أو غيره؛ فإنه يجب نبشه، ونقل رفاته إلى المقبرة العامة في حفرة خاصة يسوى ظاهرها كسائر القبور، حتى يبقى المسجد سليمًا، وحتى يصلي المسلمون فيه. هذا هو الواجب على الأمراء والعلماء أن يعنوا بهذا الأمر، وألا يتساهلوا فيه؛ لأن هذا من الشعائر الظاهرة، التي يجب العناية بها، الله يهدي الجميع، نسأل الله للجميع الهداية. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11130/مكان-ليس-فيه-الا-مسجد-فيه-قبر-فهل-يترك-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_468/46817.mp3","categories":["المساجد ومواضع السجود"]},{"id":12963,"question":"سماحة الشيخ، هذا السائل من مدينة بريدة ( ج . ر ) يقول في آخر أسئلته: مسجد يصلى فيه جميع الأوقات، ولا يؤذن فيه، هل تجوز الصلاة فيه، أم لا؟","title":"حكم الصلاة في المسجد الذي لا يؤذن فيه للصلاة","answer":"الجواب:  نعم، تجوز الصلاة فيه، والواجب أن يؤذن، يؤذن أحدهم، يعلموا، يجب أن يعلموا حتى يؤذن أحدهم، والصلاة فيه جائزة إذا كان ما هناك مسجد آخر، يغني عنه إذا كانوا محتاجين للصلاة فيه، أما إن كان عندهم مسجد آخر؛ كفاهم، لكن إذا كان في حاجة لهذا المسجد؛ يصلى في هذا، ويؤذن فيه أحدهم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11180/حكم-الصلاة-في-المسجد-الذي-لا-يوذن-فيه-للصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_502/50219.mp3","categories":["المساجد ومواضع السجود"]},{"id":13105,"question":"إذا كان المسجد ملحقًا به قبر، والقبر خارج المسجد، وليس بداخله، فهل تجوز الصلاة فيه، وهل إذا دعتني الحاجة للصلاة فيه، فهل أصلي، أم لا؟","title":"حكم الصلاة في المسجد الذي حوله قبر","answer":"الجواب:  إذا كان القبر خارج المسجد؛ فلا مانع يصلى فيه، وينبغي نقل القبر إلى المقبرة العامة؛ إبعادًا للشبهة، ولئلا يغلى فيه، لاسيما إذا كان منسوبًا للصلاح، فينبغي للمسؤولين أن ينقلوا رفاته إلى المقبرة العامة، وإذا كان يخشى من الفتنة يخفى، يدفن في الليل، ويخفى، ولا يعرفه أحد إلا الخواص الذين دفنوه، كما فعل عمر في قبر دانيال، لما خاف الفتنة؛ حفر له ثلاثة عشر قبرًا بالليل، ودفنه في واحد منها، وسواها كلها؛ حتى يخفى أمره في العراق. فالمقصود: أن القبر الذي حول المسجد ينبغي نقله إلى المقبرة العامة؛ حتى لا يفتن به الناس إذا تيسر ذلك، وهذا يتعلق بالمسؤولين من العلماء والأمراء، فإذا تيسر نقله من دون فتنة؛ نقل، وإلا بقي، ولكن لا يجوز أن يدعى من دون الله، ولا أن يطاف به، ولا أن يستغاث به، ولا أن يتمسح به، ولا يمنع من الصلاة في المسجد إذا كان خارج المسجد، لا يمنع من الصلاة في المسجد، أما إذا كان في داخل المسجد؛ فإنه ينبش، إذا كان بعد المسجد؛ ينبش، ويبعد عن المسجد إلى المقبرة العامة. أما إذا كان قديمًا، والمسجد بني عليه؛ فالمسجد هو الذي يهدم؛ لأنه أسس على غير هدى، إذا بني على القبر، صار هو الجديد؛ فإنه يهدم؛ لأنه أسس على غير تقوى، نعم. المقدم: جزاكم الله خيرًا، سؤال في نفس الموضوع تقريبًا يقول: هل هناك فرق بين صلاة النافلة، وصلاة الفرض إذا صليت في المسجد الذي فيه قبر؟ الشيخ: لا فرق في ذلك، لا يجوز، ولا تصح، سواء كانت نافلة، أو فريضة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11322/حكم-الصلاة-في-المسجد-الذي-حوله-قبر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_473/47308.mp3","categories":["المساجد ومواضع السجود"]},{"id":13176,"question":"يقول: في بلدي تعودنا في القرية في يوم الجمعة، وقبل الصلاة أن يشغلوا الإذاعة، أي: إذاعة القرآن الكريم من مكبرات الصوت، ويبدأ القاري في قراءة القرآن حتى أذان الجمعة، فما حكم الإسلام في هذا العمل، جزاكم الله خيرًا؟","title":"حكم فتح القرآن في المسجد بمكبرات الصوت في يوم الجمعة","answer":"الجواب:  أما إذاعة القرآن من الإذاعة العامة للناس هذا فيه خير كثير.\nأما إذاعة القرآن بين المصلين في المسجد فهذا لا أصل له؛ لأنه يشوش على القراء، ويشوش على المصلين، فالواجب ترك ذلك حتى يقرأ من شاء، ويصلي من شاء، لا يشوش على الناس، كونه تشغل الإذاعة في المسجد حتى يقرأ القاري، والناس الذين يصلون، والناس يقرؤون، هذا لا أصل له، فالواجب تركه حتى يقرأ من يقرأ لنفسه، وحتى يسبح من يسبح، وحتى يصلي من يصلي، ولا يشوش عليه، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11431/حكم-فتح-القران-في-المسجد-بمكبرات-الصوت-في-يوم-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_511/51112.mp3","categories":["صلاة الجمعة","المساجد ومواضع السجود"]},{"id":13199,"question":"هذا سائل من الجبيل يقول في هذا  علمت بأن الرسول ﷺ قد نهى من أكل منا ثومًا، أو بصلًا أن يقرب المصلين، أو المصلى في جماعة المسجد -وذلك حسب علمي- حتى لا يؤذي الملائكة والمصلين، فما رأي سماحتكم فيمن امتلأت رئتاه برائحة الدخان، حتى ولو أنه لم يشربه قبيل قدومه للصلاة في المسجد، والمعروف أن رائحة الدخان كريهة، وأنا أقول بأنها تزعجني في صلاتي بجانب صاحب هذه الرائحة، والنهي جاء في الحلال الثوم والبصل، فما الحكم في الدخان، هل هو محرم وهل ينطبق الحديث على شاربه؟","title":"حكم الدخان وإيذاء المصلين برائحته","answer":"الجواب:  نعم، الدخان محرم، ولا شك أنه محرم لما فيه من المضرة العظيمة؛ فينبغي للمؤمن أن يحذر ذلك، ولاسيما إذا كان مجيئه للمسجد قرب شرب الدخان؛ فإن هذا يؤذي الناس، وقد يكون أذاه أشد من الثوم والبصل لمن لم يعتده.  فالواجب على المؤمن أن يحذره؛ لأنه محرم، وفيه مضار كثيرة، وفيه -أيضًا- إيذاء للناس إذا شربه عند مجيئه للمسجد، ولم يتحفظ؛ فإنه يؤذي من حوله، والله المستعان، نعم. المقدم: الله المستعان.","link":"https://binbaz.org.sa/fatwas/11468/حكم-الدخان-وايذاء-المصلين-براىحته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_512/51206.mp3","categories":["المساجد ومواضع السجود","الأطعمة والأشربة"]},{"id":13370,"question":"السائل علي من الكويت علي مطلق له الحقيقة مجموعة من الأسئلة يقول في هذا  سماحة الشيخ! ورد عن النبي ﷺ عدة أحاديث تفيد بتقديم الطعام على الصلاة، منها على سبيل الذكر لا الحصر: ما رواه الشيخان عن أنس  أن رسول الله ﷺ قال: إذا قدم العشاء؛ فابدؤوا به قبل أن تصلوا المغرب وكذلك ما رواه مسلم عن عائشة -رضي الله عنها- قول النبي ﷺ: لا صلاة بحضرة طعام، ولا هو يدافعه الأخبثان وكذلك ورد عن النبي ﷺ في الحديث المتفق عليه، عن أبي قتادة  قال: قال رسول الله ﷺ: إذا دخل أحدكم المسجد؛ فلا يجلس، حتى يصلي ركعتين.والسؤال يا سماحة الشيخ: في حالة كوني صائمًا، ودخلت المسجد حين الأذان، هل أصلي تحية المسجد، أم أذهب لتناول الفطور، علمًا بأن فطوري داخل المسجد؟ أفتونا في ذلك مأجورين.","title":"الصائم إذا دخل المسجد هل يبدأ بالفطر أم يصلي التحية؟","answer":"الجواب: أما ما يتعلق بمدافعة الحدث، وما يتعلق بالبداءة بالطعام، هذا هو السنة؛ لأنه يتفرغ للصلاة حتى يصليها بخشوع، فلا صلاة بحضرة الطعام، والحديث الآخر: إذا حضر الطعام، وحضر العشاء؛ فابدؤوا بالعشاء والحديث الآخر: إذا حضر العشاء، وحضرت المغرب؛ فابدؤوا به قبل أن تصلوا المغرب يبدأ بالعشاء؛ حتى يستريح؛ حتى يطمئن قلبه .. حتى يؤدي الصلاة بخشوع وطمأنينة، لا يصلي وقلبه مشغول بالطعام، أو بمدافعة الأحدثين. هذا هو الواجب عليه .. هذا هو المشروع للمؤمن، والأحاديث في هذا صريحة لا صلاة بحضرة الطعام، ولا هو يدافعه الأخبثان وكذلك الأمر بتقديم العشاء قبل أن يصلي؛ لأنه بهذا يطمئن. أما إذا دخل المسجد على المغرب، وهو صائم؛ فإنه يبدأ بتحية المسجد، ولو صائمًا؛ يبدأ بالركعتين، ثم يفطر، والحمد لله؛ لأن المدة قليلة، دقيقتان ثلاث، الحمد لله، الرسول ﷺ قال: إذا دخل أحدكم المسجد؛ فلا يجلس حتى يصلي ركعتين وفي اللفظ الآخر: فليركع ركعتين قبل أن يجلس فليبدأ بالركعتين إذا كان على طهارة، يبدأ بالركعتين، ثم يجلس يفطر، الحمد لله. نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11659/الصاىم-اذا-دخل-المسجد-هل-يبدا-بالفطر-ام-يصلي-التحية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_515/51504.mp3","categories":["المساجد ومواضع السجود","صلاة التطوع"]},{"id":13554,"question":"رسالة مطولة بعض الشيء بعث بها المستمع عادل عبدالقيوم من السودان بور سودان وضمنها أربعة أسئلة، في سؤاله الأول يقول: نحن مجموعة من الشباب والحمد لله محافظون على أداء الصلوات الخمس في المسجد، وبعد صلاة العشاء نذهب إلى منازلنا، ثم نأتي لكي نبيت في المسجد، فمنا من يصلي في الليل، ومنا من يقرأ القرآن، ثم نستيقظ قبل الفجر، ونؤذن أذان التنبيه للفجر، وسبب مبيتنا في المسجد لكي نضمن أداء صلاة الفجر خوفًا من أننا إذا نمنا في منازلنا سوف تفوتنا صلاة الفجر، وبعض الناس يسخرون منا، ويقولون لنا: لماذا تنامون في المسجد؟ أليس لكم بيوت، أو أسرة تنامون عليها؟ ونحن نسأل: هل مبيتنا هذا جائز؟ نرجو إفتاءنا وتوجيهنا؟ جزاكم الله خيرًا.","title":"حكم المبيت في المسجد لإدراك صلاة الفجر جماعة","answer":"الجواب: إذا كان المبيت في المسجد لهذه العلة، وهو خوف النوم عن صلاة الفجر؛ فلا بأس بذلك، لكن إذا تيسر لكم من يوقظكم في بيوتكم، أو وضع الساعة المنبهة عند رأس أحدكم، كونه يبيت في بيته، ويتهجد في بيته آخر الليل؛ هذا هو الأفضل، وهذا هو الأولى كما فعله النبي ﷺ والصحابة، فيبيت الإنسان في بيته، ويضع الساعة عند رأسه وهي -إن شاء الله- يحصل بها التنبيه.  أما إذا لم يتيسر ذلك، ونمتم في المسجد لأجل يوقظ بعضكم بعضًا حتى تصلوا الفجر مع المسلمين؛ فهذا خير عظيم، وقصد صالح، وأنتم لكم العذر بهذا، لكن إذا تيسر لكل منكم أن يجتهد في الصلاة في بيته والبيتوتة في بيته فهذا أفضل، والساعة -بحمد الله- تنفع في الغالب إذا وقتها على وقت مناسب قرب الفجر؛ فإنها -بحمد الله- تنفعه. نعم، الساعة... التي لها منبه. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11878/حكم-المبيت-في-المسجد-لادراك-صلاة-الفجر-جماعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_480/48005.mp3","categories":["المساجد ومواضع السجود"]},{"id":13634,"question":"المستمع عايد عبدالوهاب من السودان الخرطوم بعث يسأل ويقول: مسجد في قرية كان به قبر من ناحية القبلة، ولكن أهل القرية عندما علموا أن هذا لا يجوز أخرجوا القبر خارج المسجد، وذلك بتحويل الحائط الذي على القبلة إلى الداخل بحيث يكون القبر خارج المسجد، ولكن في جهة القبلة، فهل هذا يكفي؟","title":"هل يكفي إخراج القبر خارج المسجد بجدار؟","answer":"الجواب: نعم يكفي، لما أخرجوه يكفي، لكن لو نقلوه إلى المقبرة العامة؛ كان أحسن وأطيب وأكمل، وإلا فإذا أخرجوه من المسجد عن يمين المسجد، أو شماله، أو قدامه، أو خلفه؛ كفى؛ لأنه حينئذ يكون المسجد سليمًا من القبر. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11964/هل-يكفي-اخراج-القبر-خارج-المسجد-بجدار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_480/48019.mp3","categories":["المساجد ومواضع السجود"]},{"id":13821,"question":"دخل شخص المسجد قبل أذان المغرب بحوالي ربع ساعة أو عشر دقائق أو أقل من ذلك فهل على هذا الشخص أن يصلي ركعتين تحية للمسجد؟ أم يظل واقفًا حتى يؤذن للمغرب؟","title":"حكم صلاة تحية المسجد قبل المغرب","answer":"الجواب: السنة أن يصلي الإنسان ركعتين متى دخل ولو قبيل الغروب؛ لعموم قوله ﷺ: إذا دخل أحدكم المسجد فلا يجلس حتى يصلي ركعتين، وهاتان الركعتان من ذوات الأسباب ليس لهما وقت نهي كسجود التلاوة، وكصلاة الكسوف، فإن الشمس متى كسفت صلى الناس للكسوف ولو بعد العصر، فهكذا ركعتا التحية حكمهما حكم ذوات الأسباب ليس لهما وقت نهي. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12189/حكم-صلاة-تحية-المسجد-قبل-المغرب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_537/53705.mp3","categories":["صلاة التطوع","المساجد ومواضع السجود"]},{"id":13823,"question":"هذا سائل للبرنامج أرسل بمجموعة من الأسئلة، في سؤاله الأول يقول: هل للمصلى ركعتين تحية كتحية المسجد؟ أم أنها خاصة بالمسجد فقط؟ وهل يعتبر المصلى يأخذ حكم المسجد كالبيع والشراء فيه؟ أم أنه ليس كذلك؟","title":"هل المصلى له حكم المسجد؟","answer":"الجواب: ليس للمصلى حكم المساجد، فلا تشرع الركعتان لدخوله ولا حرج في البيع والشراء فيه؛ لأنه موضع للصلاة عند الحاجة وليس مسجدًا، وإنما المسجد ما يعد للصلاة وقفًا تؤدى فيه الصلاة كسائر المساجد، أما مصلى مؤقت تصلي فيه جماعة الدائرة أو جماعة نزلوا لوقت معين ثم يرتحلون هذا لا يسمى مسجدًا، فلا حرج أن يباع فيه ويشترى وليس له تحية المسجد، وإنما التحية لما أعد مسجدًا وَقْفًا لله ؛ لإقامة الصلوات فيه. نعم.\nالمقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/12196/هل-المصلى-له-حكم-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_537/53709.mp3","categories":["المساجد ومواضع السجود"]},{"id":14025,"question":"ما رأي سماحتكم في الذين يأتون بأطفالهم إلى المساجد لأداء الصلاة، علمًا بأن الأطفال لا يقرءون ولا يحفظون من القرآن حتى سورة الفاتحة، أفتونا جزاكم الله خيرًا.","title":"حكم إحضار الأطفال إلى المساجد","answer":"الجواب: إذا تيسر بقاؤه في البيت هذا طيب حتى لا يؤذوا أحدًا، وإذا لم يتيسر لأنها تحب أن تصلي مع الناس، أو تسمع الدرس والفائدة أو الخطبة فلا حرج، ولو كان معها صبية صغار؛ لأن الرسول ﷺ أخبر في الحديث الصحيح، أنه: \"يدخل الصلاة يريد التطويل -يريد تطويلها- ثم يسمع بكاء الصبي فيخفف لئلا يشق على أمه\" فدل ذلك على أنهم يصلون معهم الصبيان، ولم ينهاهم عن إحضار الصبيان الصغار، وكذلك في الحديث الصحيح لما تأخر في بعض الليالي عن صلاة العشاء، قال عمر : \"يا رسول الله! رقد النساء والصبيان\"، فدل على أن الصبيان يحضرون.\nوالحاصل: أن حضور الصبيان مع أمهاتهم أو مع آبائهم أمر لا بأس به، وإذا كان ليس من أهل الصلاة، جاءت به لأجل تطمئن، حتى تصلي مع الناس، وحتى تسمع الخطبة والفائدة فلا بأس بذلك، وإن تيسر من يحفظه لها في بيتها؛ حتى لا تتأذى ولا تؤذي به أحدًا فهذا أولى وأفضل إذا تيسر ذلك. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12445/حكم-احضار-الاطفال-الى-المساجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_483/48313.mp3","categories":["المساجد ومواضع السجود"]},{"id":14222,"question":"المستمع (أ. م. العبادي) من يافع ومقيم في جدة بعث بسؤال يقول فيه: هل تجوز الصلاة في مسجد بني محرابه فوق قبرين قديمين؟","title":"حكم الصلاة في مسجد بني محرابه على قبور","answer":"الجواب: لا يجوز بناء المسجد على القبور لا محرابه ولا غيره، يجب أن يفصل القبران عن المسجد وأن يكونا خارج المسجد، وأن يكون محل الإمام داخل المسجد، ولا يجوز الصلاة في هذا المحراب، بل يجب أن يهدم هذا المحراب ويزال ويكون القبران خارج المسجد؛ لأن الرسول ﷺ لعن اليهود والنصارى قال: اتخذوا قبور أنبيائهم مساجد، وقال عليه الصلاة والسلام: ألا وإن من كان قبلكم كانوا يتخذون قبور أنبيائهم وصالحيهم مساجد ألا فلا تتخذوا القبور مساجد فإني أنهاكم عن ذلك. فالرسول ﷺ نهى عن اتخاذ المساجد على القبور ونهى أن يصلى عندها، الصلاة عندها اتخاذ لها مساجد. فهذا المسجد مثلًا إذا ثبت أن محرابه على القبرين يهدم المحراب ويكون القبران خارج المسجد أو ينبش القبران وتنقل رفاتهما إلى المقبرة، فإذا نبشا وأزيلا وصار المحراب في محلهما فلا حرج في ذلك، وقد ثبت عن النبي ﷺ أنه بنى مسجده في محل قبور وخرب ونخل، فأمر الرسول ﷺ بقبور من قبور المشركين أن تنبش وبالخرب أن تسوى وبالنخل أن يقطع ثم بنى مسجده عليه الصلاة والسلام. فإذا دعت الحاجة إلى محل فيه قبور نبشت القبور ونقل رفاتها إلى المقبرة العامة وإلى محل آخر وبني المسجد عند الحاجة إلى نبش القبور ولاسيما إذا كانت قبور غير مسلمة قبور المشركين تنبش، أما قبور المسلمين فلا تنبش يلتمس مكانًا مناسبًا ليس فيه قبور ويبنى فيه المسجد، لكن لو دعت الحاجة إلى نبش بعض القبور لتوسعة المسجد؛ لأن مكانه مناسب وليس هناك مكان أنسب منه ودعت الحاجة إلى نبش بعض القبور فلا مانع من أن تنبش وتنقل رفاتها إلى محل مناسب إلى مقبرة عامة لتوسعة المسجد. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12687/حكم-الصلاة-في-مسجد-بني-محرابه-على-قبور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_617/61703.mp3","categories":["المساجد ومواضع السجود"]},{"id":14225,"question":"المستمع (أ. م. العبادي) من يافع ومقيم في جدة بعث بسؤال يقول فيه: هل تجوز الصلاة في مسجد بني محرابه فوق قبرين قديمين؟","title":"حكم الصلاة في مسجد بني محرابه على قبور","answer":"الجواب: لا يجوز بناء المسجد على القبور لا محرابه ولا غيره، يجب أن يفصل القبران عن المسجد وأن يكونا خارج المسجد، وأن يكون محل الإمام داخل المسجد، ولا يجوز الصلاة في هذا المحراب، بل يجب أن يهدم هذا المحراب ويزال ويكون القبران خارج المسجد؛ لأن الرسول ﷺ لعن اليهود والنصارى قال: اتخذوا قبور أنبيائهم مساجد، وقال عليه الصلاة والسلام: ألا وإن من كان قبلكم كانوا يتخذون قبور أنبيائهم وصالحيهم مساجد ألا فلا تتخذوا القبور مساجد فإني أنهاكم عن ذلك. فالرسول ﷺ نهى عن اتخاذ المساجد على القبور ونهى أن يصلى عندها، الصلاة عندها اتخاذ لها مساجد. فهذا المسجد مثلًا إذا ثبت أن محرابه على القبرين يهدم المحراب ويكون القبران خارج المسجد أو ينبش القبران وتنقل رفاتهما إلى المقبرة، فإذا نبشا وأزيلا وصار المحراب في محلهما فلا حرج في ذلك، وقد ثبت عن النبي ﷺ أنه بنى مسجده في محل قبور وخرب ونخل، فأمر الرسول ﷺ بقبور من قبور المشركين أن تنبش وبالخرب أن تسوى وبالنخل أن يقطع ثم بنى مسجده عليه الصلاة والسلام. فإذا دعت الحاجة إلى محل فيه قبور نبشت القبور ونقل رفاتها إلى المقبرة العامة وإلى محل آخر وبني المسجد عند الحاجة إلى نبش القبور ولاسيما إذا كانت قبور غير مسلمة قبور المشركين تنبش، أما قبور المسلمين فلا تنبش يلتمس مكانًا مناسبًا ليس فيه قبور ويبنى فيه المسجد، لكن لو دعت الحاجة إلى نبش بعض القبور لتوسعة المسجد؛ لأن مكانه مناسب وليس هناك مكان أنسب منه ودعت الحاجة إلى نبش بعض القبور فلا مانع من أن تنبش وتنقل رفاتها إلى محل مناسب إلى مقبرة عامة لتوسعة المسجد. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12687/حكم-الصلاة-في-مسجد-بني-محرابه-على-قبور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_617/61703.mp3","categories":["المساجد ومواضع السجود"]},{"id":14310,"question":"مع مطلع هذه الحلقة نعود إلى رسالة المستمع ابن دامري من كركوك حيث عرضنا بعد أسئلة له في حلقة مضت وفي هذه الحلقة يسأل ويقول: أسألكم عن الصلاة في المساجد التي فيها قبور، هل يجوز ذلك أو لا؟ وما هو السبب؟ جزاكم الله خيرًا.","title":"هل يجوز الصلاة في المساجد التي فيها قبور؟","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فإن المساجد التي فيها القبور لا يصلى فيها، لقول النبي ﷺ: لعن الله اليهود والنصارى اتخذوا قبور أنبيائهم مساجد، فلعنهم على الصلاة عند القبور واتخاذها مساجد، فدل ذلك على أن الصلاة عندها معصية كبيرة، والشيء الذي لعن الرسول ﷺ فاعله لا يصح، يكون معصية لا يصح ولا يقبل، ولقوله ﷺ: ألا وإن من كان قبلكم كانوا يتخذون قبور أنبيائهم وصالحيهم مساجد ألا فلا تتخذوا القبور مساجد فإني أنهاكم عن ذلك، خرجه الإمام مسلم في صحيحه، والأول أخرجه الشيخان في الصحيحين. فالرسول ﷺ لعن من اتخذها مساجد، ونهى عن اتخاذها مساجد والصلاة عندها، فعلم بذلك أن الصلاة غير صحيحة؛ لأن الرسول ﷺ لعن من فعلها، ونهى عن فعلها، والعلة في ذلك أن هذا وسيلة للشرك، اتخاذ المساجد على القبور والصلاة عند القبور وسيلة للشرك، وسيلة لعبادة أهلها من دون الله، والاستغاثة بهم والنذر لهم والذبح لهم فيقع الشرك الأكبر، فإنه إذا بنى عليه مسجدًا غلا فيه العامة، وقالوا: هذا ما بني عليه المسجد إلا لأنه كيت وكيت، إلا لأنه ينفع المريض، ويقضي الحاجة يشفع لنا عند ربنا في كذا فيدعونه من دون الله.\nوهكذا الصلاة عند القبور ولو من غير بناء، الصلاة عندها أيضًا من اتخاذها مساجد لقول النبي ﷺ: وجعلت لي الأرض مسجدًا وطهورًا، فمن قصد أن يصلي عند القبر فقد اتخذه مسجدًا.\nفالقبر يسلم عليه ويدعى لصاحبه، لكن لا يتخذ محل للصلاة ولا محل للقراءة، ولكن يزور المؤمن أخاه المؤمن في المقبرة، ويسلم عليه ويدعو له، لكن لا يصلي عند قبره ولا يبني عليه مسجدًا ولا قبة كل هذا منكر، يقول عليه الصلاة والسلام لما أخبرته أم سلمة وأم حبيبة بكنيسة رأتاها في أرض الحبشة وما فيها من الصور، قال: أولئك يعني: النصارى إذا مات فيهم الرجل الصالح بنوا على قبره مسجدًا، وصوروا فيه تلك الصور ثم قال ﷺ: أولئك شرار الخلق عند الله. فأخبر أنهم شرار الخلق بأسباب بناؤهم على القبور واتخاذها مساجد والصلاة عندها، ثم قد يصورون الصور ويجعلونها فوقها زيادة في الفتنة، يصورون صورة صاحب القبر ويجعلونها على قبره، وفي مسجده حتى تكون الفتنة أعظم والصور قد لعن الرسول ﷺ فاعلها، في الصحيحين: أنه لعن ﷺ آكل الربا وموكله والمصور، هكذا رواه البخاري في الصحيح عن رسول الله ﷺ أنه لعن آكل الربا وموكله، والواشمة والمستوشمة ولعن المصور.\nوقال عليه الصلاة والسلام: أشد الناس عذابًا يوم القيامة المصورون، وقال ﷺ: إن أصحاب هذه الصور يعذبون يوم القيامة، ويقال لهم: أحيوا ما خلقتم.\nفالواجب على أهل الإسلام أن يحذروا البناء على القبور واتخاذها مساجد أو تجصيصها أو جعل القباب عليها كل هذا منكر، تجعل ضاحية شامسة في المقبرة لا يبنى عليها شيء، ولا تجصص ولا يتخذ عليها الستور ولا قبة بل ضاحية، كما كانت قبور الصحابة في المدينة هكذا وفي مكة هكذا فهذا هو الواجب. أما ما أحدثه الناس من البناء على القبور، واتخاذ القباب عليها فهذه بدعة منكرة ومحرمة والواجب هدمها، الواجب على ولاة الأمور إذا كانوا منقادين للشرع أن يهدموها ويزيلوها، والواجب على كل مسلم أن يعبد الله وحده، وأن يخصه بالعبادة دون كل ما سواه جل وعلا. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12776/هل-يجوز-الصلاة-في-المساجد-التي-فيها-قبور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_487/48701.mp3","categories":["المساجد ومواضع السجود"]},{"id":14313,"question":"يسأل أخونا أيضًا ويقول: هل كتابة القرآن الكريم على جدار المساجد جائز؟ أم أنه غير جائز؟","title":"حكم كتابة الآيات القرآنية على جدران المساجد","answer":"الجواب: يكره ذلك؛ لأنه يشوش على المصلين، فالأفضل والأولى أن لا يكتب في جدران المساجد لا القرآن ولا غيره، وقد نص كثير من أهل العلم على ذلك؛ لأن المساجد محل الصلاة ومحل العبادة، فالأفضل أن تكون خالية مما يشوش على المصلين من الكتابات أو النقوش، فلا ينبغي أن يكتب في جدرانها آيات قرآنية ولا غيرها حتى لا يحصل التشويش على المصلي، بل تكون سادة ليس فيها شيء هذا هو المشروع، وأقل الأحوال في الكتابات في المساجد الكراهة لما فيها من شغل المصلين والتشويش عليهم حتى ولو بغير الآيات من الأحاديث أو الأبيات الشعرية أو غير هذا مما قد يكتب، وهكذا النقوش التي قد تشغل المصلي يكره وجودها في المساجد. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12784/حكم-كتابة-الايات-القرانية-على-جدران-المساجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_622/62202.mp3","categories":["القرآن وعلومه","المساجد ومواضع السجود","الوقف"]},{"id":14316,"question":"يسأل أخونا أيضًا ويقول: هل كتابة القرآن الكريم على جدار المساجد جائز؟ أم أنه غير جائز؟","title":"حكم كتابة الآيات القرآنية على جدران المساجد","answer":"الجواب: يكره ذلك؛ لأنه يشوش على المصلين، فالأفضل والأولى أن لا يكتب في جدران المساجد لا القرآن ولا غيره، وقد نص كثير من أهل العلم على ذلك؛ لأن المساجد محل الصلاة ومحل العبادة، فالأفضل أن تكون خالية مما يشوش على المصلين من الكتابات أو النقوش، فلا ينبغي أن يكتب في جدرانها آيات قرآنية ولا غيرها حتى لا يحصل التشويش على المصلي، بل تكون سادة ليس فيها شيء هذا هو المشروع، وأقل الأحوال في الكتابات في المساجد الكراهة لما فيها من شغل المصلين والتشويش عليهم حتى ولو بغير الآيات من الأحاديث أو الأبيات الشعرية أو غير هذا مما قد يكتب، وهكذا النقوش التي قد تشغل المصلي يكره وجودها في المساجد. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12784/حكم-كتابة-الايات-القرانية-على-جدران-المساجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_622/62202.mp3","categories":["القرآن وعلومه","المساجد ومواضع السجود","الوقف"]},{"id":14335,"question":"المستمع بكري عبد القادر أحمد من السودان مديرية النيل بعث برسالة ضمنها ثلاثة أسئلة، في أحد أسئلته يسأل ويقول: ما حكم الصلاة خلف المقابر إذا كانت المقابر أمام المصلين مقدار ثلاثين متر تقريبًا هل يجوز ذلك؟","title":"حكم الصلاة إلى جهة المقابر","answer":"الجواب: إذا كان المسجد خاليًا منها، المسجد لم يبن عليها بل خاليًا منها وهي خارج المسجد فلا بأس تصح الصلاة في المسجد، أما إذا كان المسجد بني على القبور فلا يصلى في المساجد التي فيها القبور لقول النبي ﷺ: لعن الله اليهود والنصارى اتخذوا قبور أنبيائهم مساجد ولقوله ﷺ: ألا وإن من كان قبلكم كانوا يتخذون قبور أنبيائهم وصالحيهم مساجد ألا فلا تتخذوا القبور مساجد فإني أنهاكم عن ذلك فإذا كان المسجد قد بني على القبور أو جعلت فيه القبور فلا يصلى فيه، أما إذا كانت خارج المسجد يمين أو شمال أو قدامه لكن ليست فيه ولا مبنيًا عليها فلا حرج في ذلك.\nوأما وجود قبر النبي ﷺ في مسجده فهذا ليس في المسجد بل في بيت عائشة، قبر في بيت عائشة هو وصاحباه أبو بكر وعمر رضي الله عنهما لكن لما وسع المسجد وسعه الوليد بن عبد الملك، لما وسعه الوليد بن عبد الملك بن مروان أدخل الحجرة في المسجد وصار شبهة لبعض الناس الذين لا يفهمون، وهذا غلط، غلط من الوليد ولا ينبغي أن يحتج به في ذلك، فالنبي ﷺ ليس في المسجد بل مدفون في بيته، ولكن أدخلت الحجرة في المسجد، فلا يحتج بذلك على الدفن في المساجد، ولا يحتج بذلك على البناء على القبور واتخاذها مساجد، كل هذا مخالف لشرع الله. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12834/حكم-الصلاة-الى-جهة-المقابر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_623/62311.mp3","categories":["المساجد ومواضع السجود","مسائل متفرقة في العقيدة"]},{"id":14406,"question":"أبو مجاهد، مقيم في الإمارات له هذه المجموعة من الأسئلة يقول في السؤال الأول: سماحة الشيخ، يذكر بأنه إمام لأحد المساجد ومدرس في الصباح والمساء، يقول: أعمل بلا راتب، وجاء أحد الصالحين، وأعطاني مبلغًا باسم المسجد، فهل حرام علي أن أستعمل هذا المال لنفسي؟","title":"حكم أخذ إمام المسجد من أموال المسجد","answer":"الجواب: إذا كان أعطاك إياه لمصلحة المسجد كتعمير أو فراش أو للفقراء، فلا تأخذ منه شيئًا، أما لك، أعطاك إياه لك، قال: هذه مساعدة مني لك فلا بأس، أما إذا أعطاك إياه لمصلحة المسجد من فراش أو تعمير أو سراج أو غيرها من مصالح المسجد فليس لك أن تأخذ منه شيئًا، بل يصرف في مصالح المسجد، أما إذا أعطاك إياه قال: تصدق به، اصرفه فيما تراه من وجوه الخير، فاعمل به في وجوه الخير، لا تأخذ منه شيئًا أنت لك، بل تصرفه في وجوه الخير التي أشار إليها؛ لأنك وكيل، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12888/حكم-اخذ-امام-المسجد-من-اموال-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_553/55303.mp3","categories":["المساجد ومواضع السجود"]},{"id":14477,"question":"رسالة وصلت إلى البرنامج من ليبيا، وباعثها جمع من الإخوة، رمزوا إلى أسمائهم بالحروف (س. أ. ذ. ر) إخواننا لهم عدد من الأسئلة، فيسألون مثلًا ويقولون: ما حكم الصلاة في المساجد التي تحتها قبور، وإن كنت لا تنوي أن الصلاة لمن في القبر؟نرجو أن تفيدونا هل الصلاة مقبولة بسبب هذا الولي الفلاني أو لا؟","title":"ما حكم الصلاة في المساجد التي تحتها قبور؟","answer":"الجواب: الصلاة في المساجد التي فيها القبور لا تجوز، بل هي باطلة؛ لقول النبي ﷺ: لعن الله اليهود والنصارى، اتخذوا قبور أنبيائهم مساجد متفق على صحته من حديث عائشة -رضي الله عنها-، قاله في مرض موته -عليه الصلاة والسلام-، في آخر حياته، وقال أيضًا -عليه الصلاة والسلام-: ألا وإن من كان قبلكم كانوا يتخذون قبور أنبيائهم وصالحيهم مساجد، ألا فلا تتخذوا القبور مساجد، فإني أنهاكم عن ذلك خرجه مسلم في صحيحه عن جندب بن عبدالله البجلي ، فلا يجوز للمسلم أن يقيم مسجدًا على قبر، أو يدفن في المساجد، أو يصلي في المساجد التي فيها القبور، بل يجب التواصي بترك ذلك والتناصح، ويجب على ولاة الأمور في أي بلد إسلامي يجب على ولاة الأمور أن يمنعوا ذلك، فلا يدفن في المساجد أموات، ولا تبنى المساجد على القبور، لا هذا ولا هذا، يجب أن تكون المقابر على حدة، والمساجد على حدة، ولا يقبر فيها لا من يسمى ولي ولا غيره، والولي هو المؤمن، ولي الله هو المؤمن، فلا يدفن فيها لا مسلم ولا غيره، بل تكون المساجد خالية من القبور، وهذا هو الواجب الذي بينه الرسول ﷺ.\nوالعلة في ذلك والحكمة في ذلك كما قال أهل العلم: أنّ وجود القبور في المساجد من وسائل عبادتها من دون الله، إذا بنيت المساجد على القبور كان هذا من وسائل الغلو في الميت، ودعائه من دون الله، والتبرك بقبره، وطلبه الشفاعة، وطلبه الغوث والمدد، فلهذا حرم الله بناء المساجد على القبور، وحرم الله الدفن في المساجد؛ سدًا لذريعة الشرك، وحسمًا لمادة الشرك. ولا ينبغي للعاقل أن يغتر بما يوجد في بعض الأمصار وبعض الدول الإسلامية من وجود القبور في المساجد، لا ينبغي لعاقل أن يغتر بذلك هذا غلط، والغلط لا يقتدى به، والواجب على حكام المسلمين في كل مكان أن يزيلوا هذا الأمر، لا في الشام، ولا في مصر، ولا في العراق، ولا في غيره، الواجب على حكام المسلمين أن ينزهوا المساجد من القبور، وأن تكون المساجد خالية من القبور، وإذا كان فيها قبر ينقل إلى المقبرة العامة، وإذا كان المسجد بني عليه، والقبر هو السابق يهدم المسجد، وتبقى القبور خالية ليس فيها مساجد. فالحاصل: أنه إذا كان القبر هو الأول يهدم المسجد، وتبقى الأرض للقبور، وإن كان المسجد هو الأول، ودفن فيه ينبش القبر، وينقل إلى المقبرة، ولا يصلى في المساجد التي فيها القبور هذا بدعة ولا يجوز، والصلاة باطلة. أما إن كانت الصلاة للميت، كأن يصلي للميت ويتقرب إليه بالصلاة أو بالسجود كان شركًا أكبر، وكانت المصيبة أعظم، وهكذا لو طلبه المدد كأن يقول: يا سيدي المدد المدد، أو يا ولي الله المدد المدد، أو يا سيدي البدوي المدد المدد، أو يا حسين المدد المدد، أو يا شيخ عبدالقادر المدد المدد، أو أغثني، أو انصرني، كل هذا من الشرك الأكبر.\nقال الله : وَلَوْ أَشْرَكُوا لَحَبِطَ عَنْهُمْ مَا كَانُوا يَعْمَلُونَ [الأنعام:88] قال سبحانه: وَمَنْ يَدْعُ مَعَ اللَّهِ إِلَهًا آخَرَ لا بُرْهَانَ لَهُ بِهِ فَإِنَّمَا حِسَابُهُ عِنْدَ رَبِّهِ إِنَّهُ لا يُفْلِحُ الْكَافِرُونَ [المؤمنون:117] قال : ذَلِكُمُ اللَّهُ رَبُّكُمْ لَهُ الْمُلْكُ وَالَّذِينَ تَدْعُونَ مِنْ دُونِهِ مَا يَمْلِكُونَ مِنْ قِطْمِيرٍ ۝ إِنْ تَدْعُوهُمْ لا يَسْمَعُوا دُعَاءَكُمْ وَلَوْ سَمِعُوا مَا اسْتَجَابُوا لَكُمْ وَيَوْمَ الْقِيَامَةِ يَكْفُرُونَ بِشِرْكِكُمْ وَلا يُنَبِّئُكَ مِثْلُ خَبِيرٍ [فاطر:13-14] ، فسمى دعاءهم لغير الله شركًا، قال: وَيَوْمَ الْقِيَامَةِ يَكْفُرُونَ بِشِرْكِكُمْ فسمى دعوتهم للأموات واستغاثتهم بالأموات شركًا به .\nوسماهم في الآية الأخرى كفرًا، قال: وَمَنْ يَدْعُ مَعَ اللَّهِ إِلَهًا آخَرَ لا بُرْهَانَ لَهُ بِهِ فَإِنَّمَا حِسَابُهُ عِنْدَ رَبِّهِ إِنَّهُ لا يُفْلِحُ الْكَافِرُونَ [المؤمنون:117] الآية من سورة المؤمنون، وقال -جل وعلا-: وَأَنَّ الْمَسَاجِدَ لِلَّهِ فَلا تَدْعُوا مَعَ اللَّهِ أَحَدًا [الجن:18] قال سبحانه: وَلا تَدْعُ مِنْ دُونِ اللَّهِ مَا لا يَنْفَعُكَ وَلا يَضُرُّكَ فَإِنْ فَعَلْتَ فَإِنَّكَ إِذًا مِنَ الظَّالِمِينَ [يونس:106] وقال -عليه الصلاة والسلام-: الدعاء هو العبادة وقال لـابن عباس: إذا سألت فاسأل الله، وإذا استعنت فاستعن بالله. فالواجب على أهل الإسلام الحذر من هذا الشرك، والتحذير منه، والتواصي بالحق، والتواصي بالصبر، والواجب على العلماء في كل مكان أن يبينوا للناس هذا الأمر، وأن يرشدوهم إلى توحيد الله، والإخلاص له، وأن يعلموهم أنواع الشرك حتى يحذروها. والواجب على الحكام أن يزيلوا آثار الشرك، وأن يزيلوا القبور من المساجد التي فيها قبور إذا كانت القبور حادثة، فإن كانت المساجد بنيت على القبور، فالواجب أن تزال المساجد وأن تهدم، وأن تبقى القبور على حالها مقبرة ليس عليها مساجد.\nوهنا أمر قد يغتر به بعض الناس وهو: وجود قبر النبي ﷺ وقبر صاحبيه في المسجد النبوي، ويقولون: هذا قبر النبي في المسجد، وهذا غلط؛ لأن الرسول ﷺ لم يدفن في المسجد، دفن في بيت عائشة، وهكذا صاحباه أبو بكر وعمر دفنا معه في بيت عائشة، ولم يدفنوا في المسجد، ولكن الوليد بن عبدالملك لما وسع المسجد في آخر المائة الأولى أدخل القبر في المسجد من أجل التوسعة، وهذا غلط منه، فلا ينبغي أن يغتر بذلك، فالرسول ﷺ وصاحباه لم يدفنوا في المسجد، بل دفنوا في بيت عائشة، والنبي ﷺ نهى عن الصلاة إلى القبور، وقال: لا تصلوا إلى القبور، ولا تجلسوا عليها ولعن المتخذين المساجد على القبور. فالمعول على تشريعه وأمره ونهيه -عليه الصلاة والسلام-، أما عمل الناس إذا غلطوا، إذا غلط الوليد أو غير الوليد فلا يعول عليه، فينبغي التنبه لهذا الأمر، وينبغي لأهل العلم أن ينبهوا من حولهم من الناس على هذا الأمر حتى تعم الفائدة، وحتى يتبصر المسلم، وحتى يعلم الحقيقة، فلا يقع في الشرك وهو لا يشعر، نسأل الله للجميع الهداية والتوفيق، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12981/ما-حكم-الصلاة-في-المساجد-التي-تحتها-قبور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_625/62508.mp3","categories":["المساجد ومواضع السجود"]},{"id":14479,"question":"رسالة وصلت إلى البرنامج من ليبيا، وباعثها جمع من الإخوة، رمزوا إلى أسمائهم بالحروف (س. أ. ذ. ر) إخواننا لهم عدد من الأسئلة، فيسألون مثلًا ويقولون: ما حكم الصلاة في المساجد التي تحتها قبور، وإن كنت لا تنوي أن الصلاة لمن في القبر؟نرجو أن تفيدونا هل الصلاة مقبولة بسبب هذا الولي الفلاني أو لا؟","title":"ما حكم الصلاة في المساجد التي تحتها قبور؟","answer":"الجواب: الصلاة في المساجد التي فيها القبور لا تجوز، بل هي باطلة؛ لقول النبي ﷺ: لعن الله اليهود والنصارى، اتخذوا قبور أنبيائهم مساجد متفق على صحته من حديث عائشة -رضي الله عنها-، قاله في مرض موته -عليه الصلاة والسلام-، في آخر حياته، وقال أيضًا -عليه الصلاة والسلام-: ألا وإن من كان قبلكم كانوا يتخذون قبور أنبيائهم وصالحيهم مساجد، ألا فلا تتخذوا القبور مساجد، فإني أنهاكم عن ذلك خرجه مسلم في صحيحه عن جندب بن عبدالله البجلي ، فلا يجوز للمسلم أن يقيم مسجدًا على قبر، أو يدفن في المساجد، أو يصلي في المساجد التي فيها القبور، بل يجب التواصي بترك ذلك والتناصح، ويجب على ولاة الأمور في أي بلد إسلامي يجب على ولاة الأمور أن يمنعوا ذلك، فلا يدفن في المساجد أموات، ولا تبنى المساجد على القبور، لا هذا ولا هذا، يجب أن تكون المقابر على حدة، والمساجد على حدة، ولا يقبر فيها لا من يسمى ولي ولا غيره، والولي هو المؤمن، ولي الله هو المؤمن، فلا يدفن فيها لا مسلم ولا غيره، بل تكون المساجد خالية من القبور، وهذا هو الواجب الذي بينه الرسول ﷺ.\nوالعلة في ذلك والحكمة في ذلك كما قال أهل العلم: أنّ وجود القبور في المساجد من وسائل عبادتها من دون الله، إذا بنيت المساجد على القبور كان هذا من وسائل الغلو في الميت، ودعائه من دون الله، والتبرك بقبره، وطلبه الشفاعة، وطلبه الغوث والمدد، فلهذا حرم الله بناء المساجد على القبور، وحرم الله الدفن في المساجد؛ سدًا لذريعة الشرك، وحسمًا لمادة الشرك. ولا ينبغي للعاقل أن يغتر بما يوجد في بعض الأمصار وبعض الدول الإسلامية من وجود القبور في المساجد، لا ينبغي لعاقل أن يغتر بذلك هذا غلط، والغلط لا يقتدى به، والواجب على حكام المسلمين في كل مكان أن يزيلوا هذا الأمر، لا في الشام، ولا في مصر، ولا في العراق، ولا في غيره، الواجب على حكام المسلمين أن ينزهوا المساجد من القبور، وأن تكون المساجد خالية من القبور، وإذا كان فيها قبر ينقل إلى المقبرة العامة، وإذا كان المسجد بني عليه، والقبر هو السابق يهدم المسجد، وتبقى القبور خالية ليس فيها مساجد. فالحاصل: أنه إذا كان القبر هو الأول يهدم المسجد، وتبقى الأرض للقبور، وإن كان المسجد هو الأول، ودفن فيه ينبش القبر، وينقل إلى المقبرة، ولا يصلى في المساجد التي فيها القبور هذا بدعة ولا يجوز، والصلاة باطلة. أما إن كانت الصلاة للميت، كأن يصلي للميت ويتقرب إليه بالصلاة أو بالسجود كان شركًا أكبر، وكانت المصيبة أعظم، وهكذا لو طلبه المدد كأن يقول: يا سيدي المدد المدد، أو يا ولي الله المدد المدد، أو يا سيدي البدوي المدد المدد، أو يا حسين المدد المدد، أو يا شيخ عبدالقادر المدد المدد، أو أغثني، أو انصرني، كل هذا من الشرك الأكبر.\nقال الله : وَلَوْ أَشْرَكُوا لَحَبِطَ عَنْهُمْ مَا كَانُوا يَعْمَلُونَ [الأنعام:88] قال سبحانه: وَمَنْ يَدْعُ مَعَ اللَّهِ إِلَهًا آخَرَ لا بُرْهَانَ لَهُ بِهِ فَإِنَّمَا حِسَابُهُ عِنْدَ رَبِّهِ إِنَّهُ لا يُفْلِحُ الْكَافِرُونَ [المؤمنون:117] قال : ذَلِكُمُ اللَّهُ رَبُّكُمْ لَهُ الْمُلْكُ وَالَّذِينَ تَدْعُونَ مِنْ دُونِهِ مَا يَمْلِكُونَ مِنْ قِطْمِيرٍ ۝ إِنْ تَدْعُوهُمْ لا يَسْمَعُوا دُعَاءَكُمْ وَلَوْ سَمِعُوا مَا اسْتَجَابُوا لَكُمْ وَيَوْمَ الْقِيَامَةِ يَكْفُرُونَ بِشِرْكِكُمْ وَلا يُنَبِّئُكَ مِثْلُ خَبِيرٍ [فاطر:13-14] ، فسمى دعاءهم لغير الله شركًا، قال: وَيَوْمَ الْقِيَامَةِ يَكْفُرُونَ بِشِرْكِكُمْ فسمى دعوتهم للأموات واستغاثتهم بالأموات شركًا به .\nوسماهم في الآية الأخرى كفرًا، قال: وَمَنْ يَدْعُ مَعَ اللَّهِ إِلَهًا آخَرَ لا بُرْهَانَ لَهُ بِهِ فَإِنَّمَا حِسَابُهُ عِنْدَ رَبِّهِ إِنَّهُ لا يُفْلِحُ الْكَافِرُونَ [المؤمنون:117] الآية من سورة المؤمنون، وقال -جل وعلا-: وَأَنَّ الْمَسَاجِدَ لِلَّهِ فَلا تَدْعُوا مَعَ اللَّهِ أَحَدًا [الجن:18] قال سبحانه: وَلا تَدْعُ مِنْ دُونِ اللَّهِ مَا لا يَنْفَعُكَ وَلا يَضُرُّكَ فَإِنْ فَعَلْتَ فَإِنَّكَ إِذًا مِنَ الظَّالِمِينَ [يونس:106] وقال -عليه الصلاة والسلام-: الدعاء هو العبادة وقال لـابن عباس: إذا سألت فاسأل الله، وإذا استعنت فاستعن بالله. فالواجب على أهل الإسلام الحذر من هذا الشرك، والتحذير منه، والتواصي بالحق، والتواصي بالصبر، والواجب على العلماء في كل مكان أن يبينوا للناس هذا الأمر، وأن يرشدوهم إلى توحيد الله، والإخلاص له، وأن يعلموهم أنواع الشرك حتى يحذروها. والواجب على الحكام أن يزيلوا آثار الشرك، وأن يزيلوا القبور من المساجد التي فيها قبور إذا كانت القبور حادثة، فإن كانت المساجد بنيت على القبور، فالواجب أن تزال المساجد وأن تهدم، وأن تبقى القبور على حالها مقبرة ليس عليها مساجد.\nوهنا أمر قد يغتر به بعض الناس وهو: وجود قبر النبي ﷺ وقبر صاحبيه في المسجد النبوي، ويقولون: هذا قبر النبي في المسجد، وهذا غلط؛ لأن الرسول ﷺ لم يدفن في المسجد، دفن في بيت عائشة، وهكذا صاحباه أبو بكر وعمر دفنا معه في بيت عائشة، ولم يدفنوا في المسجد، ولكن الوليد بن عبدالملك لما وسع المسجد في آخر المائة الأولى أدخل القبر في المسجد من أجل التوسعة، وهذا غلط منه، فلا ينبغي أن يغتر بذلك، فالرسول ﷺ وصاحباه لم يدفنوا في المسجد، بل دفنوا في بيت عائشة، والنبي ﷺ نهى عن الصلاة إلى القبور، وقال: لا تصلوا إلى القبور، ولا تجلسوا عليها ولعن المتخذين المساجد على القبور. فالمعول على تشريعه وأمره ونهيه -عليه الصلاة والسلام-، أما عمل الناس إذا غلطوا، إذا غلط الوليد أو غير الوليد فلا يعول عليه، فينبغي التنبه لهذا الأمر، وينبغي لأهل العلم أن ينبهوا من حولهم من الناس على هذا الأمر حتى تعم الفائدة، وحتى يتبصر المسلم، وحتى يعلم الحقيقة، فلا يقع في الشرك وهو لا يشعر، نسأل الله للجميع الهداية والتوفيق، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12981/ما-حكم-الصلاة-في-المساجد-التي-تحتها-قبور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_625/62508.mp3","categories":["المساجد ومواضع السجود"]},{"id":14633,"question":"المستمع محمد حازم عبدالعزيز، من الدمام، بعث برسالة يقول فيها: أنا من جمهورية مصر العربية، ويوجد بالبلدة التي أعيش فيها مسجد به قبر في غرفة بطرف المسجد، يفصل بينهما باب، أصلي بهذا المسجد أحيانًا، أنكر علي بعض الأشخاص، وقال: لا تصل في هذا المسجد؛ لأن فيه قبر، أستشيركم في هذا الموضوع. جزاكم الله خيرًا.","title":"مسجد به قبر في غرفة بطرف المسجد، يفصل بينهما باب، هل يصلى فيه؟","answer":"الجواب: إذا كان القبر خارج سور المسجد، فلا يضر الصلاة في المسجد، ولكن ينبغي مع هذا إبعاده عن المسجد، مع المقبرة، حتى لا يحصل تشويش على الناس.  أما إذا كان في داخل المسجد فإنك لا تصل في المسجد؛ لقول النبي ﷺ: لعن الله اليهود والنصارى اتخذوا قبور أنبيائهم مساجد متفق على صحته؛ ولقوله أيضًا -عليه الصلاة والسلام-: ألا وإن من كان قبلكم كانوا يتخذون قبور أنبيائهم وصالحيهم مساجد، ألا فلا تتخذوا القبور مساجد، فإني أنهاكم عن ذلك أخرجه مسلم في صحيحه، فالرسول ﷺ نهى عن اتخاذ القبور مساجد، فليس لنا أن نتخذها مساجد، سواء كانت القبور للأنبياء أو للصالحين أو لغيرهم ممن لا يعرف. فالواجب: أن تكون القبور على حدة في محلات خاصة، وأن تكون المساجد سليمة من ذلك لا يكون فيها قبور. ثم الحكم فيه تفصيل: فإن كان القبر هو الأول -أو القبور- ثم بني المسجد فإن المسجد يهدم، ولا يجوز بقاؤه على القبور؛ لأنه بني على غير شريعة الله، فوجب هدمه. أما إن كانت القبور متأخرة، والمسجد هو السابق، فإن الواجب نبشها ونقل رفاتها إلى المقبرة العامة، كل رفات قبر توضع في حفرة خاصة، ويواسى ظاهرها كسائر القبور، حتى لا تمتهن، وتكون من تبع المقبرة التي دفن فيها الرفات، حتى يسلم المسلمون من الفتنة بالقبور. والرسول ﷺ حين نهى عن اتخاذ المساجد على القبور، مقصوده -عليه الصلاة والسلام- سد الذريعة التي توصل إلى الشرك؛ لأن القبور إذا وضعت في المساجد يغلو فيها العامة، ويظنون أنها وضعت لأنها تنفع؛ ولأنها تقبل النذور؛ ولأنها تدعى ويستغاث بأهلها، فيقع الشرك.  فالواجب الحذر من ذلك، وأن تكون القبور بعيدة عن المساجد، تكون في محلات خاصة، وتكون المساجد سليمة من ذلك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13154/مسجد-به-قبر-في-غرفة-بطرف-المسجد-يفصل-بينهما-باب-هل-يصلى-فيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_627/nour_62709.mp3","categories":["المساجد ومواضع السجود"]},{"id":14662,"question":"المرأة التي تتخذ سجادة للصلاة في بيتها هل في ذلك بأس يا شيخ؟","title":"حكم اتخاذ المرأة سجادة لها في بيتها للصلاة","answer":"الجواب: لا حرج، تتخذ سجادة، أو حصير، أو غير ذلك لا حرج في ذلك، كان النبي ﷺ له حصير يصلي عليه -عليه الصلاة والسلام-، لا بأس. المقدم: جزاكم الله عنا كل خير.","link":"https://binbaz.org.sa/fatwas/13148/حكم-اتخاذ-المراة-سجادة-لها-في-بيتها-للصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_560/56003.mp3","categories":["المساجد ومواضع السجود","الحيض والنفاس","قضايا المرأة"]},{"id":14890,"question":"الذين يقرؤون بصوت مرتفع، ويحرمون الناس من قراءة القرآن في المسجد؟","title":"حكم قراءة القرآن بصوت مرتفع في المسجد","answer":"الجواب: لا ينبغي هذا، في المسجد يقرأ قراءة منخفضة، لا يؤذي بها المصلين، ولا القراء، وقد خرج النبي ﷺ ذات ليلة على الناس في المسجد، وهم يصلون جماعات يتهجدون يرفعون أصواتهم، فقال: كلكم يناجي الله، فلا يؤذي بعضكم بعضًا فلا يجهر بعضكم على بعض.  فالسنة أن كل واحد يخفض صوته في الصف، حتى لا يؤذي غيره من المصلين ولا من القراء.\nالمقدم: جزاكم الله خيرًا، وهذا في الجمعة وفي غيرها؟ الشيخ: في الجمعة وغيرها، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13387/حكم-قراءة-القران-بصوت-مرتفع-في-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_639/nour_63907.mp3","categories":["المساجد ومواضع السجود"]},{"id":14992,"question":"السائل يقول: إمام المسجد الذي يصلي بنا يقنت في معظم الأحيان في صلاة الصبح، ونادرًا ما يتركه، علمًا بأننا نصلي خلفه هل للمأموم أن يرفع يديه خلف هذا؟","title":"حكم رفع اليدين خلف من يقنت في الفجر","answer":"الجواب: إذا قنت لا بأس أن تقنت معه، لكن الأفضل أن يدع ذلك، السنة أن لا يقنت في الفجر، إلا في الوتر فقط، إلا في النوازل إذا نزل نازلة بالمسلمين -حرب، عدو- يدعو في صلاته، بعد الركوع يرفع يديه ويدعو، يقنت في النوازل كما كان النبي ﷺ يفعل في الصبح وغيرها.  أما اعتياد قنوت الصبح دائمًا فهذا خلاف السنة، والصواب تركه، لكن لو صليت مع إمام يقنت فلا بأس أن تؤمن على دعائه وأن ترفع يديك، نعم. المقدم: أحسن الله إليكم سماحة الشيخ، وأثابكم الله.","link":"https://binbaz.org.sa/fatwas/13484/حكم-رفع-اليدين-خلف-من-يقنت-في-الفجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_562/56219.mp3","categories":["المساجد ومواضع السجود"]},{"id":15187,"question":"أيضًا يقول: بعض المساجد نشاهد فيها الدواليب التي توضع فيها المصاحف مفتوحة من الأمام والخلف مما يسبب عند إقامة الصلاة أن تكون المصاحف خلف بعض الصفوف، هل يجوز ذلك، أم لا بد من سدها مع إحدى الجهات، وهي التي تلي ظهور المصلين؟","title":"حكم جعل المصاحف خلف الصفوف","answer":"الجواب: الأمر في هذا فيما يظهر واسع؛ لأنهم ما قصدوا استدبارها، وإنما وضعت لينتفع بها المسلمون، فالأمر في هذا واسع، لكن لو جعلت في أمام المسجد قدام المصلين لكان أولى وأحسن، أبعد عن هذا الأمر، وأبعد عن مشابهة المستدبرين المحتقرين أو المستهينين. فبكل حال وجودها في مقدمة المسجد، أو في جوانب المسجد يمينًا وشمالًا، يكون أصلح وأولى وأبعد عن هذا الشيء الذي توهمه السائل، فالمصلون ما قصدوا احتقارها، ولا استهانة بها، ولكن هكذا كان وضعها في بعض المساجد.  فينبغي في المسجد الذي توضع فيه هكذا أن توضع في الأمام، أو على جنب المصلي عن يمينه أو شماله في جوانب المسجد، نعم. المقدم: بارك الله فيكم، هذه توضع في الجوامع الكبيرة، ويستحيل أن يأخذ المصلي المصحف من الدالوب إذا كان بعيد مثلًا، فيضعونها خلف بين الصفوف حتى تكون متيسرة.\nالشيخ: بين السواري يعني؟ المقدم: بين السواري نعم. الشيخ: ما نعلم في هذا شيء -إن شاء الله-؛ لأنه غير مقصود، ليست الاستهانة مقصودة، وإنما المقصود التسهيل للقراء حتى لا يتخطوا الناس، ويؤذوا الناس، لا الأمر في هذا واسع -إن شاء الله-، نعم.\nالمقدم: والسائل عبدالعزيز يقول في رسالته، وهي طويلة، كما ذكرنا يقول: لماذا لا تستر مع الجهة التي تلي ظهور المصلين؟\nالشيخ: لأجل التسهيل، من جاء هنا أخذ، ومن جاء هنا أخذ، هذا المقصود، التسهيل، كونها مفتوحة من هنا ومن هنا للتسهيل على القراء، الذي يأتي من الأمام يأخذ، والذي يأتي من خلف يأخذ حتى يكون أخذ المصحف متيسرًا من هنا ومن هنا، هذا المقصود، وجعل الحائل ما يمنع الاستدبار، فلو وضع حائلًا فالاستدبار حاصل، أقول: لو سد أحد الجانبين ما منع الاستدبار، الاستدبار حاصل، نعم.","link":"https://binbaz.org.sa/fatwas/13688/حكم-جعل-المصاحف-خلف-الصفوف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_666/nour_66604.mp3","categories":["المساجد ومواضع السجود"]},{"id":15209,"question":"يقول: ما حكم قراءة القرآن في المسجد بصوت عالٍ قبل الصلاة، وبحضور كثير من المصلين كل يقرأ على حدة؟","title":"ما حكم رفع الصوت بقراءة القرآن في المسجد؟","answer":"الجواب: السنة عدم الرفع، ما ينبغي الرفع، يكره الرفع أو يحرم؛ لأنه يؤذي، فهذا الذي في المسجد السنة له أن يخفض صوته، حتى لا يتأذى به مصل، ولا قارئ؛ لأن الناس كل واحد قد يحب أن يقرأ، أو يصلي، فإذا كان من حوله يرفع صوته بالقراءة شوش عليه صلاته، وشوش عليه قراءته.  فالسنة أنه يخفض صوته خفضًا لا يضره، ولا يشوش على من حوله، يعني: خفضًا مناسبًا، يقرأ به قراءة مناسبة، ليس فيها تشويش على من حوله. وقد ثبت عن النبي ﷺ أنه خرج ذات يوم على الناس في مسجده، وهم يصلون في الليل، وبعضهم يرفع صوته على بعض، فقال: كلكم يناجي الله، فلا يؤذ بعضكم بعضًا هذا معناه: اخفضوا أصواتكم، لا يؤذي بعضكم بعضًا برفع الصوت. وهذا شيء مشاهد، شيء معقول، إذا كان يليك من يرفع صوته شوشت عليك قراءتك وصلاتك، فإما أن تنصت له، وإما أن تشوش أنت في صلاتك وفي قراءتك، فلهذا الواجب على من يقرأ في الصفوف أكرر هذا الواجب أو المتأكد ألا يجهر، بل يخفض صوته، ولا يجهر حال قراءته في الصف، حتى لا يتأذى به من حوله من المصلين والقارئين. أما إذا كان عندك جماعة محدودة، يرضون بذلك، يسمعون له، فلا بأس، إذا كانت جماعة قليلة في المسجد ينتظرون ما هناك من يصلي، ولا يقرأ، ويحبوا أن يسمعوا صوته، فلا بأس، أما إذا كان هناك من يصلي، وهناك من يقرأ لا، لا يرفع صوته، نعم.","link":"https://binbaz.org.sa/fatwas/13717/ما-حكم-رفع-الصوت-بقراءة-القران-في-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_672/nour_67205.mp3","categories":["القرآن وعلومه","المساجد ومواضع السجود","الوقف"]},{"id":15211,"question":"السؤال السادس للمرسل محمود سيد أبو زيد، يقول فيه: ما الحكم فيمن يلقي السلام على الموجودين في المسجد؛ وذلك قبل تأدية صلاة تحية المسجد؟","title":"حكم إلقاء السلام على من في المسجد","answer":"الجواب: هذا هو السنة أنه إذا دخل على الجماعة في المسجد يسلم عليهم، ولو أنهم يصلون، يقول: السلام عليكم، وإن قال: ورحمة الله وبركاته، طيب، فالذي في الصلاة يرد بالإشارة، هكذا يشير بيده، إشارة له، والذي خارج الصلاة يرد، ويقول: وعليكم السلام ورحمة الله وبركاته، ولا بأس بهذا، ولا يكره هذا، بل مشروع، كان الصحابة يسلمون على النبي ﷺ وهو يصلي -عليه الصلاة والسلام- فيرد عليهم بالإشارة -عليه الصلاة والسلام-. وأما قول بعض العامة: إنه لا يسلم على من في المسجد أو على المصلى، هذا غلط خلاف السنة، بل يسلم عليهم ويردون عليه ولو كانوا يقرؤون، يقول: السلام عليكم، وإذا سمعوا الصوت يقولوا: وعليكم السلام، وإن كان قال: ورحمة الله يقولوا: وعليكم السلام ورحمة الله يردون مثل قوله أو أزيد؛ لأن الله قال: وَإِذَا حُيِّيتُمْ بِتَحِيَّةٍ فَحَيُّوا بِأَحْسَنَ مِنْهَا أَوْ رُدُّوهَا [النساء:86]، فإذا قال: السلام عليكم، قالوا: وعليكم السلام، وإن زادوه: ورحمة الله، كان أفضل لهم، وإن زادوه: وبركاته كان أفضل لهم. أما إذا قال: السلام عليكم ورحمة الله وبركاته، فإنه يلزمهم أن يقولوا مثل ذلك، حتى يردوا عليه تحيته، ويقفوا عن القراءة، ثم يشتغلوا بالقراءة، وإن كانوا في الصلاة ردوا بالإشارة، نعم.","link":"https://binbaz.org.sa/fatwas/13724/حكم-القاء-السلام-على-من-في-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_672/nour_67206.mp3","categories":["المساجد ومواضع السجود","الآداب والأخلاق المحمودة"]},{"id":15212,"question":"صالح عبدالعزيز الصالح، وإن كنا سوف نمضي -إن شاء الله- في أسئلة محمود سيد أبو زيد، لكن هنا سؤال يقارب سؤال الأخ، يقول صالح العبدالعزيز الصالح: ما حكم السلام على المصلين الذين يصلون في الفرض؟","title":"هل يسلم من دخل المسجد على من يصلون؟","answer":"الجواب: مثل النافلة، إذا دخل والناس في الصلاة، يقول: السلام عليكم، ويرد عليه بالإشارة من حوله من سمع صوته يرد عليه بالإشارة، ولو في الفرض، نعم. المقدم: ولو كان جميع الناس في الفرض؟ الشيخ: ولو في الفرض، يسلم على من حوله في طرف الصف الذي وصل إليهم، نعم.","link":"https://binbaz.org.sa/fatwas/13725/هل-يسلم-من-دخل-المسجد-على-من-يصلون","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_672/nour_67207.mp3","categories":["المساجد ومواضع السجود"]},{"id":15215,"question":"يقول: ما حكم قراءة القرآن في المسجد بصوت عالٍ قبل الصلاة، وبحضور كثير من المصلين كل يقرأ على حدة؟","title":"ما حكم رفع الصوت بقراءة القرآن في المسجد؟","answer":"الجواب: السنة عدم الرفع، ما ينبغي الرفع، يكره الرفع أو يحرم؛ لأنه يؤذي، فهذا الذي في المسجد السنة له أن يخفض صوته، حتى لا يتأذى به مصل، ولا قارئ؛ لأن الناس كل واحد قد يحب أن يقرأ، أو يصلي، فإذا كان من حوله يرفع صوته بالقراءة شوش عليه صلاته، وشوش عليه قراءته.  فالسنة أنه يخفض صوته خفضًا لا يضره، ولا يشوش على من حوله، يعني: خفضًا مناسبًا، يقرأ به قراءة مناسبة، ليس فيها تشويش على من حوله. وقد ثبت عن النبي ﷺ أنه خرج ذات يوم على الناس في مسجده، وهم يصلون في الليل، وبعضهم يرفع صوته على بعض، فقال: كلكم يناجي الله، فلا يؤذ بعضكم بعضًا هذا معناه: اخفضوا أصواتكم، لا يؤذي بعضكم بعضًا برفع الصوت. وهذا شيء مشاهد، شيء معقول، إذا كان يليك من يرفع صوته شوشت عليك قراءتك وصلاتك، فإما أن تنصت له، وإما أن تشوش أنت في صلاتك وفي قراءتك، فلهذا الواجب على من يقرأ في الصفوف أكرر هذا الواجب أو المتأكد ألا يجهر، بل يخفض صوته، ولا يجهر حال قراءته في الصف، حتى لا يتأذى به من حوله من المصلين والقارئين. أما إذا كان عندك جماعة محدودة، يرضون بذلك، يسمعون له، فلا بأس، إذا كانت جماعة قليلة في المسجد ينتظرون ما هناك من يصلي، ولا يقرأ، ويحبوا أن يسمعوا صوته، فلا بأس، أما إذا كان هناك من يصلي، وهناك من يقرأ لا، لا يرفع صوته، نعم.","link":"https://binbaz.org.sa/fatwas/13717/ما-حكم-رفع-الصوت-بقراءة-القران-في-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_672/nour_67205.mp3","categories":["القرآن وعلومه","المساجد ومواضع السجود","الوقف"]},{"id":15217,"question":"السؤال السادس للمرسل محمود سيد أبو زيد، يقول فيه: ما الحكم فيمن يلقي السلام على الموجودين في المسجد؛ وذلك قبل تأدية صلاة تحية المسجد؟","title":"حكم إلقاء السلام على من في المسجد","answer":"الجواب: هذا هو السنة أنه إذا دخل على الجماعة في المسجد يسلم عليهم، ولو أنهم يصلون، يقول: السلام عليكم، وإن قال: ورحمة الله وبركاته، طيب، فالذي في الصلاة يرد بالإشارة، هكذا يشير بيده، إشارة له، والذي خارج الصلاة يرد، ويقول: وعليكم السلام ورحمة الله وبركاته، ولا بأس بهذا، ولا يكره هذا، بل مشروع، كان الصحابة يسلمون على النبي ﷺ وهو يصلي -عليه الصلاة والسلام- فيرد عليهم بالإشارة -عليه الصلاة والسلام-. وأما قول بعض العامة: إنه لا يسلم على من في المسجد أو على المصلى، هذا غلط خلاف السنة، بل يسلم عليهم ويردون عليه ولو كانوا يقرؤون، يقول: السلام عليكم، وإذا سمعوا الصوت يقولوا: وعليكم السلام، وإن كان قال: ورحمة الله يقولوا: وعليكم السلام ورحمة الله يردون مثل قوله أو أزيد؛ لأن الله قال: وَإِذَا حُيِّيتُمْ بِتَحِيَّةٍ فَحَيُّوا بِأَحْسَنَ مِنْهَا أَوْ رُدُّوهَا [النساء:86]، فإذا قال: السلام عليكم، قالوا: وعليكم السلام، وإن زادوه: ورحمة الله، كان أفضل لهم، وإن زادوه: وبركاته كان أفضل لهم. أما إذا قال: السلام عليكم ورحمة الله وبركاته، فإنه يلزمهم أن يقولوا مثل ذلك، حتى يردوا عليه تحيته، ويقفوا عن القراءة، ثم يشتغلوا بالقراءة، وإن كانوا في الصلاة ردوا بالإشارة، نعم.","link":"https://binbaz.org.sa/fatwas/13724/حكم-القاء-السلام-على-من-في-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_672/nour_67206.mp3","categories":["المساجد ومواضع السجود","الآداب والأخلاق المحمودة"]},{"id":15218,"question":"صالح عبدالعزيز الصالح، وإن كنا سوف نمضي -إن شاء الله- في أسئلة محمود سيد أبو زيد، لكن هنا سؤال يقارب سؤال الأخ، يقول صالح العبدالعزيز الصالح: ما حكم السلام على المصلين الذين يصلون في الفرض؟","title":"هل يسلم من دخل المسجد على من يصلون؟","answer":"الجواب: مثل النافلة، إذا دخل والناس في الصلاة، يقول: السلام عليكم، ويرد عليه بالإشارة من حوله من سمع صوته يرد عليه بالإشارة، ولو في الفرض، نعم. المقدم: ولو كان جميع الناس في الفرض؟ الشيخ: ولو في الفرض، يسلم على من حوله في طرف الصف الذي وصل إليهم، نعم.","link":"https://binbaz.org.sa/fatwas/13725/هل-يسلم-من-دخل-المسجد-على-من-يصلون","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_672/nour_67207.mp3","categories":["المساجد ومواضع السجود"]},{"id":15223,"question":"أخيرًا تسأل أختنا وتقول: ما حكم الذهاب للمسجد لحضور الندوات والمحاضرات، إذا كانت المرأة حائضًا؛ وذلك للاستفادة من الدروس التي غالبًا ما تكون قيمة؟","title":"حكم جلوس الحائض في المسجد لسماع الدروس","answer":"الجواب: إذا كان لها مكان قرب المسجد تسمع منه عند المحراب، أو في جانب المسجد، أو في آخر المسجد، تسمع، فلا بأس. أما في داخل المسجد فلا؛ لأن النبي  قال: إني لا أحل المسجد لحائض ولا جنب وقال في حق الجنب: إِلَّا عَابِرِي سَبِيلٍ [النساء:43] وقال لـعائشة لما أمرها أن تأتي بالخمرة من المسجد، قالت : إني حائض، قال: إن حيضتك ليست في يدك فأمرها أن تعبر وتأخذ الخمرة الحصير من المسجد. أما الجلوس، لا، أما المرور للجنب والحائض فلا بأس، أما الجلوس لا، لكن إذا وجد مكان خارج المسجد تسمع منه الدروس، فهذا لا بأس به، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13713/حكم-جلوس-الحاىض-في-المسجد-لسماع-الدروس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_497/49702.mp3","categories":["الحيض والنفاس","المساجد ومواضع السجود","قضايا المرأة"]},{"id":15294,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من المستمع سعيد عبدالفتاح شاهين، من الرياض، الأخ سعيد له سؤال طويل، ملخصه:الاستفهام عن الصلاة في مسجد بناه رجل بمال أكثره من الحرام، هل يشمله حكم الصلاة في الأرض المغصوبة، فإن لم يكن يشمله فلماذا؟نرجو أن تتفضلوا بمعالجة هذه القضية، جزاكم الله خيرًا.","title":"حكم الصلاة في مسجد بني من مال أكثره من حرام","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد: فالمساجد التي تبنى بمال حرام، أو بمال فيه حرام، لا بأس بالصلاة فيها، ولا يكون حكمها حكم الأرض المغصوبة؛ لأن الأموال التي فيها حرام، أو كلها من حرام تصرف في المصارف الشرعية، ولا تترك، ولا تحرق، بل يجب أن تصرف في المصارف الشرعية، كالصدقة على الفقراء، وبناء المساجد، وبناء دورات المياه، ومساعدة المجاهدين، وبناء القناطر وغيرها من مصالح المسلمين، ولا يكون لها حكم الغصب؛ لأن الغصب مأخوذ بالقوة والظلم، أما هؤلاء دخلت عليهم الأموال من طرق غير شرعية. فالواجب عليهم صرفها في وجوه شرعية، مع التوبة إلى الله من ذلك ، والمال الذي صرف في هذه الجهات الشرعية يكون قد سلم صاحبه من أذاه، مع التوبة إلى الله ، ويكون نفع به المسلمين بدلًا من إتلافه وإحراقه، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13788/حكم-الصلاة-في-مسجد-بني-من-مال-اكثره-من-حرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_498/49801.mp3","categories":["المساجد ومواضع السجود"]},{"id":15337,"question":"خالد صالح من اليمن، حضرموت، يقول: سماحة الشيخ، أسأل عن حكم الشرع في نظركم في نقل فرش قديم تم الاستغناء عنه من مسجد إلى مدرسة أو مسجد آخر. علمًا بأن هذا المسجد أو هذه المدرسة محتاجة إلى فرش، حتى وإن كانت قديمة؛ وذلك لغرض فرشه للمصلين في المسجد أو للطلبة في المدرسة.فأفيدونا بذلك.","title":"حكم نقل أثاث مسجد إلى مسجد آخر أو مدرسة","answer":"الجواب: إذا فضل عن المسجد شيء من أثاثه ينقل إلى مسجد آخر محتاج، فإذا ما وجد مساجد محتاجة يصرف في الفقراء والمساكين، أو في حاجات المدرسة لا بأس، أما إذا وجد مسجد محتاج ينقل من مسجد إلى مسجد؛ لأن مراد الموقف نفع المصلين والتقرب بما يعين المصلين على أداء صلاتهم، فإذا كانت المساجد مستغنية، فلا بأس أن يصرف الفاضل في الفقراء والمساكين، أو في حاجة مدرسة للطلاب، نعم.\nالمقدم: إذًا سماحة الشيخ نقل هذه الفرش من مسجد إلى مدرسة ما فيه شيء يا شيخ؟\nالشيخ: إذا كان ما هناك مسجد محتاج له، أما إذا كان هناك مسجد محتاج ينقل لمسجد آخر، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/13834/حكم-نقل-اثاث-مسجد-الى-مسجد-اخر-او-مدرسة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_566/56614.mp3","categories":["المساجد ومواضع السجود","الوقف"]},{"id":15538,"question":"هذا سائل يقول: يا سماحة الشيخ، حفظكم الله، يوجد ولي بجانب المسجد، ولا يزال بعض الناس يزورون هذا الولي، هل تجوز الصلاة في هذا المسجد؟","title":"حكم الصلاة في المسجد الذي بجواره قبر يزار","answer":"الجواب: إذا كان خارج المسجد لا يضر، يسلم عليه، ويدعى له، إذا كان من المسلمين، يسلم عليه، ويدعى له، لكن إبعاده إلى المقبرة أولى، وأبعد عن الشبهة، كونه ينقل إلى المقبرة، هذا هو الذي ينبغي، ينقل إلى المقبرة، حتى لا تقع الفتنة. أما إذا كان في داخل المسجد، لا، لا يصلى في المسجد، إذا كان داخل المسجد يجب أن يهدم المسجد، إن كان المسجد بني عليه، أما إن كان هو الذي جديد، والمسجد قديم، ينبش، وينقل إلى المقبرة، أما إذا كان المسجد بني عليه، وهو قديم، هو، فالمسجد يهدم؛ لأنه بني على القبور، أما إذا كان لا، المسجد قديم، ولكن أحدثوا فيه الميت، فالميت ينبش، وينقل إلى المقبرة، نعم. المقدم: حفظكم الله سماحة الشيخ، وسدد خطاكم.","link":"https://binbaz.org.sa/fatwas/14074/حكم-الصلاة-في-المسجد-الذي-بجواره-قبر-يزار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_691/nour_69116.mp3","categories":["المساجد ومواضع السجود"]},{"id":15701,"question":"هل تحية دخول المسجد الحرام، هو الصلاة -صلاة ركعتين- أم الطواف؟","title":"تحية دخول المسجد الحرام","answer":"الجواب: تحيته الطواف، لمن تيسر له الطواف، أما من لم يتيسر له الطواف، يصلي ركعتين ويجلس، أما إذا تيسر الطواف، فهو الأفضل، يبدأ بالطواف، النبي كان إذا دخل المسجد بدأ بالطواف -عليه الصلاة والسلام-، فإذا تيسر ذلك، استحب له أن يبدأ بالطواف سبعة أشواط، ثم يصلي ركعتين، ركعتي الطواف، وتكفي عن تحية المسجد، وإن كان هناك راتبة، كالظهر، صلى الرواتب بدلها، صلى راتبة الظهر قبل الصلاة، بعد ركعتي الطواف، يصلي الراتبة إذا كان طوافه قبل الظهر، يعني: بعد الأذان، طاف ثم صلى ركعتي الطواف، ثم يصلي الراتبة، تسليمتين للظهر، نعم.","link":"https://binbaz.org.sa/fatwas/14259/تحية-دخول-المسجد-الحرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_573/57310.mp3","categories":["المساجد ومواضع السجود"]},{"id":15743,"question":"يقول: يا سماحة الشيخ، يوجد عندنا مسجدٌ بجوار قبرٍ، وقد سُمي هذا المسجد باسم صاحب هذا القبر، ويقوم إمام المسجد ونفرٌ من الناس بالذهاب إلى هذا القبر، وإقامة أدعيةٍ لا نفهم منها شيئًا، ويقومون بقرع الدُّف، فما حكم الصلاة في هذا المسجد؟ مأجورين.","title":"حكم الصلاة في مسجدٍ بجوار قبرٍ","answer":"الجواب: إذا كان القبر خارج المسجد، والمسجد بعيدًا سليمًا منه فلا بأس، أما كونهم يقفون عند القبر، ويأتون بأدعيةٍ مجهولةٍ، ويضربون الدُّف؛ هذا بدعةٌ، هذا من خُرافات الصوفية، بدعةٌ لا يجوز. إنما يُسلِّم على القبور السلام الشرعي بصوتٍ معروفٍ، كان النبي ﷺ يزور القبور، ويقول: السلام عليكم دار قومٍ، وإنا -إن شاء الله- بكم لاحقون، نسأل الله لنا ولكم العافية، وكان عليه الصلاة والسلام يُعلم أصحابه إذا زاروا القبور أن يقولوا: السلام عليكم أهل الديار من المؤمنين والمسلمين، وإنا -إن شاء الله- بكم لاحقون، نسأل الله لنا ولكم العافية، اللهم لا تحرمنا أجرهم، ولا تفتنا بعدهم، واغفر لنا ولهم، يرحم الله المُستقدمين منا والمُستأخرين، هذا وأشباهه، هذا الذي كان يفعله النبي ﷺ. أما كونه يُسلِّم عليهم بصوتٍ مجهولٍ .....، هذا يُتهم صاحبه، ولا يجوز هذا. كذلك ضرب الدُّف عند السبب هذا بدعةٌ، لا أصلَ له، نعم. المقدم: أحسن الله إليكم، وبارك فيكم.","link":"https://binbaz.org.sa/fatwas/14329/حكم-الصلاة-في-مسجد-بجوار-قبر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_575/57506.mp3","categories":["المساجد ومواضع السجود"]},{"id":15755,"question":"يسأل ويقول: هل تجوز الصلاة في مسجد بُني على قبر أحد الصالحين، حيث أن الناس يأتوا بالذبائح ويذبحونها عند هذا القبر الذي هو بجانب المسجد مباشرة؟","title":"هل تجوز الصلاة في مسجد بُني على قبر؟","answer":"الجواب: لا يصلى في المسجد الذي بني على القبور، إذا كان مسجد في وسطه قبر، بني على القبر، لا يصلى فيه؛ لأن الرسول ﷺ لعن اليهود والنصارى لاتخاذهم القبور مساجد، قال: لعن الله اليهود والنصارى، اتخذوا قبور أنبيائهم مساجد وقال ﷺ: ألا وإن من كان قبلكم كانوا يتخذون قبور أنبيائهم وصالحيهم مساجد يعني: مصلى ألا فلا تتخذوها مساجد، فإني أنهاكم عن ذلك فالرسول ﷺ نهى عن هذا، وحذّر منه، فإذا كان في المسجد قبر أو أكثر، فإنه لا يصلى فيه، فإذا كان يذبح عنده، فهذا الشرك الأكبر، أعوذ بالله. فالحاصل: أنه لا يصلى في المساجد التي فيها القبور، سواء ذبح لأهلها، أو ما ذبح لأهلها، ولكن إذا كان يذبح لهم، يُدعَوْن، وينذر لهم، هذا الشرك الأكبر، يعني: قبر مع الشرك الأكبر عنده، نسأل الله العافية.  فالواجب حينئذٍ هدم المسجد، يجب على ولاة الأمر المسلمين أن يهدموا المسجد الذي بني على القبور، وأن تبقى القبور مكشوفة، ليس عليها بناء، ولا يصلى عندها ولو ما كان لها بها بناء لا يصلى عندها، لا تتخذ مصلى، حتى ولو كان من غير بناء، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14342/هل-تجوز-الصلاة-في-مسجد-بني-على-قبر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_741/nour_74104.mp3","categories":["المساجد ومواضع السجود"]},{"id":15938,"question":"بعض النساء سماحة الشيخ تحضر معها المبخرة والبخور في المسجد في صلاة التراويح في رمضان، ثم تقوم بتبخير المسجد وتبخير المصليات، ما هو توجيهكم لهن في هذا؟جزاكم الله خيرًا.","title":"توجيه لمن يقمن بتبخير المصليات في المسجد","answer":"الجواب: الذي ينبغي عدم فعل ذلك؛ لأنهن بعد الصلاة يخرجن للأسواق، ومعهن الطيب، فينبغي ترك ذلك؛ حتى لا يحصل فتنة بخروجهن متطيبات من المسجد عند خروج الناس، ولكن يصلين مع الناس من دون خروج بطيب لا عند المجيء، ولا عند الخروج؛ عملًا بالأحاديث الصحيحة في ذلك، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14543/توجيه-لمن-يقمن-بتبخير-المصليات-في-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_710/nour_71002.mp3","categories":["قضايا المرأة","المساجد ومواضع السجود"]},{"id":15952,"question":"يقول: هل يجوز أن يصلي المسلم ركعتين تحية المسجد، ثم يذهب إلى مسجد آخر، ويصلي فيه ركعتين تحية كذلك؟","title":"حكم الذهاب إلى المسجد لأجل التحية","answer":"الجواب: إذا كان المقصود الذهاب إلى المسجد للتحية هذا غير مشروع، أما إذا كان قصد المسجد لحضور حلقات العلم؛ ليجلس فيه الصلاة؛ ليجلس فيه يقرأ القرآن، يصلي تحية المسجد، أما أنه يذهب إلى المساجد يصلي ركعتين فقط هذا غير مشروع، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14570/حكم-الذهاب-الى-المسجد-لاجل-التحية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_746/nour_74614.mp3","categories":["المساجد ومواضع السجود"]},{"id":15960,"question":"هل يجوز للمكلف بنظافة المسجد، والعناية به براتب شهري أن يدفع جزءًا من الراتب لمن يقوم بهذا العمل نيابة عنه، ويأخذ هو بقية الراتب، أو بالأصح الجزء الأكبر منه، وهو لا يفعل شيئًا؟ وإذا كان هذا لا يجوز فهل من نصيحة تقدمونها لمن يفعل ذلك؟جزاكم الله عنا خيرًا.","title":"حكم استنابة العاملين في المساجد من يقوم بأعمالهم","answer":"الجواب: لا يجوز هذا العمل إلا بإذن المسؤول عن المسجد، سواء كان عامل الأوقاف أو غير الأوقاف. المقصود: المسؤول عن هذا المسجد الذي هو نائب فيه هو المسئول هو يسأله، فإذا أذن له أن يستنيب فلا بأس، المؤذن، أو الإمام، أو الخادم ليس لهم أن يستنيبوا إلا بإذن من الجهات المسئولة إلا الشيء اليسير العارض، إذا عرض للمؤذن عارض، وأمر من يؤذن كونه يحسن الأذان، أو الإمام له عارض في بعض الصلوات، أو الخادم هذا لا بأس به، أما بصفة مستمرة، أو بصفة طويلة، أو بأوقات كثيرة؛ فلا حتى يستأذن الجهة المختصة في أن يستنيب عنه في الإمامة، أو في الأذان، أو في خدمة المسجد؛ لأن النائب قد لا يقوم بما يقوم به الأصل قد يكون الأصل خيرًا منه وأولى بهذا الأمر.  والمقصود: لا بد من الاستئذان، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14566/حكم-استنابة-العاملين-في-المساجد-من-يقوم-باعمالهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_710/nour_71011.mp3","categories":["المساجد ومواضع السجود"]},{"id":15970,"question":"يقول: أرجو أن توجهوا المسلمين كي ما يخلوا مساجدهم من البدع؛ لأنني قرأت أن كثيراً من المساجد لا تخلو من البدع؟","title":"الحث على إخلاء المساجد من البدع","answer":"الجواب: الواجب على المسلمين أن يطهروا مساجدهم من كل ما حرم الله، من بدع أو معاصي، ومن البدع بناء المساجد على القبور، دفن الميت في المسجد، جعل حصاة يسجد عليها كما يفعل بعض الشيعة يسجدوا عليها، التلفظ بالنية نويت أن أصلي كذا وكذا هذه من البدع التي يجب تنزيه المساجد عنها، ولا يجوز أن يصلى في المقبرة، ولا في مسجد بني على قبر، بل يجب هدمه لأنه منكر وبدعة ومن وسائل الشرك. المقدم: جزاكم الله خيرًا، وأحسن إليكم","link":"https://binbaz.org.sa/fatwas/14585/الحث-على-اخلاء-المساجد-من-البدع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_746/nour_74622.mp3","categories":["المساجد ومواضع السجود"]},{"id":16008,"question":"سوداني مقيمٌ بالقويعية بعث يسأل سماحتكم، ورمز إلى اسمه بالحروف (ف. ع. ص)، في سؤاله الأول يقول: عندنا مسجدٌ بالقرية وحوله من ناحية الشمال خمسة قبورٍ، وكلما مات أحدٌ من مشايخه دُفن داخل السور، وعندما أكون موجودًا في القرية لا أذهب للصلاة معهم -حتى صلاة الجمعة- نسبةً للاعتقاد الذي يعتقدونه في المشايخ.الشيخ: أعد.المقدم: يقول: عندنا مسجدٌ في القرية وحوله من ناحية الشمال خمسة قبورٍ، وكلما مات أحدٌ من مشايخه دُفن داخل السور، وعندما أكون موجودًا في القرية لا أذهب للصلاة معهم -حتى صلاة الجمعة- نسبةً للاعتقاد الذي يعتقدونه في المشايخ، فهل ما أقوم به من ناحية الصلاة -وأيضًا صلاة الجمعة- صحيحٌ، أو غير ذلك؟أرجو من سماحتكم التوجيه، جزاكم الله خيرًا.","title":"حكم الصلاة في مسجدٍ حوله قبورٌ","answer":"الجواب: إذا كانت القبور في المسجد فلا تجوز الصلاة فيه: لا الجمعة، ولا غيرها، وأنت مُحسنٌ في عدم الصلاة معهم. أما إذا كانت القبور خارج المسجد، تحت سور البلد، وليس في المسجد، بل خارج المسجد؛ فإن الواجب عليك أن تصلي معهم الجمعة وغيرها.\nالمقصود أنه لا يجوز البناء على القبور، ولا اتخاذ المساجد عليها، ولا يجوز دفن أحدٍ في المسجد، فإذا كان المسجد فيه قبورٌ فلا تجوز الصلاة فيه: لا الجمعة، ولا غيرها، وليس لك أن تصلي معهم أيضًا. أما إذا كانت القبور خارجةً؛ شمال المسجد، أو جنوبه، أو غير ذلك، يعني: ليست في داخل المسجد؛ فإنك تصلي معهم، ويلزمك ذلك: الجمعة وغيرها. وقد صحَّ عن رسول الله ﷺ أنه قال: لعن الله اليهود والنصارى؛ اتخذوا قبور أنبيائهم مساجد، وقال -عليه الصلاة والسلام- في الحديث الصحيح: ألا وإن مَن كان قبلكم كانوا يتخذون قبور أنبيائهم وصالحيهم مساجد، ألا فلا تتخذوا القبور مساجد، فإني أنهاكم عن ذلك قد نهى عن اتخاذ القبور مساجد: لا يُصلَّى عند قبورٍ، ولا يُدفن في المسجد أحدٌ، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14649/حكم-الصلاة-في-مسجد-حوله-قبور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_747/nour_74719.mp3","categories":["المساجد ومواضع السجود"]},{"id":16085,"question":"من البحرين رسالة وصلت إلى البرنامج بتوقيع أحد الإخوة رمز إلى اسمه بالحروف (أ. ح. ر) مصري مقيم في البحرين، أخونا له عدد من الأسئلة، من بينها سؤال يقول: هل الأفضل أن يؤذن المؤذن للصلاة وأنا في المسجد منتظرًا للصلاة؟ أم أنتظر الأذان في بيتي لأصلي النوافل في بيتي، وأذهب إلى المسجد بعد ذلك لأداء الصلاة جماعة؟ جزاكم الله خيرًا.","title":"مشروعية المبادرة إلى الصلاة عند الأذان","answer":"كل ذلك خير، إن ذهبت إلى المسجد قبل الأذان؛ فلا بأس، وإن انتظرت في بيتك حتى يؤذن المؤذن، ثم تتوجه إلى المسجد، فكله طيب، لكن لا يجب عليك حتى يؤذن، فإذا سمعت: حي على الصلاة؛ فبادر، وسارع إلى الصلاة، أما قبل ذلك فأنت مخير إن رأيت المصلحة في التوجه حذرًا من العوائق، تقدم إلى المسجد؛ خوفًا من العوائق التي تعوقك عن الصلاة، فهذا من الحيطة، ومن المشروع أيضًا.  وإن كان هناك أسباب تقتضي التأخر أنها أصلح في حقك في أعمال تنفعك، أو في أعمال بيتك تنفعك، أو تنفع أهل بيتك؛ فلا بأس، وإذا أذن المؤذن؛ بادر، وسارع إلى المسجد، وأبشر بالخير العظيم. المقصود: أن التقدم قبل الأذان هذا فيه تفصيل: إن كانت هناك مصلحة للتقدم إلى المسجد قبل الأذان؛ فبادر بها، فبادر بذلك؛ تحقيقًا للمصلحة، كخوف أن يمنعك أحد عن التقدم إلى المسجد، أو يعوق عائق عن الخروج بعد الأذان إلى المسجد، أو أسباب أخرى تخشى منها.  أما إذا كان ما هناك أسباب؛ فأنت المشروع لك أن تبادر إذا سمعت الأذان، تبادر إلى الصلاة، وفي بيتك تعمل ما ينفعك، وينفع أهلك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14720/مشروعية-المبادرة-الى-الصلاة-عند-الاذان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_711/nour_71111.mp3","categories":["المساجد ومواضع السجود"]},{"id":16168,"question":"من الأخت المستمعة ( نالة . ح. ع) من المملكة رسالة وضمنتها جمعًا من الأسئلة، في أحدها تقول: ما حكم زيارة المساجد السبعة في المدينة المنورة؟","title":"عدم مشروعية زيارة المساجد السبعة","answer":"الجواب: ليس لها أصل، وليست مشروعة؛ لأن هذه المساجد السبعة ليس لها أصل، وإنما اعتادها الناس على غير بصيرة، وليست مشروعة زيارتها، إنما المشروع زيارة المسجد النبوي، وإذا زار المسجد النبوي؛ يستحب له أن يزور مسجد قباء خاصة، كان النبي يزوره ﷺ، فيزوره من زار المدينة، يستحب أن يزور مسجد قباء، وأما ما سوى ذلك: مسجد القبلتين، والمساجد السبعة، وغيرها هذه غير مشروعة، لا تشرع زيارتها، وليس عليها دليل، وإنما المشروع زيارة مسجد قباء خاصة، كان النبي يزوره ﷺ كل سبت، وقال: من تطهر في بيته، ثم أتى مسجد قباء، وصلى فيه ركعتين؛ كان كعمرة. وزيارة مسجده ﷺ أمر مشروع مع المسجد الحرام، والمسجد الأقصى؛ لقوله ﷺ: لا تشد الرحال إلا إلى ثلاثة مساجد: المسجد الحرام، ومسجدي هذا، والمسجد الأقصى وقال -عليه الصلاة والسلام-: صلاة في مسجدي هذا خير من ألف صلاة فيما سواه، إلا المسجد الحرام متفق على صحته. والحاصل: أنه ليس في المدينة ما يستحب زيارته من المساجد إلا مسجد قباء لمن زار المدينة بعد مسجد النبي -عليه الصلاة والسلام- أما المساجد السبعة، أو القبلتين، أو غير ذلك فهي غير مشروعة زيارتها. وهكذا الأماكن، ليس هناك أماكن تزار تستحب زيارتها سوى مسجده ﷺ ومسجد قباء، ولكن إذا زار القبور للسلام عليهم هذا مستحب في كل بلد، يزور القبور ويسلم عليهم في المدينة، يزور قبور الشهداء، يزور قبور البقيع، ويسلم عليهم، ويدعو لهم، هذا مستحب، وهو في كل بلد يزور قبور المسلمين، ويدعو لهم، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14858/عدم-مشروعية-زيارة-المساجد-السبعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_805/nour_80511.mp3","categories":["المساجد ومواضع السجود"]},{"id":16248,"question":"يقول في ثالث سؤال له: مسجد فيه قبر صاحبه، ومحاط بسلك، هل تجوز الصلاة فيه؟ وما حكم من تعمد ذلك؟ جزاكم الله خيرًا.","title":"حرمة الصلاة في المسجد الذي فيه قبر","answer":"الجواب:  جميع المساجد التي فيها القبور لا يصلى فيها، والصلاة فيها باطلة، وإذا كان المسجد هو القديم، ثم دفن فيه صاحبه؛ ينبش المدفون، ينبش، وينقل رفاته إلى المقبرة العامة، ويصلى في المسجد، أما إن كان القبر هو القديم، ثم بني عليه المسجد؛ فالمسجد يهدم، يهدم ويزال؛ لأنه أسس على ضلالة، وقد قال النبي ﷺ في الحديث الصحيح يقول ﷺ: قاتل الله اليهود والنصارى؛ اتخذوا قبور أنبيائهم مساجد وفي اللفظ الآخر: لعن الله اليهود والنصارى؛ اتخذوا قبور أنبيائهم مساجد ويقول ﷺ: ألا وإن من كان قبلكم كانوا يتخذون قبور أنبيائهم، وصالحيهم مساجد، ألا فلا تتخذوا القبور مساجد؛ فإني أنهاكم عن ذلك. وقالت له أم سلمة، وأم حبيبة لما هاجرتا إلى الحبشة: «إنهما رأتا كنيسة في الحبشة فيها تصاوير، فقال النبي ﷺ: أولئك إذا مات فيهم الرجل الصالح؛ بنوا على قبره مسجدًا، وصوروا فيه تلك الصور ثم قال: أولئك شرار الخلق عند الله فأخبر أنهم شرار الخلق؛ بأسباب بنائهم على القبور، واتخاذهم التصاوير عليها، نسأل الله العافية. فالمقصود: أن الواجب عدم البناء على القبور، لا قباب، ولا مساجد .. ولا غير ذلك، يجب أن تكون مكشوفة ليس عليها بناء كما كانت في عهد النبي ﷺ في البقيع تكون مكشوفة، ولا يزاد عليها غير ترابها، تكون مرفوعة قدر شبر تقريبًا؛ حتى يعرف أنها قبور، ولا يصلى بينها، ولا إليها، ولا يبنى عليها قبابًا، ولا حجرًا، ولا مساجد، ولا تستر، كل هذا منكر، وكله من وسائل الشرك، كل هذا من وسائل الشرك. فالواجب الحذر من ذلك، وكل مسجد فيه قبر لا يصلى فيه، لكن إن كان القبر هو الجديد ينبش، يوضع في المقابر، ويصلى في المسجد، فإن كان القبور هي القديمة، ثم بني عليها المسجد؛ فالمسجد يهدم، ولا يصلى فيه، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم، هذا السلك الذي يذكره، ويقول: إن المسجد محاط بسلك، هل ينفع، ويؤثر، أو لا تأثير له؟  الشيخ: هذا السلك يزال، يقطع، يزال إذا كان مقصود به تعظيم الميت، أو الإشارة إلى قبره.. أو ما أشبه ذلك؛ يزال، المقصود ما له حاجة، ولا له سبب يوجب السلك، فيجب إزالة السلك الذي يعتقدون فيه. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14961/حرمة-الصلاة-في-المسجد-الذي-فيه-قبر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_752/nour_75205.mp3","categories":["المساجد ومواضع السجود"]},{"id":16339,"question":"رسالة بعث بها أحد الإخوة المستمعين، آثر فيها عدم ذكر اسمه، يسأل سماحتكم فيقول: لو أنني دخلت في صلاة العشاء مثلًا، وأصلي منفردًا، ثم تذكرت أنني لم أصل المغرب، فهل يجوز لي أن أحول النية إلى صلاة المغرب، علمًا بأنني لم أركع الركعة الأولى؟ وإذا كنت في جماعة فهل أقطع صلاتي، وأصلي المغرب أولًا قبل العشاء، وبهذا تفوتني فضيلة الجماعة؟ جزاكم الله خيرًا.","title":"حكم من دخل في صلاة وتذكر التي قبلها","answer":"الجواب: إذا تذكرت أنك لم تصل المغرب؛ تقطع صلاة العشاء، تنوي قطعها، ثم تبتدي بتكبيرة الإحرام ناويًا المغرب، سواء كنت وحدك، أو مع الجماعة، ولا بأس أن تخالف نيتك نية الجماعة، لا حرج أن تصلي خلف من يصلي العشاء، وأنت ناويًا المغرب؛ لأنك ما صليتها، تقطع النية، نية العشاء بالنية، ثم تكبر تكبيرة الإحرام ناويًا المغرب، سواء كنت وحدك، أو مع الإمام، ثم بعد الفراغ تصلي العشاء بعد ذلك، والحمد لله.","link":"https://binbaz.org.sa/fatwas/15033/حكم-من-دخل-في-صلاة-وتذكر-التي-قبلها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_714/nour_71402.mp3","categories":["المساجد ومواضع السجود"]},{"id":16440,"question":"من المستمع عبدالله محمد سعيد رسالة ضمنها بعض الأسئلة، في أحدها يقول: مسجد تصلى فيه الصلوات، والجمع والأعياد، وحوله عدد من القبور، ما هو توجيهكم حول هذا المسجد، جزاكم الله خيرًا.","title":"حكم الصلاة في المسجد الذي بجاوره قبور","answer":"الجواب:  كونها حوله لا يضره، سواء كانت أمامه، أو عن يمينه، أو شماله لا يضر... المنهي عنه أن تكون في داخله، أما إذا كانت خارجة؛ فلا يضره ذلك، ولا يضر المصلين، إذا كان بينهم وبين القبور حاجز، مثل جدار يحجزهم، أو طريق، أو وادي، أو نحو ذلك مما يدل على بعدها، وأنها غير مقصودة للقبور، غير مقصودة بالمسجد الموجود، المقصود أن وجودها قرب المسجد لا يضر المسجد، ولا يضر المصلين، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15151/حكم-الصلاة-في-المسجد-الذي-بجاوره-قبور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_755/nour_75513.mp3","categories":["المساجد ومواضع السجود"]},{"id":16657,"question":"من أسئلتها تقول سماحة الشيخ: بأنه نزل أثناء وجودهم في المدرسة مطر غزير، فاستدعى الأمر أن يدخلوا في مسجد المدرسة، تقول وهي حائض، فدخلت معهم، هل عليها شيء؟ وهل المسجد في المدرسة يأخذ حكم المصلى؟ وفقكم الله.","title":"ما حكم دخول الحائض المسجد للضرورة؟","answer":"الجواب: إذا دخلت المرأة الحائض، أو النفساء المسجد للضرورة؛ فلا بأس، كأن تخشى على نفسها إذا كانت خارج المسجد للضرورة، أو لأسباب أخرى اضطرتها إلى ذلك؛ فلا حرج. أما مسجد المدرسة إذا كان مصلى ليس له حكم المساجد، إذا كان مصلى في المدرسة لها أن تجلس فيه؛ لأنه ليس لها حكم المساجد، المصلى في المدارس ليس له حكم المساجد، فللحائض، والنفساء أن تجلس في المصلى لسماع الخطبة، أو سماع الدرس، أو الفائدة، نعم. المقدم: أحسن الله إليكم يا شيخ.","link":"https://binbaz.org.sa/fatwas/15390/ما-حكم-دخول-الحاىض-المسجد-للضرورة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_583/58314.mp3","categories":["المساجد ومواضع السجود","الحيض والنفاس","قضايا المرأة"]},{"id":16842,"question":"من الهند رسالة بعث بها أحد الإخوة يقول في نهايتها: أخوكم هاشم مصطفى يقول: مسجد في أحد أركانه الخلفية أربعة قبور، هل تجوز الصلاة فيه؟ وهل يفوت الإنسان الجمعة والجماعة، ولا يصلي في هذا المسجد؟ أم ماذا؟ جزاكم الله خيرًا.","title":"مسجد في أحد أركانه الخلفية قبور، هل تجوز الصلاة فيه؟","answer":"الجواب: كل مسجد فيه قبور، سواء في أمام، أو يمين، أو شمال، أو خلف لا يصلى فيه، ولا تصح الصلاة فيه؛ لأن وجود القبور فيه من وسائل الشرك، وتعمه الأحاديث الصحيحة، يقول النبي ﷺ: لعن الله اليهود والنصارى اتخذوا قبور أنبيائهم مساجد ويقول ﷺ: لا تصلوا إلى القبور، ولا تجلسوا عليها ويقول -عليه الصلاة والسلام-: ألا وإن من كان قبلكم كانوا يتخذون قبور أنبيائهم وصالحيهم مساجد، ألا فلا تتخذوا القبور مساجد فإني أنهاكم عن ذلك. فالمسجد لا يتخذ على القبر، وقد يكون القبر في مقدمه، وقد يكون في يمين، أو في شمال، أو في خلف، فالواجب نبش هذه القبور، ونقلها إلى المقابر العامة، إذا كانت القبور متأخرة، أما إذا كان المسجد بني عليها لتعظيمها، والتبرك بها؛ هو يهدم، فالمسجد يهدم، وتبقى القبور على حالها، والمسجد يهدم ويزال، ويكون محله مقبرة، أما إذا كانت قبورًا (لا) جديدة والمسجد قديم، فالقبور يجب نبشها، وإزالتها، وإبعادها إلى المقابر العامة، ويصلى فيه، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15603/مسجد-في-احد-اركانه-الخلفية-قبور-هل-تجوز-الصلاة-فيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_824/nour_82403.mp3","categories":["المساجد ومواضع السجود"]},{"id":16862,"question":"تقول: أنا أحب المساجد، أحبها كثيرًا؛ لأنها بيوت الله، ولكن لا أذهب إليها؛ لأنني امرأة، والمرأة غير مستحب لها ذهابها إلى المساجد، فهل أكون مع السبعة الذين يظلهم الله في ظله، يوم لا ظل إلا ظله؟","title":"حصول المرأة على أجر من قلبه معلق بالمساجد","answer":"الجواب: يرجى لك ذلك؛ لأنكِ أمرت شرعًا بأن بيتك أفضل لك، فأنت لولا أن الرسول ﷺ شرع للنساء البيوت؛ لسارعت إلى المساجد لحبك للمساجد. فالمعذور -كالمريض والمقعد ونحو ذلك- إذا كان نيته الصلاة في المسجد، ويحب الصلاة في المسجد لولا العذر؛ هو مع المصلين في الأجر، وهكذا النساء اللاتي يحببن الصلاة في المساجد، لولا أن الله شرع لهن الصلاة في البيوت؛ هن مع المحافظين على الصلاة في المساجد في الأجر، وفي كونهن من السبعة الذين يظلهم الله في ظله؛ لأنهن يرغبن فيها، لولا أن الله شرع لهن الصلاة في البيت. ومن أدلة ذلك: قوله -عليه الصلاة والسلام- في الحديث الصحيح: إذا مرض العبد، أو سافر؛ كتب الله له ما كان يعمل وهو صحيح مقيم فأعطاه الله أجر الصائمين، وهو لم يصم؛ لأنه منعه المرض، والسفر، وقال أيضًا -عليه الصلاة والسلام- في غزوة تبوك: إن في المدينة أقوامًا ما سرتم مسيرًا، ولا قطعتم واديًا إلا وهم معكم وفي لفظ: إلا شركوكم في الأجر قالوا: وهم في المدينة؟ قال: وهم في المدينة؛ حبسهم العذر وفي اللفظ الآخر: المرض. هذا يدل على أن الممنوع شرعًا من فعل الشيء -وهو يحب أن يفعله لولا العذر - أنه مع العاملين، وله أجر العاملين، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15604/حصول-المراة-على-اجر-من-قلبه-معلق-بالمساجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_764/nour_76407.mp3","categories":["قضايا المرأة","المساجد ومواضع السجود"]},{"id":16883,"question":"مستمع من ليبيا بعث برسالة، وضمنها جمعًا من الأسئلة في أحدها يقول: هل يجوز أن نضع شريطًا للقرآن الكريم في إذاعة المسجد بصوت عالٍ؟","title":"ما حكم رفع صوت إذاعة المسجد بالقرآن؟","answer":"الجواب: لا، ليس لهم ذلك؛ لأن هذا يشوش على الناس، يمنعهم من القراءة، دعوا الناس هذا يقرأ، وهذا يقرأ، وهذا يسبح، والشريط الذي تضعونه للناس يشوش عليهم في مساجدهم، ويمنعهم من القراءة لأنفسهم، لكن لو اجتمع جماعة، أو مصلون محدودون، واستمعوا لشريط حتى يأتي الإمام، لا بأس إذا كان الجماعة محدودة، ورضوا بذلك، أما في المساجد العامة لا، أو جماعة غير محدودة لا، لكن لو كان المسجد ما فيه إلا خمسة... عشرة محدووين معروفون، ورضوا لأنفسهم أن يسمعوا شريطًا حتى يأتي الإمام؛ فلا بأس. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15642/ما-حكم-رفع-صوت-اذاعة-المسجد-بالقران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_825/nour_82507.mp3","categories":["المساجد ومواضع السجود"]},{"id":17159,"question":"نختم هذا اللقاء بهذا السؤال يا سماحة الشيخ، يقول السائل: ما حكم الأناشيد الإسلامية داخل المسجد، بحيث يكون هناك ترديد لها من مجموعةٍ من الشباب؟","title":"ما حكم ترديد الأناشيد في المساجد؟","answer":"الجواب: إذا كانت الأناشيد طيبة في حق، لكن لا تنشد على سبيلٍ يؤذي الناس، أو يشغل الناس، إذا أنشدوها فيما بينهم للفائدة فلا بأس. أما إنشادها بين الناس في المساجد، أو بين الصفوف هذا فيه تشويش على الناس، لكن إنشاد الشعر الطيب في محلٍ ليس فيه التشويش لا بأس، بينهم.. في بيوتهم.. في محلاتهم.. ليس فيه تشويش على أحد. نعم.","link":"https://binbaz.org.sa/fatwas/15976/ما-حكم-ترديد-الاناشيد-في-المساجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_589/58936.mp3","categories":["المساجد ومواضع السجود"]},{"id":17206,"question":"أيضًا يسأل سماحتكم شيخ: عبدالعزيز فيقول: يوجد لدينا مساجد، ونجد في بعض المساجد قبورًا من قبور الصالحين، أو الأولياء، ليس داخل المسجد، بل بالقرب منه، على ساحة واحدة، وحوش واحد، أفيدونا إن كان هذا صحيحًا؟ جزاكم الله خيرًا.","title":"حكم الصلاة في المساجد التي حولها قبور","answer":"الجواب: أما المساجد التي تبنى على القبور، فهذه لا يصلى فيها، أو يدفن فيها الموتى، لا يصلى فيها؛ لأن النبي ﷺ قال: لعن الله اليهود والنصارى اتخذوا قبور أنبيائهم مساجد وقال -عليه الصلاة والسلام-: ألا وإن من كان قبلكم كانوا يتخذون قبور أنبيائهم وصالحيهم مساجد، ألا فلا تتخذوا القبور مساجد، فإني أنهاكم عن ذلك فكل مسجد بني على قبر، أو على قبور تحرم الصلاة فيه، بل يجب هدمه، يجب على ولاة أمور المسلمين يجب عليهم هدمه وإزالته. أما إن وضعت فيه القبور.. المسجد قائم، ولكن وضعت فيه القبور؛ فإنها تنبش، وتنقل إلى محلات القبور، ولا يبقى في المساجد قبور أبدًا، هذا هو الحق، وهذا هو دين الله  الذي بعث به نبيه محمد ﷺ. أما إذا كانت خارج المسجد عن يمينه، أو شماله، أو خلفه، أو أمامه، وراء الحيطان فلا تضر، لكن إبعادها عن المساجد إذا تيسر يكون أحسن، وإلا فلا تضر، ما دامت خارج المسجد عن يمين، أو شمال، أو أمام، أو خلف، فقد خرجت جدران المسجد حوائط المسجد أخرجتها فلا تضر المساجد. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/16032/حكم-الصلاة-في-المساجد-التي-حولها-قبور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_723/nour_72302.mp3","categories":["المساجد ومواضع السجود"]},{"id":17207,"question":"من الدوحة قطر الأخت المستمعة (أ. غ. ع) رسالتها ضمنتها أربعة أسئلة، في أحد أسئلتها تقول: ما حكم ذهاب النساء إلى محل تصفيف الشعر، أو الكوافيرة -كما يسمونه- علمًا بأن هذه المحلات لا يدخلها غير النساء؟ جزاكم الله خيرًا.","title":"نصيحة لمن يردن الذهاب إلى محلات الكوافير","answer":"الجواب: نصيحتي أن لا يذهبن إلى ذلك، وأن تعطل هذه المحلات؛ لأنه يخشى فيها الشر والفتنة، ودعوى ....... عمل أشياء لا حاجة إليها، فالمرأة -والحمد لله- تستطيع تعلم نفسها في بيتها مع أمها، أو أخواتها، أو صديقاتها كل ما يحتاج إليه، ولا ينبغي التكلف .... الشعر معروف، وكذلك فتل العمائم معروف، ولا حاجة إلى هذه المحلات التي أحدثها الناس، فربما يكون فيها فتنة، أو شر، نعم، فينبغي تركها. المقدم: وهذا مؤكد سماحة الشيخ، جزاكم الله خيرًا.  الشيخ: هذا الذي بلغنا، بلغنا أنها لا خير فيها، وينبغي تركها. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/16033/نصيحة-لمن-يردن-الذهاب-الى-محلات-الكوافير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_723/nour_72303.mp3","categories":["اللباس والزينة","المساجد ومواضع السجود","قضايا المرأة","نصائح وتوجيهات"]},{"id":17240,"question":"عبدالله من الرياض، أخوكم في الله يقول: قرأت حديثًا؛ ما معناه بأن النبي ﷺ: \"نهى عن نقرةٍ كنقرة الغراب، وافتراش؛ كافتراش السبع، وأن يوطن الرجل المكان في المسجد، كما يوطن البعير\" السؤال يا سماحة الشيخ، يقول هذا السائل: عند دخولي المسجد لأداء الصلاة، أجلس دائمًا في مكانٍ خاص، ومعين في جميع الأوقات، فهل هذا الحديث المذكور يشملني، ويشمل تصرفي هذا؟","title":"حكم تخصيص مكان معين في المسجد للصلاة","answer":"الجواب: نعم، الأفضل لك أن تنتهي حيث انتهى الصف، ولا تجعل لك مكانًا معينًا، إذا جئت والصف الأول تام، تصف في الثاني، وإذا كان الصف الأول ما تم، تصف في الأول، ولا تبقى في طرف الصف، تصف من حين انتهى الصف، إذا كان خلف الإمام، خلف الإمام، في خلف الإمام أربعة صفوف، تكون أنت الخامس، متصلًا بهم، ستة تكون أنت السابع، وهكذا، هكذا، ولا تنقر صلاتك، اطمئن، عليك الطمأنينة، وعدم العجلة في الصلاة، عليك بالطمأنينة، ولا تفرش يديك مثل السبع، إذا سجدت؛ ارفع ذراعيك، اعتمد على كفيك فقط، والذراعان مرفوعان، كان السبع الذئب ونحوه يبسط ذراعيه، والكلب كذلك، والسنة للمؤمن أن يرفع ذراعيه، بل يعتمد على كفيه فقط، في السجود. المقدم: حفظكم الله سماحة يا الشيخ بالنسبة لتخصيص المكان؛ إذا كان هذا الرجل من المحافظين، الذين يبكرون للصلاة، يعني: استخدم هذا المكان يا شيخ؟ الشيخ: يجلس خلف الإمام، إذا بكر يجلس خلف الإمام، ولا يرح في طرف الصف، والصف باقي، أما إذا كان عاجزًا، مريضًا، يبي يتسند؛ لا بأس، يدور العمود لأجل يتسند عليه. نعم. المقدم: حفظكم الله.","link":"https://binbaz.org.sa/fatwas/16071/حكم-تخصيص-مكان-معين-في-المسجد-للصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_591/59117.mp3","categories":["المساجد ومواضع السجود"]},{"id":17289,"question":"من الجمهورية العربية السورية دمشق رسالة بعث بها أحد الإخوة رمز إلى اسمه بالحروف (ع. ي. ع) يقول: قال ﷺ: ألا إن من كان قبلكم كانوا يتخذون القبور مساجد، ألا فلا تتخذوا القبور مساجد، فإني أنهاكم عن ذلك وله أحاديث تنهى عن بناء المساجد على القبور، وإذا وجد القبر فعلينا التسوية، والمسجد النبوي أسأل الله أن يطعمني زيارته، ولكن من زار المسجد النبوي وجد أن قبر النبي ﷺ بارزًا، وغير مسوىً مع الأرض، ويصلى عليه أحيانًا، أنا أسأل مع السائلين: هل هناك رخصة لقبر النبي ﷺ فقط؟ وهذا غير وارد، أفتونا، جزاكم الله خيرًا.","title":"الرد على شبهة وجود قبر النبي ﷺ في المسجد","answer":"الجواب: النبي ﷺ دفن في بيته لئلا يفتن الناس به، الصحابة رأوا دفنه في البيت حتى لا يتخذ قبره مسجدًا، هذا هو الأفضل، لكن لما وسع أمير المؤمنين -في وقته الوليد بن عبد الملك في آخر المائة الأولى- مسجد النبي ﷺ أدخل الحجرة في المسجد، ومن ذاك الوقت دخلت في المسجد، وإلا فهو مدفون في بيته -عليه الصلاة والسلام- فلا حجة فيه لأحد من الناس؛ لأنه -عليه الصلاة والسلام- لم يدفن في المسجد، وإنما دفن في بيته فدخلت الحجرة برمتها. أما الناس فلا يجوز لهم أن يدفنوا في المساجد، الرسول ﷺ لعن من فعل ذلك، قال: لعن الله اليهود، والنصارى اتخذوا قبور أنبيائهم مساجد فلا يجوز الدفن في المساجد، ولا يجوز بناء المساجد على القبور، كل هذا منكر، وقد لعن النبي ﷺ من فعله. فالواجب الحذر من ذلك، أما قبر النبي ﷺ فلم يدفن في المسجد، بل في بيته، ولكن عند التوسعة أدخل في المسجد، وكان هذا من أخطاء الوليد، يعفو الله عنه. نعم.","link":"https://binbaz.org.sa/fatwas/16133/الرد-على-شبهة-وجود-قبر-النبي-ﷺ-في-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_723/nour_72322.mp3","categories":["مسائل متفرقة في العقيدة","المساجد ومواضع السجود"]},{"id":17419,"question":"في ثاني أسئلة هذا السائل يقول: في حارتنا ثلاثة مساجد قريبة من بعضها البعض، يبعد الواحد منها عن الآخر تقريبًا مائة وخمسين مترًا، علمًا بأن الحارة يكفيها مسجد واحد لجمع المصلين، فما نصيحتكم وما الواجب علينا في ذلك؟","title":"نصيحة لأصحاب المساجد المتقاربة","answer":"الجواب: عليكم مراجعة المحكمة، وتنظر في الأمر -إن شاء الله- عليكم مراجعة المحكمة لديكم حتى تنظر في الأمر، نعم.  المقدم: سماحة الشيخ! قرب المساجد بعضها من بعض هل من توجيه؟ الشيخ: لا ينبغي قرب بعضها من بعض، بل ينبغي أن تكون كل حارة لها مسجد يخصها إذا كانت متباعدة، أما إذا كانوا متقاربين فالأفضل كثرتهم في المسجد، وتعاونهم، وأن يكونوا كثيرين. لكن إذا كانت الحارات متباعدة كل حارة لها مسجد حتى لا يشق على أهلها، أما إذا كانوا متقاربين، ما بين كل مسجد مائة متر خطوة، أو مائتين، أو ما أشبه ذلك؛ ينبغي ترك ذلك، لكن قد يكون هناك أسباب إما شحناء، أو أسباب أخرى، ينظر فيها الحاكم، وينظر فيها ولي الأمر، نعم.  المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16295/نصيحة-لاصحاب-المساجد-المتقاربة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_771/nour_77120.mp3","categories":["المساجد ومواضع السجود"]},{"id":17491,"question":"يقول: يوجد لدينا في كل ليلة من يوم الخميس، ويوم الإثنين يذكر الله أهل الطرق الصوفية بالطبول إلى ساعات متأخرة من الليل، هل الذكر بالطبل جائز وهل الطرق الصوفية هذه جائزة أم لا؟ جزاكم الله خيرًا.","title":"حكم ذكر الله بالطبل، وحكم الطرق الصوفية","answer":"الجواب: هذه الطرق الصوفية بدعة ومنكرة سواء كان على الطبول أو الدفوف أو العود أو الموسيقى أو التصفيق بالأيدي أو الضرب بالأرجل أو الرقص، التقرب بهذا الأمر هذا من البدع، سواء في ليلة الخميس أو ليلة الإثنين أو في غيرهما في أي وقت، فالواجب على أهل الإسلام التقرب بالقرب التي شرعها الله، التسبيح والتهليل والتحميد والذكر والاستغفار على غير هذا الصنف بغير الطبول وبغير ضرب الأرجل وبغير الصياح والصفير، وبغير الموسيقى والعود وغيره.\nوقد بسط العلامة ابن القيم رحمه الله هذا البحث في كتابه إغاثة اللهفان بسطًا جيدًا، فأنا أنصح بمراجعة إغاثة اللهفان الذي بسط فيها الكلام، على الطرق الصوفية والتحذير منها وهذا منها.\nفالسنة للمؤمن أن يفعل ما فعله النبي ﷺ، إذا فرغ من الصلاة يذكر الله كما فعل النبي ﷺ إذا سلم يستغفر الله ثلاثًا، ويقول: اللهم أنت السلام ومنك السلام، تباركت يا ذا الجلال والإكرام، ثم ينصرف إلى الناس إذا كان إمامًا، ثم يقول: لا إله إلا الله وحده لا شريك له، له الملك وله الحمد وهو على كل شيء قدير، لا حول ولا قوة إلا بالله، لا إله إلا الله ولا نعبد إلا إياه، له النعمة وله الفضل وله الثناء الحسن، لا إله إلا الله مخلصين له الدين ولو كره الكافرون، اللهم لا مانع لما أعطيت ولا معطي لما منعت ولا ينفع ذا الجد منك الجد، كان يفعل هذا بعد كل صلاة عليه الصلاة والسلام، كما روى هذا ابن الزبير في صحيح مسلم، وروى بعضه المغيرة بن شعبة في الصحيحين بعد كل صلاة. والاستغفار ثلاثًا مع قوله: اللهم أنت السلام.. رواه مسلم في صحيحه عن ثوبان ، وروى بعضه مسلم عن عائشة في: اللهم أنت السلام .. ثم ينصرف الإمام إلى الناس هذه السنة.\nثم بعد هذا يقول: سبحان الله والحمد لله والله أكبر ثلاثًا وثلاثين، ويختم المائة بقوله:  لا إله إلا الله، وحده لا شريك له، له الملك وله الحمد وهو على كل شيء قدير، صح هذا عن النبي ﷺ أنه قال: من فعل هذا غفرت له خطاياه وإن كانت مثل زبد البحر، وهذا فضل عظيم، فيستحب للمؤمن بعد الصلوات الخمس أن يأتي بهذا. بعد الأذكار السابقة، تقول: سبحان الله، والحمد لله، والله أكبر ثلاثة وثلاثين مرة، الجميع تسعة وتسعون، ثم يقول تمام المائة: لا إله إلا الله وحده لا شريك له، له الملك وله الحمد وهو على كل شيء قدير، وإن شاء قال: يحيي ويميت بيده الخير وهو على كل شيء قدير، كله جاء. ثم يقرآ آية الكرسي: اللَّهُ لا إِلَهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ إلى آخرها ..إلى قوله: ..وَلا يَئُودُهُ حِفْظُهُمَا وَهُوَ الْعَلِيُّ الْعَظِيمُ [البقرة:255]، هذه الآية أعظم آية يستحب أن تقرأ بعد كل صلاة فريضة ثم يقرأ قل هو الله أحد والمعوذتين بعد كل فريضة، بعد الظهر والعصر والمغرب والعشاء والفجر أفضل، لكن يكررها ثلاثًا، هذه السور الثلاث يقرأها ثلاث مرات بعد المغرب، وبعد الفجر وعند النوم، جاءت بذلك السنة عن النبي عليه الصلاة والسلام .... وفق الله الجميع.\nالمقدم: اللهم آمين، جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/16398/حكم-ذكر-الله-بالطبل-وحكم-الطرق-الصوفية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_725/nour_72513.mp3","categories":["البدع والمحدثات","الفرق والمذاهب","المساجد ومواضع السجود"]},{"id":17544,"question":"من المستمع فتح الرحمن من الرياض رسالة يسأل في هذه الرسالة بعض الأسئلة فيقول: لنا صندوق خيري لصالح المسجد، ويوجد رجل مخصص لهذا الصندوق يدور به على صفوف المصلين قبل الصلاة وخاصة يوم الجمعة، فما حكم هذا العمل علمًا بأن بعض المصلين يجد شيئًا من الحرج؟","title":"حكم الطواف بصندوق التبرعات على المصلين","answer":"الجواب: هذا فيه نظر؛ لأن هذا معناه سؤال للمصلين وقد يحرجهم ويؤذيهم بذلك، فكونه يطوف عليهم ليسألهم حتى يضعوا شيئًا من المال في هذا الصندوق لمصالح المسجد، لو ترك هذا يكون أحسن، وإلا فالأمر فيه واسع، لو قال الإمام: إن المسجد في حاجة إلى مساعدتكم وتعاونكم فلا بأس بذلك؛ لأن هذا مشروع خيري، لكن كونه يطوف بالصندوق عليهم في صفوفهم قد يكون فيه بعض الأذى، بعض الإحراج، فالذي أرى أن تركه أولى، ويكفي أن يعلموا بهذا أن الصندوق هذا لمصالح المسجد ومن شاء وضع فيه ومن شاء ترك، ولا يطوف به عليهم ولا يؤذيهم بذلك، هذا هو الأحوط والأقرب إلى السلامة.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16469/حكم-الطواف-بصندوق-التبرعات-على-المصلين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_838/nour_83803.mp3","categories":["المساجد ومواضع السجود"]},{"id":17622,"question":"يقول أيضًا في سؤال آخر: يوجد عندنا مسجد وبه جزء للنساء يفصله عن مسجد الرجال حائط وعند النساء سماعة من الميكرفون لسماع الإمام والمدرس، قام رجل وأراد هدم الحائط وترك النساء أمام الرجال، ودليله في ذلك حديث النبي ﷺ: تصف الرجال، ثم الصبيان، ثم النساء وحدث في ذلك خلاف شديد، فما هو توجيهكم جزاكم الله خيرًا.","title":"حكم الحاجز بين صفوف الرجال والنساء في المسجد","answer":"الجواب: كل ذلك لا حرج فيه، كان النساء في عهد النبي ﷺ يصلين مع الرجال خلف الرجال من دون حائط ومن دون شيء، يتسترن ويتحجبن ويصلين مع الرجال في المؤخر، كما في الحديث الصحيح يقول ﷺ: خير صفوف الرجال أولها وشرها آخرها، وخير صفوف النساء آخرها وشرها أولها لأن أولها قد يقرب من الرجال، فإذا صففن في أسفل المسجد خلف الرجال وتسترن فلا حرج، ولا حاجة إلى جدار ولا غيره، وإن جعل جدار أو ستار غير الجدار حتى يأخذن راحتهن ويكشفن وجوههن ويسترحن فلا بأس بذلك حتى يسترحن في مصلاهن ويسمعن من طريق المكبر أو من طريق صوت الإمام إذا كان يسمعن بدون مكبر، لا حرج في ذلك، الأمر في هذا واسع والحمد لله، وإن جعل شبك يرين منه الإمام والمأمومين ويسمعن الصوت فلا بأس أيضاً، الأمر كله واسع، لا ينبغي في هذا التشديد، الجدار أو الشبك أو الستارة أو بدون ذلك، كله جائز والحمد لله، وقد كن في عهد النبي ﷺ ليس هناك جدار ولا غيره، يتسترن ويصلين مع الناس خلف الرجال والحمد لله، فإذا جعل جدار أو شبك يسترهن أو ستارة حتى يسترحن يضعن عبيهن ويكشفن وجوههن ويسترحن فيه لا يراهن الرجال كان في هذا مصلحة لهن وراحة لهن فقط ولا حرج في ذلك والحمد لله.\nالمقدم: جزاكم الله خيرًا! لكن يرى سماحة الشيخ أن الزمان كالزمان في عهد الرسول عليه أفضل الصلاة والسلام وأنه لا مانع أن يرى الرجال النساء في المسجد؟\nالشيخ: لابد من هذا، إذا كن لا يتسترن لابد من مانع، إذا كن من طبيعتهن في بعض البلدان لا يتسترن لابد من وضع المانع، جدار أو ستارة، أما إذا كن يعتنين مثلما كان في عهد النبي ﷺ يعتنين بالحجاب ويتسترن فلا حاجة إلى الحجاب، يصلين خلف الرجال صفوفهن خلف الرجال، وخير صفوفهن آخرها وشرها أولها، لكن إذا كن لهن عادة في التساهل وكشف الوجوه فوجود حجاب يسترهن هذا هو الواجب حتى لا يفتن ولا يفتن. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16554/حكم-الحاجز-بين-صفوف-الرجال-والنساء-في-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_843/nour_84307.mp3","categories":["قضايا المرأة","المساجد ومواضع السجود"]},{"id":17642,"question":"الأخت: (ف. ع) من مدينة حائل، تسأل سماحتكم، وتقول: هل يجوز أن نصلي ركعتين تحيةً للمسجد، ونحن نذهب لصلاة العيد في مسجد العيد؟ أم أنا لا نصلي ركعتين في صلاة العيد؟ جزاكم الله خيرًا.","title":"مصلى العيد ليس له تحية","answer":"الجواب: مصلى العيد ليس له تحية، ليس له حكم المساجد، ليس له تحية المسجد، بل يجلس الإنسان، ولأنه وقت نهي، والمصلى ليس مسجدًا، أما إذا كانت الصلاة في مسجد عادي، معتاد، إذا صلوا العيد في المساجد، شرعت تحية المسجد، ولو في وقت النهي على الصحيح، لعموم قوله ﷺ: إذا دخل أحدكم المسجد فلا يجلس حتى يصلي ركعتين ولما رأى رجلًا جلس في بعض الأيام، قال له: قم فصل ركعتين عليه الصلاة والسلام.\nأما مصلى العيد الذي في الصحراء؛ فهذا ليس له حكم المسجد، فإذا أتى الإنسان والشمس لم تطلع جلس. نعم. النبي عليه السلام ما كان يصلي قبلها ولا بعدها صلاة العيد.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16566/مصلى-العيد-ليس-له-تحية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_726/nour_72609.mp3","categories":["صلاة العيدين","المساجد ومواضع السجود"]},{"id":17687,"question":"هل يجوز للحائض أن تدخل الحرم؟","title":"حكم دخول الحائض الحرم","answer":"الجواب: مرور، أما الجلوس لا، المرور في المسجد أو في الحرم مرور لا بأس.\nالمقدم: أحسن الله إليكم وبارك فيكم.","link":"https://binbaz.org.sa/fatwas/16627/حكم-دخول-الحاىض-الحرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_595/59516.mp3","categories":["المساجد ومواضع السجود","الحيض والنفاس","قضايا المرأة"]},{"id":17757,"question":"تقول السائلة في هذا  نعيش في بلدة نائية بها مسجد لا يصلي به أحد..الشيخ: أيش؟المقدم: تقول السائلة: نعيش في بلدة نائية بها مسجد لا يصلي به أحد إلا المارة ليس لهذا المسجد مؤذن؛ لأنه مسجد خاص بناه أحد الناس، لا تصلى فيه التراويح في رمضان ويذهب أحيانًا زوجي يؤذن ويقيم ويصلي وحده وقد نصحنا بعض الإخوان بالصلاة فيه ولكن دون فائدة، هل يستمر زوجي في الصلاة فيه لوحده أم ماذا علينا؟ وهل يجب أن يصلي في المنزل بمفرده؟","title":"حكم إقامة الصلاة بمسجد لا يغشاه الناس إلا نادرًا","answer":"الجواب: هذا الذي عمله زوج السائلة عمل طيب، وهو مشكور عليه، ونوصيه بالاستمرار بأن يذهب إلى المسجد، ويؤذن؛ لعل الله يأتي بمن يصلي معه من المارة، أو من السكان، وإن لم يأت صلى وحده، والحمد لله، نوصيه بأن يستمر، وأن لا يصلي في البيت؛ لأن المساجد عمرت لهذا، وعلى المؤمن أن يذهب إلى المسجد فإن وجد أحدًا وإلا صلى وحده والحمد لله، لا يجوز الصلاة في البيت والمساجد موجودة، وكونه قد لا يصلي مع أحد لا يضره ذلك، يكون له الأجر العظيم، فليؤذن وله فضل الأذان، يقول النبي ﷺ: لا يسمع صوت المؤذن جن ولا إنس، ولا شجر ولا حجر، ولا شيء؛ إلا شهد له يوم القيامة فضل عظيم، ثم هو بهذا يدعو الناس إلى إقامة صلاة الجماعة يكون له مثل أجورهم؛ لأنه دعاهم إلى الخير فيكون له مثل أجور من صلى معه: من دل على خير فله مثل أجر فاعله فنوصي زوجك بالاستمرار، والعمل الطيب، والذهاب إلى المسجد، وأن هذا هو الواجب عليه وإن تخلف عنه الجيران أو غيرهم. نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/16730/حكم-اقامة-الصلاة-بمسجد-لا-يغشاه-الناس-الا-نادرا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_777/nour_77712.mp3","categories":["الأذان والإقامة","المساجد ومواضع السجود"]},{"id":17827,"question":"مصري ومقيم بالمملكة يقول يا سماحة الشيخ: ما حكم الصلاة في المسجد الذي ليس فيه قبر، ولكنه بني على قبر، هل تصح الصلاة؟ أم أن ذلك باطلة؟","title":"حكم الصلاة في المساجد التي بنيت على القبور","answer":"الجواب: كل المساجد التي تبنى على القبور لا يصلى فيها، الصلاة فيها باطلة، إذا كان القبر موجودًا في المسجد، سواءً المسجد كان هو الأول أو القبر هو الأول، لكن إذا كان المسجد هو الأول ينبش القبر؛ ينقل إلى القبور، أما إذا كان المسجد هو الأخير بني على القبر؛ يهدم المسجد، ولا يبنى على القبور، يقول ﷺ: لعن الله اليهود والنصارى اتخذوا قبور أنبيائهم مساجد، ويقول ﷺ: ألا وإن من كان قبلكم كانوا يتخذون قبور أنبيائهم وصالحيهم مساجد، ألا فلا تتخذوا القبور مساجد فإني أنهاكم عن ذلك، ونهى ﷺ عن تجصيص القبر، وأن يقعد عليه وأن يبنى عليه.\nالمقدم: حفظكم الله سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16817/حكم-الصلاة-في-المساجد-التي-بنيت-على-القبور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_597/59724.mp3","categories":["المساجد ومواضع السجود"]},{"id":17849,"question":"تسأل أختنا فتقول: هل يجوز للمرأة أن تصلي عند صورةٍ في كتابٍ، أو صحيفة؟ وإذا طمستها بوضع شيء ما عليها، أو أغلقت الكتاب الذي يحتوي على بعض الصور، فهل تقبل الصلاة حينئذ؟ وهل يقبل الاستغفار والتسبيح؟ جزاكم الله خيرًا.","title":"حكم الصلاة في المكان الذي فيه صور","answer":"الجواب: نعم؛ الصلاة في المحل الذي فيه صورة، أو في كتاب الذي فيه صورة، أو بساط فيه صورة، أو وسادة فيها صورة، لا يضر، الصلاة صحيحة، ولا يضر ذلك، لكن إن كانت الصورة معلقة، وجب إزالتها، أما إن كانت الصورة مما يمتهن في الوسادة والبساط فإنها لا تؤثر، ولا حرج في ذلك، وإنما يمنع المعلق الذي يمنع دخول الملائكة، ولا يجوز تعليق الصور، وما كان في الكتاب فهو كالمطموس؛ لأنه يبسط عليه الكتاب، ويغلق عليه الكتاب، فلا يبين، وإذا أزال المؤمن صورة الرأس، زال المحظور بالكلية، إذا قطع الرأس بالحبر حتى زال كله، وطمس كله، أو من الصورة المجسمة قطع وأزيل بالكلية؛ فلا بأس، كما ثبت عن النبي ﷺ أنه أمر بقطع رأس التمثال، حتى يكون المصور كالشجرة بلا رأس. نعم.\nالمقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/16842/حكم-الصلاة-في-المكان-الذي-فيه-صور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_728/nour_72803.mp3","categories":["قضايا المرأة","المساجد ومواضع السجود"]},{"id":17879,"question":"إذا جاء مصحف هدية لأحد الأشخاص أو وزع على المدارس أو غيرها، وكان عليه كلمة وقف لله، ولكن لم يأخذ من المسجد، هل في ذلك شيء؟","title":"حكم توزيع المصاحف الموقوفة","answer":"الجواب: لا. ما فيه بأس، للقراءة، توزيعه للقراءة فيه، لكن لا يباع، ما دام كتب عليه وقف لا يباع. نعم.","link":"https://binbaz.org.sa/fatwas/16885/حكم-توزيع-المصاحف-الموقوفة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_598/59810.mp3","categories":["القرآن وعلومه","المساجد ومواضع السجود","الوقف"]},{"id":18054,"question":"إذا دخل الإنسان المسجد، هل يسلم؟","title":"حكم السلام عند دخول المسجد","answer":"الجواب: يسلم على أهل المسجد، إذا كان فيه أحد، يسلم عليهم، قبل أن يشرع في الصلاة، يسلم ثم يشرع في تحية المسجد، أو في الراتبة، إن كان في الظهر، أو الفجر، راتبتها قبلها وبعدها، راتبتها قبل الظهر، والفجر راتبتها قبلها، أما الظهر لها راتبة قبلها، وبعدها، فهو يبدأ بالسلام، ثم يشرع في النافلة، أو في الفريضة إن كان فريضة. نعم. المقدم: إذا كان من في المسجد مشغولون مثلًا، أو مشغولين؟ الشيخ: ولو أنهم يصلون، يسلم عليهم ولو أنهم يصلون، وهم يردون بالإشارة، أو يقرؤون، يسلم، ويردون عليه، يقف عن القراءة، ويرد، كونه يقرأ، يمسك عن القراءة، ويقول: وعليكم السلام، ثم يعود للقراءة. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17087/حكم-السلام-عند-دخول-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_729/nour_72912.mp3","categories":["المساجد ومواضع السجود"]},{"id":18075,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين يقول: أخوكم محاسب جلال الدين عبد العال مصري ويعمل في جدة، أخونا له ثلاثة أسئلة، في سؤاله الأول يقول: هل أخذ مصحف شريف من أحد المساجد للقراءة فيه دون علم أحد بالمسجد يعتبر سرقة؟ وكيف التكفير عن ذلك إذا كانت سرقة؟","title":"حكم أخذ المصحف من المسجد إلى البيت","answer":"الجواب: لا يجوز لأحد أن يأخذ من المسجد ما وضع فيه من المصاحف إلى بيته أو إلى بلده، بل يجب أن يبقى في المسجد؛ لأن الذي وضعه في المسجد أراد به نفع المسلمين الذين يأتون المسجد فيقرأ فيه مادام في المسجد، ثم يضعه في المسجد ولا يخرج به خارج المسجد، إلا إذا وضع في مكان معروف للتوزيع وجاء به أصحابه للتوزيع وبينوا للمؤذن أو الإمام أن هذا للتوزيع فهذا شيء آخر. أما ما يوضع في الدواليب في المسجد أو في الرفوف في المسجد لينتفع بذلك زوار المسجد والمصلون في المسجد، فليس لأحد أن يأخذه من المسجد؛ لأن الواقف إنما أراد به البقاء في المسجد، فمن أخذ شيئًا من هذا فالواجب عليه أن يعيده وإن كان تلف أو ضيعه فعليه إبداله بمثله أن يشتري مثله ويضعه في المسجد بدلًا مما أخذ من المسجد مع التوبة والاستغفار. نعم. المقدم: جزاكم الله خيرًا. نصيحتكم سماحة الشيخ للقائمين على أمر المساجد كالمؤذنين والخدم هل يسمحون لأحد باستعارة مصحف من المسجد ثم يعيدوه أو ما أشبه ذلك؟ الشيخ: ليس لهم لا، ليس للإمام ولا للمؤذن أن يعيروا في ذلك، إلا إذا كان الذي جعله في المسجد سمح لهما بهذا، أما إذا كان وضعه في المسجد ولم يسمح لهما بهذا فليس لهما أن يعيرا أحدًا. نعم. المقدم: جزاكم الله خيرًا. الكفارة أخونا يسأل عنها؟ الجواب: ليس عليه كفارة إلا التوبة والاستغفار، وأن يعيد المصحف كما أخذه أو يعيد بديلًا منه إن كان ضاع عليه أو تلف. المقدم: أحسنت، وهذا كفارته؟ الشيخ: هذا كفارته، نعم، مع التوبة. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17110/حكم-اخذ-المصحف-من-المسجد-الى-البيت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_903/nour_90302.mp3","categories":["المساجد ومواضع السجود","الوقف","القرآن وعلومه"]},{"id":18085,"question":"يوجد عندنا مسجد، وبخارجه قبور، وهو المسجد الوحيد في القرية، وقد توقفت عن الصلاة في هذا المسجد، من أجل هذه الأضرحة التي بخارجه، أفيدوني هل أنا على صواب؟","title":"حكم الصلاة في المسجد الذي خارجه قبور","answer":"الجواب: إذا كانت في خارج المسجد؛ فلا حرج في الصلاة فيه، إذا كانت خارج المسجد، ولست على صواب، بل صل في المسجد. أما إذا كانت في داخله، فلا يصلى فيه؛ لأن الرسول ﷺ قال: لعن الله اليهود والنصارى، اتخذوا قبور أنبيائهم مساجد، فالرسول حذر من اتخاذ القبور مساجد، لا يصلى عندها، وكل مسجد فيه قبور، لا يصلى فيه، ويجب نبش القبور، إذا كانت موضوعةً فيه، وهو السابق، فإنها تنبش وتنقل إلى المقبرة، أما إذا كان بني عليها هو، هي السابقة، ولكن بني عليها المسجد؛ فإنه يهدم، ولا يجوز بقاؤه؛ لأن الرسول لعن من فعل ذلك عليه الصلاة والسلام. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/17120/حكم-الصلاة-في-المسجد-الذي-خارجه-قبور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_730/nour_73009.mp3","categories":["المساجد ومواضع السجود"]},{"id":18192,"question":"سماحة الشيخ السائلة تقول: مسجد فيه قبر، وحضرت الفريضة فهل أصلي فيه مع العلم بأنه لا يوجد أي مسجد آخر ليس فيه قبر في المنطقة التي أعمل بها؟ أين أصلي؟","title":"لا يوجد في المنطقة إلا مسجد فيه قبر هل أصلي فيه؟","answer":"الجواب: لا يجوز لك الصلاة في المسجد الذي فيه قبور، الرسول لعن اليهود والنصارى الذين اتخذوا قبورهم مساجد قال: لعن الله اليهود والنصارى اتخذوا قبور أنبيائهم مساجد ولما قيل له: إن بعض المشركين يتخذ الصور ويبني على القبور أخبر أن هؤلاء أشرار الخلق، وأنهم يعني: النصارى إذا مات فيهم الرجل الصالح بنوا على قبره مسجدًا، وصوروه في تلك الصور قال: أولئك شرار الخلق عند الله. فالمسجد الذي فيه قبر أو قبور لا يصلى فيه، لا نافلة، ولا فريضة، وإذا لم تجد مسجدًا صل في بيتك أو في بيت إخوانك أنت وإياهم تجتمعون، أو تعمرون مسجدًا جديدًا ليس فيه قبور حتى تصلوا فيه. وإذا أمكنكم إزالة القبر من المسجد إذا كان القبر حديث، والمسجد سابق، تسعون في إزالة القبر من المسجد، وتصلون فيه، إذا كان القبر هو الجديد، والمسجد قديم، فالمسجد في هذا القبر يزال، ينبش ويزال ويصلى في المسجد إذا استطعتم أن تفعلوا ذلك مع أهل البلد. المقصود أن المسجد الذي فيه قبور لا يصلى فيه، وإذا لم يجد المؤمن مسجدًا سليمًا صلى في بيته، أو في أي مكان ليس فيه قبور. نعم. المقدم: أثابكم الله، وأحسن إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17261/لا-يوجد-في-المنطقة-الا-مسجد-فيه-قبر-هل-اصلي-فيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_782/nour_78207.mp3","categories":["المساجد ومواضع السجود"]},{"id":18215,"question":"إذا كان هناك مسجدان قريبين من بعضهما، والبعض يشوش على البعض الآخر، فما هو توجيه سماحة الشيخ في هذا الموضوع، إذ لا يبعد المسجد عن أخيه، إلا بما يقرب من خمسين مترًا؟","title":"توجيه حول التشويش بين المساجد المتقاربة","answer":"الجواب: الواجب العناية بعدم التشويش، كل واحد يخفض الصوت -صوت المكبر- حتى لا يشوش أحدهما على الآخر، يسمعون من الداخل، ولا يكون فيه سماع من الخارج، يشوش، يكون خفيف من الخارج، حتى لا يشوش هذا على هذا، ولا هذا على هذا. وفي الحقيقة أن هذا القرب غريب، لماذا صار هذا القرب، الواجب أن تكون المساجد متباعدة، بحسب الحاجة، لا تكون متقاربة، يبنى في الحي مسجد، حتى يصلي فيه هذا الحي، أما التقارب هذا لا وجه له، فلعل هذا التقارب له أسباب شرعية ما نعلمها. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/17258/توجيه-حول-التشويش-بين-المساجد-المتقاربة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_731/nour_73120.mp3","categories":["المساجد ومواضع السجود"]},{"id":18264,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين يقول: حسين إسماعيل العيدروس من اليمن الديمقراطية -حضرموت- تاربة، أخونا له مجموعة من الأسئلة، يسأل في سؤاله الأول ويقول:هل التوابيت والقبور والأضرحة للأموات حرام، وإذا كانت في مسجد، فماذا نعمل أنفصلها؟ أم نتركها ملتحمة بالمسجد؟ وجهونا جزاكم الله خيرًا.","title":"حكم التوابيت والأضرحة للموتى في المساجد","answer":"الجواب: السنة الدفن في الأرض لا في تابوت، ولا في غيره من الصناديق، ولا يجصص القبر ولا يزفلت، ولا يوضع فيه شيء آخر من الحديد أو الألواح أو غير ذلك، السنة أن يدفن الميت في الأرض كما دفن ﷺ في الأرض ودفن الصحابة في الأرض، وهكذا غيرهم، يحفر لهم في الأرض ويلحد له، ويجعل في الأرض: مِنْهَا خَلَقْنَاكُمْ وَفِيهَا نُعِيدُكُمْ [طه:55]، لكن إذا كانت الأرض رخوة مائية ضعيفة فلا مانع من جعله في تابوت، أو جعل ألواح تحته حتى تمسكه لا تنهار الأرض به، أو حجارة.. أو نحو ذلك لا بأس بذلك عند الحاجة، أما إن كانت الأرض قوية فلا حاجة إلى شيء من ذلك. أما الدفن في المسجد فلا يجوز، يجب أن تكون القبور خارج المسجد؛ لأن دفن القبور في المساجد وسيلة إلى عبادة الأموات من دون الله ، والنبي ﷺ قال: لعن الله اليهود و النصارى اتخذوا قبور أنبيائهم مساجد متفق على صحته، وقال عليه الصلاة والسلام: ألا وإن من كان قبلكم، كانوا يتخذون قبور أنبيائهم وصالحيهم مساجد، ألا فلا تتخذوا القبور مساجد فإني أنهاكم عن ذلك رواه مسلم في الصحيح، عن جندب بن عبد الله البجلي . هذا يدل على أنه لا يجوز اتخاذ القبور مساجد يصلى فيها، وإذا كان الأمر هكذا لم يجز أيضًا الدفن فيها؛ لأن الدفن فيها يجعل القبور مساجد. وإذا وجد في المسجد قبر وجب أن ينبش وتنقل رفاته إلى المقبرة، أما إن كان القبر هو القديم، وبني عليه مسجد وجب هدم المسجد، وأن لا يصلى فيه وأن لا يبقى، بل يهدم؛ لأنه بني على معصية الله، فلا يبقى بل تجب إزالته، ولا ينبغي أن يغتر بما وقع في بعض البلدان الإسلامية من البناء على القبور واتخاذ المساجد عليها فإن هذا منكر، وإن فعله كثير من الناس فهو منكر تجب إزالته على ولاة الأمور، يجب على ولاة أمر المسلمين أن يزيلوا هذا المنكر، وأن لا يبنوا على القبور وأن لا يتخذوا عليها المساجد؛ لأن الرسول نهى عن هذا عليه الصلاة والسلام، وكذلك لا تجصص، ولا يبنى عليها قبة، ولا أي بناء، لما ثبت عن رسول الله عليه الصلاة والسلام من حديث جابر أنه: «نهى عن تجصيص القبور والقعود عليها والبناء عليها»، رواه مسلم في الصحيح. فالقبر لا يبنى عليه، لا قبة ولا غيرها ولا يجصص ولا يتخذ عليه قبة ولا مسجدًا، كل هذا منكر، وإن فعله بعض الناس كما قد يوجد في مصر والشام والعراق وغير ذلك، كله غلط. نسأل الله أن يوفق ولاة الأمور في كل مكان لإزالة هذه المساجد، وإبقاء القبور على الطريقة المحمدية التي درج عليها رسول الله عليه الصلاة والسلام في مقابر مكشوفة لا يبنى عليها، لا مساجد ولا غيرها، ولا تجصص ولا تعظم بفعل بأي شيء، بل الواجب أن يدفن الموتى في الأرض كما كان الرسول يفعل عليه الصلاة والسلام في المدينة، وكما فعله المسلمون بعده، والبناء عليها واتخاذ القباب وسيلة إلى عبادتها من دون الله، وسؤالها والاستغاثة بها والنذر لها، والذبح لها، وهذا هو الشرك الأكبر، كما قد وقع، وقد يطاف بالقبور إذا وضعت في المساجد كما قد يفعل ذلك كثير من الناس في قبور معروفة. وبسبب هذا الغلو وقع الشرك في الناس لما بني على القبور وعظمت ظن العامة أنها تدعى من دون الله وأنه يستغاث بها وأنه يطاف بها ففعلوا، فوقع الشرك الأكبر، والعياذ بالله. نسأل الله للجميع العافية والهداية. نعم.","link":"https://binbaz.org.sa/fatwas/17313/حكم-التوابيت-والاضرحة-للموتى-في-المساجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_909/nour_90905.mp3","categories":["حمل الميت ودفنه","المساجد ومواضع السجود"]},{"id":18387,"question":"هذا يمني مقيم بالرياض، يقول: يوجد عندنا مسجد صغير، وهو قديم، وهو مبني على كتلة صغيرة، وفي مكان مهم بالنسبة للقرية، وبعد المسجد مباشرة وباتجاه القبلة توجد مقبرة مسورة بطول ثمانية متر وعرض أربعة متر، هل الصلاة سماحة الشيخ في هذا المسجد جائزة؟ أو من الأفضل أن نغير هذا المكان؟","title":"حكم الصلاة في المسجد الذي بجواره مقبرة","answer":"الجواب: لا حرج الصلاة فيه جائزة، ما دام المقبرة خارج المسجد، وبينها وبينه حاجز سور بينها وبينه، والمسجد له سور خارج المقبرة فلا حرج، المقصود المسجد الذي قدامه المقبرة محجوزة ومسورة لا يضر، والحمد لله. إنما الذي لا يجوز أن تكون القبور في المسجد، هذا هو المنكر، أما كونها مقبرة خارجية والمسجد محجوز عنها فلا يضر ذلك. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/17466/حكم-الصلاة-في-المسجد-الذي-بجواره-مقبرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_784/nour_78409.mp3","categories":["المساجد ومواضع السجود"]},{"id":18449,"question":"الرسالة التالية رسالة وصلت إلى البرنامج من المستمع عبد الله بطي المطيري، أخونا له مجموعة من الأسئلة، في سؤاله الأول يقول: نحن في قرية نصلي في المسجد الجامع بالقرية، وبعد أن نختم الصلاة بالتسبيح والتحميد والتكبير، وفي بعض الأوقات يدعو أحد المصلين الذين يصلون بالمسجد لشرب القهوة في داره، وهذه الدعوة داخل المسجد، فهل تصح داخل المسجد أو أنها مكروهة؟ أفيدونا جزاكم الله خيرًا.","title":"حكم الدعاء إلى الوليمة في المسجد","answer":"الجواب: لا حرج في ذلك، لا حرج أن يدعو إلى القهوة، أو إلى وليمة غداء أو عشاء لا بأس بذلك، وليس هذا من جنس الدعوة إلى البيع والشراء والبيع والشراء، بل هذا معروف وخير وإحسان. نعم.","link":"https://binbaz.org.sa/fatwas/17551/حكم-الدعاء-الى-الوليمة-في-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_865/nour_86511.mp3","categories":["المساجد ومواضع السجود"]},{"id":18563,"question":"أخونا يقول: عندنا مسجد وحيد في القرية التي أسكنها، ولكن بجواره من جهة القبلة ضريح، ويفصل بينهما حائط، ولا يوجد باب بين الضريح والمسجد، فهل الصلاة في هذا المسجد جائزة أو لا؟","title":"حكم الصلاة في مسجد أمامه قبر يفصله عنه جدار","answer":"الجواب: نعم، إذا كان المسجد ليس في المقبرة، ولم يبن على المقبرة، ولا على قبور، فالصلاة فيه صحيحة، إذا كان مفصول عن القبور، محجوزًا بينهما بالجدار، أما إذا كانت القبور أمام المصلي فلا؛ لقول النبي ﷺ: لا تصلوا إلى القبور، ولا تجلسوا عليها. والواجب أن يكون مفصولًا بينهما بجدار حتى لا يصلى إليها، وإذا كان مبني على طرف البناء لتعظيم القبور وجب هدمه، أما إذا كان مبني في أرض سليمة ليس فيها قبور، أو كانت القبور حادثة قدامه فلا يضر، نعم. ولكن ينبغي للمؤمن أن يبتعد عن أسباب الفتنة مهما أمكن، فإذا كان يخشى أن يظن ظان أن هذا المسجد من أجل القبور يجعله في محل آخر بعيد عن أسباب الفتنة؛ لأن بعض الناس عنده جهل كثير فربما ظن أن المسجد بني من أجل القبور التي حوله، فينبغي في هذا للمؤمن وأهل الخير أن يحتاطوا، وأن تكون المساجد بعيدة عن القبور حتى لا يظن ظان أنها بنيت لأجل القبور. المقدم: جزاكم الله خيرًا، ونفع بعلمكم.","link":"https://binbaz.org.sa/fatwas/17676/حكم-الصلاة-في-مسجد-امامه-قبر-يفصله-عنه-جدار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_917/nour_91705.mp3","categories":["المساجد ومواضع السجود"]},{"id":18689,"question":"يوجد في منطقتنا مسجدان، أحدهما قريب علينا، والآخر بعيد، ولكننا غالبًا ما ننصب إلى البعيد؛ وذلك لأن خطيبه يجيد الخطبة بدون استعمال ورقة مع بلاغته. أما في المسجد القريب لنا فإن خطيبه يستعمل في خطبته الورقة، مما جعل أغلب الناس يتجهون إلى ذلك المسجد البعيد، ويتركون هذا المسجد، فهل هذا جائز؟وجهونا إلى الخير والرشاد، بارك الله فيكم.","title":"جواز ترك المسجد القريب والصلاة في البعيد","answer":"الجواب: المؤمن يلتمس ما هو الأنفع له، وما هو أكثر أثرًا في قلبه، فإذا كانت الصلاة مع البعيد تؤثر في القلب أكثر، وينتفع بها أكثر لحسن أسلوب خطابته، ولعنايته بالخطبة، واهتمامه بها، فهذا أولى، سواء كان يخطب من ورقة، أو عن ظهر قلب. ولا عيب على الخطيب من الورقة؛ لأنها قد تكون أضبط لخطبته، وأثبت له، فإذا كان يخطب من ورقة، ولكنه يحسن الخطبة ويجيدها، ويعتني بما يكتب في الورقة هذا طيب، ولا لوم عليه، ولا عيب عليه في هذا، وبعض الناس الذين يخطبون من دون ورقة قد يغلطون كثيرًا، وقد يرددون الكلام على غير فائدة. فأنت -يا أخي- عليك أن تستعمل ما هو أصلح لقلبك، وما هو أنفع لك، فالمسجد البعيد فيه زيادة الخطى، وقد قال -عليه الصلاة والسلام-: أعظم الناس في الصلاة أجرًا أبعدهم فأبعدهم ممشى. وإذا كانت خطبته أنفع لقلبك، وأشد أثرًا فيه، فلا مانع من الذهاب إليه، أما كونها من ورقة أو من غير ورقة، فهذا لا ينبغي أن يكون له أثر، فالخطبة من الورقة ومن غير الورقة كله جائزة، والحمد لله، والخطيب ينظر ما هو أصلح إن كانت خطبته من ورقة أنفع وأصلح وأثبت لقلبه، وأعون له على الأداء الحسن فليخطب من الورقة، وإن كانت خطبته عن ظهر قلب أنفع وأصلح وأشد أثرًا في الناس فليفعل هذا، هو أعلم بنفسه وأعلم بما يطيق، نعم. المقدم: جزاكم الله خيرًا، إذًا: يجب ألا يؤثر هذا في الناس شيخ عبد العزيز ؟ الشيخ: نعم، لا ينبغي هذا، لا ينبغي أن يؤثر، بل ينبغي للمؤمن أن يتحرى ما هو الأصلح في سماع الخطبة، وفي الذهاب إلى المسجد الذي يصلي فيه، وينبغي للخطيب أيضًا أن يتحرى ما هو الأصلح، إن كان الأصلح له أن يخطب عن ظهر قلب فعل، وإن كان الأصلح له أن يخطب من ورقة فعل. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17793/جواز-ترك-المسجد-القريب-والصلاة-في-البعيد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_920/nour_92005.mp3","categories":["المساجد ومواضع السجود"]},{"id":18813,"question":"لا زالت الأسئلة لأخينا من ليبيا يقول: يوجد عندنا مسجد بجانبه قبران خارج المسجد، أحدهما يوجد داخل حجرة مبنية له، بحجة أنه ولي صالح، ويوجد بداخل الحجرة صندوق مخصص للتبرعات، يضع فيه الزوار النقود، وتنفق هذه النقود فيما ينقص المسجد.  ما الحكم في إنفاق هذه النقود؟ وما الحكم بالنسبة للصلاة فيه؟ وبماذا تنصحوننا؟أفتونا، أثابكم الله.","title":"حكم وضع صندوق تبرعات للمسجد عند قبر مجاور","answer":"الجواب: إذا كان القبر خارج المسجد؛ فلا حرج في الصلاة في المسجد؛ لأنه مستقل حينئذٍ، الرسول ﷺ نهى عن اتخاذ المساجد على القبور، قال: لعن الله اليهود والنصارى، اتخذوا قبور أنبيائهم مساجد فإذا كان القبر خارج ذلك، في حجرة خارج المسجد فلا حرج، لكن هذا القبر يجب أن يبعد إلى مقابر المسلمين حتى لا يغلى فيه، حتى لا يعبد من دون الله، وهذا الصندوق يجب أن يزال؛ لأن الجهلة يسلمون الأموال تقربًا إلى الميت، إلى صاحب القبر؛ لأنه بزعمهم ولي، فكونهم يتقربون إليه بالنذور والصدقات، هذا شرك أكبر لا يجوز. فالواجب على المسئولين في البلد أن يتصلوا بالعلماء، وأن يزيلوا هذا القبر، ويزيلوا رفاته إلى مقابر المسلمين مع المقابر، وتزال هذه الحجرة التي قد يفتن بها الناس، ويزال الصندوق، وهذه الأموال التي في الصندوق تصرف في مصالح المسلمين، في مصالح المسجد، أو مصالح المدارس، أو يعطاها الفقراء، ونحو ذلك؛ لأنها أموال ضائعة ليست لها مالك في الحقيقة، فتصرف في المصالح العامة، ويزال هذا الصندوق. ويخبر الناس أنه لا يجوز التقرب لأهل القبور، لا بالذبائح ولا بالنذور، ولا يصلى عند القبر، ولا يصلى لهم، ولا يدعون من دون الله، ولا يستغاث بهم، ولا ينذر لهم؛ لأن هذا لا يجوز، النذر لهم شرك بالله، ودعاؤهم من دون الله، كأن يقول: يا سيدي، أنا بجوارك، يا سيدي المدد المدد، هذا من الشرك الأكبر، من جنس عمل المشركين في عهد النبي ﷺ من أهل مكة وغيرهم. الميت يدعى له، ويستغفر له، ويترحم عليه، ولا يدعى من دون الله، لا يستغاث به، لا ينذر له، لا يذبح له، فمن فعل هذا مع الأموات؛ فقد أشرك، قال الله : قُلْ إنّ صلاتي ونُسُكي ومحْياي ومماتي للّه ربّ الْعالمين ۝ لا شريك لهُ وبذلك أُمرْتُ وأنا أوّلُ الْمُسْلمين [الأنعام:162-163] وقال سبحانه: إنّا أعْطيْناك الْكوْثر ۝ فصلّ لربّك وانْحرْ [الكوثر:1-2]. وقال -عليه الصلاة والسلام- في الحديث الصحيح عن علي  -أمير المؤمنين- أنه قال -عليه الصلاة والسلام-: لعن الله من ذبح لغير الله، لعن الله من لعن والديه، لعن الله من آوى محدثا -يعني: مبتدعًا، أو غيره ممن يحدثون حدثًا في الدين، فينصرون ويجارون- لعن الله من غير منار الأرض -يعني: مراسيمها وحدودها-. والشاهد قول: لعن الله من ذبح لغير الله الذبح لغير الله: تقرب إلى غير الله، كالصلاة لغير الله، فلا يجوز أن يذبح لفلان أو فلان تقربًا إليه، للميت الفلاني والولي الفلاني، أو للجن، أو للملائكة يتقربون إليهم، أو للأنبياء يعبدهم بهذا من دون الله، هذا لا يجوز، الذبيحة لله وحده ، والدعاء كذلك لا يدعى مع الله أحد، نعم.","link":"https://binbaz.org.sa/fatwas/17936/حكم-وضع-صندوق-تبرعات-للمسجد-عند-قبر-مجاور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_876/nour_87610.mp3","categories":["المساجد ومواضع السجود"]},{"id":18843,"question":"يسأل أخونا ويقول: رأيت في جريدة اللواء الإسلامي: أنه يمكن الصلاة بالنعلين، علمًا: بأن الإنسان يمر ويقف على الأوساخ والنجاسات، فما رأيكم -جزاكم الله خيرًا- حول هذا الموضوع؟","title":"إذا صلينا في النعال فكيف نحافظ على نظافة الفرش بالمساجد","answer":"الجواب: قد ثبت عن رسول الله -عليه الصلاة والسلام- أنه كان يصلي في نعليه، وصلى مرة فيهما، فجاءه جبرائيل فأخبره أن بهما قذرًا؛ فخلعهما، وجعلهما عن يساره، واستمر في صلاته -عليه الصلاة والسلام- فلما سلم قال للناس؛ لأن الناس لما رأوه خلع خلعوا، فلما سلم قال: ما بالكم خلعتم نعالكم؟ قالوا: يا رسول الله، رأيناك خلعت نعليك فخلعنا نعالنا، فقال: إن جبرائيل أتاني فأخبرني بأن فيهما قذرًا، فلهذا خلعتهما، فإذا أتى أحدكم المسجد فلينظر، فإن رأى في نعله أذى؛ فليمسحه، ثم ليصل فيهما فهذا هو الدليل، وما جاء في معناه على شرعية الصلاة في النعلين، وأنهما يصلى فيهما إذا كانتا نظيفتين.  فالواجب على المؤمن إذا أراد دخول المسجد وعليه النعلان أن ينظر فيهما، ويتأكد من سلامتهما من الأذى، فإذا كانتا سليمتين من الأذى فلا بأس أن يصلى فيهما، بل يشرع الصلاة فيهما كما صلى فيهما النبي ﷺ. وكان المسجد في عهده ﷺ من الرمل والحصى، وليس مفروشًا، أما الآن بعدما فرشت المساجد، وصارت بها الفرش التي تتأثر بالنعال، وما يكون فيها من التراب، وربما قذر ذلك على المصلين، ونفرهم من الصلاة فيها؛ فالأولى فيما نعتقد أن يخلعهما، ويجعلهما في مكان حتى يصلي، حتى لا يتأثر بذلك المصلون، وحتى لا تتأثر الفرش التي في المساجد، وهذا من باب ترك المستحب خوفًا مما هو أشد من ذلك، الصلاة فيهما مستحبة في أرجح القولين إذا كانتا نظيفتين، لكن قد يترتب على الصلاة فيهما مع الفرش ما هو أشد من ذلك، وما هو أخطر من ذلك؛ وهو تقذير الفرش، وتنفير المصلين، لا سيما وأكثر الناس لا يبالي بالنعلين ولا يتفقدهما، ولا يعتني بهما، فأكثر الناس عامة، لا يعتنون بهذا الأمر، فإذا رأوا زيدًا وعمرًا دخل بنعليه، دخلوا ولم يبالو؛ فأفضى هذا إلى شر كثير، والقاعدة: سد الذرائع، قاعدة الشرع المطهر: سد الذرائع. فالذي نوصي به، ونراه هو عدم الصلاة فيهما في المساجد التي فيها الفرش؛ لأنها قد تتقذر بذلك، ولأن أكثر الناس لا يبالي بنعليه، ولا ينتبه لما فيهما من الأذى، فلهذا قد يسبب مشاكل كثيرة، وتقذيرًا للفرش، وتنفيرًا للمصلين من الصلاة في الجماعة، وهذا أمر لا يحبه الله ولا يرضاه من المؤمن، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17981/اذا-صلينا-في-النعال-فكيف-نحافظ-على-نظافة-الفرش-بالمساجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_878/nour_87802.mp3","categories":["المساجد ومواضع السجود"]},{"id":18885,"question":"عندنا جماعة دينية لا داعي لذكر اسمها تبيح الأناشيد الدينية في المسجد وبصوت مرتفع، ما هو توجيهكم؟","title":"حكم ترديد الأناشيد في المسجد","answer":"الجواب: الأشعار العربية، والأناشيد العربية الإسلامية التي فيها فائدة في مقام العلم والتعليم لا بأس بها إذا كان في المسجد حلقة علم، أو واعظ يعظ الناس، ويذكر الناس، ويقرأ عليهم بعض الأشعار المفيدة، والأناشيد الشرعية الطيبة المفيدة، لا حرج في ذلك، فقد كان حسان  ينشد الشعر في مسجد النبي -عليه الصلاة والسلام- ويهجو الكفرة في مسجده ﷺ ويقول له النبي ﷺ: اهجهم، والذي نفسي بيده إنه لأشد عليهم من وقع النبل ويقول: اللهم أيده بروح القدس فإنشاد الأشعار في المساجد الأشعار الإسلامية المفيدة النافعة والأناشيد الطيبة في حلقات العلم وفي المواعظ كل هذا لا بأس به. أما الأغاني المنكرة، أو الأشعار المنكرة، أو الأناشيد المنكرة فلا تجوز، لا في المساجد، ولا في غيرها. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18010/حكم-ترديد-الاناشيد-في-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_922/nour_92211.mp3","categories":["المساجد ومواضع السجود"]},{"id":18988,"question":"ننتقل الآن إلى السودان -بل إلى مستمع من السودان- هو: (ك.ب) له عدد من الأسئلة، يقول في أحدها: ما حكم السلام في المسجد؟ وذلك أن يقول الإنسان للجالسين عند دخوله المسجد: السلام عليكم، ويردون عليه السلام، جزاكم الله خيرًا.","title":"حكم إلقاء السلام عند دخول المسجد","answer":"الجواب: حكم السلام أنه سنة، وقربة لمن دخل على قوم في المسجد، أو في أي مكان، يسلم عليهم يقول: السلام عليكم، وإن زاد: ورحمة الله وبركاته فهو أفضل، وهم يردون عليه مثلما قال أو يزيدونه، قال تعالى: وَإِذَا حُيِّيتُمْ بِتَحِيَّةٍ فَحَيُّوا بِأَحْسَنَ مِنْهَا أَوْ رُدُّوهَا[النساء:86]. فالرد واجب مثل التحية، والزيادة مستحبة، فإذا قال: السلام عليكم؛ وجب عليهم أن يقولوا: وعليكم السلام، فإن زادوه ورحمة الله كان أفضل، وإن زادوه وبركاته كان أفضل. وإذا قال: السلام عليكم ورحمة الله، وجب عليهم أن يقولوا: وعليكم السلام ورحمة الله، وإن زادوه وبركاته كان أفضل. فإن قال: السلام عليكم ورحمة الله وبركاته، وجب عليهم أن يقولوا: وعليكم السلام ورحمة الله وبركاته هذا ردها، الله قال: فَحَيُّوا بِأَحْسَنَ مِنْهَا أَوْ رُدُّوهَا[النساء:86] وهذه هي النهاية في السلام، السلام عليكم ورحمة الله وبركاته. فعليهم أن يردوها فإذا زادوه بعد ذلك كيف حالك، بارك الله فيك، كيف أولادك، كل هذا طيب، هذا من الزيادة الطيبة. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18151/حكم-القاء-السلام-عند-دخول-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_793/nour_79304.mp3","categories":["المساجد ومواضع السجود"]},{"id":19022,"question":"مستمع بعث يسأل ويقول: علمنا أن رسول الله ﷺ قد نهى عن رفع الصوت في المساجد في أوقات الصلاة ولو بقراءة القرآن، وقد لاحظت أن معظم الإخوة المسلمين حيث أقيم يرفعون أصواتهم بقراءة القرآن وخاصة في الأوقات بين الأذان والإقامة لدرجة قد تجعلني في كثير من الأحيان لا أحسن الوقوف بين يدي الرحمن، فما العمل؟وأرجو الله إن كان في تصرف هؤلاء الإخوة ما لا يجوز أن ينبهوا على ذلك كثيرًا فإن الأمر قد عم جميع المساجد، حتى إنك إذا أخبرت أحدهم بما في هذا الأمر فإما أن يتعجب مما تقول: وإما أن يستمع إليك ثم لا يتوقف عن فعل ذلك العمل، هدانا الله جميعًا إلى سواء السبيل، وصاحب هذا السؤال أخ مصري يعمل في السعودية كما يقول: يبدو أن اسمه طارق حسين.","title":"حكم رفع الصوت بالقرآن في المساجد قبيل الصلاة","answer":"الجواب: لا شك أن هذا واقع في المساجد، ولا شك أن الأفضل عدم الجهر بالصوت، وعدم رفع الصوت في الصفوف في المساجد، وأن الإنسان يقرأ وهو خافض صوته حتى لا يشوش على من حوله من القراء والمصلين هذا هو السنة، وقد ثبت عنه ﷺ أنه خرج ذات يوم إلى الناس في المسجد وهم يقرءون، قد رفعوا أصواتهم فقال: كلكم يناجي الله فلا يجهر بعضكم على بعض أو كما قال عليه الصلاة والسلام. فالمقصود أن السنة مراعاة من حوله من المصلين، وألا يجهر بقراءته فيشوش عليهم، ولكن يقرأ قراءة منخفضة ليس فيها تشويش بينه وبين نفسه، أو يرفع قليلًا لا يتعدى الضرر إلى غيره لكنه رفع قليل. فالحاصل: أنه ينبغي له أن يراعي شعور المصلين فلا يجهر جهرًا يشوش على مصل أو على قارئ، أما لو قدر أن من حوله يسمعون وينصتون له وليس في ذلك أذىً لأحد بلا بأس بالجهر الذي ينفع من حوله، إذا فرضنا أنه في مكان من الصف حوله مستمعون يحبون أن يرفع صوته قليلًا حتى يستمعوا هذا فيه نفع لهم ولا حرج فيه؛ لأنه لا يضر أحدًا، ولكن في الأغلب أنه يكون حوله المصلي وحوله القارئ فالذي ينبغي له أن يسر أن يخفض صوته، وأن يكون بقدر ما لا يؤذي أحدًا ممن حوله. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18192/حكم-رفع-الصوت-بالقران-في-المساجد-قبيل-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_927/nour_92708.mp3","categories":["المساجد ومواضع السجود"]},{"id":19076,"question":"يسأل ويقول: هل يجوز أخذ المصاحف والكتب من المسجد، واستبدالها بغيرها من المصاحف، كأن يأخذ الشخص مصحفًا من المسجد ويضع غيره في طبعة أخرى، ولون آخر؟ جزاكم الله خيرًا.","title":"حكم أخذ أشياء المسجد واستبدالها","answer":"الجواب: لا يجوز لأي مسلم أن يأخذ من مصاحف المسجد أو كتب المسجد شيئًا؛ لأن الذي وضعها قصد أن ينتفع بها المسلمون في هذا المسجد، فليس لأحد أن يأخذها من المسجد، ولا من مكتبته، بل تبقى لأهل المسجد، ولمراجعي المكتبة، وإذا أحب أن يزيد ويضع كتبًا أخرى ومصاحف أخرى، فجزاه الله خيرًا. أما أن يأخذ مصحفًا؛ لأنه أنسب له لحسن طبعته، أو لكبر حروفه، ويأتي بمصحف آخر أو كتاب آخر لا، بل يترك ما في المسجد للمسجد، ولأهل المسجد، وفي مكتبة المسجد. وإذا كان هناك فضل في المصاحف لا مانع من نقلها إلى مسجد آخر، إذا كان هناك فضل فيها، وعدم حاجة إلى بعضها تنقل إلى مسجد آخر محتاج، وهكذا إذا كان في المكتبة كتب كثيرة، وهناك مكتبات تابعة لمساجد أخرى تحتاج إليها، ونقل بعضها إلى هناك فلا بأس، إلا أن يكون صاحب الكتاب نص على هذه المكتبة المعينة أنه يبقى فيها فيبقى فيها. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18258/حكم-اخذ-اشياء-المسجد-واستبدالها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_797/nour_79703.mp3","categories":["المساجد ومواضع السجود"]},{"id":19123,"question":"رسالة وصلت إلى البرنامج من المستمع مفتاح مصطفى، من الجماهيرية، أخونا له مجموعة من الأسئلة، يسأل في سؤاله الأول ويقول: حين راح رجل يبحث عن شيء ضاع منه في المسجد قال له الرسول ﷺ: لا رد الله عليك ضالتك، لماذا؟ أرشدوني أفادكم الله","title":"ما معنى: «لا رد الله عليك ضالتك»؟","answer":"الجواب: المساجد لم تبن لنشد الضوال وطلب الحاجات المفقودة، المساجد بنيت لما بنيت له من ذكر الله، وقراءة القرآن، وإقامة الصلاة، وحلقات العلم، والاعتكاف، ولم تبن للبيع والشراء، ولا لأن ينشد فيها الضوال واللقط التي تذهب من الناس؛ ولهذا حذر من هذا عليه الصلاة والسلام، وقال: من سمع رجلًا ينشد ضالة في المسجد فليقل: لا ردها الله عليك، ولما سمع من يقول: من يدل على كذا.. على جمل له ضاع، قال: لا وجدته، وهذا من باب التحذير ومن باب الزجر، حتى لا يتساهل الناس في إنشاد الضوال في المساجد ويتخذوها محلاً لإنشاد الضوال، أو لبيعهم وشرائهم؛ ولهذا في الحديث الآخر: إذا رأيتم من يبيع أو يبتاع في المسجد فقولوا: لا أربح الله تجارتك. والمقصود الزجر والتحذير، ليس المقصود العداء للشخص، أو كراهة أن يجد راحلته، لا، المقصود من هذا التحذير والزجر لئلا يعود الناس إلى هذه الأمور في المساجد، ولئلا يعتادوها، فأتى بهذه العبارة: لا وجدته، لا ردها الله عليك، للزجر والتحذير حتى يبتعد الناس عن هذا الأمر في المساجد. والله جل وعلا أباح لرسوله ﷺ أن يزجر الناس عما يضرهم، وهكذا العلماء بعده خلفاء الرسل، يحذرون الناس مما يضرهم ولو بالزجر ولو بالدعاء في بعض الأحيان، للزجر والتحذير. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18316/ما-معنى-لا-رد-الله-عليك-ضالتك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_885/nour_88507.mp3","categories":["المساجد ومواضع السجود"]},{"id":19156,"question":"إننا نبعد عن مسجد القرية، ولكننا نصلي جماعة في مكان اتخذناه مصلى لنا، فهل علينا شيء في عدم الذهاب إلى المسجد؟","title":"حكم الصلاة جماعة في مصلى بسبب بُعد المسجد","answer":"الجواب: إذا كنتم تسمعون النداء بالصوت المجرد من دون مكبر لقربه منكم، فإنه يلزمكم الذهاب والصلاة معهم؛ لقول النبي ﷺ: من سمع النداء فلم يأت فلا صلاة له إلا من عذر وجاءه رجل أعمى فقال: «يا رسول الله! ليس لي قائد يلائمني إلى المسجد، فهل لي من رخصة أن أصلي في بيتي؟ فقال عليه الصلاة والسلام: هل تسمع النداء بالصلاة؟ قال: نعم، قال: فأجب. فالواجب عليكم أن تصلوا مع الجماعة في المسجد إذا كنتم تسمعون النداء، وتستطيعون الذهاب إليه، أما إذا كان بعيدًا منكم يشق عليكم الذهاب إليه ولبعده أو لأن أهل محلكم مرضى أو عاجزون لكبر السن ونحو ذلك فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]. فالحاصل أن الواجب عليكم الصلاة مع الجماعة، ما دمتم تسمعون النداء العادي عند هدوء الأصوات تسمعون النداء فعليكم السعي. أما إذا كان بعيدًا عنكم عرفًا يشق عليكم السعي إليه ولا تسمعون النداء فلا مانع أن تصلوا في محلكم ولا حرج في ذلك. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18340/حكم-الصلاة-جماعة-في-مصلى-بسبب-بعد-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_932/nour_93205.mp3","categories":["المساجد ومواضع السجود"]},{"id":19245,"question":"نعود مع مطلع هذه الحلقة سماحة الشيخ إلى رسالة المستمع عبد الرحمن هشام من السودان الخرطوم بحري، أخونا عرضنا جزءًا من أسئلته في حلقة مضت، وفي هذه الحلقة يسأل مع إخوة له سبق وأن سألوا سؤالًا واحدًا، ذلكم السؤال هو: هل تجوز صلاة العيد إلى المقابر وتكون المقبرة أمامهم؟ وبماذا تنصحوننا جزاكم الله خيرًا.","title":"حكم صلاة العيد إلى المقابر","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فالصلاة إلى القبور لا تجوز؛ لأنه ثبت عن النبي ﷺ أنه قال: لا تصلوا إلى القبور، ولا تجلسوا عليها رواه مسلم في الصحيح. فالقبر لا يصلى إليه، ولا يجلس عليه، يحرم الجلوس عليه، أو التغوط عليه، أو وطئه بالرجل، قبر المسلم، لا يجوز ذلك، ولا يصلى إلى القبور تجعل قبلة، ولا بينها؛ لما ثبت عنه عليه الصلاة والسلام أنه قال: ألا وإن من كان قبلكم كانوا يتخذون قبور أنبيائهم وصالحيهم مساجد ألا فلا تتخذوا القبور مساجد فإني أنهاكم عن ذلك فنهاهم عن اتخاذ القبور مساجد يعني: مصلى فإني أنهاكم عن ذلك فلا يصلى بينها، ولا إليها، بل يجب أن يكون بين المسجد وبينها فاصل مثل الجدار، أو مسافة بعيدة كوادٍ بينهم وبين القبور أو جبل، أو أرض واسعة بعيدة، حتى لا يظن أنه يصلى إليها، وأنها تقصد. وإذا كان بين المسجد وبينها جدار آخر غير جدار المقبرة جدار المسجد كان ذلك أبعد عن الفتنة، وإذا كانت المقبرة عن يمين أو شمال يكون أحسن، وأبعد عن الفتنة أيضًا. والمساجد يجب أن تكون بعيدة عن مظان الشرك، وأسباب الشرك، فإذا كانت بين القبور، أو أمامها القبور، أو كانت في وسطها شيء من القبور كان هذا من وسائل الشرك؛ ولهذا نهى الرسول ﷺ عن الصلاة في المساجد التي في القبور، وقال عليه الصلاة والسلام في ذم اليهود والنصارى: اتخذوا قبور أنبيائهم مساجد، وقال في الحديث الآخر في حديث عائشة رضي الله عنها عن أم سلمة وأم حبيبة أنهما رأتا كنيسة في أرض الحبشة وما فيها من الصور، فقال النبي ﷺ: أولئك إذا مات فيهم الرجل الصالح بنوا على قبره مسجدًا، وصوروا فيه تلك الصور، أولئك شرار الخلق عند الله. فأخبر أنهم شرار الخلق بسبب عملهم الخبيث، وبناء المساجد على القبور، واتخاذ الصور عليها، يعني: صور أهل القبور كما فعل قوم نوح حين صوروا ودًا وسواعًا، ويغوث ويعوق، ونسرًا، ونصبوها في مجالسهم حتى عبدت من دون الله. والخلاصة: أن الواجب أن تكون المساجد بعيدة عن القبور، ولا يقبر فيها أحد، لا يجوز أن يقبر في المسجد أحد، لا في قبلته ولا في شماله، ولا جنوبه ولا مؤخره، يجب أن تكون المساجد بعيدة عن القبور بينها وبين القبور فاصل، حتى لا يظن أن المصلين يصلون إلى القبور، أما فاصل من الجدران، أو البيوت، أو طريق فاصل بينها وبين المساجد، أو وادي أو نحو ذلك مما يبعد الشبهة. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18429/حكم-صلاة-العيد-الى-المقابر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_800/nour_80001.mp3","categories":["المساجد ومواضع السجود"]},{"id":19310,"question":"تسأل أختنا وتقول: هل يجوز التصفيق لحاجة أثناء الصلاة ؟","title":"مشروعية تصفيق المرأة للحاجة أثناء الصلاة","answer":"الجواب: نعم، سنة في حق النساء، التصفيق سنة في حق النساء إذا حدث حادث، أما الرجال فلهم التسبيح، يقول النبي ﷺ في الحديث الصحيح: من نابه شيء في صلاته فليسبح الرجال ولتصفق النساء هكذا السنة.  المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/18497/مشروعية-تصفيق-المراة-للحاجة-اثناء-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_894/nour_89403.mp3","categories":["المساجد ومواضع السجود"]},{"id":19445,"question":"يسأل أخونا سعد حامد سرحان طالب في إعداد الدراسات الإسلامية في العراق، نينوى الموصل يسأل أيضًا ويقول: هل تجوز الصلاة في الجامع الذي فيه قبر؟ أفتونا بارك الله فيكم.","title":"هل تجوز الصلاة في المسجد الذي فيه قبر؟","answer":"الجواب: الصلاة في المساجد التي فيها القبور لا تصح، كل جامع فيه قبر أو مسجد فيه قبر ولو كان ليس بجامع ولو كان لا تقام فيه الجمعة، المساجد التي فيها القبور لا يصلى فيها، ولا تصح الصلاة فيها، لأن الرسول عليه الصلاة والسلام قال: لعن الله اليهود والنصارى اتخذوا قبور أنبيائهم مساجد وقال عليه الصلاة والسلام: ألا وإن من كان قبلكم كانوا يتخذون قبور أنبيائهم وصالحيهم مساجد ألا فلا تتخذوا القبور مساجد فإني أنهاكم عن ذلك رواه مسلم في صحيحه. وصح عنه ﷺ «أن أم حبيبة بنت أبي سفيان أم المؤمنين وأم سلمة أم المؤمنين أيضاً ذكرتا للنبي ﷺ كنيسة رأتاها بأرض الحبشة وما فيها من الصور فقال: أولئك إذا مات فيهم الرجل الصالح بنوا على قبره مسجدًا وصوروا فيه تلك الصور أولئك شرار الخلق عند الله فجعلهم بهذا العمل من شرار الخلق عند الله وهو بناؤهم المساجد على القبور وتصويرهم الصور فيها. فالواجب على أهل الإسلام أن يحذروا ذلك، وأن لا يبنوا على القبور، وأن لا يتخذوها مساجد، وأن لا يجعل عليها بناءً ولا قبة، بل تكون ضاحية مكشوفة ليس عليها بناء بالكلية، هذا هو المشروع وهذا هو الواجب، أما البناء عليها أو اتخاذ القباب عليها أو المساجد فكل هذا منكر، ولهذا يقول ﷺ: لعن الله اليهود والنصارى اتخذوا قبور أنبيائهم مساجد قالت عائشة رضي الله عنها: يحذر ما صنعوا»، وقال عليه الصلاة والسلام: ألا وإن من كان قبلكم كانوا يتخذون قبور أنبيائهم وصالحيهم مساجد ألا فلا تتخذوا القبور مساجد فإني أنهاكم عن ذلك. فنهاهم ﷺ عن اتخاذ المساجد على القبور ولعن من فعل ذلك، فدل ذلك على أن هذا من الكبائر من كبائر الذنوب، والنهي يقتضي فساد المنهي عنه، فساد الصلاة عند القبور وفي المساجد المبنية عليها وقال عليه الصلاة والسلام: لا تصلوا إلى القبور ولا تجلسوا عليها وفي حديث جابر عند مسلم في صحيحه قال: «نهى رسول الله ﷺ أن يجصص القبر وأن يقعد عليه وأن يبنى عليه» فنهى عن هذا وهذا، عن التجصيص للقبور، وعن البناء عليها، وعن القعود عليها. فالواجب على أهل الإسلام أن يحذروا ما حرم الله وما نهى عنه رسوله عليه الصلاة والسلام، وليس لهم أن يصلوا في المساجد التي اتخذت على القبور، لأن الرسول نهى عن ذلك ولعن من فعله عليه الصلاة والسلام، والصلاة عندها اتخاذ لها مسجد ولو لم يبن المسجد كونه يصلي عند القبور معناه أنه اتخذها مسجدًا. ولا ريب أن الصلاة عندها والدعاء عندها، تحري الدعاء عندها، تحري القراءة عندها، كل هذا من أسباب الشرك ومن وسائله، فالواجب الحذر من ذلك، وإنما تزار، يزورها المسلم ويدعو للميتين ولنفسه معهم، يقول: السلام عليكم أهل الديار من المؤمنين والمسلمين وإنا إن شاء الله بكم لاحقون، نسأل الله لنا ولكم العافية، يرحم الله المستقدمين منا والمستأخرين يغفر الله لنا ولكم ونحو هذا الدعاء يدعو لهم ولنفسه معهم غفر الله لنا ولكم، نسأل الله لنا ولكم العافية ثم ينصرف، ما يجلس عندها للقراءة أو الدعاء عندها ولا يطوف بها هذا منكر، والطواف على القبور بقصد التقرب إلى الميت هذا من الشرك الأكبر مثل الدعاء، كما لو قال: يا سيدي! أغثني، المدد المدد انصرني، اشفني هذا من الشرك الأكبر. فالواجب الحذر، وكثير من الدول الإسلامية يوجد فيها قبور قد اتخذ عليها مساجد، فالواجب الحذر من ذلك، والواجب على ولاة الأمر أن يزيلوا ذلك وأن تبقى القبور ضاحية مكشوفة ليس عليها أبنية كما كان الحال في عهد النبي ﷺ في البقيع وفي بقية مقابر المسلمين في البلاد الإسلامية، وإنما حدث هذا حدث هذا البناء بعد ذلك في القرن الثاني وبعده، بسبب الرافضة والغلاة الذين غلوا وتشبهوا بـالرافضة في ذلك حتى وقع ما وقع من اتخاذ المساجد على القبور واتخاذ القباب، وحتى وقع الشرك بالموتى وسؤالهم والاستغاثة بهم والنذر لهم بسبب هذا الغلو، نسأل الله للجميع العافية والسلامة والهداية. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18692/هل-تجوز-الصلاة-في-المسجد-الذي-فيه-قبر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_938/nour_93811.mp3","categories":["المساجد ومواضع السجود"]},{"id":19490,"question":"يقول السائل سماحة الشيخ: هل يجوز للإنسان أن يأخذ مصحفًا من المسجد لنفسه أو أن يستبدل مصحفًا له؟","title":"حكم أخذ مصحف من المسجد أو استبداله بغيره","answer":"الجواب: ليس له ذلك، لا يجوز أن يأخذ من المسجد شيئًا، لا لنفسه ولا يبدله، بل يجب ترك ما في المسجد في المسجد للمسلمين. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/18738/حكم-اخذ-مصحف-من-المسجد-او-استبداله-بغيره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_939/nour_93922.mp3","categories":["المساجد ومواضع السجود"]},{"id":19648,"question":"يقول السائل: سماحة الشيخ! لدينا في الكلية مصلى، ندخل فيه ونجلس فيه متى ما نشاء ونفطر فيه أيضًا، وقد ينام البعض وقد يدخل الطالب وهو على غير وضوء، ما رأيكم في هذا؟","title":"حكم الصلاة في المصلى الذي ليس له أحكام المسجد","answer":"الجواب: الواجب عليكم أن تصلوا في المساجد، في المسجد الذي بقربكم تسمعون نداءه، الواجب أن تصلوا في المسجد، فإذا لم يتيسر ذلك لبعد المساجد عنكم فإنكم تصلون في المصلى الذي تعينونه وليس له حكم المسجد، إذا نام فيه أحد أو دخله ليس له حكم المساجد، فله أن ينام فيه، والمسجد ينام فيه لا بأس، وللحائض أن تدخله، وللجنب أن يدخله لا حرج؛ لأنه ليس بمسجد، المصلى ليس بمسجد. نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/18932/حكم-الصلاة-في-المصلى-الذي-ليس-له-احكام-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_950/nour_95002.mp3","categories":["المساجد ومواضع السجود"]},{"id":19661,"question":"الحمد لله رب العالمين، والصلاة والسلام على أشرف المرسلين، نبينا محمد، وآله وصحبه أجمعين، أما بعد: فقد ورد إلي سؤال مضمونه: أن جماعة من المسلمين القاطنين في جنوب أفريقيا قد بنوا مسجدًا في حيهم، يصلون فيه الجمعة والجماعة والعيد، وقد أمرتهم حكومتهم بإخلاء ذلك الحي من السكان المسلمين وإبعادهم إلى جهة أخرى.فهل يجوز بيع المسجد المذكور بواسطة القاضي أو المتولي عليه، وعمارة مسجد آخر في الحي الجديد الذي يسكنون فيه؟ وهل يباع بشكله مسجدًا، أو يغير فيه كرفع المحراب والمنبر والمئذنة، وكل شيء يدل على كونه مسجدًا، أو يهدم ويباع أرضًا بيضاء، مع العلم أنه في هذه الحالة تنقص قيمته كثيرًا، بل لا يساوي شيئًا؟","title":"حكم نقل المسجد إذا تعطلت منفعته","answer":"الجواب: والجواب: لا ريب أن المسجد المذكور سوف تتعطل مصلحته إذا ارتحل المسلمون عن الحي الذي هو فيه، وإذا تعطلت منفعة الوقف سواء كان مسجدًا أو غيره جاز بيعه في أصح أقوال العلماء، وتصرف قيمته في وقف آخر بدل منه، مماثل للوقف الأول حيث أمكن ذلك. وقد روي عن أمير المؤمنين عمر بن الخطاب  أنه أمر بنقل مسجد الكوفة إلى مكان آخر لمصلحة اقتضت ذلك. فتعطل المنفعة أولى بجواز النقل، والمسألة فيها خلاف بين العلماء، ولكن القول المعتمد جواز ذلك؛ لأن الشريعة الإسلامية الكاملة جاءت بتحصيل المصالح وتكميلها، وتعطيل المفاسد وتقليلها، وأمرت بحفظ الأموال ونهت عن إضاعتها، ولا ريب أن الوقف إذا تعطل لا مصلحة في بقائه، بل بقائه من إضاعة المال. فوجب أن يباع ويصرف ثمنه في مثله، إلا أن يكون بيع بعضه يكفي لإصلاحه، فإنه يباع بعضه، ويصرف ثمنه في إصلاح الباقي. أما هذه الصورة المسئول عنها، فلا يمكن حصول المنفعة إلا ببيع الجميع، فيباع المسجد كله على حاله من دون نقص، ويصرف ثمنه في عمارة المسجد الجديد في الحي الذي تحول إليه المسلمون، وإذا بيع زال عنه حكم المسجد، وصار كسائر البقاع، يجوز اتخاذه مزرعة وحوانيت ونحو ذلك، وانتقل حكم المسجد إلى المسجد الجديد. وأما إزالة ما يدل على أنه مسجد بعد العزم على بيعه، كالمئذنة ونحوها، فلم أقف فيه على كلام لأحد من أهل العلم، والأقرب -والله أعلم- أن إزالة ذلك أولى، ولا سيما إذا كان بين الكفرة؛ لأنهم قد يقصدون إغاظة المسلمين بامتهانه؛ نظرًا إلى أنه كان مسجدًا، وإن كان حكمه قد زال، ولكنهم لا ينظرون إلى الأحكام، ولكنهم ينظرون إلى الصورة الظاهرة، فإذا أزيلت أمارات المسجد البارزة، كالمئذنة والمحراب، زال هذا المحذور. والله  أعلم. ونسأل الله سبحانه أن يصلح أحوال المسلمين، ويولي عليهم خيارهم، ويرفع شأنهم في كل مكان، وأن يذل أعداء الإسلام، ويكفي المسلمين شرهم؛ إنه على كل شيء قدير، وصلى الله وسلم على عبده ورسوله محمد، وآله وصحبه[1]. نائب رئيس الجامعة\nالإسلامية بالمدينة المنورة\nعبدالعزيز بن عبدالله بن باز","link":"https://binbaz.org.sa/fatwas/18953/حكم-نقل-المسجد-اذا-تعطلت-منفعته","audio":"","categories":["المساجد ومواضع السجود","الوقف"]},{"id":19678,"question":"سماحة الشيخ يسأل هذا السائل من الجزائر عن حكم الصلاة في السجادة المزخرفة، هل هي بدعة؟","title":"حكم الصلاة على السجادة المزخرفة","answer":"الجواب: لا، مكروهة لأنها تشوش عليه صلاته، فالأفضل أن يصلي في سجادة عادية -سادة- ليس فيها نقوش حتى لا تشغله عن صلاته، أو يصلي على الأرض الطيبة، أما السجادات المنقوشة فقد تشوش عليه صلاته، تركها أولى وأفضل.","link":"https://binbaz.org.sa/fatwas/18970/حكم-الصلاة-على-السجادة-المزخرفة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_950/nour_95031.mp3","categories":["المساجد ومواضع السجود"]},{"id":19690,"question":"يوجد مسجد في الولايات المتحدة الأمريكية جُمع له مال وبني، وبقي من المال كثير، ويوجد في منطقة أخرى مسجد وحوله جالية إسلامية كبيرة، ويتطلب بناء مكتبة ومدرسة وبعض الملاحق، ويريد بعض القائمين عليه أخذ شيء من المال الموجود عند القائمين على المسجد الأول، ويمانع أصحاب المسجد الأول؛ بحجة أن المال للمسجد الأول، ويقولون: إذا أفتى الشيخ/ عبدالعزيز بن باز في جواز نقل المال من ذاك إلى هذا، فلا مانع لدينا من ذلك. نرجو الإفادة عن ذلك؟","title":"حكم نقل مال مسجد لآخر","answer":"الجواب:\n\nإذا كان المسجد الأول الذي جمع له المال قد كمل واستغني عن المال، فإن الفاضل من المال يصرف لتعمير مساجد أخرى، مع ما يضاف إليها من مكتبات ودورات مياه ونحو ذلك كما نص على ذلك أهل العلم في كتاب الوقف؛ ولأنه من جنس المسجد الذي تُبرع له، ومعلوم أن المتبرعين إنما قصدوا المساهمة في تعمير بيت من بيوت الله، فما فضل عنه يصرف في مثله، فإن لم يوجد مسجد محتاج، صرف الفاضل في المصالح العامة للمسلمين، كالمساجد والأربطة والصدقات على الفقراء، ونحو ذلك، والله ولي التوفيق[1].\n\n\n\n\tنشر في كتاب (فتاوى إسلامية)، من جمع الشيخ /محمد المسند ج3، ص: 24. (مجموع فتاوى ومقالات الشيخ ابن باز 20/14).","link":"https://binbaz.org.sa/fatwas/18989/حكم-نقل-مال-مسجد-لاخر","audio":"","categories":["القرآن وعلومه","المساجد ومواضع السجود","الوقف"]}]
